window.BOOKS = window.BOOKS || {};
window.BOOKS['2'] = {"id": "2", "title": "Meretes videre erindringer", "subtitle": "Bind 2 · 1973 – 1998", "years": "1973 – 1998", "dedication": "", "forord": {"title": "Forord", "blocks": [{"type": "para", "text": "Lørdag den 9. februar 2008"}, {"type": "para", "text": "Efter de mange positive tilbagemeldinger på min første erindringsbog, som blev færdiggjort til julen 2006, og som Lars fik i julegave, har jeg besluttet mig for at gå i gang med Bind 2. Jeg har lige siden færdiggørelsen haft lyst til at komme i gang igen, fordi jeg syntes, det var et mægtigt spændende projekt, men tiden har ikke været til det, og desuden har jeg hele tiden tænkt, at det kunne vente til den dag, jeg skulle pensioneres. Mit job som lektor og international koordinator på Ingeniørhøjskolen i Århus kræver meget af min tid."}, {"type": "para", "text": "Jeg startede ret hurtigt efter Bind 1 med at lave research på Bind 2 ved at finde gamle dagbøger frem og tage notater, og da Lars så for nylig lod en bemærkning falde om, at Bind 1 jo slet ikke havde handlet om ham, og at han gerne ville læse noget om sig selv, tænkte jeg, at nu måtte jeg vist i gang. Hvornår jeg bliver færdig, må stå hen i det uvisse, for vi går i år i gang med at bygge nyt hus, så tiden vil sikkert gå med meget andet end at sidde ved computeren."}, {"type": "para", "text": "Siden sidst er der kommet en lille ny verdensborger i vores familie, idet Mette og Lars har fået William, som blev født den 22. maj 2007. Denne bog skal derfor også dedikeres til William, som jeg håber vil få rigtig megen fornøjelse af at læse om sin far, men den er mest skrevet for Lars’ skyld."}, {"type": "para", "text": "God fornøjelse."}]}, "sections": [{"id": "1970erne", "title": "1970’erne", "chapters": [{"title": "Hvedebrødsdage", "blocks": [{"type": "para", "text": "Da vi var kommet os ovenpå al festivitasen efter brylluppet den 28. juli 1973, gik livet videre som før. Vi havde jo boet sammen siden 1970, så det var der ikke noget nyt i, og vi havde boet i nyt hus i et år. Vi var med andre ord veletablerede og havde et godt netværk i Spørring."}, {"type": "para", "text": "Sommeren 1973 var varm, så brudebuketten hang lidt, da jeg om tirsdagen kørte til Haar for at få den presset og sat i glas og ramme hos en dame, der gjorde i den slags. Det var meget brugt dengang, at man bevarede sin brudebuket på den måde som et minde og havde den hængende i flere år, hvis da ægteskabet holdt. Vores ægteskab holdt heldigvis længere end brudebuketten, som vi havde hængende i soveværelset i nogle år, inden den røg ud. Hvad jeg dog ikke vidste var, at mor i al hemmelighed havde fjernet to marguerithoveder fra buketten, inden jeg tog den med. Hun havde efterfølgende indleveret dem til guldsmeden og fået dem forgyldt til at hænge i en kæde. Min overraskelse var derfor stor, da jeg af mor og far den 12. november samme år til min 24-års fødselsdag fik en forgyldt marguerit fra min brudebuket. Den anden beholdt mor selv, så i dag har jeg to. Måske vil mine kvindelige efterkommere værdsætte dem."}, {"type": "para", "text": "Kort efter brylluppet inviterede vi naboerne til efterbryllup – de havde givet os en havegrill, som vi efterfølgende fik megen fornøjelse af."}, {"type": "para", "text": "Det var ikke så almindeligt med bryllupsrejser dengang, men vi besluttede alligevel, at vi ville på en rejse, dog først den efterfølgende vinter, mere præcist i januar 1974, og turen skulle gå til Marokko. Da vi var meget sammen med Vagns bror Tage dengang, var det kun naturligt, at han skulle med på ferien. Det blev en uforglemmelig rejse. Da vi hovedsagelig tog lysbilleder dengang, er der i vores scrapbog mest postkort og nogle af de papirbilleder, som Tage tog."}, {"type": "para", "text": "Det var før Dankortets tid, så vi havde American Express rejsechecks med for ca. 5.000 kr. Vi rejste med Tjæreborg, og selve rejsen for os alle tre kostede 4.030 kr. for to uger. Møntsorten i Marokko var Dirham."}, {"type": "para", "text": "Vi tog fra Spørring den 3. januar kl. 3.40 om morgenen og var i Marrakech om eftermiddagen, en oase-by omringet af et grønt bælte af daddelpalmer. Byen med 270.000 indbyggere er delt op i en gammel bydel, der huser paladser, monumenter og markeder, og en ny bydel, som er fransk præget. Vi boede på et lækkert 4-stjernet hotel i den nye bydel, Hotel Tafilalet, med swimmingpool. Vi var kommet til en hel ny verden og et andet klima. Vi havde forladt det kolde nord og var havnet i en solrig oase med palmer, hvor den rødbrune farve var fremherskende på såvel bygninger som bymur, og hvor jeg stadig kan fornemme køligheden af morgenluften og hotellets marmorgulve. Når vi begav os uden for hotellet, så vi tilhyllede kvinder, hvor kun øjnene var til syne, slangetæmmere, medicinmænd, okse- og hestekærrer samt appelsin- og citronlunde. Noget af det mest spændende, men også til tider lidt skræmmende, var at gå ind i Medinaen, hvilket var en labyrint af smalle gader, hvor de handlende holdt til, og hvor kloakvandet og andre uhumske ting flød rundt."}, {"type": "figure", "caption": "", "page": 5, "file": "assets/images-bog2/p005_01.jpg", "dim": [818, 691]}, {"type": "para", "text": "Stoppede man op for at tage et billede, kom de indfødte straks med hånden og afkrævede betaling. Det mest uhumske, vi så, var slagterbutikken, hvor kødet hang i varmen, helt dækket af fluer, og fårehoveder lå dynget op i kurve. Men man kunne gøre mange gode handler, hvis man kunne lide at prutte om prisen."}, {"type": "para", "text": "Især skind og tæpper var billige."}, {"type": "para", "text": "Vi tog på nogle ture, som altid startede tidligt om morgenen, så dagen begyndte med en varm trøje men endte som regel med shorts og solbluse. En af turene gik dog op i sneen i Atlasbjergene i 4000 meters højde, og på en anden tur besøgte vi en berberlandsby, hvor livet havde stået stille gennem århundreder. De små huse var bygget af lerjord, og beboerne sov på jorden, for de havde ingen møbler. Vi prøvede også at ride på kameler."}, {"type": "para", "text": "Da Tage var ungkarl, måtte han dele værelse med en anden ungkarl, som viste sig at være en sømand ved navn Leif, men vi kaldte ham aldrig andet en Sømanden fra Marrakech. Han var en flink fyr, som vi tit var sammen med, ofte ved poolen, hvor vi spillede yatzi. Ofte var vi også sammen med en sød familie fra Lunderskov, familien Bøgelund, som havde tre døtre med. En aften var vi på Casino, hvor vi så show med mavedans."}, {"type": "para", "text": "Efter en uge i Marrakech, skulle mange fra selskabet hjem, men vi havde heldigvis en uge tilbage, som skulle tilbringes i badebyen Agadir, hvortil vi ankom med bus sammen med Sømanden fra Marrakech. På vejen dertil så vi nomader, der kun ejede et par magre geder og en transistorradio. Agadir blev efter jordskælvet i 1960 genopbygget i stål og beton og havde nu 25.000 indbyggere, en diametral modsætning til Marrakech og ikke nær så charmerende. Under jordskælvet døde 12.000 mennesker på 12 sekunder!"}, {"type": "figure", "caption": "", "page": 5, "file": "assets/images-bog2/p005_02.jpg", "dim": [539, 681]}, {"type": "para", "text": "Vi var ude og bade på Tages fødselsdag den 15. januar, hvor vandet var 19 grader og luften 25-30 grader, ligesom de andre dage. På hotellerne fik vi meget europæisk mad, men vi smagte også nationalretten cous-cous og drak pebermynte te. Dejligt var det også at købe store poser fyldte med mandariner og appelsiner af den saftigste slags for næsten ingen penge."}, {"type": "para", "text": "Vi købte en del souvenirs, bl.a. et tæppe, som vi havde liggende på stuegulvet i flere år derefter, og en lilla kaftan, som jeg havde på til Pers konfirmation den 21. april samme år. Den 17. januar var eventyret forbi, og vi sagde farvel til Sømanden fra Marrakech. Senere besøgte han os i Spørring en weekend, hvor Tage var på besøg. Siden har vi ikke set ham."}]}, {"title": "Vores forældre", "blocks": [{"type": "para", "text": "Jeg tror, at vores forældre var ganske godt tilfredse med, at vi var blevet gift, så de snart kunne få nogle børnebørn, selvom Vagns forældre jo allerede havde to, nemlig Charlotte og Jens Christian. Der skulle imidlertid gå 4 år, inden det lykkedes, men derom meget mere senere."}, {"type": "para", "text": "Vi var, når vi selv skulle sige det, meget flinke til at besøge vores forældre – det var lidt sjældnere, at de besøgte os. Mor skulle altid gøre sig kostbar, når vi ringede og spurgte, om de ikke kom, og hun skulle først ”drøfte det med far”. Så kunne der gå flere dage, inden hun meldte sig på banen igen med et som regel positivt svar. Vi vidste imidlertid alt om, at det var mor, der bestemte. Men det var rigtig hyggeligt at have dem på besøg, og vi glædede os meget til, at de skulle komme. Vagns forældre kom ikke så tit, men det var dejligt, når det skete."}, {"type": "para", "text": "Som et eksempel kan jeg nævne, at vi i 1977 besøgte vores forældre 20 weekends, mor og far var hos os 5 weekends og Vagns forældre kun 2 gange. Sidstnævnte gjorde ofte en endagstur herned, for de havde jo gården at passe, og de gjorde altid ophold i Svenstrup og fik en kop kaffe hos Doris og Poul Erik. I 1978 var vi i Vendsyssel 21 weekends, så 1977 var ikke rekord."}, {"type": "para", "text": "I starten, når vi kørte nordpå, skulle vi igennem både Randers og Hobro, så turen kunne godt tage noget over 2 timer, men da motorvejen blev bygget og senere udbygget, undgik vi byerne og kunne gøre turen på ca. 1½ time."}, {"type": "para", "text": "En typisk weekend foregik på den måde, at vi kørte fra Spørring fredag sidst på eftermiddagen og kunne så være i Thorshøj ved 19-tiden. Mor havde altid stillet noget lækkert an, og når så far fik åbnet en flaske vin og stearinlysene blev tændt, spredte hyggen sig. Vi sad som regel i stuen ovenpå, især hvis vi skulle se TV, som vi jo ofte skulle fredag aften. Helt vidunderligt var det, hvis Per også var hjemme, og det var han naturligvis i starten af 70’erne, inden han begyndte at gå til fester og have kærester. Lørdag havde mor altid linet nogle projekter op. Det kunne være noget praktisk i huset, som Vagn skulle hjælpe far med, mens mor og jeg kørte ud og handlede. Vi kørte enten til Hjørring eller Frederikshavn og kom altid hjem med et stykke stof, så mor kunne komme i gang med at sy en bluse eller jakke til mig. Hun var fuld af gode idéer. Måske er det derfor, at jeg altid har haft svært ved at få idéer, for mor havde udtænkt, hvordan det skulle se ud, og det var der ingen grund til at lave om på. Det kunne også ske, at mor og far havde inviteret gæster til lørdag aften, når vi var hjemme, og det var vi bestemt ikke kede af, for mor og fars venner var ikke kedelige, og nogle af dem blev også vores venner og er det stadig. Mor var nu også flink til at tænke på mormor, når vi var hjemme, for vi ville jo også gerne se hende og hun os, så ofte kørte vi en tur på kirkegården lørdag eftermiddag og tog så mormor med hjem til aftensmad. Hun ville helst sove i sin egen seng, og blev derfor kørt hjem til den tid. Der var jo kun 10 km. Søndag skulle vi som regel være i ”Vestergård” til middag, og middag var kl. 12.00. Mor var somme tider lidt sur søndag morgen og ville gerne trække vores besøg lidt, så hun kom altid frem med noget, hun skulle vise os, eller noget tøj jeg skulle prøve, lige før vi skulle ud af døren. Det var især Vagn meget irriteret over. Vi prøvede virkelig at fordele sol og vind lige, men mor var ikke nem at stille tilfreds. Selvom vi var flere timer i Thorshøj end i Tårs, så syntes hun ofte, at hun blev forfordelt. Helt slemt var det i høsten, hvor Vagn jo skulle hjælpe til derhjemme og var nødt til at være der både lørdag og søndag. Mor led ikke i stilhed, hvorimod far altid var den samme og ikke sagde noget negativt. Jeg har forsøgt at analysere mors adfærd og er kommet til den konklusion, at det må have været, fordi hun elskede os så højt og bare ikke kunne klare det, når vi skulle afsted. Hun opførte sig jo på samme måde, da jeg skulle flytte hjemmefra. Da jeg altid gerne har villet have harmoni i familien, endte jeg altid som en lus imellem to negle, for jeg ville behage både min mor og min mand. Vagn var nærmest ligeglad med, om mor blev sur. ”Hun skal sgu nok blive god igen”, sagde han. Typisk for mænd at tænke og sige sådan. Men det var jo mig, der skulle snakke med mor i telefonen bagefter, og da var hun måske ikke nået at blive god igen. Mor sagde også tit: ”Ja, jeg bestemmer jo ikke over min svigersøn” – det havde hun trods alt fundet ud af."}, {"type": "para", "text": "Når vi så kom til ”Vestergård”, blev vi også modtaget med åbne arme. Det var rigtig hyggeligt, hvis Tage, Doris, Poul Erik og børnene også var hjemme, for så gik snakken lystigt ved middagsbordet. Især Doris var god til at snakke, og samtidig spiste hun meget, hvilket absolut ikke kunne ses på hende. Hun var åleslank og levede slet ikke op til det kælenavn, Poul Erik havde givet hende, nemlig ”Tykke”. Vagns far, Chr. Viggo, sagde tit: ”Det er in så galt mæ ålt det do spiser, Doris, for do ka tåål det. Det er møj wærre mæ dej tij det tår”. Han skulle jo være færdig og hen og sove til middag. Sommetider forlod han bordet, inden vi andre var færdige. Til hverdag lagde han sig bare på sofaen med avisen over hovedet, og 10 minutter senere vågnede han op og var frisk. Om søndagen fortrak han til soveværelset og var væk i længere tid. Vagns mor, Krista, kunne også godt finde på at sove til middag. Det var helt uvant for mig, at man gik hen og lagde sig for at sove til middag. Jeg var vant til, at mine forældre satte sig i en stol og lukkede øjnene. Middagsmaden var god og solid, og der var altid to retter, så jeg var mega-mæt ovenpå sådan et måltid. Også fordi man blev nødet til at tage mere, og sagde man nej, landede der ofte fra min svigerfar et stykke kød på tallerkenen alligevel. Mine svigerforældre var meget gæstfrie, og der var ikke nogen, der skulle gå sultne fra bordet! Men man skulle jo også have plads til eftermiddagskaffen kl. 15.00, som typisk bestod af boller og kringle eller lagkage, alt sammen hjemmebagt naturligvis, men det var jeg også vant til hjemmefra, for mor sværmede ikke for købekage og færdigretter. Når vi havde spist til aften og var i gang med opvasken, kom Krista altid med smørrebrødspapir, så jeg kunne smøre Vagns madpakke. Så var jeg fri for det næste morgen, og jeg havde jo heller ikke noget pålæg i køleskabet. Ofte fik vi rester med hjem fra middagen, så jeg kunne have det nemt næste dag. Inden vi kørte sydpå ved 22-tiden, skulle vi også lige have aftenskaffe med kage, så når vi sad i bilen på vej hjem, kunne vi knap nok vrikke med et øre."}]}, {"title": "Livet i Spørring i 70’erne", "blocks": [{"type": "para", "text": "Vi havde allerede en del venner i Spørring, da vi flyttede ind i 1972, og vi fik flere, som tiden gik. Mange af dem boede på Østervang, hvor der var et enormt godt sammenhold, ikke mindst når der skulle spilles gadekampe til de årlige byfester, som startede først i 70’erne og i starten varede en hel uge. De foregik i Spørring Gl. Skole og i skolegården. Det var en god måde at lære flere mennesker at kende på, så vi sad i starten nede i skolegården hver aften i hele byfestugen. Det var hyggeligt og sjovt. Højdepunkterne ved byfesten var revyen og gadekampene. Vi opførte et år ”Huset på Christianshavn”, og et år opførte nogle af mændene en ballet, iført trikot og tylsskørter. Jeg husker især Leo Pedersen (oliesheiken), som ikke var af de tyndeste, og Villy Morgenstjerne. De så ømme ud i deres små tylskostumer, og behøver jeg at nævne, at de tog publikum med storm? Under gadekampene var alt tilladt, og de var som regel store udstyrsstykker. Vi gik under navnet ”Østervang Lions” og havde T-shirts med dette påtrykt sammen med logo. Det så meget prof ud, men andre gange var vi alle klædt i pyjamas eller klædt ud som tykke mænd og koner."}, {"type": "para", "text": "Også ST70 var meget aktiv bag byfesterne, og som et eksempel på idérigdommen og virkelysten kan nævnes byfestbingo i 1976. Der skulle bruges mange annoncører, for der skulle være en annoncør for hvert bingotal mellem 1 og 90 inkl. Idéen var, at man på forhånd selv skulle lave sin spilleplade med 15 tal, og hver gang et tal blev råbt op, skulle annoncøren nævnes. For at have plads til alle deltagerne var man fordelt på hotellet og kroen. Udtrækningen foregik på hotellet, og via en til lejligheden installeret forbindelse fra Jysk Telefon, kunne man også på kroen høre numrene blive råbt op, ligesom man på hotellet kunne høre, når der blev råbt bingo på kroen – sådan."}, {"type": "para", "text": "En anden festlig tradition var Skt. Hans gadefesterne, som gik på tur hos dem, der havde mest plads, dvs på gårdene (hos Børge Bonne, Jørgen Johnsen, Mikael Andersen og Gert Sørensen). I 70’erne gik det lystigt til med dans i laderne og nogle gange på bordene. Vi havde selv mad og drikke med, dvs vi slog os som regel sammen med Alice og Reinholt samt Grete og Poul, men vi sørgede altid for, at Grete ikke skulle have sildene med, for hun og Poul kom altid for sent, og når vi havde sildene, kunne vi jo bare gå i gang. I 1977 var vi hos Gert Sørensen til Skt. Hans, og da Grete og jeg var i lykkelige omstændigheder, drak vi ikke for meget. Vejret var fint, og vi dansede udenfor. Poul og Vagn var især omsværmede af en ”dejlig” fager dame, der hed Ruth og som boede sammen med Erik Hald i et gammelt bindingsværkshus. Hun bød dem ustandseligt op til dans og trykkede sig helt tæt ind til dem, så de rigtig kunne ”dufte” hendes odeur, som just ikke var Chanel no.5, nærmere en ram gang armsved. For at redde de to ungersvende, spurgte vi hende, om hun ikke ville gå hjem og lave noget kaffe. Det ville hun gerne, og hun inviterede Grete og mig med. Vi brød os egentlig ikke om hende, men vi var nysgerrige efter at se, hvordan de boede. Du altforbarmende, hvor var der rodet, og der var katte overalt, som sprang rundt oppe på køkkenbordet blandt beskidt porcelæn og madrester. I stuen var der hverken til at komme frem eller tilbage, men vi fik dog vores store maver kantet ind og sat os ned. Vi sagde nej tak til at drikke noget, for det hele var så uhumsk. På et tidspunkt skulle jeg på toilettet, men det viste sig, at døren var væk, så jeg måtte sidde for åbent tæppe og tisse. Det var lidt af en oplevelse."}, {"type": "para", "text": "Samlingsstedet i Spørring var hotellet, som dannede rammen omkring den årlige dilettant, generalforsamlingerne, høstfesterne og begravelseskaffen. Vi var et år med i høstfestkomitéen, men det var nu ikke vores skyld, at vi fik kyllinger, hvor blodet fossede ud på tallerkenen. Det var, før vi kendte til salmonellaforgiftninger, så mange af gæsterne spiste de blodige kræ, for noget skulle de jo have. Den var ikke gået i dag."}, {"type": "para", "text": "Spørring Dilettantforening blev stiftet i 1928 af kulturinteresserede borgere i Spørring, og foreningens aktiviteter bestod af foredrag samt amatørskuespil af lokale og for lokale folk i Spørring. Der blev spillet teater hvert år frem til 1985. Fra ca. 1972 blev der også spillet sommerrevyer i forbindelse med byfesterne. Der var altid bal efter dilettantforestillingerne."}, {"type": "para", "text": "Sammenskudsgilderne fortsatte lystigt op gennem 70’erne, selv spontane søndagsfrokoster kunne ende med, at der blev hentet mere snaps, og at vi dansede i stuerne. Det var oftest sammen med Alice og Reinholt eller Ruth og Villy, men også Kirsten og Erik var med til disse gilder, hvor Kirsten var den første til at danse på bordene, næsten uden at have nydt spiritus. Hun var bare et livstykke dengang. I foråret 1974 fik vi nye genboer, Grete og Poul. Poul var født og opvokset i Spørring, og hans forældre Ragnhild og Mikael boede på en gård på Østervang. Vi kom i snak til en fest på hotellet, hvor de fortalte os, at vi skulle være genboer, og da vi syntes, de var vældig flinke, inviterede vi dem til middag en aften. De kom en halv time for sent, men så gik de til gengæld heller ikke hjem før kl. 3. Det var en utrolig hyggelig aften, og det blev starten på et langt og godt venskab med dem. Men Poul lærer aldrig at komme til tiden, og hvor har vi ventet på dem mange gange."}, {"type": "figure", "caption": "", "page": 9, "file": "assets/images-bog2/p009_01.jpg", "dim": [691, 466]}, {"type": "figure", "caption": "", "page": 9, "file": "assets/images-bog2/p009_02.jpg", "dim": [745, 514]}, {"type": "para", "text": "Til sammenskudsgilde hos Ruth og Villy i 1975. Fra venstre Ruth, Reinholt, Merete, Grete, Vagn og Bodil."}, {"type": "para", "text": "Det var også i 70’erne, at vi begyndte at brygge vin. Vi købte ingredienserne hos materialisten, og efter 3 uger stod den herligste hvidvin eller rødvin klar til at blive drukket. Vi havde konstant en ballon med vin stående i bryggersskabet, og Eva og Leo havde også en hos dem, og så mødtes vi, når der skulle smages på herlighederne. Kirsten og Erik maler var også med til vinsmagning, og engang var vi ca. 10 mennesker i vores lille bryggers til denne tradition. En af dem var Evas kusine, som havde fine fornemmelser og gerne ville vise, at hun havde forstand på vin, og for at pointere, at det billige sprøjt, vi fremstillede, var af dårlig kvalitet, sagde hun: ”Den hænger på glasset”. Den bemærkning brugte vi altid senere, når vi drak vin sammen med malerens, og så sagde vi det på en tilpas affekteret måde. Jeg husker ikke, hvor længe vinbrygningen stod på, og om det var følgende pinlige episode, der satte en stopper for det. Det må have været i foråret 75, for genboerne havde boet kort tid i huset, og jeg læste til skriftlig engelskeksamen. Vagn havde gået og hjulpet Poul med noget, så Grete ville give middagsmad. Jeg takkede nej, for jeg havde travlt med eksamenslæsningen og ville ikke forstyrres. Vagn fik mig dog overtalt til at gå med over og spise. Jeg kunne jo bare gå hjem, når det var overstået. Svogeren Hans fra Hornslet var der også (gift med Pouls søster Birgit), og det var første gang, jeg mødte Hans. Vagn kendte ham fra Hvidsted, hvor han havde tjent hos Martin Andersen, så verden er lille."}, {"type": "para", "text": "Vi syntes da lige, at vi ville tage en karaffel af den dejlige hjemmebryggede vin med, så de kunne smage den liflige drik. Det kan vel være, at den ikke var helt færdiggæret, men pyt – den smagte som saftevand. Det ene glas tog det andet, og Vagn hentede flere karafler. Til sidst blev han træt af at rende frem og tilbage, så han kom bærende på hele ballonen! Hvis nogen har set det, har de fået sig et billigt grin, for en time senere kom han bærende på mig den modsatte vej. Vejret var fantastisk, så Grete havde foreslået, at vi skulle lægge os ud på en drømmeseng i haven. Vi kunne jo tage vinen med. Jeg lånte en af hendes mange bikinier, og derude i solen blev jeg så fuld, at jeg ikke husker noget som helst, før jeg stod under bruseren om aftenen kl. 19. Da var Vagn ved at forsøge at få liv i mig, for vi skulle i teatret sammen med Alice og Reinholt og se ”Can-Can”. Vi havde flere sæsoner et abonnement til Århus Teater sammen med dem. Pludselig blev der banket på bryggersdøren, og udenfor stod Alice for at hente os. Godt nok var jeg fuld, men jeg sansede at sige, at det først var kl. 20, at forestillingen begyndte, og ikke 19.30, som de troede. Jeg mente derfor godt, at jeg kunne blive klar til at komme med. Det mente Vagn nu ikke, så han beklagede. Heldigvis nåede de at få Ruth og Villy med på afbud, for det viste sig først at være kl. 20. Næste dag sad jeg en halv time og gloede på telefonen, inden jeg tog mod til mig og fik ringet til Alice for at give dem en undskyldning. Heldigvis var der ingen sure miner, og stykket havde været godt. Vi fik lejlighed til at se det på et andet tidspunkt, men vores 3-ugers vin blev herefter aldrig kaldt andet end ”Can-Can-Vinen”."}, {"type": "para", "text": "Hvis Vagn og jeg en enkelt gang skulle ud og spise, kunne vi finde på at tage ind på det, der dengang hed ”Flaskehalsen” og senere ”Den Grimme Ælling”. Her fik man rigtig god mad til rimelige priser og i hyggelige omgivelser."}, {"type": "para", "text": "Vi fik telefon den 16. august 1973. Før den tid måtte vi ned i telefonboksen foran den gamle skole, hvis vi skulle ringe. Grunden til, at vi fik telefon på det tidspunkt var, at farmor var død i juli, og vi kunne overtage hendes telefonabonnement for halv pris. Sådan var reglerne dengang. Så i stedet for at betale 1200 kr. for at få telefon lagt ind, skulle vi kun betale 600 kr. Det var vild luksus."}, {"type": "para", "text": "Borgerforeningens betydning for udviklingen i Spørring blev efter sammenlægningen med Århus Kommune i 1970 langt større end tidligere. Folk herude (673 sjæle) var ellers ganske tilfredse med tingenes tilstand. Byen havde alt, syntes de: Mange større og mindre butikker, et godt foreningsmiljø og ikke mindst et godt sammenhold beboerne imellem, det sidste godt hjulpet af de store arrangementer som byfester, høstfest, juletræ og dilettant m.v. Men lige som det gik så godt, begyndte den ene lille butik efter den anden at forsvinde: Det lille ”posthus”, håndkøbsudsalget og slagterbutikken var blandt nogle af de første. Tidligere handlede alle jo lokalt, og folk var meget loyale over for det lokale forretningsliv. Nu blev det pludselig spændende at handle i de store supermarkeder, og de mange nye tilflyttere, som arbejdede uden for Spørring, havde jo let ved at dreje om ad disse og gøre deres indkøb. Borgerforeningens bestyrelse blev hurtigt enige om, at skulle vi bevare et rimeligt serviceniveau, skulle befolkningsunderlaget øges væsentligt til omkring 1000-1200, dvs. der skulle skaffes mulighed for en udstykning på ca. 150-200 parcelhusgrunde. Det var derfor et stort chok for alle, da vi blev klar over, at Århus Kommune slet ingen planer havde for Spørring og heller ikke umiddelbart havde tænkt sig at gøre noget."}, {"type": "para", "text": "Spørring Juniorklub blev etableret i 1978 og fik lokaler i Spørring Gl. Skole. Juniorklubben fungerede i mange år som både børnepasningsordning og som skolefritidsordning. Den blev i perioden 1971 til 2004 ledet af Peter Jes Petersen."}]}, {"title": "Fritidsinteresser", "blocks": [{"type": "para", "text": "Dans Den 3. september 1973 begyndte vi at gå til ægtepar-dans hos Søren Jensen i Risskov. Vi gik hver søndag aften i 3 år, hvorefter vi stoppede af naturlige årsager (jeg blev gravid). Det var en dejlig tid, hvor vi lærte grundtrin og flere variationer i alt fra vals og quickstep til jive og cha-cha-cha. Vi stillede endda op til opvisning ved afdansningsballet i Vejlby-Risskov Hallen for en hel hal af tilskuere – det var vildt."}, {"type": "para", "text": "Svømning Da jeg var barn, lærte børn ikke at svømme, og derfor havde jeg aldrig haft lyst til de store udskejelser i hav eller svømmepøl. I 1973 bød der sig en lejlighed til at få det lært, for en skolelærer på vejen, Ole Skot-Hansen, var svømmelærer på Hornslet Skole, og der kunne man gå en gang om ugen. Vi meldte os begge til og fik med Oles hjælp lært at svømme den første vinter. Jeg overvandt også mig selv og kom på dybt vand, hvor jeg ikke kunne bunde, men det var altid en trøst, at hvis jeg sank til bunds, ville Ole straks være der og redde mig. Helt fortrolig med det våde element bliver jeg aldrig, og jeg skal helst ikke have hovedet under vand, så det er ikke så sært, at Lars siger, at jeg ligner en hund, når jeg svømmer. Vi blev gennem svømningen venner med Ole og hans kone Kirsten, som også var lærer. De var begge meget specielle men flinke, og vi besøgte ofte hinanden efter svømning, hvor også Hanne og Keld Henriksen, som boede over for Kirsten og Ole, var med. Kirsten og Ole havde på det tidspunkt to piger, Charlotte fra 1970 og Karoline, som var yngre. I 1978 fik de sønnen Sune. Når man så Ole i badebukser, mindede hans skikkelse om en dames, og han var meget feminin i sin tale og sine bevægelser. De var begge meget sparsommelige, grænsende til det nærige, men jeg tror ikke, at børnene led nogen nød. Jeg ved ikke, hvornår det begyndte at knage i ægteskabet, men en aften, vi var inviteret derover, gik Kirsten i seng uden videre forklaring, så der har nok været en kurre på tråden. Det gik virkelig op for os i sommeren 1988, at ægteskabet vaklede, for da kom Ole på besøg en dag og fiskede for at få at vide, hvor vi skulle hen på ferie. Vi havde planer om at campere i Hanstholm, og det var vi naive nok til at fortælle ham. Da vi havde ligget i Hanstholm nogle få dage, hvem stod da uden for døren? Det gjorde Ole og Sune – med et lille telt og en lille bylt tøj. Sune havde kun det tøj, han stod og gik i, samt en alt for stor træningstrøje, som han havde fået af en familie, de havde mødt, der havde haft ondt af drengen. Ole havde sin slimlinede træningsdragt anno 1960 på. Sandheden var, at Ole havde ”bortført” Sune uden at fortælle Kirsten, hvor han tog hen med ham. Det fik vi at vide bagefter. Høflige som vi var, bød vi dem indenfor til et måltid mad, men når man rækker fanden en lillefinger, ta’r han hele armen. De slog deres telt op ved siden af os, og så var vi ellers sammen det meste af tiden. Til sidst havde vi fået nok, så vi opfandt en nødløgn og sagde, at vi skulle videre. Det skulle vi sådan set også, men det havde ikke været planen. Vi kunne bare ikke klare dem mere. I tiden derefter løb Kirsten og Ole os på dørene i Spørring hver for sig, og vi hørte sagen fra begge sider. En dag kom Kirsten og bønfaldt os, om vi ikke kunne tage Sune i pleje i en periode. Vi havde ondt af drengen og indvilgede, hvorefter vi næste dag i telefonen fik et møgfald af Ole. Vi orkede til sidst ikke at høre mere på deres historier, så vi holdt lav profil, og da Kirsten flyttede og tog Sune med, kappede vi forbindelsen. Det resulterede i, at hun blev skide-sur på os en dag, hvor hun ringede og ville have Lars til at komme ud og lege med Sune. Jeg sagde pænt nej, for jeg vidste, at Lars helst ville være fri. Siden har der været stramme miner, når vi har mødt hende. Ole blev ved med at komme over og ringe på om aftenen, når der igen havde været skænderier mellem dem på grund af bodeling og børnedeling, og vi skulle lægge ører til meget. Det må have været fedt at være advokat i den skilsmissesag, for de kunne ikke engang blive enige om, hvem der skulle have fjederen til fjerkræssaksen. Og det er ikke engang løgn. På et tidspunkt skulle låsene også skiftes, fordi Kirsten havde låst sig ind og havde fjernet noget inventar, der ikke var hendes. Det er den værste skilsmissesag, vi nogensinde har hørt om. Det værste var dog, at de også blev uvenner med deres børn, så i dag ser Ole ikke sine døtre, og Kirsten ser ikke sin søn. I dag går vi næsten i en bue uden om Ole, når vi ser ham, og mon ikke han også nu har fattet, at vi ikke gider snakke med ham. Sørgeligt at det skulle ende sådan."}, {"type": "para", "text": "Badminton Mon ikke det i skrivende stund (2008) er 35 år siden, jeg begyndte at spille badminton med Alice. Det foregik og foregår stadig i Den gamle Skoles gymnastiksal i Spørring. Vagn startede også på den tid og spillede i flere år sammen med Alices mand Reinholt og genboen Poul, og det skete også, at vi spillede mix double sammen med Alice og Reinholt. Det var vældig hyggeligt og gav god motion. Alice og jeg spillede også i mange år sammen med Pouls søster Grethe Poulsen, og i en periode sammen med Hanne Henriksen, som boede i nr. 15. Når vi var tre, sad den ene altid over et sæt, og var den ene forhindret, kunne vi altid spille to. Sidst i 70’erne blev Alice og jeg overtalt til at spille turnering, og træningen blev da henlagt til Trigehallen. Vi spillede både single, double og mix double, men sidstnævnte var med nogle lidt yngre fyre, som var noget bedre end os, bl.a Lars Bjerregård. Lars var sød og rar, og han lærte os a serve rigtigt, men hans makker var temmelig temperamentsfuld og ikke sjov at have som makker i en mix double til en turnering. Hvis man ikke lige nåede bolden, kunne han råbe helt vildt efter én, så man var et helt nervevrag op til en sådan kamp. Jeg ved ikke, om det var derfor, vi stoppede med turneringsspillet, men vores turneringskarriere var i hvert fald ikke lang. Den bedste oplevelse inden for turneringsspillet, jeg husker, var en kamp i Spørring, hvor jeg spillede single, og gymnastiksalen var fyldt med tilskuere, også oppe på balkonen. Jeg vandt kampen og høstede mange klapsalver og tilråb, men de kampe, jeg tabte, har jeg heldigvis glemt."}, {"type": "para", "text": "Håndarbejde Jeg har lige købt mig en ny symaskine, en Singer til 799 kr. i Føtex, nedsat med 900 kr. Den gamle Major, som jeg fik i fødselsdagsgave i starten af 70’erne, kunne ikke mere. Den havde kostet 1400 kr. Jeg kom jo fra et hjem med symaskine, og mor syede rigtig meget og var dygtig til det, men hun havde aldrig lært mig det. Da jeg så fik min egen symaskine, havde jeg lyst til at lære det. Sammen med Alice meldte jeg mig på et sy-kursus, og vi gik i to sæsoner, inden vi indså, at det nok ikke lige var os. Jeg syede et par brune kassebukser, som var moderne dengang, men fik dem aldrig på. Lidt må jeg alligevel have lært, for jeg syede senere et par nederdele og veste herhjemme, og jeg husker også, at jeg var vældig bidt af det, lige når det stod på. Senere mistede jeg helt interessen. I dag bruger jeg maskinen til reparationer og oplægning af bukser. Jeg har også sat lapper på mange af Vagns arbejdsbukser, men det var først efter, at hans mor besluttede sig for, at det ikke længere var hendes opgave. Hun fik ellers æren i mange år, fordi hun var så eminent god til det. Hun skiftede simpelthen hele knæet ud i stedet for at sætte en lap på, og så flot kunne jeg ikke gøre det, så hun skulle naturligvis have lov til det så længe, hun havde lyst."}, {"type": "para", "text": "Som barn lærte jeg at strikke, og sådan noget glemmer man jo aldrig, når først man har fået det lært. I 70’erne strikkede jeg meget og kunne være helt bidt af det. Jeg strikkede foran TV, når jeg var i byen og i bilen. En trøje kunne jeg trævle op mange gange, inden jeg fandt ud af, hvor stor den skulle være, og så var det ikke sikkert, den passede alligevel, når jeg var færdig med den. Jeg skulle helst gå lige efter opskriften, ellers gik det helt galt, og ofte var en trøje så længe undervejs, at den var umoderne, når den var færdig, eller at jeg var træt af at se på den i så lang tid. I dag er strikketøjet lagt på hylden, og det har det været siden 1991, hvor jeg strikkede min sidste trøje i bilen på en ferie i Skotland. Hækling blev jeg aldrig ferm til, men i 1973 hæklede jeg dog en hue til mor. Ud over det blev det kun til hækling af kanter."}, {"type": "para", "text": "Scrapbøger En af mine store passioner er at lave scrapbøger, og jeg har det ikke godt, hvis der ligger billeder, der ikke er sat i albums. Derfor har jeg også i dag en hel reolvæg fyldt med albums og scrapbøger. Indtil for få år siden gemte jeg alle brochurer, billetter, postkort og andre souvenirs, der kunne klistres i disse bøger og fortælle en historie om en dejlig ferie. Jeg skrev masser af tekst til billederne, så man til enhver tid kunne tage et album frem og genopleve ferien. Jeg har nu, også efter digitalbilledernes indtog, indset, at jeg ikke har plads til ret mange flere albums og scrapbøger, så nu gemmer jeg hovedsageligt billeder på PC eller ekstern harddisk."}, {"type": "para", "text": "Den tradition, min mor indførte med at udvælge årets billede og skrive bagpå, har jeg ført videre, så hvert år, indtil Lars fyldte 18 år, har jeg fået årets billede forstørret og skrevet bagpå."}]}, {"title": "Hus og have i 70’erne", "blocks": [{"type": "para", "text": "Da vi byggede i 1972, måtte huset ikke koste for meget, så der blev sparet på mange ting. Senere gik vi så ind og lavede forbedringer, fx blev der slået trælofter op i gæsteværelset, køkkenet og børneværelset i 1979, og væggen fra soveværelset ind til badeværelset blev beklædt med træ samme år. I november samme år fik vi pejs i stuen med to glaslåger, så nu skulle der rigtig råhygges. Vi købte nyt skrivebord til kontoret samt to brune læder Siesta stole og to lyse egetræsvitrineskabe til stuen hos Rosborg Møbler, der ligger lige uden for Spørring på vej til Randers. Rosborg var og er en forretning, der kun handler med kvalitets- og designmøbler, så det er og var møbler i den dyre ende."}, {"type": "para", "text": "I starten, vi boede i huset, skulle vi prøve at have urtehave, og vi dyrkede da også alt lige fra radiser til blomkål og majs. Vi dyrkede rødbeder, græskar og asier, som jeg syltede hvert år, så jeg levede helt op til husmoderrollen. Kød, kyllinger og æg fik vi hos Vagns forældre i ”Vestergård”, og ud af grisen lavede jeg bl.a. rullepølse og leverpostej. Kyllingerne, som var kæmpestore, blev grillet i ovnen, hvor de selv roterede rundt på et spyd. Der kunne til nød være to ad gangen, hvis de blev klemt helt sammen. Jeg var dengang også flittig til at bage, og havde nogle gange den store bagedag, hvor jeg bagte 9 slags kage til fryseren. Jeg førte kartotek over fryseren, så jeg vidste lige præcis, hvad jeg havde deri. Den idé havde jeg fået af min veninde Inga, da hun var gift med Poul. En af min fars favoritkager var kiksekage, så den lavede jeg nogle gange, når mor og far skulle komme. Mange år senere var der nogle mennesker, der døde af salmonellaforgiftning fra æg i kiksekage, så efter den tid lavede jeg den aldrig mere. Min svigermor lavede også nogle gange kiksekage, men åbenbart efter en anden opskrift, for den var lysere i chokoladen, og kiksene var bløde, så den fik hun ikke mange kokkehuer for. Men det var da også en af de få retter, hvor jeg var bedre end hende. Et år fik vi et vaffeljern af mine svigerforældre i julegave, og så kan det nok være, at den stod på vafler i tiden derefter. Vi bagte vafler i køkkenet, i stuen og på terrassen, for det var praktisk at have det lige ved hånden der, hvor vi skulle sidde og spise dem, for man skulle være over dem hele tiden, og så var man fri for at rende."}, {"type": "para", "text": "Hvad var et 70’er køkken uden Tupperware. Første gang, jeg stiftede bekendtskab med dette produkt var, mens jeg boede hjemme. Da havde mor sit første party. I 70’erne gik vi også til Tupperware parties i Spørring, det første i 1973 hos Alice, og det gør vi minsandten stadigvæk."}, {"type": "para", "text": "Når vi rigtigt skulle hygge os med venner, og de ikke var inviteret til middag, stod menuen ofte på forårsruller eller bøfsandwich, og vi spiste dåsevis af muslinger, dyppet i rasp og stegt på panden sammen med champignons. En gang blev Vagn og jeg så syge af denne ”delikatesse”, at vi ikke spiste den i flere år derefter. Vi havde spist for meget, og det var derfor blevet vammelt."}, {"type": "para", "text": "Først den 27. juli 1974, ca. et år efter at vi var flyttet ind, holdt vi indflytterfest eller færdiggilde, som de kaldte det på disse kanter. Vi var ca. 25 mennesker, både naboer og familie, og det jeg husker bedst var det kort, der fulgte med gaven fra naboerne, og det var første gang, vi oplevede Reinholts kreativitet, men absolut ikke sidste gang. Kortet var i stift karton og forestillede vores hus, ja det var nærmest en tro kopi, udformet på en meget kunstnerisk måde. Gaven husker jeg ikke."}]}, {"title": "Vennerne i 70’erne", "blocks": [{"type": "para", "text": "Vi kom meget sammen med Alice og Reinholt i nr. 28, Erik og Kirsten (malerens) i nr. 21, Eva og Leo (oliesheiken) i nr. 19 og senere Grete og Poul i nr. 26. Vi rendte ofte sammen hverdagsaftner til en kop kaffe eller en bøfsandwich/forårsruller/muslinger, hvis vi rigtig skulle hygge os."}, {"type": "para", "text": "Pouls forældre, Ragnhild og Mikael Andersen, var rigtig flinke mennesker, og de boede på en gård på Østervang, nr. 36. Vi besøgte somme tider hinanden, og jeg kunne finde på at gå op til Ragnhild og drikke en kop te eller gå op og ønske dem glædelig jul et par dage før jul, hvor jeg havde fået juleferie. Vi var meget beærede, da vi i oktober 1978 blev inviteret til Mikaels 70 års fødselsdag med middag, dans og det hele. Det var en søndag. Om tirsdagen var vi til mor og fars sølvbryllup og om lørdagen til bryllup med Lis og Jens Ole, så det var tre fester på én uge, hvoraf de to blev holdt samme sted, nemlig i Thorshøj Selskabslokaler."}, {"type": "para", "text": "Vagn arbejdede en periode sammen med Vagn Poulsen, som var gift med Pouls søster Grethe, og de boede i Spørring. På det tidspunkt kom vi meget sammen med Grethe og Vagn, som vi havde lært at kende gennem Grete og Poul en gang, de skulle være barnepige på deres børn. Vi blev inviteret med som barnepiger, så vi var fire, der passede på Tina og Jesper. Det var et meget gæstfrit hjem at komme i, og der kunne hurtigt komme noget mad på bordet, også en hverdagsaften efter arbejde, hvor der spontant blev ringet efter mig, fordi de havde budt Vagn på kaffe efter arbejdstid. Vi var også til en del fester hos dem sammen med Grete og Poul Andersen og Else og Calle Haag, som var vores tidligere genboer. Vi havde årlige ålegilder, og i februar 1977 foregik det hos Grethe og Vagn. Vi fik alle de stegte ål, vi kunne proppe i os sammen med stuvede kartofler, skyllet ned med øl og snaps, og den fik ikke for lidt. Det var en giftig cocktail, som resulterede i, at alle, undtagen Grete og mig, som var i lykkelige omstændigheder (det var vist kun os selv, der vidste det), var hønefulde allerede kl. 22. Næste dag var Vagn meget syg, nok en af de få gange, hvor han ikke har kunnet tåle mosten."}, {"type": "para", "text": "I nogle år havde vi en tradition med at tage på pinseture allesammen i et sommerhus nordpå, men vi trak os ud af traditionen samtidig med, at de to Vagn’er stoppede deres samarbejde, men Grete og Poul har stadig pinsetraditionen sammen med Else og Calle."}, {"type": "para", "text": "Endelig var der jo alle vendelboerne, som vi stadig havde et nært forhold til. Der var Vagns fætter Svend og hans kone Alice, som vi tit besøgte og også holdt nytårsaftner sammen med. Vi var med til deres bryllup i 1970. Alice havde tidligere været gift og havde to børn fra første ægteskab, Anne Mette og Per. I 70’erne fik Alice og Svend døtrene Lene og Susanne. Alle tre døtre har vi været til bryllup med. Poul Andersen fra Vendsyssel var blevet skilt fra Inga i 1973 og havde fundet sig en ny kæreste, Anne Marie. Den 12. april 1979 var vi til bryllup med dem i Tårs. Da havde de fået Gitte, som var knap 2 år og brudepige. Jeg kan endnu se den lille yndige pige i den hvide kjole ligesom sin mors brudekjole."}, {"type": "figure", "caption": "", "page": 14, "file": "assets/images-bog2/p014_01.jpg", "dim": [954, 686]}, {"type": "para", "text": "Søren Larsen var en af Vagns ungdomskammerater, og han købte i 70’erne en ejendom, ”Nedergård” i Hvidsted. Hans to søskende, Birthe og Jan og deres ægtefæller kom vi også sammen med. Vi blev altid inviteret med, hvis de holdt fest eller komsammen deroppe, og vi kunne jo bare bo hos Vagns forældre, så der var ingen problemer med overnatning. Værre var det den anden vej. Hvis vi skulle invitere dem, kunne vi blive 12 til at overnatte, så det var lidt voldsomt. Vi gjorde det ganske vist nogle gange, hvor de alle kom en hel weekend, og så blev der festet igennem. En overgang havde vi også Pouls fætter Kaj og dennes kone Karen med. Engang de besøgte os, besluttede vi, at vi ville på ”Bambi” i Hinnerup. Det må have været i december, for der var fyldt med selskaber, der var til julefrokost. Vi kom ind og følte os lidt udenfor på grund af de lukkede selskaber, så mændene besluttede, at de ville lave lidt rav i den. Hver gang, de havde tømt et glas i baren, puttede de det i lommen. Et askebæger røg samme vej, og på vej ud til vores to biler snuppede Søren en stor sammenplantning. Det var for pinligt, syntes Birthe og jeg, som var chauffører, så vi skyndte os at starte bilerne, men inden vi kunne slippe derfra, kom der en servitrice løbende ud for at høre, om vi havde taget nogle glas. Hun snakkede ikke om sammenplantningen, som stod i bagagerummet. Selvom der lød en klirren af askebægre og glas i bunden af bilen, fik mændene hende snakket til ro, og hun endte med at sige, at de skulle være velkomne en anden gang. Det kunne ikke gå for stærkt med at komme derfra, og en af mændene havde stadig et ben hængende ud af døren, da Birthe gassede op og drejede ud på vejen. Da vi kom hjem, ville Søren forære mig sammenplantningen, men jeg sagde nej, for det er værre at være hæler end stjæler. Ligeså galt gik det engang, vi var på en af vores mange weekendture, hvor Grete og Poul også var med. Det kan have været i foråret 1977, i starten af vores graviditeter. Grete og jeg havde lige fået at vide, at vi var gravide, og vi kunne slet ikke vente med at fortælle det til Gud og hver mand. Og for at det skulle kunne ses på os, var vi begyndt at bruge omstændighedstøj. Hvad der ikke kom frem var, at der var to andre piger i selskabet, der også var gravide, nemlig Anne Marie, som fødte Gitte den 9. oktober 1977 og Sørens kæreste Birthe, som fødte Peter i september samme år. De var mere beskedne end os. Der kunne ske ting og sager, når Jan og Kaj var med, og det gjorde der da også på denne tur. Vi var på Sallingsund Færgekro, og under festen lørdag aften blev der pludselig bælgravende mørkt. Forinden havde Jan været rundt og blæse alle stearinlysene ud med det formål, at der skulle blive mørkt, når Kaj gik ud og slog strømmen fra i målerskabet. Ved samme lejlighed havde Kaj været ude i køkkenet og tilegne sig diverse låg og grydeskeer, som han var en mester i at spille på i festligt lag. Efter den officielle fest var slut, og vi alle sad på ét værelse for at fortsætte den mere uformelle del af festen, begyndte det at regne med kransekage. Det var Jan, der havde fundet vej til kroens fryser i kælderen, hvor han havde fyldt lommerne med kransekage. Vi spiste det med god appetit, men næste dag, da vi skulle betale, var vi lidt flove, for de var godt klar over, hvem der havde været på spil, og hvem der havde larmet til langt ud på natten. De sagde heller ikke til os, at vi var velkomne en anden gang. Engang, hvor vi skulle betale et weekendophold, lavede hotellet en fejl og gav os alle checks tilbage, så det endte med, at vi ikke havde betalt noget. Søren, som stod for betalingen, sagde ingenting men lod dem stege lidt et par dage. Så ringede han og spurgte dem, om de ikke havde fejl i regnskabet. De fik selvfølgelig deres penge, men vi fik ikke så meget som en tak, ej heller et tilbud om at komme forbi til en kop kaffe. Havde Søren ikke henvendt sig, havde de aldrig fået pengene."}, {"type": "para", "text": "Den 23. februar 1979 var vi inviteret til fest hos Birthe og Søren på ”Nedergård”. Lars var knap 1½ år og blev passet af farmor og bedstefar. På et tidspunkt ville jeg gerne hjem, og jeg spurgte Vagn, om han ville med. Svaret var nej – jeg kunne selv køre. Det gjorde jeg så, og der skal lige tilføjes, at jeg var pinlig ædru. Da jeg kom ud i bilen, konstaterede jeg, at der var meget tåget og hundekoldt, og jeg havde tynde sko og kun en habitjakke over min kjole. Jeg var så sur over, at Vagn ikke ville med hjem, at jeg ikke gav mig tid til at skrabe vinduerne fri for is, så jeg startede og kørte derfra. Jeg kendte vejen udmærket, og der var kun et par kilometer hjem. Pludselig kunne jeg ikke orientere mig, og jeg vidste ikke, hvor jeg var. Jeg kunne fornemme, at jeg var kørt ud i noget blødt, og pludselig sad bilen fast. Jeg stod ud i den iskolde nat og kunne konstatere, at alt var sort omkring mig. Hvilken vej skulle jeg gå i mine tynde sko og uden overtøj? Heldigvis valgte jeg den rigtige vej, for ellers tror jeg ikke, jeg havde siddet her i dag. En eller anden holdt hånden over mig, som det er sket før. I starten kunne jeg slet ikke orientere mig, og panikken bredte sig, så jeg tænkte slet ikke på, hvor koldt der var. Jeg gik og gik, og pludselig så jeg et lys. Det var en gård. Jeg gik hen og kiggede ind ad vinduet, som var til kostalden, men der var ingen liv, bortset fra køerne. Jeg gik tilbage til vejen og fortsatte lidt længere, indtil jeg pludselig så et skilt, hvorpå der stod Hvidstedvej. Så var jeg klar over, hvor jeg var. Jeg vendte om og gik tilbage forbi Martin Andersens gård, for det var der, jeg havde set lys, og snart var jeg ved ”Vestergård” og kunne drage et lettelsens suk. Det første, jeg gjorde, var at ringe til ”Nedergård” for at fortælle Vagn, hvad jeg havde været udsat for. Hans eneste kommentar var: ”Hvor fanden er bilen?” Se, det kunne jeg ikke svare på. Jeg gik i seng og lå længe og bævrede for at få varmen. Næste dag gik de på jagt efter bilen. De fandt den på Anders’ mark, så i stedet for at svinge skarpt til højre ad Hvidstedvej, var jeg kommet til at svinge for lidt og var endt ude på marken. De syntes alle, at det var vældig morsomt det, jeg havde lavet, og de troede alle, at jeg havde været beruset. Jeg var nok lidt flov, men jeg har aldrig været god til at orientere mig, og på grund af de tilisede ruder, var jeg kørt forkert."}, {"type": "para", "text": "Vibeke og Elbo Knudsen var egentlig mor og fars venner. Elbo havde overtaget sin fars tømrerforretning i Thorshøj, og hvordan mor og far begyndte at komme sammen med dem, husker jeg ikke. I perioder var de rigtig meget sammen, men på et tidspunkt, mens jeg boede hjemme, kom der en kurre på tråden, og de sås ikke et stykke tid. Det var selvfølgelig damerne, der var problemer med, og det var da også dem, der redede trådene ud igen, og så var alt glemt. Vibeke og Elbo var i sin tid blevet gift med kongebrev på grund af deres unge alder, og de havde tre børn, Morten, Lars og Anette. Lars var på alder med min bror Per, og de to havde megen fornøjelse af hinanden. Vibeke arbejdede på Sæby Kommunekontor og havde rengøringskone. Det syntes mor nok var lidt luksus, men Vibeke ordnede også Elbos regnskab, så hun havde nok at se til. Det var altid hyggeligt at besøge dem, og derfor blev de da også vores venner. I 70’erne kørte vi mange ture sammen, hele familien Knudsen og os, i alt 10 personer. Det kunne være søndagsture med madkurv eller Tysklandsture, hvor vi boede i et lejet hus på den danske side af grænsen og så kørte i pendulfart over grænsen for at købe lagre af vin, sprut, cigaretter, sukker og slik. Vi havde det virkelig sjovt sammen. Vi mødtes også i Norge nogle gange, hvor Knudsens var på campingtur og vi boede i hytte, og mor, far, Vibeke og Elbo har været på ferier sammen i Norge og boet i Bjørnstads sommerhus (mors penneveninde Agathes fars hus)."}, {"type": "para", "text": "Jeg genoptog forbindelsen med min bedste skoleveninde, Lisbet, og besøgte hende i Hobro efter at hun havde fået Nina i foråret 1977. Hendes mor Aase blev syg af brystkræft og døde den 8. april 1978, kun 49 år gammel. Hendes mor var også død af brystkræft omkring 50-års alderen, og for at det ikke skal være løgn fik Lisbet brystkræft omkring 60-års alderen. Hun er heldigvis blevet helbredt og har det godt i dag."}, {"type": "figure", "caption": "", "page": 16, "file": "assets/images-bog2/p016_01.jpg", "dim": [991, 673]}, {"type": "para", "text": "Petra og Christian Thomsen boede i en lille ejendom på Ask Mark ved Solbjerg, og Chr. Viggo havde tjent hos Christians far. Vagn havde været på ferie der om sommeren, så det var kun naturligt, at vi, når vi nu boede i Århus-området, skulle besøge dem."}, {"type": "para", "text": "Vi skulle altid komme tidligt til en kop kaffe, så vi var der som regel kl."}, {"type": "para", "text": "19.00. Vi blev dog altid mødt af følgende salut fra Christian: ”Kommer I først nu?” Han sagde mange ting, som man ikke skulle tage så højtideligt, men han kunne også være lun. De havde én datter, som hed Edith. Hun var gift med Dynes og boede på en gård, Studsgård ved Herning, og havde tre børn, to døtre og en søn. Jeg syntes, at Petra og Christian var frygtelig gamle og gammeldags, både i tøj og indretning af bolig, men også i holdninger og meninger. De fulgte godt nok med i, hvad der rørte sig i verden, og de havde været i USA for at besøge familie (de var ellers meget sparsommelige), men de var meget hårde mod ungdommen. Fordi jeg gik på universitetet, mente de, at jeg gik rundt og demonstrerede hele tiden, og jeg blev ofte spurgt: ”Nå, har du været ude og demonstrere for nylig?” men ellers var de søde og rare, og da Lars kom til verden, tog de også imod ham med åbne arme. Vi gjorde to ture med dem til Studsgård (de havde ikke selv bil), den første i juni 1977 og den sidste i august 1978, hvor Lars var knap 1 år. Deres piger elskede at lege med ham. Første gang, vi besøgte dem, var på den yngste pige Karens 14 års fødselsdag. Hun var en vældig kvik pige, mens de to andre børn virkede lidt tunge i det. Jeg fik lidt af et kulturchok første gang, vi besøgte dem. Det hele bar præg af, at de ikke havde for meget at gøre med og derfor var meget sparsommelige. Vi fik kun vand til maden, og dengang kom der normalt aldrig vand på bordet som i dag, så jeg var lidt chokeret. Men helt galt blev det, da jeg skulle på toilettet. Det viste sig nemlig, at de ikke havde et sådant men kun et das i gården, og toiletpapiret var af den hårde kradse type. Så kunne man godt holde sig i flere timer, og jeg tror nok, jeg kun benyttede det den ene gang. Året efter fik de lavet badeværelse."}]}, {"title": "Studier", "blocks": [{"type": "para", "text": "Da vi blev gift, havde jeg bifagseksamen i fransk og var 1½ år inde i mit hovedfag, engelsk, ved Århus Universitet. Efter et halvt år gik jeg op til bifagseksamen i engelsk og bestod. Jeg manglede derefter mindst to år, inden jeg kunne kalde mig cand.mag. Under den sidste del af studiet så jeg en dag et opslag om et vikariat på gymnasiet i Struer. De manglede en engelsklærer til en HF-klasse. Jeg ville gerne ud og have noget erfaring, så jeg søgte jobbet og fik det. Det betød så, at jeg skulle tidligt op om morgenen for at nå toget til Struer og kom sent hjem om aftenen. Det var en hård 3- måneders periode, men jeg lærte meget, og jeg syntes, det gik godt med at undervise – der var i hvert fald ikke nogen, der brokkede sig. Det sidste halve år af studiet skrev jeg speciale, samtidig med, at jeg gik til timer. Det var lidt usædvanligt, men jeg havde besluttet mig for, at jeg ville være færdig, så vi kunne få startet på at stifte familie, for jeg ville under ingen omstændigheder have børn, før jeg var færdig med min uddannelse. Senere kunne jeg så spekulere på, om det havde været en fornuftig disposition."}, {"type": "para", "text": "Jeg var en meget disciplineret studerende (med undtagelse af Can-Can-oplevelsen), så hver morgen kl. 6.30 kørte jeg med Vagn ind til Ringgadekrydset og satte mig ind på Engelsk Instituts Bibliotek for at skrive på mit speciale, hvis titel var ”En kontrastivanalyse af danske, engelske og franske relativ- og interrogativsætninger”. Grammatik har altid interesseret mig meget, så jeg gik ombord i emnet med stor interesse. Jeg fik skrevet 75 sider og reddede mig et 8-tal (en middel karakter), som jeg var godt tilfreds med, taget i betragtning, at jeg gennemførte et heltidsstudium sideløbende.  Da jeg i januar 1976 nåede til mine afsluttende eksamener, sørgede jeg for at komme ind og høre på så mange mundtlige eksamener som muligt, idet de var offentlige. På den måde var jeg lidt forberedt på, hvad jeg kunne forvente. Jeg læste som en gal i lange perioder, hvor jeg bare lod stå til med rengøring og andre huslige pligter. Der lå et lag støv til sidst, men jeg var ligeglad – jeg skulle bare bestå den eksamen, så jeg kunne komme ud og arbejde, selvom jeg vidste, at situationen var vanskelig for gymnasielærere. Den sidste dag skulle jeg op i et emne i engelsk litteratur, der hed ”Robinsonade”, og aldrig i mit liv har jeg været så nervøs. Vores lærer hed Ib Johansen, en meget distræt person, der lignede en vildmand med stort skæg og bare tæer i sundhedssandaler. Han var meget sød ved mig og gav mig et 8-tal, så jeg havde lyst til at flyve ham om halsen men gjorde det ikke. Jeg husker min beruselse ovenpå at have bestået mit sidste fag og kunne kalde mig cand.mag. i engelsk og fransk. Dagen efter arrangerede vi i al hast en fest for de nærmeste venner – det havde vi ikke turdet planlægge før, af frygt for at jeg ikke bestod."}]}, {"title": "Pædagogikum", "blocks": [{"type": "para", "text": "Dengang skulle alle have pædagogikum for at kunne søge job på et gymnasium. Jeg blev desværre sendt helt til Skive Gymnasium og HF, så hver morgen tog jeg toget fra Hadsten over Langå til Skive og mødte kl. 8. To dage om ugen tog jeg teoretisk pædagogikum på Skive Seminarium, hvorefter jeg så først var hjemme sent om aftenen. Jeg startede pædagogikum til februar og sluttede den 10. maj med følgende Vidnesbyrd om prøve i undervisningsfærdighed: ”Cand.mag. Merete Møller Christensen har i forårssemestret 1976 gennemgået kursus i undervisningsfærdighed ved Skive Gymnasium i sit hovedfag engelsk i klasserne 2 ns og 1 HF tilvalg og i bifaget fransk i 1 s."}, {"type": "para", "text": "Merete Møller Christensen har i løbet af kursus gjort gode fremskridt med hensyn til at erkende, hvad der kræves af en sproglærer på gymnasie- og HF niveau. Hun har været meget åben over for kritik og har efterhånden formået at indarbejde mere og mere af vejledningen i sin egen undervisning."}, {"type": "para", "text": "På de mere elementære trin af undervisningens sproglige side har Merete Christensen nået et tilfredsstillende resultat i forhold til den korte tid, der har været til rådighed i forårssemestret. I begynderundervisningen i fransk har hun arbejdet meget med at sortere det sproglige stof, således at eleverne får indøvet de grundlæggende strukturer og et basalt ordforråd, og hun har vist sans for at udvælge eller selv udarbejde tekster og tilrettelægge samtaler efter elevernes forudsætninger. På engelskundervisningens noget højere niveau har hun til tider vist manglende sikkerhed med hensyn til sproglige problemer, men der er sket fremskridt i retning af større præcision og effektivitet i forklaringerne."}, {"type": "para", "text": "Tekstgennemgangen har været svingende. Det har undertiden kunnet knibe med at klare visse sproglige og indholdsmæssige enkeltproblemer og med at gennemføre en samlende behandling af teksten. Men til andre tider har Merete Christensen formået at fremdrage aspekter i det læste, som har fået eleverne aktivt med i behandlingen af stoffet. Hun har ved bevidst indsats opnået en god udvikling af sin spørgeteknik."}, {"type": "para", "text": "Merete Christensens optræden i timerne er rolig og venlig, og de klasser, hun har undervist, har haft en positiv holdning over for hende”. Udtalelsen var underskrevet af mine 3 vejledere, rektor Jens Lund og en udefra kommende repræsentant fra Virum Statsskole."}, {"type": "para", "text": "Forud for denne udtalelse var gået tre pinefulde måneder, som havde været ved at drive mig ud på sammenbruddets rand, og jeg priste mig lykkelig over, at jeg ikke havde små børn derhjemme men kun en forstående mand. Mange gange græd jeg, så tårerne løb ned i de spejlæg, jeg formåede at stege, når jeg kom hjem efter en lang og træls dag. Det var et mareridt at tage afsted hver dag, og det skyldtes for det første, at jeg var dødtræt oven på en lang dag med forberedelse til den næste, og for det andet, at jeg var under konstant supervision og efter hver time blev bedømt af min vejleder. Jeg havde tre vejledere. I fransk havde jeg Sonja Uhrenholdt, som var min redningsmand. Hun var fra første færd sød og venlig, inviterede mig hjem, så jeg kunne overnatte, og stille og roligt lod mig overtage undervisningen. Hun lærte mig meget, og i hendes timer udviste jeg en sikkerhed og overlegenhed, jeg aldrig havde drømt om skulle overgå mig i fransk. Jeg blev så selvstændig, at hun aldrig behøvede at blande sig, og hun gav mig oftest meget positiv kritik. Havde det ikke været for hende, var jeg løbet skrigende bort. I HF-klassen havde jeg Inga Gad, som selv var meget usikker og en dårlig vejleder. Hun havde også problemer på hjemmefronten, for en dag kom hun meget rødøjet i skole og bad mig tage undervisningen, selvom jeg ikke var forberedt på det. Hvordan jeg klarede mig igennem de timer, husker jeg ikke, men jeg husker, at jeg tænkte: ”Det kan hun altså ikke være bekendt”. Hun brugte helt andre metoder i undervisningen end min anden vejleder i engelsk, Ida Christiani, som var en ung, mandhaftig og streng lærer, der kunne sit kram og krævede en kæmpeindsats af mig. Blot ved sin barske optræden gjorde hun mig usikker, og jo mere usikker jeg blev, jo hårdere kritiserede hun mig, så jeg blev endnu mere usikker. Da jeg i 1977 læste i Gymnasiebladet, at hun pludselig var død i en alder af 33 år, kunne jeg ikke nære mig for at tænke: ”Det var straffen, hun fik for at være så ubarmhjertig!”"}, {"type": "para", "text": "Midt i forløbet var der en midtvejsprøve, hvor der kom tre høje herrer og skulle overvære min undervisning. Skæbnen ville, at jeg havde influenza den dag, men jeg kunne jo ikke blive væk, så jeg kæmpede mig igennem dagen på halvt blus, hvilket også resulterede i, at jeg fik at vide, at jeg nær var dumpet. Mindre blev min nervøsitet så heller ikke, da jeg var oppe til den afsluttende prøve den 10. maj. Jeg syntes selv, at det gik rigtig godt, især i fransk, men jeg vidste jo, at Ida havde et horn i siden på mig, så jeg sad i spænding på lærerværelset og ventede i flere timer, før jeg fik min dom. Heldigvis bestod jeg, og jeg var da også ovenud glad for udtalelsen, men jeg er sikker på, at Sonja var kraftigt medvirkende til, at den blev så positiv, som den blev. I afskedsgave gav jeg hende da også 6 hvide porcelænsskåle, hvorimod de andre ikke fik noget."}, {"type": "para", "text": "Da jeg den dag kørte hjem fra Skive, fik jeg en fartbøde mellem Skive og Viborg, hvor der ikke var en eneste bil på vejen, lige med undtagelse af Politiet. Jeg kunne ikke komme hurtigt nok hjem og fortælle Vagn den gode nyhed: at jeg havde bestået Pædagogikum."}]}, {"title": "Sommerhuset på Rævevej 22 i Thorsager", "blocks": [{"type": "para", "text": "I 1976, samme år som vi tog til USA, byggede vi også sommerhus. Det var gode tider, og selvom jeg ikke var begyndt at tjene penge endnu, havde vi råd til at bygge sommerhus, tage på ferie i USA og købe nyere bil, endda en Volvo. Huset var af træ og ret stort af et sommerhus at være, ca. 100 m2. Der var en stor stue med køkken, tre værelser, hvoraf de to var med køjer, en gang og et badeværelse, og desuden var der en dejlig stor træterrasse. I stuen var der pejs, hvilket var dejligt, når vi kom derud om fredagen sidst på eftermiddagen. Om vinteren kunne der være ret koldt, så det første Vagn gjorde, var at tænde op i pejsen. Når jeg så havde pakket ud og lavet mad, satte vi os og spiste tæt op ad pejsen og med fjernsynet tændt. Så spredte hyggen sig."}, {"type": "figure", "caption": "", "page": 19, "file": "assets/images-bog2/p019_01.jpg", "dim": [1017, 683]}, {"type": "para", "text": "Huset lå i en skov på en naturgrund med store træer, og vi gik lange ture i skoven. Vi kunne også gå ind til Thorsager, som var en lille by med en brugs og en rundkirke. Men det var først og fremmest ren afslapning, når vi var derude. Tage kom ofte og tilbragte weekenden sammen med os. Vi har også haft mange gode oplevelser med Lars derude. Første gang, vi var derude med Lars, var den 4. december 1977. Vi tog derud allerede om torsdagen, og om fredagen kom Tage. Han og Lars fik et meget nært forhold til hinanden, og han var god til at passe Lars. Dog var jeg ikke så glad for at være der netop den weekend, fordi vi fangede to mus. Allerede da vi trådte ind ad døren, kunne vi se, at der var mus. Der lå efterladenskaber overalt, og da vi lukkede et køkkenskab op, dryssede der papirstumper ud, og stearinlysene havde de gnavet i af mangel på madvarer. Vagn satte en fælde op inde i soveværelset, så der skulle jeg i hvert fald ikke sove om natten. I stedet sov vi inde på et af værelserne. Det lykkedes Vagn at fange den ene mus i fælden, og den anden slog han ihjel med sin træsko, da den pilede hen over gulvet i gangen. Først da kunne jeg ånde lettet op, men det var et stort arbejde at gøre rent efter de ækle kræ."}, {"type": "figure", "caption": "Jens Christian og Poul Erik gør båden ren efter en fisketur", "page": 20, "file": "assets/images-bog2/p020_01.jpg", "dim": [999, 681]}, {"type": "figure", "caption": "", "page": 20, "file": "assets/images-bog2/p020_03.jpg", "dim": [685, 472]}, {"type": "figure", "caption": "", "page": 20, "file": "assets/images-bog2/p020_02.jpg", "dim": [689, 472]}, {"type": "para", "text": "Onkel Tage og Lars i sommerhus april 1978                           Lars og Klaus i sommerhus den 25. juli 1978 Fordelen ved mit arbejde var, at jeg havde en lang sommerferie. I 1978 havde jeg to måneders ferie fra den 8. juni, hvor vi tog i sommerhus og havde mormor (oldemor) med. Lars og oldemor var glade for hinanden, og hun var god til at passe ham, men han blev hurtigt for tung for hende."}, {"type": "para", "text": "Vi solgte sommerhuset i foråret 1980 for ca. 300.000 kr. Vi havde planer om at skulle bygge til huset i Spørring, fordi vi gerne ville have flere børn, så vi ræsonnerede, at vi ville få mindre og mindre tid til at være i sommerhuset. I starten havde vi brugt det meget, både sommer og vinter. I 1977 havde vi været der 12 gange og 8 gange i 1978, hvoraf nogle af gangene havde været en uge eller mere på grund af påske-, sommer- og efterårsferie. Det var vemodigt, da vi var der sidste gang, og jeg husker, at jeg tog Lars med ud på bænken, hvor vi tog en sidste afsked."}, {"type": "figure", "caption": "", "page": 21, "file": "assets/images-bog2/p021_01.jpg", "dim": [999, 681]}]}, {"title": "Den store USA-rejse i 1976", "blocks": [{"type": "para", "text": "Jeg havde, lige siden jeg forlod USA i 1963 efter mit år i Denver, haft lyst til at tage derover igen på ferie, og efter jeg mødte Vagn, havde jeg haft lyst til at vise ham de steder, jeg havde været. Denne drøm blev til virkelighed i sommeren 1976, hvor vi sammen med min onkel Helge og hans daværende kone Tove først tilbagelagde 17.500 km med fly og dernæst 8.372 km i bil tværs over USA. Ferien varede fra den 18. juni til den 19. juli, og det var 200- året for USA’s uafhængighed. Vi var Besøg af Margaret og Martinus september 1975                         meget spændte på turen og glædede os helt vildt. Vores genbo Grete kørte os til Tirstrup Lufthavn, hvorfra vores rejse skulle begynde. I Kastrup Lufthavn mødtes vi med Tove og Helge, og så kunne den store rejse virkelig begynde. Det var i de gode gamle dage, før der var noget, der hed terror, så vi fik frit lov til at komme på besøg i cockpittet. Det var Helge, der havde ordnet alt omkring rejsen, og det havde han gjort godt. Vi fløj til New York og boede på The Roosevelt Hotel på Manhattan. Vi sugede til os af indtryk og var allerede den første dag på en fantastisk sejltur omkring Manhattan, hvor vi så ”World Trade Center” for første gang og Frihedsgudinden. Det var stort. Dagen bød også på udsigt fra toppen af Empire State Building, Rockefeller Center og Central Park, hvor vi forgæves forsøgte at finde en statue af H.C.Andersen. Samme år var også Dronning Margrethe og Prins Henrik på besøg i New York, men de havde bodyguards med. Vi har et billede, hvor jeg står imellem to bevæbnede betjente, vel også en slags bodyguards. Vi spurgte om vej og fik ved den lejlighed lov til at fotografere dem. Da de hørte, at vi kom fra Danmark, sagde de: ”Åh, det lille land med den høje levestandard og fri porno”. Det sidste var nu ikke det, vi helst ville” brandes” på."}, {"type": "para", "text": "Det blev også til et kig ind i World Trade Center, hvor der var en dansk udstilling, en rundvisning i FNbygningen og en sejltur ud til Frihedsgudinden, hvor vi stod i en milelang kø for at komme op i kronen. Det blev til mange kilometers gåture gennem New Yorks gader med ophold i Wall Street, Broadway, 5th Avenue og Times Square. Efter tre dage i The Big Apple var vi mætte og skulle videre. Det foregik i en lejet bil fra Avis, som Helge og jeg hentede kl. 4 om morgenen, en Plymouth med læderindtræk, automatgear, automatspeeder og air kondition, alt sammen nyt for os. Vi betalte 154 $ for en uge. Vi startede ud af New York kl. 6 med Helge bag rattet. Det var nok et godt tidspunkt med hensyn til trafik, troede vi, men i denne by, der aldrig sover, er der altid trafik. I starten gik vi i stå i et lyskryds, og vi gik lidt i panik, fordi vi lige skulle vænne os til automatgear, men snart var vi kørende igen, og så gik det bare derudaf med skiftevis Helge og Vagn bag rattet. Den eneste gang, jeg vovede at køre, var i Nevadas ørken, hvor der var en snorlige vej hundredevis af kilometer og ikke mange biler. Tove havde ikke kørekort."}, {"type": "figure", "caption": "", "page": 21, "file": "assets/images-bog2/p021_02.jpg", "dim": [985, 678]}, {"type": "para", "text": "Vi var nu på vej mod Canada og Niagara Falls, som vi nåede ved aftenstid. Vi boede på Drago’s Motel og betalte 20 $ for et værelse. Om aftenen kørte vi i regnvejr ud og så Niagara Falls fuldt oplyst, den eneste gang på turen, vi havde brug for regnfrakker. Det var et fantastisk syn. På vej tilbage fór vi vild og kunne ikke finde motellet. Vi standsede en sherif, der kom kørende, og han lovede at køre foran og vise os vej, men da han skulle starte, kørte han over en smadret flaske og punkterede, så han nøjedes med at forklare os vejen. Vi mødte mange hjælpsomme mennesker på vores vej. Næste dag kørte vi igen ud til vandfaldene og så dem i flot solskinsvejr. Vi tog også på en sightseeing tur i området og fik sågar et ”Honeymoon Certificate” med os hjem, hvori der står, at Niagara Falls er ”The Honeymoon Capital of the World”, og de ønsker os et langt og lykkeligt liv sammen. Det er da også gået ganske godt indtil nu."}, {"type": "para", "text": "Næste dag passerede vi igen grænsen til USA og kørte igennem Michigan og Illinois, inden vi nåede Iowa, som var vores næste mål. Her skulle vi nemlig besøge morfars bror Julius, hvor vi skulle mødes med Margaret og Martinus, som var kommet fra Denver, Colorado. Det var jo dem, jeg havde tilbragt et år hos i 1962-63. Julius boede i Council Bluffs, hvor jeg også havde besøgt ham i 1962, men han var flyttet i et andet hus. Vi havde adressen med og fandt også nemt nok gaden. Jeg var lidt spændt på at se det ”nye” hus, han var flyttet ind i efter sin kones død, for det hus, han havde haft sammen med Blanche, havde været meget luksuriøst. Vi spejdede derfor efter en stor villa, men fik os noget af et chok, da vi mellem to ret pæne huse så et lille træskur, der passede til adressen på vores papir. Jo, ganske rigtigt, der kom Julius ud for at tage imod os, iført forklæde og karsefrisure. Han var en rigtig humørbombe og ønskede os hjertelig velkommen med knus og kram. Margaret og Martinus kom også ud, han iført sin sædvanlige hvide undertrøje, og hun med forklæde og curlers i håret. Det var dejligt at se dem igen."}, {"type": "para", "text": "Forklaringen på den ydmyge bolig var, at Julius aldrig havde brudt sig om det fine hus, han havde haft sammen med Blanche. Da hun så døde, havde han pakket alt det fine inventar ned og købt sig dette lille hus, som han rigtig kunne rode i. Og rode, det gjorde han. Køkkenet lignede noget, der var løgn. Man kunne ikke se køkkenbordet for ting og sager, og melposer, plastikbøtter og andet køkkengrej samt opvask fyldte det meste af bordet. Maling og tapet lignede noget fra den forrige ejer, og i stuen stod et stort skrummel køleskab, hvor en stor trækile var brugt til at holde lågen på plads, et køleskab han havde købt for 2 $ på en auktion. Men badeværelset var det mest interimistiske. Første gang, jeg brugte det, kunne jeg ikke forstå, at vandet sprøjtede ud på mine ben, da jeg vaskede hænder, indtil jeg kiggede ned og så en spand under afløbet. Det var så meningen, at man, når spanden var fuld, skulle tømme den ud i badekarret. Derfra løb det ned i kælderen og endte i en stor tønde, som Julius tømte udenfor engang imellem. I de fire dage, vi var der, kom jeg ikke i bad eller fik vasket hår, men heldigvis var det på mode at gå med tørklæde, så jeg bandt en af min mors batikbleer om hovedet, da håret blev for fedtet."}, {"type": "para", "text": "Vi skulle alle fire sove i stuen, og til det formål var der stillet to feltsenge op. Da vi skulle i seng, åbnede Julius dragkisten og hev noget sengetøj frem, der var så mørt, at jeg ret hurtigt stak en storetå igennem lagenet. Det gav anledning til den helt store fnisetur i stuen, for de andre skulle jo nødig høre, at vi gjorde grin med inventaret. Vi havde det ret sjovt og kunne virkelig se komikken i den livsstil, som Julius, der var god for mange millioner, havde tilegnet sig."}, {"type": "para", "text": "Vi havde en hel flaske snaps med til Julius, for vi vidste, at han gerne ville have en lille én. Det foregik så, når Margaret og Martinus var gået i seng, for Margaret var jo katolik og modstander af spiritus. Vi havde det som en flok børn, der var på forbudt område, når forældrene var gået i seng. Julius var en rigtig hyggelig fyr, som kunne fortælle sjove historier fra sit lange liv i USA og fra 1. Verdenskrig, som han havde deltaget i. Han var god til at lave mad, især pandekager, som han fløjtende og iført undertrøje vendte på panden om morgenen, mens alting flød omkring ham. Mens vi var der, blev vi inviteret over til morfars (og jo også Julius’ og Martinus’) kusine Krista til middag. Hun havde også inviteret sin datter Mary Jean og dennes mand Bud samt datteren Diane, som var 3 år, sidst jeg så hende. Nu var hun 17. Det var også vældig hyggeligt at se dem igen, og Krista havde ikke glemt at tale dansk. Under besøget blev vi inviteret på en drink hjemme hos Bud og Mary Jean, som havde en stor bar i kælderen. Her var Margaret og Martinus heller ikke med."}, {"type": "figure", "caption": "Christian på besøg i Danmark den 7. november 1980", "page": 23, "file": "assets/images-bog2/p023_01.jpg", "dim": [469, 703]}, {"type": "para", "text": "En dag kørte vi over og besøgte en tredje af morfars brødre, Christian, som boede på en farm, og hvis kone Lilly var på plejehjem. Christian var den af brødrene, der havde haft det hårdest og tjent færrest penge, og det lyste da også langt væk, da vi så ham og farmen. Det var et lidt ynkeligt syn, der mødte os. Stuehuset så ud, som det havde set ud 13 år tidligere, og fjedrene var på vej op af stolene gennem den luvslidte polstring, hvilket man mærkede, når man satte sig ned. Ingen af hans to døtre havde sørget for, at han så ordentlig ud i tøjet, eller at der var mad i huset, når vi kom. Den ene datter stak lige hovedet (fyldt med curlers) ind på et tidspunkt og sagde hej, uden at give hånd eller på anden måde vise interesse for os. Christian havde taget en købt blåbærtærte op af fryseren, som vi fik til en kop kaffe, men hvor havde jeg ondt af ham. Han lignede én, der kunne falde om når som helst, men han overlevede alligevel de to andre og nåede at komme en tur til Danmark i november 1980 i en alder af 86 år. Hvis det havde været min far, var jeg taget med ham, men hans døtre var ikke meget for ham, og de interesserede sig ikke for deres danske familie. Christian havde ikke givet sine søskende ordentlig besked om, hvornår han ankom, så der var ingen til at hente ham i lufthavnen. Det resulterede i, at nogen fandt ham i forvirret tilstand på en gade i Ålborg og fik ham hjulpet hen til familien. Tilbage til 1976. På vej hjem fra Christian besøgte vi en anden dansk familie, Chris Fuglsang, i Atlantic. Han og konen boede i et rigtig dejligt hus, så vi nød de få timer i luksus, inden turen gik hjem til hønsehuset. Under besøget hos Fuglsangs, besøgte vi en dansk mølle i den danske by Elk Horn tæt derved. Møllen var stykke for stykke blevet sejlet fra Danmark til Elk Horn og var nu under opførelse. Forleden så jeg en udsendelse i TV, som hed ”Danmark på prærien”. Det var en dokumentar om det danske samfund i Elk Horn, der er centreret omkring den danske mølle, som er byens vartegn. I Elk Horn er de mere danske, end vi er i Danmark."}, {"type": "para", "text": "Den sidste oplevelse, vi havde hos Julius, var en picnic, hvor vi selv skulle have mad med. Her skulle vi bl.a. være sammen med Krista og hendes familie, hvilket betød, at vi også fik hilst på to andre børnebørn, Mark og Christie, som jeg havde leget med 14 år tidligere. Nu var de gift og havde børn. Vi havde en rigtig sjov eftermiddag med volleyball, sækkevæddeløb og hesteskospil, mens de ældre spillede banko, men lige som det var allersjovest, og øllene og whiskyen var ved at komme frem, skulle vi hjem!"}, {"type": "figure", "caption": "", "page": 24, "file": "assets/images-bog2/p024_01.jpg", "dim": [991, 675]}, {"type": "para", "text": "Efter fire dage hos Julius trængte jeg til at få vasket hår, men nu skulle turen også gå videre sammen med Margaret og Martinus i deres store Lincoln, hvor man mageligt kunne sidde 3 på forsædet og 4 på bagsædet. Vi sagde farvel til min dejlige grandonkel Julius, som havde været så festlig at besøge, og turen gik nu de 550 miles til Denver med Martinus bag rattet. Den lille mand følte sig lidt vigtig bag rattet i den store bil, hvor jeg blev placeret mellem ham og Margaret. Det var, som følte de, at Julius, Helge, mig, Margaret, Martinus og Tove                     de havde fået deres lille pige tilbage Nummerpladerne var til Helges samling.                           (”you are our girl!”, sagde Margaret ofte)."}, {"type": "para", "text": "Margaret og Martinus boede nu ikke længere på Federal Blvd. men var flyttet nogle få hundrede meter til 2755 Grove Street. Det var et dejligt hus og et slot ved siden af Julius’ gamle rønne. Næste dag kom Mr. Harms, min gamle engelsk- og historielærer, på besøg. Han skulle hjælpe mig med at spore mine klassekammerater, som vi ville forsøge at samle, mens jeg var der. Jeg ringede rundt til dem, der boede i nærheden. Det var hyggeligt at tale med dem igen, men kun fire kunne komme: Jacque, Vickie, Sandra og Gary. Derudover kom Pastor Pollack med frue, Mr. & Mrs. Harms, Mr. & Mrs. Rathe (Mr. Rathe havde været min matematiklærer), og Mrs. Anzur. Vi havde en fornøjelig eftermiddag i haven, hvor Margaret For enden ses Gary, dernæst Vicky, Sandra, mig og Pastor Pollack     trakterede os med sandwiches, kiks, med frue                                                                                   kage, lemonade og kaffe."}, {"type": "figure", "caption": "", "page": 24, "file": "assets/images-bog2/p024_02.jpg", "dim": [1004, 686]}, {"type": "para", "text": "Det var sjovt at være tilbage og vise Vagn, hvor jeg havde boet i et år fra 1962 til 1963. Jeg fik også hilst på Sally, Margarets søster Agnes, Hr. & Fru Casperson, Florence og Sramek-familien, som nu havde 9 børn. Vi var inde og se Emmaus Lutheran School & Church, den skole og kirke jeg havde gået i, og jeg var naturligvis til gudstjeneste om søndagen."}, {"type": "figure", "caption": "", "page": 25, "file": "assets/images-bog2/p025_02.jpg", "dim": [696, 469]}, {"type": "figure", "caption": "", "page": 25, "file": "assets/images-bog2/p025_01.jpg", "dim": [674, 468]}, {"type": "para", "text": "På besøg i Sallys køkken                                               Mr. Harms og jeg i mit gamle klasseværelse Men vi havde begået en stor fejl: vi havde ikke meldt klart ud, hvor længe vi ville blive i Denver, af den simple grund, at vi ikke vidste det. Vi ville se, hvordan det hele gik, og hvor meget der var at se. Vi havde også troet, at vi kunne låne den ene af Martinus’ tre biler, men han vogtede over os, som var vi en flok børn. Hver gang, vi meddelte, at vi kunne tænke os at se det ene eller det andet, prøvede han enten at tale os fra det eller sige, at han ville med. Vi fik næsten aldrig lov at gå ud på egen hånd. En aften havde vi besluttet, at vi ville i Elitch Garden, en slags forlystelsespark, men det kom til at foregå på den måde, at Martinus kørte os derhen og hentede os igen til et bestemt tidspunkt. Vi måtte helst ikke være ude efter mørkets frembrud, for det var for farligt, sagde han. Vi kunne jo risikere at møde en flok mexicanere med knive!"}, {"type": "para", "text": "Vi havde virkelig set frem til den 4. juli, som var 200-års dagen for ”Declaration of Independence”. Så måtte der da være fest og ballade i gaderne, mente vi. Men ak, også det gik vi glip af. Martinus sagde, at der var alt for mange mennesker i gaderne, så der hverken var til at komme frem eller tilbage. I stedet for at trodse ham, tog vi i Zoologisk Have, og senere, da vi kom ind til byen, kunne vi se sporene efter alle de parader, vi var gået glip af. Det var virkelig en skuffelse."}, {"type": "para", "text": "En aften, hvor vi sad og hyggede os, efter at husets folk var gået til køjs, besluttede vi, at vi ville videre på vores tur, hvis vi skulle nå at se noget mere af USA. Vi var blevet lidt trætte af, at vi ikke fik lov at opleve det, vi gerne ville i Denver. Men da jeg næste dag meddelte Margaret og Martinus, at vi havde planer om at tage afsted om nogle få dage, blev de meget skuffede. Vi havde dog været der i elleve dage, så vi syntes, vi havde givet dem et godt besøg. Nu skulle der så pludselig til at ske noget, fire dage før vi skulle rejse. Der blev arrangeret picnic for både den ene og den anden, og en dag var vi alle seks i Colorado Springs og om aftenen ude at spise hos Marie og Svend Sønderup. Dem havde jeg lært at kende i 1962 (de flyttede senere til Holme, men herom senere). Svend var ked af, at de ikke tidligere havde fået at vide, at vi var kommet, for han ville gerne have vist os rundt. Nu var der ikke tid."}, {"type": "para", "text": "En af de sjoveste oplevelser, vi havde, var med min skoleveninde Jacque, som en dag hentede os og tog os med på tur i bjergene. Hun havde frokost og øl med, og vi havde det virkelig sjovt. Vi var i Central City, Loveland Pass (i sneen), the Continental Divide og Mt. Evans, en tur på 250 miles."}, {"type": "figure", "caption": "", "page": 26, "file": "assets/images-bog2/p026_01.jpg", "dim": [1014, 683]}, {"type": "para", "text": "Det blev til en vemodig afsked med Margaret og Martinus, som var kede af at vi ”allerede” skulle afsted. Vi havde været et friskt pust fra Danmark, og nu var det forbi. Da vi kørte derfra, var jeg da også lidt trist til mode. Jeg tænkte på, om jeg mon nogensinde så dem igen. Det gjorde jeg ikke. Martinus døde den 4. januar 1980. Jeg holdt forbindelsen til Margaret, som endte sine dage på et plejehjem, hvor hun døde i 1988. Hun var flittig til at skrive til mig, men det blev sværere og sværere at læse hendes skrift, som i forvejen var vanskelig at tyde. Mit hjerte blødte for hende, for jeg kunne mærke på hendes breve, at hun var ensom og at hun savnede mig. Vi havde haft et fantastisk nært forhold, og jeg vil altid mindes hendes varme sind og dejlige latter. Jeg skrev til hende så ofte, jeg kunne, sendte gaver til hende og indtalte bånd. Når Marie og Svend var i Denver, besøgte de altid Margaret og havde gaver med hjem til mig. Jeg har stadig en keramiklysestage med et lyserødt lys, som hun sandsynligvis lavede i terapien på plejehjemmet. Dette var et sidespring – tilbage til 1976."}, {"type": "para", "text": "Resten af ferien var sjov og ballade, for Helge var altid frisk. Vi kom i det hele taget godt ud af det med hinanden alle fire, og der var aldrig et ondt ord mellem Helge og Tove, bortset fra den gang, ude midt i ørkenen, hvor Tove meddelte, at hun skulle tisse. Helge stoppede fluks bilen, men Tove nægtede at sætte sig, for der var jo ingen buske, der kunne skjule hende. Så trådte Helge i karakter og beordrede hende til at sætte sig og lade vandet – vi havde jo ikke set en bil i flere timer. Og sådan blev det."}, {"type": "para", "text": "Vi oplevede meget på resten af turen. Vi kørte igennem staten Utah, badede i the Great Salt Lake, hvor vandet var 17 % salt og luften var over 100 grader F, og vi så Mormontemplet. Videre til Nevada med alle kasinoerne og byen Reno, en miniudgave af Las Vegas. I Californien besøgte vi Alices søster Kirsten og dennes mand Gordon i Loomis nær Sacramento. Datteren Alice, som havde boet i Danmark et år hos sin moster Bodil, var også hjemme. Hun talte dansk og viste os sin hest, som vi fik lov at ride på. San Francisco var spændende med Golden Gate broen og sporvognene (cable cars). Derfra gik turen videre til Redwood skovene, Santa Cruz, Carmel og Big Sur, hvor vi boede på River Inn Motel med udendørs swimmingpool. Dette var en speciel oplevelse, fordi naturen og luften var så pragtfuld, og vi svømmede i poolen kl. 22 om aftenen, Vagn og Helge iført deres nyerhvervede redningsveste for at prøve, om de kunne holde dem oppe. På senere ture til USA har vi gjort stop ved netop dette sted og har mindedes opholdet der i 1976. Derfra gik turen til Solvang, hvor vi spiste dansk smørrebrød i Ellen’s Danish Pancake House. Videre til Santa Barbara og Los Angeles, hvor vi fandt alle tiders flotte motel, Executive Inn Motor Hotel, med farve TV, isskab med is til kolde drinks, telefon, radio og swimmingpool. Vi var der i tre nætter."}, {"type": "figure", "caption": "", "page": 27, "file": "assets/images-bog2/p027_03.jpg", "dim": [996, 673]}, {"type": "para", "text": "Nu kom turen så til Disneyland, som vi havde set frem til, og vi blev ikke skuffede. Det kostede 6,50 $ per person for indgang og elleve forlystelser, som vi havde svært ved at få brugt på den ene dag. Den første, vi mødte, var Anders And, og det kom faktisk bag på os, så vi grinede så meget, at vi var ved at tisse i bukserne. Vi fandt virkelig vores barnlige sjæle frem igen, og vi var kommet for at more os og have det sjovt. Ind imellem turene med ”Submarine Voyage”, Monorail, ”Tom Sawyer Island”, “Pirates of the Caribbean”, ”Jungle Cruise” og meget mere, mødte vi Snehvide og de 7 små dværge, Minnie og Mickey Mouse, Store Stygge Ulv, som var ved at æde os, Praktiske Gris og en sydstatssoldat. Vi morede os, til parken lukkede, og var trætte og mætte oven på denne uforglemmelige oplevelse."}, {"type": "figure", "caption": "", "page": 27, "file": "assets/images-bog2/p027_01.jpg", "dim": [675, 999]}, {"type": "figure", "caption": "", "page": 27, "file": "assets/images-bog2/p027_02.jpg", "dim": [667, 1006]}, {"type": "para", "text": "Næste dag var vi friske igen til at tage i Universal Studios, som var en næsten ligeså stor oplevelse som Disneyland. Vi var på den obligatoriske Universal City Studio Tour, hvor vi oplevede forskellige filmtricks, såsom at køre over en bro, der kollapser, opleve en stormflod og en lavine, se Det Røde Hav skilles og være nær ved at blive spist af hajen fra ”Dødens Gab”. Vi så også forskellige shows, såsom Stuntman Show og dyredressur. Den sidste oplevelse, vi havde på turen, var Marineland, hvor vi så fantastiske shows med hvaler, delfiner, søløver m.m."}, {"type": "figure", "caption": "Jeg fandt mig en ny ven i Universal Studios", "page": 28, "file": "assets/images-bog2/p028_01.jpg", "dim": [686, 1004]}, {"type": "para", "text": "Da vi landede i Tirstrup, stod der en modtagelseskomité bestående af mor, far, Alice, Reinholt, John og Per, og Alice gav kaffe, da vi kom hjem. Det var en dejlig overraskelse. Ragnhild havde lavet en flot blomsterdekoration, som stod på spisebordet, da vi kom hjem. Mens vi havde været bortrejst, havde Alice skaffet mig en stilling, og det var da lidt fantastisk. Jeg havde søgt flere stillinger, inden vi tog på ferie, og da vi jo var væk i lang tid, havde jeg bedt Alice kigge i posten, hvis der skulle være svar fra nogen. En dag blev jeg ringet op i Denver af mor, som havde besked fra Alice om, at der var en stilling ved Studenterkursus i Ålborg og en ved Handelshøjskolen i Århus. Det blev arrangeret sådan, at jeg var til samtale begge steder og fik begge stillinger, som kunne kombineres med to dage i Ålborg og tre dage i Århus. Jo, det er godt at have gode venner og naboer."}]}, {"title": "Den søde ventetid", "blocks": [{"type": "para", "text": "Jeg tror, jeg blev gravid Nytårsaften 1976. Det var lige efter bogen, selvom vi var klar til det allerede fra sommeren det år. Den 1. februar 1977 var jeg hos lægen og fik det bekræftet, og vi var ellevilde af lykke, for nu skulle vi have vores ønskebarn. Vores forældre blev også meget glade, da de hørte det, for der var ikke for mange små børn i vores lille familie. Vagns søster og svoger havde Jens Christian og Charlotte, men på min side var dette det første barnebarn. Mor begyndte straks at sy omstændighedstøj til mig. Det kaldte vi det dengang. Jeg købte nogle bukser, der kunne udvides med elastik, og mor syede forskellige toppe, som kunne bruges dertil, og som skjulte den voksende mave. Men jeg ønskede bare, at hele verden skulle se, at jeg var gravid, så glad var jeg."}, {"type": "para", "text": "Et stykke tid efter, at jeg havde fået den gode nyhed hos lægen, kom Grete, vores genbo, og fortalte, at hun også var gravid. Det var sjovt, at vi skulle være gravide samtidig. Hun skulle føde sidst i oktober, og jeg skulle føde omkring den 20. september."}, {"type": "para", "text": "Jeg havde det fantastisk godt under graviditeten. Ikke noget med morgenkvalme eller opkastninger, og jeg kunne holde til det utroligste. Om sommeren var vi på en 3-ugers rundrejse med bil i Europa, hvor Tage var med. Jeg havde spurgt Doktor Svendsen, om jeg godt kunne tage på sådan en lang tur i 7. måned, hvortil han havde svaret: ”Det er jo ikke nogen sygdom”."}, {"type": "para", "text": "Vi startede sydpå den 2. juli i vores cremefarvede Volvo 242. Jeg sad og tronede på bagsædet med min store mave, for jeg fyldte allerede godt i landskabet. Pladsen bagi blev dog mindre og mindre, som turen skred frem, og det skyldtes ikke, at maven voksede, men at Vagn havde fået den idé, at han ville samle på tomme ølflasker fra de forskellige lande, så hver gang de herrer havde nydt en øl, måtte jeg pænt spørge, om de måtte tage flaskerne med hjem! Det blev til en pæn samling, som i få år stod og pyntede på nogle hylder i sommerhuset, indtil dette blev solgt. Så røg flaskerne ud. Ragnhild havde bagt småkager til os og skrevet en sød hilsen: ”Vi ønsker jer en rigtig god tur. Pas godt på lillebror. De bedste hilsner Mikael og Ragnhild”. Hun var altid sød til at komme med bagværk eller blomster, men hvorfra hun vidste, at det ville blive en dreng, ved jeg ikke. Måske kunne hun se det på mavens form."}, {"type": "para", "text": "To dage senere kørte vi over grænsen til Schweiz og var snart i Basel. I nærheden af Luzern overnattede vi på en hyggelig bondegård, og derfra gik turen videre til Sct. Gotthard med sne og kulde på toppen. Før Lugano blev vi privat indkvarteret og nød næste dag byen og den flotte udsigt over søen, som vi også sejlede på. Men hvor var alting dog dyrt i dette land. Samme dag kørte vi over grænsen til Italien og var snart i Milano. Vi kom ind i centrum lige i myldretiden men fik bilen parkeret uden at få skrammer, og så gik vi på udkig efter et hotel for natten. Da det var bagende varmt, havde jeg kun shorts og en top på, men italienerne i denne by var åbenbart ikke vant til at se en gravid kvinde iført så få tekstiler, for de gloede helt hæmningsløst, selv iført sorte kjoler og habitter. Da en bus kørte forbi, vendte alle sig deri for at overbeglo mig. Vi følte os ikke særlig godt til mode i denne kvalmende by, så da vi på det første hotel fik beskeden: ”Alt optaget”, var vi ikke sene til at finde Volvoen og komme hurtigt ud af byen. Et stykke ude ad motorvejen fandt vi et stort og flot luksushotel, som vi lejede os ind på. Vi boede som regel på samme værelse alle tre, for det var billigere og også hyggeligere. Og her var det, at jeg virkelig fandt ud af, hvor stort et ordensmenneske Tage var og er, for i hans kuffert lå tøjet bare i snorlige rækker, og selvom vi havde boet i en kuffert i nogle dage, havde dette ikke influeret på ordenen. Det var dejligt at komme ud af Milano til dette luksushotel med swimmingpool, som jeg kunne bade i uden nysgerrige blikke, og vi fik en pragtfuld 3-retters menu om aftenen. En nat kostede 27.550 Lire (ca. 225 kr.). Desværre skulle vi forlade dette Paradis næste morgen, for vi skulle videre på vores færd til den Italienske Riviera. Næste nat fandt vi et dårligt hotel til 12.000 Lire (ca. 100 kr.) og spiste en billig middag, men det var jo det, der var det spændende ved turen. Vi vidste aldrig, hvad den næste dag ville bringe."}, {"type": "para", "text": "Nu var vi så fremme ved den 8. juli, hvor vi kørte ind i Monaco. Her var det umuligt at finde et hotel til en rimelig pris, så vi kørte udenfor og fandt et billigt hotel og kørte så tilbage til Monaco om aftenen. Vi så Monte Carlo, Fyrsteslottet og Akvariet og var inde i Kasinoet, dog uden at spille. Fra Monaco kørte vi videre til den Franske Riviera, noget pænere og renere end den Italienske ditto. Vi kom til Nice og Cannes, hvor vi fandt et dejligt hotel uden for byen. Om aftenen var vi inde i Cannes for at spise, men priserne var så høje, at vi nøjedes med at spise en forret (laksepostej). Da tjeneren spurgte os, hvad vi så ønskede som hovedret, sagde vi, at vi var mætte og ikke ønskede mere. Det var lidt flovt, men vi var nok kommet til et sted, der var lidt for fint og dyrt for os. De fleste dage lavede vi selv morgenmad. Vi havde et lille gasblus med og en gryde, og det var Tage, der altid stod for at koge æg. På den måde kunne vi også nyde frokosten i det grønne, hvis vejret var fint, og var ikke nødsaget til at sidde inden døre i det gode vejr og spise et stort måltid.  Dagen efter kørte vi ind i et område, som duftede vidunderligt. Det viste sig, at vi nærmede os parfumebyen Grasse på vej til Route Napoléon og Gorges du Verdon, et flot bjerglandskab bestående af dybe kløfter og høje klipper. Nu gik turen videre nordpå til Grenoble, hvor vi tog en svævebane op i bjergene og bagefter fandt et billigt hotel uden for byen, hvor vi spiste en dejlig middag om aftenen. Det viste sig, at vores værelse vendte ud mod gaden, hvor der var temmelig megen støj, også om natten fra de tunge lastbiler, der kørte forbi. Vi kunne derfor ikke have vinduet stående åbent. Da det var temmelig varmt og beklumret, i hvert fald ifølge min graviditetsvarmetærskel, foreslog jeg, at vi i stedet lukkede døren op ud til gangen. Trods det lå jeg længe og kunne ikke falde i søvn. Pludselig mærkede jeg noget loddent ved mine ben, og jeg skreg: ”Få den kat ud af min seng!” Det var hotellets kat, der havde set sit snit til at smutte ind på vores værelse og lægge sig til rette i vores seng. Katten blev nok ligeså forskrækket som mig, for den fór ud af døren hurtigere, end den var kommet ind, og døren blev lukket med et brag. Hvordan jeg kom igennem natten med mine hedeture og uden nogen form for ventilation, husker jeg ikke, men bagefter grinede vi meget af episoden."}, {"type": "para", "text": "Næste stop var Paris, byernes by, hvor vi kørte lidt udenfor for at finde et hotelværelse, der ikke var for dyrt. Vi ville være der i tre dage. Vi fandt ud af at køre hen til en metrostation og tage metroen ind til centrum. Vi fik set meget på de dage og travet meget, uden at det rørte mig det mindste. Vi sejlede på Seinen og gik gennem Tuilleri-haven til Avenue des Champs-Elysées, hvor jeg købte en kjole, og vi så en dansk bagerforretning med en kage, der kostede 36 F. Vi var oppe i Triumfbuen og tog en taxa til Montmartre, hvor vi var inde i Le Sacré-Coeur kirken. Næste dag, den 14. juli, Frankrigs nationaldag, var vi inde og se Notre-Dame kirken, hvorefter vi vandrede rundt og så Sorbonne-Universitetet, Luxembourg-haven, Invalidekirken, Napoleons grav og Eiffeltårnet, som vi naturligvis var oppe i, hvorefter vi så en militærparade og faldskærmsudspringere i anledning af Bastilledagen. En aften, hvor vi var ude og spise i Paris, bestilte vi løgsuppe. Det var jo mit job at tyde menukortene, og jeg fik da også trænet mit franske lidt, men jeg havde ikke tænkt på at spørge om, hvad der var i suppen ud over løg. Det viste sig, at der var et låg af varm ost, som kunne trækkes så langt så langt og var svært at få ind i munden. Men det gjorde nu heller ikke så meget, for vi syntes alle tre, at det smagte hæsligt. Vi var ikke vant til, at der var ost i maden – sådan noget nymodens noget kunne vi ikke lide. I dag kunne vi måske godt have spist det, men det var voldsomt."}, {"type": "para", "text": "Efter Paris gik turen stik nord til havnebyen Calais, hvorfra der gik flyvebåd til England. Vi lejede et værelse og sad om aftenen og så, hvordan bådene kørte helt op på land, inden passagererne stod af. Det var betagende, syntes vi. Næste morgen tog vi denne ”Hoverlloyd” til Ramsgate i England, en tur på 40 min. Vi fløj/sejlede med 100 km/timen, og båden hoppede og dansede, så jeg var nær ved at nedkomme i utide. Vi tog toget fra Ramsgate til London, hvor vi ankom til Victoria Station kl. 10. Nu havde vi hele dagen til at traske rundt og se på seværdighederne. Vi sejlede en tur på Themsen, hvorfra vi så Parlamentet, Whitehall, Westminster Abbey, Big Ben, Royal Festival Hall og Tower Bridge. Vi spadserede til Buckingham Palace, hvor vi så vagtskifte, vi spiste på Picadilly og var på Trafalgar Square, hvorfra vi spadserede hele vejen tilbage til Victoria Station og tog toget kl. 16.40 tilbage til Ramsgate. Vi var først tilbage i Calais kl. 22.30, idet flyvebåden var en time forsinket. Der blev udleveret brækposer, men dem fik vi heldigvis ikke brug for."}, {"type": "para", "text": "Den 17. juli forlod vi Frankrig og kørte ind i Belgien, hvor næste stop var Bruxelles. Her var vi oppe i toppen af Atomium, et jernmolekyle forstørret 200 millioner gange og opført i 1958 i anledning af Verdensudstillingen. Vi så også EF-bygningen og Grande Place, som var flot belyst om aftenen. Vi havde læst og hørt om en berømt statue, Mannekin-Pis, så næste dag begav vi os ud for at finde den. Det skulle blive vanskeligt, viste det sig. Selvom vi havde et kort og vidste nogenlunde, hvor vi skulle lede, fandt vi den ikke, og dem vi spurgte, kunne ikke hjælpe os. Da vi var ved at opgive, så vi pludselig i et uanseligt hjørne over for en lille butik, der solgte postkort, en lille statue af en dreng, der står og tisser. Vi havde forestillet os en kæmpe statue på en stor plads, så det var ikke så sært, at vi ikke kunne finde den. Tænk at denne lille dreng var så berømt. Vi kørte mod Antwerpen og fandt et lækkert hotel med uden- og indendørs pool og TV. Vi nød virkelig denne sidste aften i Belgien, inden vi næste dag kørte over grænsen til Holland. Det var lidt af et antiklimaks at komme til Belgien og Holland oven på alle de oplevelser, vi havde haft. Vejret blev dårligt, og vi var ved at være møre. Men trods det, strammede vi os an til at møde Holland. I Rotterdam så vi verdens største havn, og mændene var oppe i Euromast. Vi fandt et motel i Amsterdam og tog på kanalrundfart. Næste dag var vi inde og se slottet og Mme Tussaud’s Vokskabinet, hvor jeg blev fotograferet sammen med Anne Frank, og Vagn sammen med Churchill. Da Amsterdam er kendt for sine diamanter, var vi inde og se et diamantværksted, hvor dørene blev forsvarligt låst, så ingen kunne stikke af med ringene, da de blev taget frem fra montrerne. De ville jo gerne sælge til turisterne. Vagn ville give mig en ring i anledning af min nært forestående fødsel, så jeg var selv med til at vælge en diamantring. Det var nok en af de billigste, jeg valgte, men det var den enkleste og den, jeg bedst kunne lide: en hvidguldsring med en brillantsleben diamant 0,03 karat til 75 US $. Den ring betyder meget for mig i dag. Den 21. juli om aftenen var vi hjemme efter en fantastisk dejlig ferie sammen med Tage (og lillebror i maven). Det var altid en fornøjelse at være sammen med Tage på ferie, for jeg blev vartet op, ikke af én men af to mænd. Det eneste men var, at når jeg gerne ville shoppe, stod der ikke én men to mænd og ventede på mig uden for butikken, og det kunne godt være stressende, selvom de ikke åbenlyst viste deres utålmodighed."}, {"type": "para", "text": "Den 23. juli var jeg inviteret til 10-års realskole jubilæum hos Aase på Ødegård, med påhæng. Det skulle have været en havefest, men det regnede, så arrangementet blev henlagt til stuerne, hvor vi drak eftermiddagskaffe. Senere flyttede vi i kælderen, hvor aftensmaden med fadøl blev indtaget, og Aases bror Henning, som spillede i orkester, underholdt sammen med sit band. Aase havde nogle kolleger med fra Lufthansa, bl.a. sin kæreste, som var flykaptajn. Det var et flot initiativ at holde et sådant arrangement, og vi beundrede Aase, når hun jonglerede mellem jysk, rigsdansk og tysk. Aase blev senere gift med kunstneren Karl Pichler, og jeg har lige besøgt dem i Ottensheim ved Linz i Østrig, hvor de bor på et slot. Det var en spændende oplevelse. Edmund, mig, Aase og Anne Grethe."}, {"type": "figure", "caption": "Til skolejubilæum hos Aase. Fra venstre er det Birgit, Jytte, Lisbet, Irene, Tove, Yrsa,", "page": 31, "file": "assets/images-bog2/p031_01.jpg", "dim": [1020, 689]}, {"type": "para", "text": "Appetitten fejlede ikke noget, mens jeg var gravid. Tværtimod. Jeg kunne spise som en ko, og jeg følte mig også som en sådan. Min svigerfar sagde altid, når vi var hjemme hos dem: ”Tag nu noget mere – du skal jo spise for to”. Dette var nu en stor misforståelse, for barnet skulle nok tage den næring, det skulle bruge, selvom man ikke spiste for to. Jeg havde i starten af perioden en ubændig trang til appelsiner – ikke det værste at være vild med. I ferien havde jeg virkelig spist og taget på, så jeg ved hjemkomsten vejede 68 kg, dvs at jeg havde taget 12 kg på 7 måneder henne i graviditeten. Hvad skulle det ikke ende med? På slutningen gik Grete og jeg til fødselsforberedelse, hvor vi prustende og stønnende lå på gulvet og lærte, hvordan vi under fødslen skulle trække vejret. Der var også en masse teori på kurset, som var interessant at få med."}, {"type": "para", "text": "Det var en hel selvfølge, at vores barn skulle ligge i den samme vugge, som min bror Per havde ligget i. Mor havde i mellemtiden fået en glasplade lagt på stellet og brugte det som bord i gangen. Nu blev glaspladen fjernet og kurven fundet frem. Mor syede nyt betræk, som blev monteret i vuggen sidst i august. I starten af september købte vi barnevogn af Henning Pedersen, som var barnevognssælger. Vi havde lært Else-Marie og Henning at kende gennem Doris og Poul Erik, og de blev efterhånden betragtet som en del af familien og er nogle af vores rigtig gode venner i dag."}, {"type": "figure", "caption": "", "page": 32, "file": "assets/images-bog2/p032_01.jpg", "dim": [1020, 678]}, {"type": "para", "text": "De har ingen børn men har altid vist stor interesse for både Doris og Poul Eriks børn og vores Lars."}, {"type": "para", "text": "Den 6. september var jeg hos jordemoderen, som fortalte mig, at barnet nu vejede 3100 g."}, {"type": "para", "text": "Her er Lars i vuggen den 19. februar 1978"}, {"type": "para", "text": "Midt i september gik Vagn i gang med at male stuen og værelserne. Han malede loft i gæsteværelset og lakerede gulvene, så der kunne være fint, når lillebror kom. Vi indrettede børneværelse i værelset ved siden af soveværelset, men i starten skulle vuggen, som var på hjul, stå ved siden af vores seng i soveværelset. Vi malede væggene i børneværelset gule og gjorde alt parat med puslebord, skråstol og tøj. Meget af tøjet var brugt babytøj, som jeg havde fået af en tidligere studiekammerat Grete. Den 24. september var alt klar, huset var gjort rent, jeg havde endda i min meget gravide tilstand haft vaskemaskinen ude for at gøre rent bag ved den. Så nu kunne barnet bare komme an. Grete Andersen, som jo også var højgravid, og jeg gik lange ture i håb om, at fødslerne ville gå i gang, men der skete ikke noget. Jeg gik stadig på arbejde og skulle blive ved, til barnet kom. Jeg havde ret til tre måneders barselsorlov fra Ålborg, men på Handelshøjskolen havde de ikke den ordning, når man var timelærer. Man kunne allernådigst få to uger!"}, {"type": "para", "text": "Søndag den 25. september var jeg alene hjemme og sad i stuen i færd med at rydde op i min syæske. Jeg havde endevendt alt i huset og ryddet op, så der var kun syæsken tilbage. Pludselig så jeg en mus pile hen over gulvet og ud i den lange gang. Jeg blev stiv af skræk, for mus var det værste, jeg vidste. Jeg skyndte mig at lukke døren til gangen og ringede resolut op til Alice, som havde kat. Hun kom straks ned med katten, men den lagde sig bare dovent på min briks på kontoret. Vi lukkede døren ud til køkkenet og satte os ned med en kop te. På et tidspunkt gik Alice ned i bryggerset, og jeg hørte et skrig. Musen havde siddet oven over døren og var sprunget ned, da hun kom derud. Alice påstod, at hun ikke var bange for mus, men at det, der havde udløst skriget, var det uventede møde med kræet. Nu vidste vi i hvert fald, at musen var i bryggerset, så jeg skulle i hvert fald ikke bruge vaskemaskinen, før den var fanget. Lidt efter gik Alice hjem med sin kat – gennem fordøren vel at mærke. Vagn prøvede at finde musen, da han kom hjem, men den må være smuttet ud af døren, da han har haft den åben, for vi fandt den aldrig. Jeg holdt mig imidlertid væk fra bryggerset, indtil jeg kom hjem fra hospitalet. Før var jeg ikke sikker på, at musen var væk. I ugen op til fødslen har jeg gjort følgende notater i min dagbog: ”Mandag gravede jeg gulerødder op og kogte 10 pund til fryseren. Desuden syltede jeg rødbeder. Tirsdag gjorde jeg bilen ren. Onsdag vaskede jeg (det gjorde jeg i hånden, for jeg vovede mig ikke ned til vaskemaskinen). Torsdag gik jeg tur sammen med Grete, syltede græskar, bagte småkager og franskbrød. Fredag gjorde jeg rent og var deprimeret. Hvorfor kom det barn dog ikke snart? Havde det tænkt sig at blive derinde?”"}]}, {"title": "Vores ønskebarn bliver født den 1. oktober 1977", "blocks": [{"type": "para", "text": "Natten til lørdag den 1. oktober gik vandet, og jeg begyndte at få veer. Jeg havde fået at vide, at jeg skulle ringe til lægen, når der var 10 minutter mellem veerne. Det var der slet ikke endnu. Jeg husker egentlig ikke, hvornår vi ringede, men vi kørte i hvert fald ind på Finsensgades fødselsafdeling kl. 11. Det var der, man fødte børn, hvis der ingen komplikationer var. Ellers skulle man på Stiftelsen. Jeg husker tydeligt, at jeg stod og satte min taske i bagagerummet, mens Poul gik og arbejdede på en tilbygning til sin garage. Vi vekslede et par ord om, at nu var det nu, og jeg registrerede, at der var det flotteste efterårsvejr med solskin, en dejlig dag at komme til verden på, hvis det altså blev den dag."}, {"type": "para", "text": "Det blev det, men først kl. 16.45. Vagn var næsten med til fødslen men måtte gå ud, da der blev lidt for megen aktivitet på stuen. Da han havde sundet sig, kom han ind igen, og da var han blevet far til en dejlig dreng på 3600 g og 52 cm. Fødslen var lidt hård, men det var hurtigt glemt, da jeg lå med Lillebror i mine arme. Det var den største dag i vores liv, og vi kunne slet ikke blive trætte af at beundre ham. Navnet Lars bestemte vi først senere, så indtil videre gik han under navnet Lillebror. Vi havde nogle dejlige dage på klinikken, hvor jeg lå sammen med en ung pige på 18 år, der også havde fået en dreng. Jeg var 27 og følte mig gammel sammenlignet med hende. Jeg lærte meget om børnepasning, mens jeg var der, og det var nogle dejlige dage, hvor jeg også fik min nattesøvn, for de kørte babyerne ud om natten. Kl. 5 kørte de dem ind til mødrene igen, og de stunder husker jeg tydeligst. Det var en helt fantastisk fornemmelse at kigge ned til den lille fyr, der lå i vuggen med sine store øjne. Hvor var jeg lykkelig. Ingen kunne være lykkeligere end vores lille familie, følte jeg. Lillebror var meget nem og græd næsten aldrig, men alligevel var det dejligt, at han ville bruge sut. Jeg selv havde ikke brugt sut, men i stedet suttede jeg på tommelfinger og brugte sutteklud, når jeg kom i seng, indtil jeg var en ret stor pige."}, {"type": "figure", "caption": "", "page": 33, "file": "assets/images-bog2/p033_01.jpg", "dim": [697, 470]}, {"type": "figure", "caption": "", "page": 33, "file": "assets/images-bog2/p033_02.jpg", "dim": [679, 464]}, {"type": "para", "text": "De lykkelige forældre med deres 1-dag gamle guldklump           Mor havde syet dette køretæppe – her i brug den 6.12."}, {"type": "para", "text": "Dagen efter fødslen kom mor, far, Per og mormor for at se vidunderet. Mor havde syet et flot lilla patchwork køretæppe med pude og Vagn fik en flaske champagne. Forinden havde Vagn givet mig en mor- og barn-buket. Vi fik i det hele taget mange dejlige gaver af venner og familie. Flere af naboerne kom på besøg, og Grete kom med sin store mave og ønskede, at det snart blev hendes tur. Det blev det den 21. oktober, hvor hun fødte Klaus, en stor dreng på over 4 kg."}, {"type": "para", "text": "Da vi skulle finde et navn til Lillebror, lånte vi en bog med navne og pløjede dem alle igennem. Vi fandt kun to, der kunne komme på tale: Lars og Jens. Vi trak lod og trak Jens, men så bestemte vi os alligevel for Lars. Hvis han var kommet til at hedde Jens, ville han være blevet kaldt op efter min morfar, og vi syntes nok ikke, at han skulle opkaldes efter nogen, så derfor blev det Lars."}, {"type": "para", "text": "Det var dejligt at komme hjem til Spørring den 6. oktober. Vagn kunne desværre ikke tage fri (der var dengang ikke noget, der hed barselsorlov for fædre), så det blev Grethe Poulsen, der hentede os og kørte os hjem. Det var sødt af hende, men hvor ville jeg gerne have haft Vagn hjemme den dag. Jeg følte mig så mærkelig ensom og meget træt. Om aftenen kom Hans fra Hornslet og skulle reparere vores køleskab, men jeg sov på sofaen. Jeg havde ellers glædet mig til at skulle se fjernsyn, for den dag, Lars blev født, fik vi farvefjernsyn. Det var også den dag, harejagten gik ind, og Pelé stoppede med at spille fodbold. Vagn var derfor overbevist om, at der var blevet født en ny fodboldspiller, der skulle afløse verdensstjernen. Sådan skulle det dog ikke gå, for Lars blev danser og ikke fodboldspiller."}, {"type": "figure", "caption": "Lars i bad den 13. oktober", "page": 34, "file": "assets/images-bog2/p034_01.jpg", "dim": [665, 1017]}, {"type": "para", "text": "Derhjemme kom der også mange og skulle se den lille ny, og vi viste ham stolt frem. Om lørdagen kom Vagns familie og så ham, både hans forældre og søskende. Ragnhild havde igen været på spil og bagt en flot kransekage, som vi kunne byde gæsterne."}, {"type": "para", "text": "Lars var kun to uger, da vi kørte nordpå med ham for første gang, op til hans mormor, morfar, farmor, bedstefar og oldemor. Vi havde anskaffet os to sikkerhedsseler, så vi kunne spænde liften fast på bagsædet. Køreturen i bil bekom ham vel – han sov hele vejen, og det gjorde han hver gang, vi herefter gjorde turen. Vi var inviteret i byen i Hvidsted den første lørdag, vi var nordpå med Lars, så farmor var barnepige. Det gik fint, men jeg havde ikke megen ro på mig til festen hos Ellen og Helmer Larsen, så ved midnatstid sagde jeg godnat og kørte hjem for at amme. Da havde Lars sovet, fra vi tog afsted. Senere kunne han sove fra kl. 19 til kl. 3, hvor jeg så tog ham over i sengen og ammede ham. Det var dejligt at mærke den specielle kontakt, der er mellem en mor og et barn, når det bliver ammet, så jeg nød disse stunder. Desværre stoppede amningen efter tre måneder, da jeg skulle på arbejde igen."}, {"type": "para", "text": "Mor tog med os hjem om søndagen og var her i tre dage, hvilket var hyggeligt, og mormor kom ugen efter og var her i en uge. Det var altid hyggeligt at have mormor på besøg, og hun elskede at være her."}, {"type": "para", "text": "Vi fandt en god rytme i hverdagen, og det var en stor glæde hver dag at følge vores lille søn, som udviklede sig, som han skulle og fik prædikatet ”en fin dreng” til 5-ugers undersøgelsen."}]}, {"title": "Barnedåb den 27. november 1977 i Spørring Kirke", "blocks": [{"type": "para", "text": "Vi havde planlagt barnedåb sammen med genboerne, som havde valgt navnet Klaus til deres lille dreng. Vi var tit sammen, også i ugens løb til en kop kaffe, så børnene var vant til hinanden. Poul skulle bære Klaus, og jeg skulle bære Lars. Vi havde lånt Alice og Reinholts kælder til at holde spisningen i, og genboerne skulle spise hos Pouls forældre på gården, som lå under 5 minutters gang fra deres hus. Vi var 22 med Lars. Ud over bedsteforældre og oldemor var naturligvis Per, Tage, Doris, Poul Erik og børn også med. Desuden havde vi inviteret moster, Ib og Jens Christian samt Alice og Reinholt med børn."}, {"type": "para", "text": "Vi havde bestilt Mary Lundkvist til at lave maden. Hun gik ud som kogekone, og Alice havde haft hende flere gange. Vi kendte hende ikke men vidste, at hun og manden Rasmus (Ras) boede på en lille ejendom uden for Spørring. Senere blev de naboer til os, da de i 1984 flyttede ind i nabohuset."}, {"type": "para", "text": "Selvom jeg ikke selv skulle lave maden, var der mange forberedelser til et sådant barnedåb. Jeg lavede selv bordkort, bittesmå lyseblå sokker, som sad på tandstik-strikkepinde. En sådan ufærdig sok var limet på et hvidt kort, hvorpå navnet stod. Grete og jeg var ude og købe nyt tøj til barnedåben, og jeg kunne allerede på det tidspunkt skrue mig ned i en str. 34. Det var utroligt, så hurtigt jeg havde tabt mig igen, når man tænker på, at jeg havde taget 15 kg på under graviditeten. Jeg købte en sort skjorteblusekjole med et lille tørklæde i halsen til at have på i kirken, og til festen bagefter en lang, sort forklædenederdel med en beigefarvet rullekravetrøje indenunder."}, {"type": "para", "text": "Vi var i Trige og tale med præsten, G. Ingemann Jensen. Han var en ældre, mærkelig mand, der havde ord for at kigge lidt for dybt i flasken og også til tider køre sin Folkevogn i beruset tilstand. Engang, da han forrettede en begravelse, faldt han på vej hen til graven og brækkede begge arme, men alligevel gennemførte han begravelsen. Han skulle altså døbe Lars og Klaus. Vi skulle vælge faddere, og valget faldt på Doris og Poul Erik. Det var det naturligste valg for os, for vi havde stået faddere til Charlotte, og ydermere syntes vi, at det skulle være et par, der var gift. I dag kan vi godt se, at det kunne have været ligegyldigt. Men vi tænkte også på, at hvis det værste skulle ske, og fadderne skulle træde til, så kunne Lars ikke få et bedre hjem at vokse op i. Tage og Per elskede også Lars, men Tage var stadig ungkarl, og Per var kun 17 år, og vi skulle naturligvis have flere børn, så deres tur skulle nok komme, troede vi."}, {"type": "para", "text": "Men mor var skuffet over, at Per ikke skulle stå fadder, og set i bakspejlet kunne der jo godt have været fire faddere, så begge familier havde været repræsenteret. Vi vidste jo bare ikke, at vi ikke kunne få flere børn. Jeg tror såmænd ikke, at Per tænkte over det, men mor var aldrig god til at skjule sine skuffelser, så det udviklede sig til et bragende skænderi mellem hende og mig i telefonen. Det endte med, at hun sagde, at hun alligevel ikke kunne bage de flutes, hun havde lovet at bage til forretten. Jeg var meget ulykkelig og ringede som altid, når mor og jeg havde skændtes, til min dejlige mormor for at få trøst. Hun lovede, at hun nok skulle bage flutes for mig, men det reddede jo ikke det dårlige forhold, der var blevet mellem mor og mig. Jeg talte ikke meget med mor inden barnedåben, og luften var kold imellem os. Det var meningen, at mor og far skulle komme dagen før for at hjælpe med de sidste forberedelser, men jeg var rystende nervøs og glædede mig slet ikke. Stor var derfor min glæde og forbavselse, da jeg lørdag middag blev mødt af mor med kys, knus og højt humør. Det føltes, som om intet var hændt – ja, hun havde oven i købet lavet en sang til Lars. Med hvert eksemplar fulgte et stearinlys, som gæsterne skulle tænde og holde, mens de sang, og til slut stille hos Vagn og mig i en hjerteform med sand. Det var en meget smuk sang, og det med lysene skabte en rigtig varm og højtidelig stemning."}, {"type": "para", "text": "Da dagen oprandt, var det mor og Doris, der klædte Lars på i den 80 år gamle dåbskjole fra min fars familie. Lars var den sidste, der blev døbt i den, for den var simpelthen blevet slidt op i vask. Vi transporterede Lars til kirken i liften, men da Vagn skulle løfte den ud af bilen, tabte han den på fortovet, så Lars var ved at falde ud. Der var et kort øjeblik optræk til gråd, men det gik heldigvis i sig selv igen, for vi skulle jo nødig bære et skrigende barn til døbefonten. Jeg husker, at vi sad oppe ved alteret sammen med Grete, Poul og Klaus og så på, at alle gæsterne satte sig til rette i kirken. Det var en stor dag. Vi var spændte på, om præsten ville være ædru nok til at døbe dem ordentligt. Det gik nogenlunde, bortset fra, at han glemte at spørge Poul, om Klaus var hjemmedøbt. Desuden havde han ikke fået fat på, om Klaus skulle staves med K eller C, så efter barnedåben måtte han opsøge dem for at sikre sig, at navnet var stavet rigtigt. Han flakkede derfor lidt rundt på Østervang for at finde familien Andersen, og da han ringede på hos os, kunne vi fortælle ham, at de holdt festen på gården. Jeg husker, at Lars var temmelig tung at bære med sine ca. 5 kg, men begge drenge var flinke under det meste af seancen. Til sidst blev Lars dog utålmodig og sang med på den sidste salme. Lars fik mit mellemnavn og kom til at hedde Lars Møller Christensen."}, {"type": "figure", "caption": "", "page": 36, "file": "assets/images-bog2/p036_01.jpg", "dim": [999, 691]}, {"type": "para", "text": "Efter kirken fik vi champagne på Østervang 25, og Lars fik mælk hos mig. Så blev der taget familiebilleder med Lars i centrum. Reinholt, som var fotograf, stod for dette, og Ib smalfilmede. Gæsterne havde fine gaver med: Af sin mormor og morfar fik Lars årskruset, af Per en indrammet tegning af en lille dreng, af farmor og bedstefar en tinramme og en strikket krave, af Tage, Doris og Poul Erik et hankønstegn i guld med kæde, af Charlotte og Jens Christian en karrusel til at hænge over kravlegården, af oldemor en broderet klokkestreng, af Alice, Reinholt og børnene en sparegris med 15 kr. og af skagboerne en servietring. Desuden var der gaver fra fru Ejlersen, Elbo, Vibeke og Lars, blomster fra Poul Eriks forældre og fra Anna-Lise Grosen, som serverede, og 5 $ fra USA. Kl. 12.30 gik vi op i Alice og Reinholts kælder, hvor der var dækket fint op. Menuen bestod af rejecocktail, vildænder, som Vagn havde skudt, og islagkage. Maden var god, men vi har aldrig fået så små rejecocktails. Det undrede os lidt, for vi havde købt rigeligt ind. Næste dag fandt vi masser af fisk og rejer i Alices køleskab, så vi holdt en lille efterfest om aftenen, hvor vi fik de flotteste stjerneskud. Det var ærgerligt, men typisk for Mary, som var temmelig sparsommelig, grænsende til det nærige."}, {"type": "para", "text": "Som det sig hør og bør, sov Lars sin første søvn i dåbskjolen under de to første retter, men så vågnede han og ville have mad. Vi trak ham af dåbskjolen, og han spiste med ved bordet. Man skulle have troet, at folk var mere blufærdige dengang, men der var ingen, der syntes, det var mærkeligt, at jeg ammede Lars ved bordet. Det ville en mor ikke gøre i dag."}, {"type": "para", "text": "Efter middagen gik vi hjem og fik kaffe og kransekage, som Ragnhild havde bagt. Per og Jens Christian kørte en tur med Lars i barnevognen, dernæst kom turen til Charlotte og Helle, som også syntes det kunne være spændende at trille en tur med dåbsbarnet."}, {"type": "para", "text": "Aftensmaden, som bestod af kold kartoffelsalat og frikadeller, blev indtaget i kælderen, og folk indtog deres tidligere pladser. Kl. ca. 20 sluttede festen og gæsterne tog hjem. Det havde været en dejlig barnedåb. Lars fik efterfølgende noget at spise og sov så til kl. 5.30 næste morgen. Det havde åbenbart været en trættende dag for Lars, for han sov igen fra kl. 10 til kl. 14.30 i barnevognen, så jeg kunne få det hele ryddet op. Det var flinkt af ham."}, {"type": "figure", "caption": "", "page": 37, "file": "assets/images-bog2/p037_01.jpg", "dim": [684, 1012]}, {"type": "para", "text": "Den 5. december fotograferede Reinholt begge dåbsbørnene i sit ”atelier” i kælderen, både hver for sig og sammen, og det blev til nogle fine billeder, som vi kunne glæde familien med til jul."}]}, {"title": "Lars’ første jul", "blocks": [{"type": "para", "text": "Det var dejligt at være blevet forældre, især når barnet var så nemt som Lars. Han græd sjældent, og han var meget nem og smilende, hvilket ses på de billeder, der blev taget af ham. Vi kunne tage ham med overalt og havde sjældent barnepige til ham. Den 20. december havde jeg ham med i Århus og købe julegaver. Det gik fint, og han sov under hele turen."}, {"type": "para", "text": "Den 23. december om aftenen kørte vi traditionen tro op til farmor og bedstefar i Hvidsted. Næste dag pyntede jeg som altid juletræet, og vi fik grønlangkål til frokost. Farmor og bedstefar holdt altid jul sammen med Tage, Doris, Poul Erik og børnene, enten i Hvidsted eller i Svenstrup, og vi holdt altid jul med min mor, far og Per i Thorshøj. Det var lidt uretfærdigt over for Vagns forældre, og jeg tror gerne, at Krista ville have haft os engang imellem juleaften, men som den søde person hun var, brokkede hun sig aldrig. Jeg ville gerne have set mors reaktion, hvis vi ikke var kommet hjem til dem hver juleaften. Men sådan lå landet, og det blev aldrig diskuteret, så på den måde var det nemt. Juleaftensdag kørte vi så til Thorshøj til aften, og for mig var det en helt speciel oplevelse hvert år at åbne døren til dette julehjem. Mor havde pyntet så fint alle vegne, og der var tændt levende lys og hyggebelysning overalt. Der duftede af and og rødkål, og juletræet stod og var flot pyntet af far, og så var der alle gaverne. Det var dejligt at komme hjem til jul."}, {"type": "figure", "caption": "Far og søn den 3. december 1977", "page": 37, "file": "assets/images-bog2/p037_02.jpg", "dim": [1020, 689]}, {"type": "figure", "caption": "Lars i sin skråstol, 8 uger gammel", "page": 38, "file": "assets/images-bog2/p038_01.jpg", "dim": [684, 1022]}, {"type": "para", "text": "Denne Lars’ første jul var naturligvis helt speciel, idet vi nu havde et lille barn iblandt os, som for eftertiden ville give juleaften et pift. Da vi kom, var Lars vågen og i godt humør. Han pludrede og smilede, og alle var glade for at se ham og syntes, at han var blevet stor siden sidst. Lars fik sit fineste tøj på og sad i sin skråstol, så vi kunne se ham, og han kunne se os, når vi spiste. Efter ris à l’amanden opdagede vi, at han havde lavet i bukserne, så det var en kort fornøjelse med det fine tøj. Dengang brugte man ikke engangsbleer som i dag, og stofbleerne var ikke så tætte, så indholdet løb somme tider ud, hvilket det gjorde på denne højtidsaften. Efter bleskiftningen blev han lagt i seng og sov til kl. 24, hvor vi næsten var færdige med at pakke gaver ud."}, {"type": "para", "text": "Vi havde kun købt en bamse til ham, for han havde jo ingen forstand på gaver. Af mormor og morfar fik Lars et Brio tog, et par overalls og en nisse, af onkel Per et pædagogisk rigtigt puslespil, som William nu leger med, når han er her. Oldemor havde broderet et juleophæng, som hang uden for Lars’ værelse i mange år op til jul, af farmor og bedstefar fik han et dejligt tæppe, som vi stadig bruger. Af Jens Christian og Charlotte en natdragt, fra Skagen en politibil og godnathistorier, af Klaus en lille Capri bil, og som rosinen i pølseenden gav onkel Tage ham et elektrisk tog. Det blev starten til en større jernbane, som onkel Tage supplerede hvert år. Vagn og Per var nok i starten mere glade for toget end Lars, men det blev Lars’ kæreste legetøj. Da Tage købte det første til toget, spurgte ekspedienten, hvor gammel drengen var, der skulle have det. Tage kunne ikke få sig selv til at sige, at han kun var 3 måneder, så han sagde 3 år."}, {"type": "figure", "caption": "", "page": 38, "file": "assets/images-bog2/p038_02.jpg", "dim": [662, 1036]}, {"type": "para", "text": "Juledag var vi sammen med mors familie til julefrokost, og om aftenen dansede vi om juletræ i Vestergård, hvor Lars var vågen hele aftenen. Han sad på sin bedstefars knæ, når vi skulle spise, og så godt vigtig ud. 2. juledag var vi til mormors fødselsdag, 3. juledag i Vestergård igen, og 4. juledag havde vi Lars med til Skagen for første gang, hvor vi så smalfilm fra barnedåben, som Ib havde optaget. Billedet her er fra nytårsaften."}]}, {"title": "Lars i dagpleje m.m", "blocks": [{"type": "para", "text": "Efter nytår skulle jeg begynde at arbejde igen, både på Studenterkursus i Ålborg mandag og onsdag, og tirsdag og torsdag på Handelshøjskolen i Århus. Vi havde fået ”sort” dagplejeplads til Lars på Østervang hos Åse Lading, som vi kendte lidt. Den første dag, jeg skulle aflevere Lars, var den 4. januar 1978, hvilket jeg var meget ked af. De 3 måneder var gået alt for hurtigt, og nu da jeg var begyndt at arbejde, kunne jeg ikke blive ved med at amme, så Lars begyndte at få flaske indimellem. Det gjorde det heller ikke bedre, at det var vinter og mørkt om morgenen, og to dage om ugen skulle jeg rigtig tidligt hjemmefra for at være i Ålborg kl. 8. Men Lars var ligeglad, og Åse sagde, at han var nem at passe."}, {"type": "para", "text": "Den 11. januar begyndte Lars at få frugtmos (det kunne man ikke købe færdigt dengang, så det lavede vi selv) og appelsinsaft, og om aftenen fik han kærnemælkssuppe i sutteflasken. Han spiste alt med stor appetit men var især glad for bananmos. Han vejede nu 13½ pund og målte 62 cm. Han sov typisk fra kl. 20 til kl. 6, men mens jeg stadig ammede ham, og han lå i vuggen, vågnede han om natten og skulle have mad. Da det jo var lige ved hånden, tog jeg ham bare op i sengen til mig og gav ham bryst. Somme tider faldt både han og jeg i søvn under måltidet, og når han var færdig og havde bøvset, lagde jeg ham bare tilbage i vuggen, og så sov han videre. Han var en meget mild dreng, der smilede, bare man kiggede på ham."}, {"type": "para", "text": "Om fredagen havde jeg fri, hvilket jeg nød. Jeg hyggede mig rigtigt med Lars i sengen, når Vagn var taget på arbejde. Kravlegården havde vi også stor fornøjelse af. Lars kunne ligge der længe og kigge på alle sine kulørte rangler, bøger og krammedyr, og han faldt tit i søvn og sov sin middagssøvn der."}, {"type": "para", "text": "Det var ikke længe, Lars var i pleje hos Åse. Hun havde længe gerne villet have et rigtigt arbejde, og pludselig fik hun noget tilbudt, som hun ikke kunne sige nej til. Men Åses mand Mogens havde en kusine, Karen Lis, som boede sammen med sin mand Finn og to piger Jane og Lene på Gammel Landevej. Karen Lis var frisør men gik hjemme, og hun ville gerne overtage Lars, hvilket skete den 7. februar1978. Det blev vores lykke, for bedre dagplejemor kunne man ikke finde. Lars blev optaget som et medlem af familien og nærmest betragtet som en lillebror af Jane og Lene, som i 1978 var henholdsvis 7 og 8 år. Lars elskede Karen Lis og den øvrige familie, og det var aldrig noget problem at aflevere ham."}, {"type": "para", "text": "I februar begyndte Lars at få kartoffelmos, hvilket han ikke var begejstret for, så jeg blandede lidt æbler i, hvilket fik det til at glide bedre ned. I en alder af 5 mdr. begyndte han også at få kød. Ud over det allerede nævnte fik han også yoghurt og øllebrød. Dengang var forældre ikke så påpasselige over for, hvad børn spiste, så det var ikke unormalt at give børn is og chokolade. Lars spiste begge dele med god appetit og var ofte smurt ind i chokolade helt op til ørerne. Den 11. februar sov Lars i sin nye tremmeseng for første gang på sit eget værelse ved siden af soveværelset. Det var lidt trist ikke at have ham inde hos os mere, men om morgenen hentede vi ham og hyggede os i sengen, hvis vi ikke skulle ud af døren tidligt."}, {"type": "para", "text": "Den 18. marts vendte Lars sig om på maven for første gang, og han vippede forover i skråstolen, så nu var det slut med at sidde i den."}, {"type": "para", "text": "Den 19. marts blev Lars passet hos sin mormor og morfar i Thorshøj, og det var første gang, vi ikke havde ham om natten. De nød at have ham, hvilket vi sagtens kan forstå i dag, hvor vi selv er bedsteforældre. På det tidspunkt spiste han alt muligt men var især glad for desserter."}, {"type": "para", "text": "Den 20. marts fik vi sat en hoppegynge op mellem køkkenet og spisestuen, noget som børn ikke må bruge i dag. Vi mener nu ikke, at Lars har taget skade af at sidde i den. Det var en dejlig afveksling fra kravlegården og fint at kunne se ham, når jeg arbejdede i køkkenet. I april lærte Lars også at klappe kage og vinke til os, når vi tog afsted."}, {"type": "para", "text": "Lars fik sin første tand den 9. april 1978."}, {"type": "para", "text": "I ”Barnets Bog” har jeg skrevet en slags dagbog, og den 8. juni 1978 står der følgende: ”Der er sket meget, siden mor sidst skrev. Du kan sidde alene nu, og du har lært at kravle, så nu er du overalt. Du kan klappe kage, vinke og vise, hvor stor du er, og så griner du over hele femøren. Du er i det hele taget meget mild og smiler til alle, selv til lægen. Du kan sige ABBA-DADA-MAMMAM, men det betyder vist ikke noget. Du er også flink til at spise. Du er altædende og er blevet flink til at spise kartofler."}, {"type": "para", "text": "For ca. en måned siden var du lidt syg – du hostede meget om natten og kastede op, men om dagen var du i godt humør. Mor kørte til lægen med dig, og han tog en prøve for at se, om du havde kighoste, men det havde du heldigvis ikke, og du blev hurtigt frisk igen. Klaus har været meget syg af meningitis og ligget på hospitalet i 11 dage. Han kom hjem den 21. maj frisk og rask, og det er vi meget glade for. Du var forkølet på det tidspunkt, så mor ville ikke tage dig med derover. Du forærede ham et Brio tog, da han kom hjem, så nu kan I lege sammen med jeres tog."}, {"type": "para", "text": "Den 1. juni begyndte sommeren, og du kunne ligge i barnevognen næsten uden tøj. Samme dag kom Klaus og hans mor og far over til os, og vi spiste grillmad på terrassen. Klaus’ mor havde jordbær med til jer. I sad i barnevognene ved siden af hinanden, og I sad rigtigt og pludrede og grinede ad hinanden. I havde ens kasketter på og så rigtig frække ud."}, {"type": "para", "text": "Du er blevet flinkere til at sove om morgenen nu, for far har hængt et rullegardin op på dit værelse. Du sover fra kl. ca. 20 til kl. 6-7 om morgenen, og du er altid i godt humør, når du vågner."}, {"type": "para", "text": "I tirsdags var du hos Karen Lis for sidste gang i denne omgang. Du havde en blomst med til hende i en brun urtepotteskjuler. Om eftermiddagen væltede du på din pottestol og slog hovedet ned i badeværelsesgulvet. Du græd meget, men det var hurtigt overstået – ikke engang en bule blev der. Du er meget flink til at sidde på potte – du laver aldrig i bleen mere (du kan ikke lide fornemmelsen af at have noget i bleen), og du har siddet på potte, siden du var 5 mdr. (Det var dog først fra januar 1980, at bleen blev droppet fuldstændig)."}, {"type": "figure", "caption": "", "page": 40, "file": "assets/images-bog2/p040_01.jpg", "dim": [667, 1033]}, {"type": "para", "text": "Du har fire tænder nu – to i undermunden og to hjørnetænder i overmunden, så du kan rigtigt bide fra dig. Du har fået sele på i barnevognen, så vi ikke risikerer, at du falder ud.”"}, {"type": "para", "text": "I juni købte vi klapvogn i brunt fløjl og autostol. Alt det udstyr, vi købte til Lars, købte vi gennem Henning Pedersen. Henning handlede med barnevogne og andet babyudstyr, og han gav gode procenter. Lars så godt vigtig ud, når han sad i autostolen midt på bagsædet. På det tidspunkt begyndte Lars og Klaus også at forstå at lege med hinanden, men de ville altid have det samme legetøj. Vi tog også børnene med til byfest med pyntede barne- og klapvogne, og om aftenen, når vi sad i ølteltet, kunne vi godt have barnevognen med."}, {"type": "para", "text": "Da Lars var knap 9 mdr. gammel, rejste han sig op i kravlegården for første gang. Til 10-måneders undersøgelsen vejede han 11,5 kg og målte 77 cm. Lars var meget glad for sin sutteflaske, og havde den med i seng hver aften, men da han var 10 mdr. gammel, tog vi den fra ham uden problemer."}, {"type": "para", "text": "Da Lars var 10 mdr., kunne han stå selv, og den 3. oktober tog han sine første skridt. Den 14. oktober havde han 7 tænder, som han glad viste frem, når han smilede, hvilket han tit gjorde. Når han hørte musik, stod han og hoppede og dansede, så der var nok allerede på det tidspunkt en danser gemt i ham. Desuden ville han gerne spille på min blokfløjte, og da han blev 2 år, fik han en brugt båndoptager af John Kjøller i fødselsdagsgave, en af de bedste gaver det år. Jeg husker selv, da jeg fik min første radio, en brugt B&O transistorradio, af min onkel Erik, da jeg blev 16 år. Den virker stadigvæk. Da Lars var 16 mdr., kunne han sige ”Va’ det?”, ”Buh” og ”Moar”, og da han var 19 mdr. kunne han også sige ”Far (Dar)”. Da han var 22 mdr., kunne han sige ”Mormor”, ”Bedstefar (Bebar)”, ”Helle”, ”Per (Dea)”, ”Bølle” (Alice og Reinholts hund), ”Poul”, ”traktor” og alle dyrelyde. I starten han kunne sige sit eget navn, blev det kun til LAR, da han ikke kunne sige s."}, {"type": "figure", "caption": "", "page": 41, "file": "assets/images-bog2/p041_02.jpg", "dim": [681, 1017]}, {"type": "figure", "caption": "", "page": 41, "file": "assets/images-bog2/p041_01.jpg", "dim": [996, 689]}, {"type": "para", "text": "Klaus og Lars hos Klaus den 27. maj 1979                                            Lars til byfest den 23. juni 1979 Vi måtte på et tidspunkt sætte kravlegården væk, fordi han faldt ud af den. Han var god til at lege med sig selv og legede tit med dyr og bondegård. Derfor var det da også en stor succes, da vi omkring den 1. juli 1979 var nogle dage i København og besøge Erik, Helge og Tove, for vi var bl.a. i Zoologisk Have, hvor Lars var helt fortrolig med dyrene og var helt henne og klappe nogle geder i en mini-zoo. På samme tur var vi også i Christiania og ude at sejle i onkel Helges båd, hvor Lars havde fået en fin lille redningsvest til formålet. En aften spiste vi hos onkel Erik, og det var lidt af en oplevelse. Erik har aldrig været af de hurtigste og ta’r tit tingene, som de kommer. Planlægning er ikke noget, han bruger tid på, men så gi’r det også til tider bagslag. Således denne aften, hvor han havde glemt at tage flæskestegen ud af fryseren. Kl. 22 meddelte han spøgefuldt: ”Så er lynkokken færdig!” Det grinede vi meget af."}, {"type": "figure", "caption": "", "page": 42, "file": "assets/images-bog2/p042_02.jpg", "dim": [683, 1001]}, {"type": "figure", "caption": "Billeder fra turen til København: Til venstre hilser Lars på en isbjørn Til højre får vi en tur i Helges båd", "page": 42, "file": "assets/images-bog2/p042_01.jpg", "dim": [657, 993]}, {"type": "para", "text": "Vagn lavede legehus til Lars i baghaven i november 1979, og i april 1981 kom gyngestativet op ved siden af. Placeringen var nok ikke den allerbedste, idet vi ikke kunne se det inde fra huset. Havde det været uden for køkkenvinduet, ville der nok være blevet leget mere i det, men der var der ikke plads."}, {"type": "figure", "caption": "", "page": 42, "file": "assets/images-bog2/p042_03.jpg", "dim": [1017, 689]}, {"type": "figure", "caption": "Lars får båndoptager af John (Alice til højre) og cykel af onkel Tage", "page": 42, "file": "assets/images-bog2/p042_04.jpg", "dim": [518, 665]}, {"type": "para", "text": "Vi morede os over Lars’ store huslighed. Han kom tit rendende med kost og fejeblad og elskede at støvsuge, og når vaskemaskinen var færdig, hentede han straks baljen, så tøjet kunne blive hængt op. Han begyndte meget tidligt at interessere sig for at se TV, og i en alder af 2 år var Muppet Show hans foretrukne udsendelse. Det var også til hans 2-års fødselsdag, at onkel Tage gav ham en trehjulet cykel. Lars var så glad for sin gave, at den skulle stå ved siden af sengen den første nat, og i starten fik han lov at cykle rundt inde i stuen, mærkeligt nok uden at lave skrammer i møblerne."}, {"type": "figure", "caption": "Til venstre kigger Lars nysgerrigt i vaskemaskinen oktober 1979 Til højre er Lars klar til at gå med bedstefar i stalden den 3. august 1979, på farmors 65-års fødselsdag", "page": 43, "file": "assets/images-bog2/p043_01.jpg", "dim": [662, 1009]}, {"type": "figure", "caption": "", "page": 43, "file": "assets/images-bog2/p043_02.jpg", "dim": [675, 1009]}, {"type": "para", "text": "Udover at lege med dyr var biler naturligvis også et hit. Til det formål lavede onkel Per en kæmpe bilbane på mors gamle voksdug. Der var påmalet veje og grønne områder samt små søer, så når Lars kom hjem til onkel Per, legede de med biler på bilbanen, som var nem at rulle sammen og gemme væk, når der skulle ryddes op. Jo, Lars havde nogle dejlige onkler, der var meget glade for at lege med ham og passe ham. Per havde selv haft nogle super onkler (Helge og Erik), som havde lavet en rød scooter til ham, da han var 4 år. Den eneste forskel, der var mellem den og en rigtig scooter, var motoren, som manglede. Da Lars var 2½ år, lavede Vagn en bondegård i træ til ham, og jeg malede den, nok en af de få gange, jeg har fået lov at male noget. Den var tre-længet, og taget kunne åbnes. Da var der glæde i det lille hjem. Det var også på det tidspunkt, at han begyndte at ville med ud til bedstefars grise. Vestergård den 17. august 1979 Den 12. august 1980 begyndte Lars at gå i legestue to formiddage om ugen. Karen Lis fulgte ham derned og hentede ham igen. Der var aldrig problemer med at aflevere Lars, og han var som en fisk i vandet hos Karen Lis. Jeg var derfor også grædefærdig, da hun i efteråret 1981 meddelte, at hun havde fået arbejde som bibliotekar og ikke længere kunne passe Lars. Jeg kunne naturligvis godt forstå, at hun tog chancen for at komme lidt uden for husets fire vægge, men det var en sorgens dag, da Lars den 30. november 1981 sagde farvel til sin elskede dagplejemor. Heldigvis havde vi opbygget et venskab med Karen Lis og Finn, så vi sås med jævne mellemrum."}, {"type": "figure", "caption": "Poul & Anne Maries Gitte leger med Lars i", "page": 43, "file": "assets/images-bog2/p043_03.jpg", "dim": [996, 673]}, {"type": "para", "text": "Den 1. januar 1982 startede Lars i kommunal dagpleje hos Solvejg Mikkelsen. Han blev hurtigt glad for Solvejg, som havde en søn, Allan, et år yngre end Lars. Reservedagplejemødrene hed Ingrid og Litta. Lars blev passet hos Solvejg indtil den 30. maj 1985. Til afsked gav han hende årskruset. Udover dagplejen var det ikke megen pasning, vi havde til Lars, for vi tog ham ofte med i byen – han var jo så nem. Men det skete, at vi havde Helle Kjøller som barnepige."}]}, {"title": "Sommeren 1978", "blocks": [{"type": "para", "text": "Den 15. juli drog vi med Vagns familie afsted til Norges land. Det var lidt af en sensation, for bedstefar havde ikke haft ferie i 33 år, men nu var det muligt at få gården passet, så nu skulle det være. Vi var 10 personer: farmor, bedstefar, Tage, Doris, som var gravid i 7. måned med Thomas, Poul Erik, Jens Christian, Charlotte, Vagn, Lars og undertegnede. Vi havde lejet et 2-etagers hus på en gård i Valdres med masser af plads til os alle, pris 1560 kr. for en uge. Vi startede om morgenen i strålende vejr i to biler over Frederikshavn-Göteborg og havde en dejlig overfart, hvor vi spiste ta’-selv morgenbord, og bedstefar kom straks i snak med en mand og fortalte ham, at han ikke havde haft ferie i 33 år. På vej gennem Sverige spiste vi vores medbragte frokost i det fri. Først om aftenen kl. 21.15 ankom vi til hytten og hentede nøglen hos Torstein Nordstad, som var bonde og ejede huset. Vi havde mad med til det meste af ugen og hjalp hinanden med at stille det an og rydde op. Hytten lå i smukke omgivelser, så vi gik lange ture, og mændene fiskede. Nogle dage smurte vi madpakker og begav os ud i naturen, bl.a. til Beitostølen og til en sø, hvor selv farmor prøvede at fiske."}, {"type": "figure", "caption": "", "page": 44, "file": "assets/images-bog2/p044_01.jpg", "dim": [478, 719]}, {"type": "para", "text": "Det gik vældig godt med Lars, for der var altid nogen til at tage sig af ham. På førstepladsen stod onkel Tage, og så var der Jens Christian og Charlotte, som også gerne ville køre ham i barnevognen, ja alle ville gerne lege med vores lille guldklump."}, {"type": "para", "text": "Det bedste han vidste var, når Tage eller bedstefar satte ham op på skulderen og red rundt med ham – så var han i sit es. Bedstefar havde fået sig et par kondisko til turen, så han kunne rigtigt gå ture. Når vi kørte, havde vi farmor og bedstefar med i vores bil (den rustfarvede Volvo 240). Farmor og jeg sad på bagsædet med Lars imellem os i indsatsen til barnevognen. Den kunne lige stå på langs imellem os, så det var rigtig hyggeligt. En formiddag fangede mændene 5 aborrer, som blev gjort til et festmåltid, og så kom snapseflasken på bordet. En anden dag blev det til 8 fisk."}, {"type": "para", "text": "Bedstefar fik sig ofte en god snak med bondemanden, som viste ham rundt på gården, og en dag inviterede bonden os med op på sæteren, hvor hans kone boede i to måneder om sommeren. Vi var inde og hilse på hende og se deres hytte. Vi var også på udflugter til Lærdalen, Ryfossen, Hemsedalen, Gol, Heggenes, Fagernes og Hydalen, hvor vi var kommet så langt ud ad alfarvej, at vejen pludselig endte, og der kun var en flok geder at se. Da syntes farmor godt nok, at hun var kommet langt hjemmefra."}, {"type": "para", "text": "Det blev en dejlig og uforglemmelig uge."}, {"type": "para", "text": "Det var helt vemodigt at skulle på arbejde igen i starten af august efter så dejlig en sommer. Lars var blevet godt solbrændt. Han havde været et pragteksemplar på turen til Norge, og vi var meget stolte af ham. Han var begyndt at rejse sig op overalt og havde også fået fine sko, men han ville alligevel hellere kravle eller mave sig frem, hvis det skulle gå stærkt."}, {"type": "figure", "caption": "Charlotte og Jens Christian havde sang med", "page": 45, "file": "assets/images-bog2/p045_01.jpg", "dim": [1025, 694]}, {"type": "para", "text": "Den 12. august fyldte Vagn 30 år, og der blev holdt fest på Østervang for familie og venner."}]}, {"title": "Lars’ 1-års fødselsdag", "blocks": [{"type": "para", "text": "Vi havde besluttet at holde Lars’ første fødselsdag i sommerhuset og invitere hele min familie med overnatning. De kom lørdag formiddag den 30.9.: Helge, Tove og Erik fra København, Edith, Ib og Jens Christian fra Skagen, mormor fra Skæve og mor, far og Per fra Thorshøj, så vi var i alt 13, et uheldigt tal, hvis man er overtroisk. Weekenden blev nu også noget af en blandet fornøjelse og ikke særlig heldig, for det startede med, at mor var sur, fordi Helge og Tove ikke havde takket for indbydelsen til deres sølvbryllup den 24. oktober, men som Helge sagde, var datoen for at give svar ikke overskredet, så han kunne ikke se, det var så forfærdeligt. Så var stemningen ligesom slået an, og efter weekenden lovede jeg mig selv, at aldrig mere skulle de inviteres sammen til vores hjem. Takket være Lars, som jo var dagens midtpunkt den 1. oktober, vendte stemningen lidt, og vi havde det ganske hyggeligt indimellem diskussionerne. Moster Edith og tante Tove havde travlt med at lære Lars at gå, så det var måske takket være dem, at han tog sine første skridt den 3. oktober. Mormor (altså Lars’ oldemor) var god til at made Lars, så den opgave fik hun i weekenden. Lars fik mange gaver, bl.a. et plastiktog af os, en flot træstol med rødt sæde af sin mormor, morfar og onkel Per (den er i dag blevet fixet op i andre farver og står på Williams værelse) og en hjemmestrikket trøje af faster Doris. Inden weekenden havde vi haft Vagns familie på besøg, og efter weekenden kom Karen Lis med pigerne, Alice med børn, og malerens piger til chokolade og kagemand."}, {"type": "figure", "caption": "", "page": 45, "file": "assets/images-bog2/p045_02.jpg", "dim": [581, 728]}]}, {"title": "Julen 1978", "blocks": [{"type": "para", "text": "Vi skulle som noget nyt i Thorshøj have besøg af mormor og onkel Erik juleaften, for ellers skulle de have siddet alene i Skæve, og det syntes mor ikke, de skulle. Da vi kørte fra Vestergård sidst på eftermiddagen den 24. december, var det begyndt at sne voldsomt, og i løbet af aftenen blæste det op til en mindre snestorm. Lars var vældig optaget af juletræet, som far havde pyntet nedenunder, og alt gik planmæssigt og åndede idyl, indtil Lars faldt mod nederste trappetrin i gangen og slog en flænge i panden. Da var klokken 22, og det sneede temmelig voldsomt. Lars skreg ret højt, og det blødte slemt fra panden, så jeg blev dårlig og måtte hen og ligge. Men mor tog straks affære og ringede til vagtlægen, som bad dem komme så hurtigt, de kunne. Det endte med, at Vagn, mor og far kørte afsted til Agersted med Lars, mens vi andre ventede i spænding, til de var hjemme igen. Hvor blev vi glade, da døren gik op, og Lars kom smilende ind i stuen med sutten i munden. Han var blevet lappet over højre øje og var helt stolt over det plaster, han havde fået på. Af gaver det år fik han bl.a. en stor plastiklastbil af Per (den var så stor, at han selv kunne sidde på ladet), en snurretop af bedstefar, en karate natdragt af Jens Christian og Charlotte og et fint strikket sæt tøj med hue af farmor (hjemmestrikket, naturligvis)."}, {"type": "figure", "caption": "", "page": 46, "file": "assets/images-bog2/p046_01.jpg", "dim": [922, 691]}]}, {"title": "Lars’ bedste- og oldeforældre", "blocks": [{"type": "para", "text": "Lars havde i starten af sit liv to oldemødre. Den ene var Vagns bedstemor (farmor), Agnes Christensen, som boede på et plejehjem i Strandby. Det var ikke så tit, vi så hende, men jeg husker hende som en sød gammel dame. Hun var somme tider med i Vestergård, når alle Vagns tanter og onkler var forsamlede, og det var en ordentlig flok, for de var 12 søskende på bedstefars side. Hun havde været enke i 45 år. Den 11. januar 1977 fyldte hun 90 år, hvilket blev fejret med en stor fest den 8. januar med 110 gæster i Kvissel. Kun familien var med. Oldemor Agnes døde den 18. marts 1978, 91 år gammel."}, {"type": "figure", "caption": "Oldemor med sine 3 børnebørn til sin 75-års fødselsdag, 26.12.76", "page": 46, "file": "assets/images-bog2/p046_02.jpg", "dim": [686, 1017]}, {"type": "para", "text": "Den anden oldemor var min mormor, Elna Christensen, som Lars fik et meget nært forhold til. Hun passede Lars, mens vi var til begravelse med Vagns bedstemor Agnes. Vi besøgte hende næsten altid, når vi var nordpå, eller også var hun inviteret til Thorshøj, så vi var sammen med hende der. Hun kom godt ud af det med Vagns forældre og de var virkelig på bølgelængde og snakkede godt sammen. Når hun var i Spørring, blev hun her ofte i nogle dage. Så havde vi ”ung pige” i huset og barnepige. Hun havde ikke noget imod at være alene hjemme, mens vi var på arbejde. Så lavede hun håndarbejde eller stoppede Vagns strømper. Hun lavede også mad og bagte. Hun sagde selv, at vi var nogle af dem i familien, hun helst ville besøge, så det var jo meget smigrende."}, {"type": "para", "text": "Når vi i dag taler om mormor, siger Vagn altid: ”Hun var en dejlig dame”. Han syntes, det var hyggeligt, når hun var her, bortset fra at hun ikke kunne holde mund, når han sad og så en fodboldkamp. Hun kunne også finde på at ringe herned en lørdag aften, lige når vi sad og så en god film på TV. Så indledte hun altid samtalen med at sige: ”Det er noget værre skidt, de sender i fjernsynet i aften, så jeg ville lige ringe til jer!” Jeg nænnede aldrig at sige, at vi sad og så en film, for hun var jo alene og trængte til selskab, men det var ligeså sikkert som amen i kirken, at ringede telefonen en lørdag aften, så var det mormor i den anden ende."}, {"type": "para", "text": "Mormor lavede meget håndarbejde, og hun sad til daglig ved sit spisebord og broderede, samtidig med at hun fulgte med i, hvad der skete ude på vejen. Hun broderede til sig selv, til hele familien, til venner og på bestilling. Hun nåede at brodere 5 bjørnekloer på hørlærred, hvoraf vi fik den ene, og den hang i vores spisestue indtil vores sølvbryllup i 1998, hvor den blev skiftet ud med det billede, vi fik af Vagns mor i gave. Da vi flyttede i nyt hus sidste år (2009), var vi enige om, at bjørnekloens tid var forbi, men vi nænnede ikke at smide den ud, så nu ligger den på loftet i en kasse sammen med andre af mormors broderier, som har udtjent deres værnepligt, bl.a. en pakkekalender til Lars fra 1979, som vi hvert år hængte 24 pakker på, indtil han blev for stor til det. Derefter hang den der uden pakker hvert år, indtil vi flyttede. Lars var også glad for alle sine fire bedsteforældre, og de forgudede ham, hver på deres måde. Mor havde stor erfaring med børn fra børnehaven Bødkergården, hvor hun arbejdede i mange år. Børnene der elskede hende, for samtidig med at hun var sød og rar og forstod at snakke med dem, så satte hun også grænser, og det kan børn godt lide. Far, derimod, var lidt tilbageholdende, men han havde alligevel en tiltrækningskraft på børn, som mor ikke kunne konkurrere mod. Måske var det hans rolige gemyt, som børn faldt for, og så var der jo hans sjove små fingre på højre hånd, som børn gerne ville studere og stille spørgsmål til. Mange troede, at han havde fået dem kappet af i en maskine og ikke var født sådan. Sjovt var det, at mor ofte kunne kalde på Lars og sige: ”Lars, kom hen til mormor!” Men i stedet gik han hen til morfar! Han kunne få lov til alt med sin morfar: rode ham i håret, se hvad han havde i lommerne, kravle overalt på ham og tage hans briller. Far fik tilnavnet ”Pusle-morfar” af Lars, fordi de lavede så mange puslespil sammen. Far kunne godt lide selv at sidde og pusle med puslespil, så Lars gave ham et Lars og morfar 19.8.79                   med 5000 brikker i julegave i 1983. Han havde det på en stor plade, som fik lov at ligge fremme, hvis der da ikke lige kom gæster. Kryds-og-tværs var en anden af hans store passioner, og han ville have elsket alle de quiz-shows, der er på TV i dag."}, {"type": "figure", "caption": "", "page": 47, "file": "assets/images-bog2/p047_01.jpg", "dim": [579, 866]}, {"type": "para", "text": "Da Lars var godt 2 år, blev han passet en hel uge hos sin mormor og morfar, og han var med mormor på arbejde i børnehaven. Derved kom han også til at lære nogle af børnene deroppe at kende. Vi var en uge i England sammen med Grete og Poul (herom senere). Da vi kom hjem, havde Lars lært at sige ”morfar”. Lars fik også lov at hjælpe sin mormor med at bage til jul, og det var hende, der indførte honningkagerne, som vi stadig bager hver jul. I 1985 bagte hun et helt honningkagehus til Lars."}, {"type": "figure", "caption": "", "page": 48, "file": "assets/images-bog2/p048_01.jpg", "dim": [985, 697]}, {"type": "para", "text": "Mor var som sagt eminent til at sy, og hun elskede det. Hun havde sit lille hobbyrum, sin hule, på 5 m2, og der havde hun et bord med sin Bernina symaskine og et skab med stoffer, knapper, lynlåse, alt tilbehør til syning, sit strygebræt og elektriske rulle. Det var et helt under, at hun selv kunne være der, men hun elskede det rum. Hun syede meget tøj til Lars, og det var jeg naturligvis taknemmelig for. Mor mente også, at når Lars var vokset ud af tøjet, kunne vi gemme det, og hvis vi ikke selv fik brug for det, ville Per sikkert gerne have det, når han engang fik børn. Men moden skifter, og Lars var født i den orange, lilla og brune alder, så Per ville sikkert have betakket sig for at overtage det tøj til hans børn i år 2000. Mor fik aldrig at vide, at jeg solgte det meste af Lars’ baby- og børnetøj i ”Den Blå Avis” flere år senere. Vi gemte kun nogle særlige sæt, som vores mødre havde syet og strikket, men resten blev solgt i kassevis til 100 kroner pr. kasse. Det var dejligt, at andre kunne bruge det. Noget af det flotteste, som mor syede, var et patchwork køretæppe og pude i lilla farver, som jeg fik, da Lars var blevet født. Og sjovt er det, at da vores svigerdatter Mette og jeg inden flytningen fra Østervang ryddede op i det tøj, vi havde gemt fra Lars, ville hun gerne have køresættet og noget af tøjet, og det ville bestemt have glædet mor."}, {"type": "para", "text": "Den 24. oktober 1978 fejrede mor og far sølvbryllup. Lars var med til morgenbesøg men blev passet af Nora i Hvidsted om aftenen, hvor vi var til stor fest i Thorshøj Selskabslokaler. Der var 12 sange, bl.a. en sang fra Lars, så middagen trak ud, men det var en dejlig fest."}, {"type": "figure", "caption": "", "page": 48, "file": "assets/images-bog2/p048_02.jpg", "dim": [723, 485]}, {"type": "figure", "caption": "", "page": 48, "file": "assets/images-bog2/p048_03.jpg", "dim": [722, 485]}, {"type": "para", "text": "Lars havde også en særlig plads i sin farmor og bedstefars hjerter. Han nød at besøge dem og følges med bedstefar ud i stalden og laden. Fætter Thomas og Lars har haft mange herlige stunder i ”Vestergård”, både med at lege med halmballer og tælle korn. Farmor kunne man ikke andet end elske, for hun var godheden selv og vidste ikke alt det gode, hun ville gøre for os alle. Nogle gange kunne hun godt køre lidt rundt i børnebørnenes navne, men så indførte Thomas og Lars en bødekasse, så hun, hver gang hun kaldte dem noget forkert, skulle betale 1 krone. Den bedste gave, farmor og bedstefar nogensinde gav Lars, var den store røde traktor, som han selv kunne sidde på og køre. Han fik den juledag 1979, da vi holdt juleaften i Vestergård. Den aften skulle vi ikke synge ret mange salmer, for bedstefar kunne slet ikke vente med at finde gaven, og stor var glæden, da den blev pakket ud. Året efter fik Lars en anhænger dertil, og de to ting blev hans kæreste legetøj, som til sidst blev helt slidt op, men de holdt i mange år, både til ham og Klaus."}, {"type": "figure", "caption": "Lars og Thomas leger i halmen 12.8.84", "page": 49, "file": "assets/images-bog2/p049_01.jpg", "dim": [683, 1022]}, {"type": "figure", "caption": "", "page": 49, "file": "assets/images-bog2/p049_02.jpg", "dim": [1004, 694]}]}, {"title": "Lars’ faster og onkler", "blocks": [{"type": "para", "text": "Min bror Per, som jo er 10 år yngre end mig, havde sin første kæreste Helene med hjemme i 1977, men allerede året efter hed hun Helle og var datter af Anne og Henning i Riis Toft. I marts 1979 blev vi præsenteret for en ny kæreste ved navn Lene, men det holdt ikke længe, og så gjorde Jette Vrængmose sit indtog i december samme år. Hun var fra en gård i Øster Vrå, og mor og far kunne godt lide både hende og hendes forældre. Jette var en dejlig pige, som vi kom til at holde meget af, og hun tog sig altid meget af Lars. Vagns søster Doris og hendes mand Poul Erik havde jo Charlotte og Jens Christian, så vi havde ikke troet, at de skulle have flere børn, men på Charlottes 8-års fødselsdag meddelte Doris, at de ventede barn nr. 3. Det var en dejlig nyhed, og vi kunne mærke, at de virkelig glædede sig. Den 17. oktober 1978 kom Thomas til verden, og han og Lars fik rigtig stor fornøjelse af hinanden. For Lars var Doris altid faster Doris, og Vagns bror Tage var onkel Tage. Desværre har vi ikke Doris hos os mere, men Tage er stadig for Lars onkel Tage eller bare Onkel, og det gode og nære forhold er bevaret."}, {"type": "figure", "caption": "", "page": 49, "file": "assets/images-bog2/p049_03.jpg", "dim": [1017, 691]}, {"type": "figure", "caption": "", "page": 50, "file": "assets/images-bog2/p050_01.jpg", "dim": [385, 530]}]}, {"title": "Den øvrige familie", "blocks": [{"type": "para", "text": "Vi har altid været nært knyttet til mors familie, og mine to onkler i København, eller rettere sagt Greve Strand, snakkede godt med Vagn. Der var en gensidig respekt, og Tove gjorde ingen fortræd, så det var behageligt at være sammen med dem. Derfor besøgte vi også hinanden engang imellem. Erik var fortsat ungkarl og havde ingen kone eller kæreste, så når vi besøgte dem, var vi oftest alle hos Helge og Tove. En weekend husker jeg tydeligt, nemlig den 31. august 1973. Vi sad hos Helge og Tove og så farvefjernsyn, da de sagde i nyhederne, at Hotel Hafnia brændte (natten til den 1. september). Næste dag var vi inde i København og se det nedbrændte hotel. Det gjorde indtryk. Det var en af de begivenheder, der virkelig rystede danskerne. 35 mennesker indebrændte. Evnesvage 38-årige Erik Solbakke Hansen, som havde påsat branden, og som havde meget andet på samvittigheden, blev idømt forvaring for livstid. Bagefter diskuterede man skylden. Der var nemlig to hold af skyldige: brandstifteren på det ene hold og politikere og brandsynsmyndigheder på det andet. Hold et tog det mange år at finde (skete 1986): Pyromanen blev tilfældigvis taget under en pyromanbrand på Hillerød Station. Han havde mange brande på samvittigheden og til stor overraskelse for alle fortalte han mangt og meget, ting som ingen havde anelse om med i alt 38 døde og skader for 138 mio. kr. (f.eks. storbrandene AspHolmblad, Pia Lys, mm). I 1980 dræbte han en 15-årig pige på stranden på Fanø efter et voldtægtsforsøg. Dette drab medførte en af de helt store eftersøgninger i Danmark, og aviserne var i lang tid optaget af dette sensationelle drab.  Men tilbage til branden: Med 120 brandfolk i arbejde, blinkende politibiler og hylende ambulancer på gaden var alt kaos. I røgfyldte værelser søgte gæsterne hen til vinduet og ventende på at blive taget op i en af brandvæsenets redningskurve. Hotellet var bygget i 1899, men de skiftende ejere havde sagt nej til at bære udgifterne ved at installere sprinkleranlæg. Husets eneste beredskab var et par vandspande. Hverken brandstiger eller vogne kunne komme ind i hotellets lille gårdhave. Af brandens 35 ofre havde de fleste netop haft værelser ud mod gården. De blev indespærret og døde af røgforgiftning. Bemærk den stakkel i vinduet i midten - klar til spring. Personen på gesimsen under prøver fortvivlet at hjælpe. Som ung havde Erik haft et godt øje til en Skagens-pige, Lene Kjær, men Erik har aldrig været af de hurtigste, så det var ikke rigtig blevet til noget. I julen 1973 var hun imidlertid med ham i Skæve, så nu håbede vi alle på, at det kunne blive til noget mellem dem. Problemet var, at Erik boede i Greve og Lene i Skagen, og ingen af dem ville flytte. Lene boede, og bor den dag i dag, i et gammelt skagenshus, hendes barndomshjem. Rygtet siger, at Lene følte sig forpligtiget til at blive hjemme og passe forældrene, fordi hun selv havde været syg som barn og derfor følte, at hun skyldte forældrene noget. I hvert fald var det moderen, der fik skylden for, at forholdet ikke holdt, ifølge mosters forklaring, men om den holder i byretten, ved jeg ikke. Hvorom alting er, så holdt forholdet ikke, og Lene fik en søn i 1977, Lasse, som Erik ikke var far til. Da vi i 1991 inviterede til Lars’ konfirmation, ringede Erik for at høre, om han måtte tage Lene og Lasse med, så da havde de fundet sammen igen. Heller ikke denne gang holdt det, men for nogle år siden, fandt de sammen for jeg ved ikke hvilken gang, og nu ser det ud til at fungere, selv om Lene bor i Skagen og Erik i Greve. Men nu er Lenes forældre borte, Lasse har fået kæreste og barn, Lene og Erik er ikke på arbejdsmarkedet længere, så nu er der ingen forpligtelser, bortset fra huset og annexet, som lejes ud. I perioder er de i Skagen og i perioder i Greve, og jeg tror, de har det godt sammen på den måde."}, {"type": "para", "text": "På min fars side var kontakten knap så god, og efter farmors død i 1973 sås vi ikke så ofte. Jeg har noteret, at vi besøgte Grethe og Peter i Mellergård i 1973. Det har sikkert været før vi blev gift, for mor havde fortalt i familien, at Vagn ikke ville have nogen med til brylluppet, han ikke havde besøgt, så Grethe har nok tænkt, at de hellere måtte invitere os."}, {"type": "para", "text": "Hvis der var nogen, der stod højt på listen af mors familie, så var det Emma og Maltha (morfars bror, som var slagtermester i Nørresundby). Maltha blev syg i vinteren 1977. Han havde tidligere haft blodpropper, men denne gang var det alvorligt. I den tid, jeg arbejdede i Ålborg, tog jeg somme tider på besøg hos dem, og senere besøgte jeg Maltha på sygehuset. På det tidspunkt var jeg gravid, og Maltha fulgte meget med i processen. Han lå syg i flere måneder på grund af sin pacemaker, som forhindrede ham i at dø. Til sidst, den 26. april 1980, bukkede han dog under, men da var Emma også blevet utrolig tynd, fordi det havde været så opslidende en periode for hende."}]}, {"title": "Meretes arbejde", "blocks": [{"type": "para", "text": "I januar 1976 var jeg blevet færdig som cand.mag. i engelsk og fransk, så jeg regnede blot med, at jeg kunne få en stilling på et gymnasium. Jeg skrev mange ansøgninger, men det var blevet svært at få stilling som gymnasielærer, så det meste, jeg fik ud af det, var en andenplads til en stilling. Det kunne jeg ikke rigtigt bruge til noget. Jeg havde flere ansøgninger ude, da vi om sommeren tog til USA, og som tidligere nævnt fik jeg jobs i Århus og Ålborg."}, {"type": "para", "text": "Jeg startede på Handelshøjskolen som timelærer den 1. september 1976 og var ansat der til sommeren 1994. På slutningen af min graviditet fandt jeg ud af, at der ikke var noget, der hed barselsorlov, når man var timelærer. Jeg kunne få 14 dages fri i forbindelse med fødslen. Det var lidt hårdt, men jeg protesterede ikke. Det gjorde mine klasser, derimod. De bestod næsten udelukkende af piger, og de syntes, det var urimeligt, at jeg skulle gå på arbejde, når jeg havde sådan en lille størrelse derhjemme. Protesten resulterede i, at jeg efter en uge på arbejde kunne holde fri til den 1. januar 1978, samme periode som jeg havde barselsorlov fra mit andet job, som jeg nu vil komme ind på."}, {"type": "para", "text": "Fra den 1. august1976 til den 1. august 1978 arbejdede jeg på Ålborg Studenterkursus. Selvom det kun drejede sig om to år, var det en af de bedste perioder i min karriere som lærer, og det på trods af, at jeg skulle køre i tog frem og tilbage to gange om ugen. Jeg havde mine 12 timer fordelt på to dage, og jeg var først hjemme sent om aftenen, fordi jeg også havde mellemtimer. Grunden til, at jeg faldt så godt til, var først og fremmest deres rektor, Sten Nordhagen. Han var jordens flinkeste mand og viste stor interesse for hver enkelt ansat. Lærerstaben var lille, og vi kom hinanden ved. Når der blev holdt personalefest, var ægtefællerne inviteret med, og selv Vagn, som ikke yndede den slags selskabelighed, følte sig godt tilpas blandt mine kolleger og deres ægtefæller. Eleverne var også vældig rare, og da jeg havde fået Lars, samlede de ind til gave, og en af mine klasser tog turen til Spørring på barselsvisit. Jeg kunne godt have beholdt jobbet, hvor jeg underviste i både engelsk og fransk (jeg førte en klasse op til studentereksamen i fransk), for jeg fik tilbudt en fuld stilling i sommeren 1978. Vi var ikke indstillet på at skulle flytte, så jeg sagde med beklagelse nej tak. I stedet fik jeg et barselsvikariat på Skanderborg Amtsgymnasium fra den 1.8.78 til den 20.11.79 (15 timer/ugen), og det var noget af en omvæltning, da det var et ret nyt gymnasium med unge venstreorienterede lærere, der gik i sundhedssandaler og hønsestrik og havde lapper på bukserne. Da Vagn også her var inviteret med til personalefest, fik han sit livs chok, og han har aldrig senere deltaget i lignende arrangementer."}, {"type": "figure", "caption": "", "page": 52, "file": "assets/images-bog2/p052_01.jpg", "dim": [652, 694]}, {"type": "para", "text": "Jeg burde have vidst bedre, men jeg ville jo have, at min mand så pæn ud, når jeg skulle præsentere ham, så jeg udstyrede ham med habit og slips. Til sin forfærdelse så han, at han var den eneste i en sådan mundering. De andre mænd havde slidte eller lappede cowboybukser på og ternede skjorter med halsklud samt sandaler, så han faldt lidt igennem på det punkt. Konversationen gik heller ikke så glat som i Ålborg, for de, som Vagn sad ved siden af, kunne kun snakke fag, så allerede der var han koblet af. Jeg syntes nu heller ikke, jeg følte mig så godt hjemme, og jeg tænkte med længsel på mine dejlige kolleger fra Ålborg. Det var sidste gang, jeg udsatte Vagn for en sådan pinsel."}]}, {"title": "Vagns arbejde og fusk", "blocks": [{"type": "para", "text": "I 1973 arbejdede Vagn for tømrerfirmaet A.J.Andreasen. Vagn var og er en dygtig tømrer, og jeg husker kun én gang, at han er gået arbejdsløs. Han kunne lide sit arbejde og var ikke bange for at tage fat – det havde han jo lært hjemmefra. Det resulterede også i, at han altid havde noget at lave i fritiden. Sommetider sagde han spøgende, at han i sit næste liv ville være graver, for så var der sikkert ingen, der ville bede ham om at lave fusk. Jeg var til tider træt af alt det, han lavede for andre, for det gik også ud over mig. Han havde jo aldrig tid til at hjælpe med noget derinde. I de tilfælde, hvor det var gensidig hjælp, var det OK, men der var også mange tilfælde, hvor hjælpen kun gik den ene vej, og han var alt for beskeden til at forlange noget for sit arbejde. Af større projekter, han var involveret i, kan nævnes tilbygningen hos Doris og Poul Erik i Svenstrup fra den 21. september til den 7. december 1973, hvor han var deroppe i 10 weekends og arbejde. Projektet fortsatte ind i det efterfølgende år, hvor der var bilfrie søndage på grund af energikrisen, så vi kunne først køre hjem efter midnat. Huset blev rigtig dejligt, da de var færdige. Kort tid efter gik han i gang med at hjælpe Alice og Reinholt med at bygge til deres hus, som var blevet for lille til en familie med tre børn, så de fik bygget til og lavet kælder, hvilket også blev rigtig dejligt. Da de var færdige, holdt de kombineret færdiggilde og kobberbryllup."}, {"type": "para", "text": "Vi var kommet ind i en stime med tilbygninger, for i 1976 gik mor og far i gang med at bygge oven på deres hus. Mor ville gerne have en stor stue ovenpå og et stort værelse til Per samt et pulterum, men det var nu begrænset, hvad Vagn kom til at hjælpe med. De tog Elbo til at lave tømrerarbejdet og Lau til at lave el. Vagn hjalp til med at tage tagplader af huset og slog trælofter op, men hele sommeren 76 var vi jo i USA, så der havde han fri. Resultatet blev flot, og mor og far havde megen fornøjelse af pladsen. Der blev naturligvis holdt færdiggilde, hvor alle håndværkerne med påhæng og andre, der havde hjulpet til, var inviteret."}, {"type": "para", "text": "I 1977 hjalp han Poul (genboen) med at bygge garage i september/oktober og støbte mødding i Vestergård den 15. oktober. Den 21. april 1978 hjalp han far med at lave ”legehus” til redskaber, og i april/maj samme år hjalp han Hans i Hornslet med at bygge til huset. Samme år i juli stod den på nyt badeværelse i Vestergård, og i november byggede han carport for vores naboer Ellen og Ras. Inden Ellen og Ras byggede huset, købte vi 250 m2 jord af dem, så vi kunne bygge til. Heldigvis var Vagn forskånet for alvorlige arbejdsulykker. I 70’erne husker jeg kun en enkelt gang, den 23. juli 1979, hvor han faldt ned ude på arbejde og trykkede et ribben. Dagene derefter skulle man ikke sige noget sjovt, for det gjorde ondt at grine."}]}, {"title": "Ferier i 70’erne", "blocks": [{"type": "para", "text": "I sommeren 1975 var vi to uger i Valdres i Norge sammen med mor, far og Per. På vej derop besøgte vi mors penneveninde Agathes forældre, Hr. og Fru Bjørnstad, i Lillestrøm. De boede i et dejligt nyt hus, og vi blev modtaget og beværtet som kongelige. Agathe og hendes mand, Harald, var der også med deres tre børn, Kathrine, Anders og lille Cecilie på 1½ år. Sidstnævnte forelskede sig i far og ville kun sidde hos ham. Vi fik en dejlig alkoholfri frokost, men Vagn og far kunne ikke komme sig over, at de skulle drikke ingefærøl til maden. Dette venskab med Agathes familie bevarede vi alle, og vi er stadig på jule- og feriekort med Agathe og Harald, som nu nyder deres otium det halve af året i Spanien."}, {"type": "figure", "caption": "", "page": 53, "file": "assets/images-bog2/p053_01.jpg", "dim": [993, 689]}, {"type": "para", "text": "Den første hytte, vi havde lejet, lå i Nøsen helt oppe på sæteren, hvor fårene og køerne gik lige uden for vores vinduer. Alt var meget primitivt men hyggeligt, og vi havde udsigt til sne og vand. Der var et gammelt komfur i køkkenet og ingen toilet eller indlagt vand. Vi måtte vaske os ved en slange udenfor i iskoldt vand. Det blev ikke til mange bade eller hårvask i den uge. Vi havde 9 km til købmanden og skulle betale 5 kr. i bompenge for at komme dertil. Til gengæld fik vi pengene refunderet, hvis vi købte for over 75 kr. Tiden gik for mændene med at fiske, tidligt om morgenen og om aftenen, men det blev kun til en halv snes lækre aborrer. Mor og jeg gik mange ture, mens mændene fiskede. En dag kørte vi en lang tur på 400 km via Geilo til Vøringfossen, som var et betagende syn. Vi kørte igennem Måbødalen, der består af 7 km sving og videre til Eidfjord og Hardanger Fjord. På mors foranledning var vi naturligvis inde og se nogle stavkirker. Da vi havde været i hytten i en uge, kørte vi 65 km til en lille by, der hed Vang i nærheden af Beitostølen. Her havde vi lejet et luksussommerhus i den sidste uge, og nu kunne vi komme i bad. Det var dejligt med den nye hytte, men vi savnede atmosfæren fra den første uge. I den sidste uge kørte vi også en lang tur på 400 km til Lærdalselven, hvor kun de rige har råd til at fiske. På samme tur oplevede vi at komme ud på en bræ, Nigardsbreen, og vi boltrede os i sneen i Årdal. Den 24. juli fyldte Per 15 år. Mor havde bagt boller, kringle og lagkage, og vi fik kakao. Per glædede sig vist mere til at skulle hjem til sin nye knallert. På turen fik far tilnavnene ”guiden” og ”meteorologen”, sidstnævnte sikkert fordi han gik meget op i, hvordan vejret blev, og førstnævnte sikkert fordi han var så dårlig til at finde vej."}, {"type": "para", "text": "I sommeren 1979 var vi igen i Norge, denne gang sammen med Alice, Reinholt og deres børn, Per, Helle og John på hhv. 15, 14 og 9 år. Vi skulle sejle fra Frederikshavn kl. 6.30 den 9. juli, så vi kørte op til Vagns forældre aftenen før og overnattede der. Vi kørte naturligvis i to biler, vores rustfarvede Volvo og Reinholts hvide Taunus med sort tag. Den første dag brækkede Reinholt tændingsnøglen, så på resten af turen måtte han starte bilen med en skruetrækker. Vi havde lånt Reinholts søster Aases hytte ned til Tunhovdsøen. Aase boede i Oslo, så vi skulle på vejen ind og hente nøglen hos hende. Det havde hun imidlertid glemt, så hun var ikke hjemme, da vi ankom kl. 16.30. Så var gode råd dyre. Vi ringede på hos naboen, som forbarmede sig over os og bød på saftevand og kage i haven, da der var meget varmt. Vi opgav at vente på Aase og kørte kl. 18 videre i håb om, at Gro, som var nabo til hytten, lå inde med en nøgle og var hjemme, når vi kom ved 22.30-tiden. Det var hun heldigvis. Vi kunne ikke køre helt ned til hytten, så vi måtte slæbe al bagagen ½ km gennem regnvejr, mulm og mørke, så humøret var ikke så højt. Næste dag så det hele lysere ud. Hytten var gammeldags uden el og vand, men den var hyggelig med pejs, brændeovn og petroleumslamper, og vi var heldige med vejret alle 14 dage, ellers havde det nok ikke været så sjovt at skulle ned til søen og vaskes i isnende koldt vand."}, {"type": "figure", "caption": "", "page": 54, "file": "assets/images-bog2/p054_02.jpg", "dim": [638, 519]}, {"type": "figure", "caption": "", "page": 54, "file": "assets/images-bog2/p054_01.jpg", "dim": [691, 472]}, {"type": "para", "text": "Søen lå lige neden for hytten, og der var den fineste sandstrand, hvor Lars og John kunne boltre sig med at grave hinanden ned i sandet. ”Lille Lars” var i sit es (Lars Morgenstjerne var ”Store Lars”). En dag kørte vi alle en tur på 250 km hver vej for at besøge mor, far, Vibeke og Elbo, der var på ferie sammen i Bjørnstads hytte i Feiring ved Minnesund. Vi ankom kl. 15 og kørte derfra igen efter aftensmaden kl. 20. Vi havde en hyggelig dag, og Lars nød især at sidde på sin morfars arm. En dag fik vi besøg af Reinholts søster Mie, hendes mand Poul og deres datter Charlotte. Til hytten hørte der en båd, som vi også sejlede i engang imellem, og Per og Vagn fiskede derfra. Vi var en dag i Geilo, hvor vi kørte op med stolehejs, og en anden dag kørte vi til Vøringfossen. Vi tilbragte megen tid ved søen, hvor vi solede os i sandet og lavede sandkager (også de voksne). Vi havde medbragt det meste af maden, da alting også dengang var dyrt i Norge, men vi måtte jo ud og købe kød engang imellem. Det blev også til hvalbøf en dag, hvor Alice og Reinholt skulle stå for maden. På vej til færgen i Göteborg besøgte vi Aase i Oslo, og denne gang var hun hjemme. I Oslo skulle vi mødes med Lars Knudsen, som skulle have et lift med os til Frederikshavn. Det havde været en fantastisk ferie, og Lars var rigtig blevet forkælet af vores dejlige venner og deres søde børn. Den 14.-19. oktober 1979 tog vi til England sammen med genboerne. Lars blev passet i Thorshøj, og Klaus blev passet af Pouls forældre. Vi kørte i vores rustfarvede Volvo og skulle sejle EsbjergHarwich. Overfarten var sjov. Vi startede med at gå på pub og spiste derefter i cafeteriet. Vi handlede og sluttede aftenen af med musik og dans ovenpå. Der røg nogle drinks indenbords, bl.a. en drink der hed ”60 knots”, så næste morgen var Poul ikke med ved morgenbordet. Han dukkede dog op senere, hvor vi gik ud på dækket og slikkede sol i liggestolene. Der var fantastisk varmt, og varmen fortsatte de næste dage. Vi var i Harwich kl. 14, og kl. 17 ankom vi til Bell Hotel i Thetford, Norfolk. En dag kørte vi til London, en tur på 4 timer på grund af tæt trafik den sidste 1½ time. Vi spadserede rundt og var bl.a. i Mme Tussaud’s Vokskabinet, hvor jeg blev fotograferet sammen med H.C.Andersen, Poul med Sophie Loren og Vagn med Liza Minelli. Der blev også tid til at shoppe, og tøj var meget billigt, så Grete og jeg fik garderoben suppleret op. En anden dag kørte vi til Oxford, hvor Poul skulle på besøg hos Fiat. Mens vi holdt parkeret i Oxford og så Universitetet, fik vi en P-bøde på 6 £, som vi aldrig betalte. Den dag, vi forlod hotellet og kørte mod Harwich, skulle Poul besøge Ford og have nogle reservedele med hjem (disse reservedele var anledning til turen). Vi stoppede i Chelmsford, hvor Grete og jeg fik tre timer at shoppe i, mens mændene hentede reservedele. Da de kom tilbage for at hente os, måtte vi kante os ind på bagsædet, som var godt fyldt op med reservedele, samtidig med at bagageklappen ikke kunne lukkes. Aldrig har Volvoen været så tæt proppet til. Hjemturen blev lidt lang og dramatisk, da vi om morgenen blev vækket af en stemme, der annoncerede, at pga havnestrejke i Esbjerg, ville vi i stedet gå i land i Cuxhaven i Tyskland. Dette betød, at vi skulle køre den lange vej hjem fra Tyskland og videre til Thorshøj op til Lars. Vi var virkelig trætte af situationen, for vi længtes alle så meget efter vores små poder, og nu ville der yderligere gå mange timer, før vi så dem. Vi spiste morgenmad på rederiets regning og fik udleveret en kuvert med 70 DM til benzin som et lille plaster på såret. Mens vi havde været væk, havde Lars lært at sige ”morfar” (”morbar”)."}, {"type": "figure", "caption": "", "page": 55, "file": "assets/images-bog2/p055_01.jpg", "dim": [1023, 694]}]}, {"title": "Historiske begivenheder", "blocks": [{"type": "para", "text": "• Olsen-Banden-filmene bliver populære Huset på Christianshavn-serien bliver populær • • Oliekrise og bilfrie søndage, den første d. 26. november 1973 • Øl-strejke Watergate-indbrud og -skandale • • Richard Nixon træder tilbage Slut på Vietnamkrigen • • Frygt for atomkrig • Høj inflation • Høj arbejdsløshed PC-revolutionen • • Lommeregneren gør regnestokken gammeldags • Disco og punk/punk rockmusik Microsoft bliver grundlagt • • Bombemanden fra Gladsaxe placerer bomber på døre i telefonbokse i Københavnsområdet Margaret Thatcher bliver premierminister • • Christiania området bliver besat af slumstormere i 1971 • Apple Inc. bliver grundlagt • Hot pants i Folketinget: I marts 1971 tog en journalist og pressefotograf et billede af det unge socialdemokratiske folketingsmedlem Lene Bro. Hun stod uden for sit kontor iført tidens hotteste mode: korte shorts – hot pants – lange hvide støvler og maxi-cardigan. Fotografiet af Lene Bro vakte opsigt i både dansk og udenlandsk presse: Ingen kunne forestille sig, at en smart pige også kunne være klog, eller at kvindelige politikeres arbejdstøj kunne være moderigtigt. Journalisten overtalte Lene Bro til at lade sig fotografere på Folketingets talerstol, selv om hun aldrig havde haft hot pants på inde i tinget. Sagen var så opsigtsvækkende, at japansk fjernsyn inviterede Lene Bro til at deltage i et spørgeprogram om forskellige personers tøj og erhverv. Hot pants blev lanceret af den engelske designer Mary Quant i 1971."}, {"type": "para", "text": "Regeringen indfører sommertid i 1979 •"}]}]}, {"id": "1980erne", "title": "1980’erne", "chapters": [{"title": "Livet i Spørring i 80’erne", "blocks": [{"type": "para", "text": "Først i begyndelsen af firserne begyndte Århus Kommune at interessere sig for udvikling af lokalområderne. Det lykkedes os at blive udlagt som aftale-by i den første Kommuneplan for området, hvilket ville sige, at vi kunne få en begrænset udvikling på 10 boliger over en fireårig periode. Byrådet besluttede i slutningen af 1985, at der skulle udarbejdes bevarende lokalplaner for de landsbymiljøer, der efter kommuneplanen var bevaringsværdige. Spørring blev, så vidt vides, den første landsby, som stadsarkitektens kontor gik i gang med at lave lokalplan for. Spørring Borgerforening blev tilbudt at være med i hele planlægningsfasen. Den 6. december 1989 vedtog Århus Byråd lokalplanen. Plangrundlaget for de ønskede byggeprojekter, bl.a. Hjulbyhegn, som er et socialt-økologisk samfundsforsøg, og andelsboligerne Spørringgård bag ved Brugsen, var dermed på plads."}, {"type": "para", "text": "Et landsplandirektiv pålagde i 1984 alle kommuner at udarbejde varmeplaner for landsbyer ned til 200 husstande. Spørring Borgerforening modtog et oplæg fra kommunen med tilbud om hjælp til selv at etablere en fælles varmecentral for Spørring by, baseret på enten halmfyr, varmepumpe (vand fra Spørring Å) eller naturgas. En spørgeskemaundersøgelse viste, at de fleste ville have naturgas. De mange forurenende oliefyr kunne slukkes, og den enkelte husstand kunne spare op mod 40% på varmeregningen. Det ville gavne den enkelte husstand og gøre det mere attraktivt at bo eller bygge i Spørring, hvilket igen ville fremme mulighederne for, at Lokalplanen blev en succes. Varmen skulle produceres på et biogasanlæg, som kom til at ligge ved Motorvejen/Bjergagervej. I dag er prisen på fjernvarme i Spørring den samme som i den øvrige del af Århus Kommunes forsyningsområde. Det viste sig dog desværre, at der blev gener ved anlægget. Der var og er først og fremmest lugtgenerne, som dog blev forbedret efter en større ombygning, men det er en stående joke, når nogen spørger, hvor Spørring ligger, at sige: ”Når det begynder at lugte på motorvejen, er du kommet til Spørring”. Det værste var dog i februar 2004, hvor Spørring Å kom på forsiden af alle aviser. Der skete et gylleudslip fra anlægget, og via afvandingskanaler og drænrør løb gyllen ud i Spørring Å. Alle fisk i åen døde på en 10 km lang strækning til Lilleåen. Også her skete der væsentlige skader, og selv i Gudenåen kunne man måle forureningen."}, {"type": "para", "text": "Uden for Spørring er der en grusgrav, som flere gange har været truet af at blive inddraget til støjende aktiviteter. I den sidste halvdel af 1980’erne og første del af 1990’erne måtte Spørring bøvle alvorligt med myndighederne for at undgå, at der blev placeret et meget stort skydebaneanlæg i den gamle grusgrav. Der var tale om et anlæg med 56 baner og planlagt i alt 700.000 skud om året. 50 dage om året skulle der være mørkeskydning til kl. 24, og skydningen ville i øvrigt hovedsageligt foregå i folks fritid, dvs. på hverdage efter kl. 15.30 samt på lørdage/søndage otte gange om året. De 500.000 militære skud ville fortrinsvis afgives af rifler og maskingeværer, halvdelen af de 200.000 civile skud skulle afgives af rifler. Det var jo noget af et monstrum at få placeret 300 m vest for byen. Vi har heldigvis altid haft en stærk Borgerforening i byen, og sammen med oprørte Spørringborgere arrangerede den forud for et byrådsmøde en demonstration mod skydebanen i juni 1986 foran Århus Rådhus. Vi ville ikke sidde på vores dejlige terrasser om sommeren og få ørerne tudet fulde af skydegale folks vanvittige fritidsinteresser. Spørring var på det nærmeste lukket, da man tog afsted i chartrede busser og private biler. Medierne inkl. landsdækkende TV var parate og viste historien stor bevågenhed. Aktionen virkede sammen med en del andre tiltag, og projektet blev afblæst. Ud over demonstrationen sørgede Borgerforeningen også for, at der blev indsamlet 18.000 kr. ved husstandsindsamling, så der var penge til at betale Jysk Teknologisk Institut for en uvildig støjrapport, og der blev nedsat arbejdsgrupper, som gik i dialog med Kommunen."}, {"type": "figure", "caption": "", "page": 57, "file": "assets/images-bog2/p057_01.jpg", "dim": [1007, 694]}, {"type": "para", "text": "Skydebanen forsøgte flere gange derefter at komme op til overfladen igen, indtil den for alvor døde i 1994."}, {"type": "para", "text": "Senere har man forsøgt med motocross bane, men heller ikke her var stemningen god. Vi har heldigvis stadigvæk en grusgrav, og alle trusler om lufthavne og andre støjkilder er Poul og Vagn klædt ud som damer til gadekampe i 1981                 manet i jorden."}]}, {"title": "Naboer og venner", "blocks": [{"type": "para", "text": "Selv kunne vi godt lide at larme, og vi holdt fortsat sammenskudsgilder, men måske knap så vilde som i 70’erne. Vi hyggede os med vennerne og følte, at vi havde et godt netværk omkring os. Vi havde i flere år været efter Poul, fordi de ikke var gift, og vi havde på fornemmelsen, at det var Poul, der var skyld i, at de stadig levede på polsk. Den lange kjole, som jeg købte i USA i 1976 med henblik på deres bryllup, var allerede umoderne, og det fortalte jeg ham. Men så pludselig kom invitationen, og det skulle være i Spørring Kirke med efterfølgende fest på Spørring Hotel den 22. november 1980. Det blev et bryllup med Klaus som fin brudesvend, og vi havde naturligvis en sang med. Den 3. september 1986 fik de en dejlig pige, som de døbte Pernille den 2. november. Vi var naturligvis med til festen, som blev holdt på Spørring Hotel. Allerede den 4. september var jeg inde og se til mor og barn på klinikken. Det var lidt svært for mig, for jeg havde lige mistet far, og jeg ville så gerne have en pige men kunne ikke blive gravid. Men vi glædede os på deres vegne og fik da også lov til at passe Pernille engang imellem. Selvom vi betragtede genboerne som nogle af vores bedste venner, var vi oftest sammen hverdagsaftner til en kop kaffe eller et måltid mad men sjældent på ture eller andre oplevelser, med undtagelse af Englandsturen i 1978. En enkelt gang var vi i biografen sammen (9. januar 1987), hvor vi så en morsom film, ”Kuk i timeplanen” med John Cleese."}, {"type": "figure", "caption": "", "page": 58, "file": "assets/images-bog2/p058_01.jpg", "dim": [1015, 694]}, {"type": "figure", "caption": "Klaus til Lars’ fødselsdag i 1980", "page": 58, "file": "assets/images-bog2/p058_02.jpg", "dim": [1009, 689]}, {"type": "para", "text": "Alice og Reinholt var også blandt vores bedste venner. De holdt et dejligt sølvbryllup den 20. oktober 1987, hvor mor også var med. Alle vennerne havde lavet sang til dem, og desforuden stod jeg op og holdt en tale fra Vagn og mig."}, {"type": "para", "text": "Det er en af de bedre taler, jeg har holdt, og det var endda helt uden manuskript. Da så Alice bagefter bad om talen, måtte jeg rekonstruere og skrive ned. Det var Alice og Reinholt, der tog initiativet til den tradition, vi havde i mange år, med surprise ø-udflugter. Den 2. april 1988 blev vi inviteret på en søndagstur med dem, men vi måtte ikke vide, hvor turen skulle gå hen. Det viste sig, at vi skulle på Skovmøllen til frokost, et af de steder hvor de selv var kommet som unge. Efter frokosten gik vi en dejlig tur i skoven og kom tilbage for at indtage eftermiddagskaffen. Dette blev starten på vores årlige surprise ø-ture, som gik på skift. De blev på et tidspunkt udvidet til at være weekendture i vores campingvogn, og vi har haft mange sjove oplevelser, hvor det faste ritual var champagne under sejlturen til øen, drukket af rigtige champagneglas, vel at mærke, også selvom turen kun varede 5 minutter. 1988 var også året, hvor Alice fyldte 50 år (den 23. oktober), og Reinholt og børnene havde arrangeret surprise-fest for hende i Grundfør Forsamlingshus. I deres familie er de glade for surprise-fester, måske fordi Alices søster Kirsten bor i USA, hvor man mere praktiserer den slags. Der var inviteret over 70 gæster til frokost, og det foregik på den måde, at Alice skulle sidde i bilen med bind for øjnene og tro, at hun skulle et sted hen og spise med Reinholt og børnene. Det skulle hun også, men at der stod 70 mennesker uden for Forsamlingshuset var ved at tage pusten fra hende. Hun var så overvældet, at hun slet ikke kunne opfatte, hvad der skete og ikke nød festen så meget, som hvis hun selv havde stået for arrangementet. Men vi andre syntes, det var sjovt. Lige med undtagelse af mor, som også var inviteret med. Hun havde tilbragt noget af efterårsferien hos os og var så taget videre til København, hvor Per dengang boede. Han skulle sætte hende på et fly til Århus, så hun kunne være med til festen. Om morgenen havde vi været til kaffe hos Alice, og jeg husker, at vi venner i Spørring forærede hende en sort skindnederdel. Jeg skulle hente mor i Tirstrup ved 10-tiden, så hun kunne nå at klæde om hos os inden festen. Da jeg kom til Tirstrup, fik jeg at vide, at mor ikke var med flyet. Det, der var sket, var følgende: Per, som plejede at sætte mor på et fly til Ålborg, havde ikke tænkt over, at der denne gang stod Århus på hendes billet. Han og mor havde gået og snakket på vej ud til flyet, og vanen tro var han gået til Ålborg-flyet. Mors bagage var i Århus-flyet, og hun selv sad nu i Ålborg-flyet. Sådan en fejl ville ikke kunne ske i dag med al den tjek og kontrol, der er i lufthavnene. Pludselig spidsede mor øren, da kaptajnen bød hende velkommen ombord i dette SAS-fly til Ålborg. ”Jamen, jeg skal da ikke til Ålborg men til Århus”, råbte hun, og så kan det nok være, at flyet blev standset og hun kom ud. Men da var Århus-flyet desværre lettet, så gode råd var dyre. Hun måtte pænt vente, til det næste fly gik til Århus og så tage en taxa til Grundfør, hvor festen var i gang. Det værste var, at hun ikke var klædt om, så hun følte sig ikke særlig godt tilpas. Hendes kuffert kom med en taxa noget senere. Det var rigtig synd for hende, for hun havde også glædet sig til at se Alices ansigt, når hun så de 70 gæster. Heldigvis fik hun kørelejlighed nordpå af Alices bror Knud og hans søde kone Tekla, men Per var ikke stolt ved situationen, og vi afstod fra at drille ham med det i en sang til hans bryllup."}, {"type": "figure", "caption": "", "page": 58, "file": "assets/images-bog2/p058_03.jpg", "dim": [1017, 697]}, {"type": "figure", "caption": "", "page": 59, "file": "assets/images-bog2/p059_01.jpg", "dim": [1028, 694]}, {"type": "para", "text": "Reinholt, som oprindeligt var uddannet elektriker men også praktiserede kunsten at fotografere, startede i februar 1989 som bestyrer af en fotoforretning på Trøjborg. Som fotograf var han meget dygtig og populær, og mange i Spørring og omegn kom og blev fotograferet i hans atelier i kælderen, ligesom han også tog ud og fotograferede til fester. Ofte havde vi ondt af Reinholt, når han selv var gæst til en fest, hvor han skulle fotografere, for han fik sjældent varm mad, idet det blev serveret lige på det tidspunkt, hvor han skulle gå rundt og tage billeder ved bordene."}, {"type": "para", "text": "Alice og Reinholts naboer, Ruth og Villy Morgenstjerne, havde sølvbryllup den 14. december 1982, og vi var ligesom mange andre i Spørring inviteret med. Forinden havde vi lavet en sang, eller rettere sagt Alice havde lavet en sang, for det var hendes speciale. Jeg var ikke selv begyndt at fabrikere sange på det tidspunkt. Sangen skulle jo serveres i en sangskjuler, så vi måtte lægge hovederne i blød. Villy arbejdede på Centralværkstedet i Århus, så hvad var mere nærliggende end at lave et tog. Aldrig har vi gjort så meget ud af en sangskjuler, og det var Vagn, der var primus motor. Han lavede den med flere vogne ud af mælkekartoner, inkl. lokomotiv. Det blev malet efter alle kunstens regler, og Reinholt tryllede med fotografier, så Ruth og Villy kom til at sidde i toget og kigge ud af vinduerne. Æresporten blev lavet hos os aftenen før, og traditionen tro gav jeg kaffe til alle deltagerne, inden vi sneg os op og satte æresporten op. Næste morgen kl. 7 mødte vi op med fakler og oplevede den flotteste morgenmusik nogensinde: et 35-mands orkester fra Centralværkstedet, også kaldet CO, som Villy selv spillede i. Om aftenen var vi til stor fest på Spørring Hotel. Det var det første sølvbryllup i vores vennekreds."}, {"type": "figure", "caption": "Lars Morgenstjernes konfirmation 11.4.76", "page": 60, "file": "assets/images-bog2/p060_01.jpg", "dim": [988, 694]}, {"type": "para", "text": "I 80’erne var vi en del sammen med Grete og Poul i nr. 26, Alice og Reinholt i nr. 28, Erik og Kirsten maler i nr. 21 og Karen Lis og Finn. Vi behøvede ikke altid at være inviteret, og ofte løb vi sammen hverdagsaftner til en kop kaffe og te. Det var rigtig hyggeligt."}, {"type": "para", "text": "Kirsten og Eriks ældste datter Dorthe blev indlagt den 4. september 1979 med maveonde, men hun kom hurtigt hjem, og alle troede, at hun var rask. Det viste sig at være værre end som så, og hun røg ind og ud af hospitalet indtil de fandt ud af, at hun havde kræft i underlivet. Det var et hårdt slag for forældrene, og vi var alle dybt berørte, men vi håbede og troede på, at lægerne kunne kurere hende, for en ung pige på 16 år kunne da ikke dø af kræft! Dorthe fik kemo og tabte håret. Oftest gik hun med tørklæde, og hun passede sin skole så godt, hun kunne. En dag blev hun dårlig i skolen og måtte tage hjem, og da der ikke var nogen hjemme, kom hun over til os. Vi kunne virkelig se, at hun led, og vi prøvede at hjælpe hende så godt, vi kunne. Heldigvis kom Kirsten hjem og kunne tage over. I marts 1980 blev Dorthe indlagt og fik det dårligere, men hun fik lov at komme hjem på weekend. Vi besøgte malerens en aften og havde Lars med, og da lå Dorthe på sofaen og fik sondemad, og hun havde ingen paryk eller tørklæde på. Stemningen var god trods de dystre udsigter, men forældrene blev også ved med at håbe."}, {"type": "figure", "caption": "Dorthes konfirmation april 1977.  Vi var med.", "page": 60, "file": "assets/images-bog2/p060_02.jpg", "dim": [1001, 675]}, {"type": "para", "text": "Den 14. april fyldte Erik 40 år, og Vagn gik om aftenen over med en flaske til ham. Da havde de lige fået at vide på hospitalet, at der ikke kunne gøres mere for Dorthe. Hun døde den 18. april, 17 år gammel. Det var en fredag, og vi skulle til Svenstrup, så vi udsatte kondolencebesøget til mandag. Det var en frygtelig mandag, hvor jeg gik og ventede på, at Vagn skulle komme hjem, så vi kunne komme over til Kirsten og Erik. Det var hårdt, og de var utrøstelige, men vi fik det overstået. Begravelsen var også frygtelig, og vi kunne høre Kirsten hulke. Hvor var det synd for dem og deres to andre piger, Tina og Gitte. Kirsten ville ikke have Spørring præsten, så de fik Ødum præsten til at forestå begravelsen, for ham kendte de, og det var de glade for. I tiden derefter prøvede vi på at få Kirsten tilbage til livet, men det var svært. Erik havde det også svært, for han ville gerne snakke om Dorthe, hvorimod Kirsten gerne ville lukke sig inde. Kirsten blev aldrig den glade pige igen, og det er forståeligt nok. Dorthes sygdom havde også gjort indtryk på Lars, som var glad for Dorthe, og en dag, hvor Erik var på besøg kort tid efter begravelsen, spurgte Lars: ”Hvor er Dorthe?” ”Dorthe er død”, svarede Erik, og så stillede Lars sig tilfreds med det svar, selvom han ikke forstod det."}, {"type": "para", "text": "I januar 1982 fyldt Karen Lis 35 år, så hun havde inviteret de allernærmeste venner, ca. 15 til en munter aften. Vi havde besøg af mormor, så vi havde en god barnepige og kunne bare feste løs. Og det gjorde vi sandelig også, for vi var først hjemme kl. 5.30 næste morgen. Et af samtaleemnerne den aften var viceskoleinspektør Lyngs selvmord dagen før. Han boede med sin familie på Gl. Landevej og var dagen før fyldt 40 år. Efter gæsterne var taget hjem, havde han sat sig ud i bilen i garagen og havde gasset sig selv. Det gjorde indtryk i så lille en by. Fem år senere inviterede Karen Lis til 40-års fødselsdag, denne gang i kælderen, fordi familien også var inviteret med. Det var kutyme dengang i vores vennekreds at møde op kl. 6 om morgenen på selve fødselsdagen og synge for fødselaren. Gæsterne havde selv kaffe og rundstykker med, for fødselaren skulle jo forestille at blive taget på sengen. Dagen efter festen var en af de lånte sølvknive borte. Den blev næste dag fundet i Vagns inderlomme, og det skulle han høre for i mange år derefter. Det viste sig, at han havde puttet den i lommen i forbindelse med, at det bord, han sad ved, skulle fjernes for at give plads til dansegulv. Han skulle derfor flytte over til et andet bord, og hvad gør man så lige ved kniven, mens man flytter? Jo, den stopper man i inderlommen. Han glemte bare, at han havde gjort det, så kniven lå der stadig næste dag."}, {"type": "para", "text": "Henning Christiansen startede med at udfylde selvangivelse for os i 1973. og i flere år kom hans kone Birgit og drak kaffe med os, når mændene var færdige. Det var altid sjovt, for Henning kunne fortælle nogle gode historier fra Spørring, hvor han og Birgit havde boet i mange år. Henning havde samme alder som mor. I 1983 foregik det på en kold og snefuld lørdag i februar, og vi skulle skynde os at være færdige, for vi skulle alle fire til dilettant på Hotellet om aftenen. Det blev en uforglemmelig aften, og højdepunktet var, da Ivan Pedersen kastede Bodil Emdal op i luften og greb hende igen i en forrygende dans. Det griner vi stadig af, når vi er sammen om selvangivelsen, og nu er Anna-Lise og Tage også kommet med. Prisen for at få lavet selvangivelse er pt 1000 kr."}, {"type": "para", "text": "Vores nærmeste naboer, Gulla og Leif Hedegård, kom vi ikke meget sammen med. Leif var murer og en stilfærdig og flink mand. Hans kone skulle nok bestemme, hvor skabet skulle stå, og så havde de en lille hund, der hed Pjevs. De havde to døtre, Lissie og Sannie, og en søn, Brian, som var efternøler. De har kun en enkelt gang passet Lars, og det var den 8. april 1984, da vi skulle til Johns konfirmation. De var med nogle gange til fest hos os, og de var alle tiders festaber, når de havde fået lidt inden for vesten. Men i 1986 sagde de nej tak til at komme til vores kobberbryllup med den begrundelse, at de aldrig selv holdt noget. Det blev vi skuffede over, og fra den dag lagde vi dem lidt på is. Da de så et års tid senere inviterede til Brians efterkonfirmation, sagde jeg i telefonen til Gulla, at vi nok burde blive hjemme. ”Hvorfor det?” spurgte hun. Jeg gav som begrundelse, at de ikke ville komme, når vi inviterede, men det var ikke det samme, sagde hun. Jeg bøjede mig og takkede ja, men da aftenen oprandt, så vi beviset på, at de ikke havde forstand på at have gæster. Fra vores køkken kunne vi se over i deres køkken, og vi havde hele dagen gået og holdt øje med, om de havde gang i madlavningen derovre, for vi vidste ikke, om vi skulle spise hjemmefra. Der var ikke megen aktivitet, så vi tog en bid brød til aften, inden vi gik derover. De havde inviteret revl og krat, og de sidste måtte sidde på taburetter. Vi fik ost og kiks, og da der blev stillet en bordskåner på sofabordet, tænkte jeg: ”Det er nok til den lune frugttærte”, men da blev jeg skuffet. Det var til tekanden, og frugttærten kunne vi godt skyde en hvid pil efter. Ved 23-tiden var de sidste gæster gået, og vi kunne fra vores køkkenvindue se, hvor aktive de nu var derovre med at få alt ryddet væk efter alle gæsterne, så de igen kunne slappe af. Det var helt tydeligt, at den aften bare var noget, der skulle overstås. Vi inviterede dem ikke mere med, når vi holdt noget."}, {"type": "para", "text": "I 80’erne kom vi også en del sammen med Vivi og Frode fra Auning. Frode og Vagn havde arbejdet sammen som tømrere i deres unge dage, og vi vidste ikke, at Frode var alvorligt syg, før de meldte afbud til vores kobberbryllup med en virkelig god grund: Frodes hjerte voksede, og han skulle have en stor hjerteoperation på det tidspunkt, hvor hjertet skulle tages ud af kroppen. Da jeg besøgte ham på hospitalet efter operationen, viste han mig det lange ar foran, hvor han var blevet skåret op, og efterfølgende da vi besøgte dem i Auning, diverterede han os under middagen med de mest bloddryppende detaljer fra operationen. Operationen gik heldigvis godt, og Frode har ikke fejlet noget siden."}, {"type": "para", "text": "Ellen og Ras, som boede i nr. 27, var meget glade for børn. De havde kun én datter, som havde to børn, og de boede i Feldballe, men de kom ikke så tit hjem. Derfor var Ellen og Ras glade for Lars’ besøg, og han elskede at komme derover og spille kort med Ras. Han blev også somme tider passet derovre, også når barnebarnet Susanne var hjemme, så hun kunne lege med ham. Ellen blev kun 65 år. Hun faldt om på badeværelset af en hjerneblødning i begyndelsen af december 1982 og døde på hospitalet den 5. december. Det var en stor sorg for Ras, og vi andre savnede hende også. Ved begravelsen stod svigersønnen Ivar op og holdt tale, og deri nævnte han den lille dreng på 5 år, der kiggede over hækken. Det var meget rørende. Ras måtte nu klare sig uden Ellen, men han var ikke mobil, så han sad det meste af tiden i en stol. Han var bestemt ikke kedelig at snakke med, så vi gik somme tider derover, og så fik Lars lov at blive der og spille kort med Ras. En dag, da jeg kom for at hente ham, ville Ras have mig til at tage noget saftevand i køleskabet. Lars gik med mig og konstaterede, at gulvet var klistret. Det gik han ind og sagde til Ras, som sagde, at det var sket, da han skulle tage noget saft ud af køleskabet. Hvem der gjorde rent hos Ras, husker jeg ikke, men der var rimelig beskidt over det hele. Jeg tænkte, at jeg da godt kunne vaske køkkengulvet for ham, og det tilbud tog han imod, men da jeg bad om en gulvklud, henviste han mig til et skab fyldt med Ellens lyserøde underbukser, som ikke var særligt velegnede til at suge vand. Men skidtet fik jeg da fjernet. Ras døde den 7. marts 1984 og blev begravet den 10. marts, dagen efter mors 50-års fødselsdag, så vi var nordpå og kom desværre ikke med til begravelsen."}, {"type": "para", "text": "Huset blev hurtigt solgt til en ny Ras, nemlig til Mary og Rasmus Lundkvist, som flyttede ind den 1. maj samme år. Jeg gik over med en blomst for at byde dem velkommen. Vi kendte Mary, som jo havde lavet mad til Lars’ barnedåb, og det blev til et godt nabo- og venskab, især efter at Rasmus døde. Det har sin forklaring. Mary var 65 år, da de flyttede ind, og Rasmus var en del år ældre, nemlig 80 år. De havde haft et lille husmandssted uden for Spørring, hvor 4 børn var vokset op, og en overgang boede bedsteforældrene der også, så Mary havde slidt hele sit liv med det derhjemme, samtidig med at hun gik ud og lavede mad til fester. Rasmus, derimod, var en doven rad, som ikke måtte bruge hænderne for meget, idet det kunne skade hans violinspil. På Østervang havde han sit eget værelse, hvor han gik op og øvede sig, men der skulle øves meget, for når han spillede, lød det, som når man trækker en kat i halen. Mary forgudede sin mand, hvilket var prisværdigt, men det gav sig udslag i, at hun altid kaldte på ham, når jeg kom over for at snakke med hende. Så kom han ned i køkkenet og sad og blandede sig i vores samtale, og når vi snakkede i øst, snakkede han i vest. Måske var han også på det tidspunkt ved at være lidt senil, men jeg ville sådan ønske, at hun ville lade ham blive ved sit violinspil, så vi kunne snakke i fred og ro. Rasmus døde på hospitalet den 8. december 1988, 84 år gammel. Mary var fyldt 70 år den 11. juli samme år. Efter Mary blev alene, fik vi rigtig meget sammen med hende, og hun fulgte med i vores liv og familie. Når vi havde haft gæster, kunne hun næste dag sige: ”Det var da sent jeres gæster tog hjem”, men det syntes vi bare var hyggeligt. Mary kunne godt lide, når Vagn tog gas på hende, og hun kunne godt svare igen. Det skete, at han hjalp hende med nogle småting, for børnene var ikke for flinke til at besøge hende, og når han så for sjov sagde til hende, at det blev dyrt, når det var weekend-takst, så svarede hun fluks, at der da ikke var nogen, der forhindrede ham i at lave det en anden dag. Mary og jeg gik til sangaftner sammen og i kirke, og hun var med, når der skete noget i familien hos os. Vi holdt rigtig meget af Mary, og vi kunne se, at hun blomstrede op efter at hun blev alene og ikke skulle passe Rasmus op. Desværre havde hun nogle bekymringer omkring børnene og deres skilsmisser. Engang sagde hun grædende til os, at hun ikke kunne forstå, hvad hun havde gjort galt, når tre ud af fire børn og også to børnebørn var skilt. Engang, hvor hun var på besøg hos et af børnene i januar 1989, var der indbrud hos hende. Det var rigtig synd, for ikke nok med at der havde været indbrud, tyvene havde besørget i vaskekummen på gæstetoilettet, så det var virkelig ulækkert at komme hjem til."}, {"type": "para", "text": "Marie og Svend Sønderup var et andet ældre ægtepar, som vi af og til besøgte på Hortensiavej 4 i Holme. Jeg havde lært dem at kende i USA i 1962, og på deres ældre dage flyttede de til Danmark. De havde ingen børn, og Marie var aldrig faldet til i USA, men Svend forblev amerikansk statsborger. De var interessante at besøge, for de fulgte med i og kunne snakke med om alt, og de var meget interesserede i at høre om vores liv. Inden de flyttede til Danmark, kom de altid på besøg hos os, når de var i landet. Engang, de var på besøg, hvor Lars var 2-3 år, sagde han, mens vi sad i sofaen: ”Jeg kan ikke lide Marie”. Første gang hørte jeg ikke rigtigt, hvad han sagde, så jeg bad ham gentage, og endnu engang sagde han: ”Jeg kan ikke lide Marie”. Det var meget pinligt, og jeg ved ikke, hvordan jeg på en eller anden måde fik lavet en afledningsmanøvre, men vi fik hurtigt samtalen ind på et andet emne. Hvorfor knægten sagde det, ved jeg ikke, måske fordi Marie ikke var særlig køn og måske ikke har haft så megen forstand på børn, i og med at hun ikke selv havde fået nogen. Men de var altid begge meget opmærksomme over for Lars, og jeg tror ikke Lars’ ord blev opfattet så bogstaveligt. Vagn var ofte den, som Svend spurgte til råds, også da han skulle købe bil i foråret 1987. Vagn var med ham ude og købe en ny BMW med automatgear, som han jo var vant til fra USA. Vi var med, når Marie og Svend holdt fest, som fx den 30. juni 1988, da Svend fyldte 75 år. Festen blev som altid holdt på Frederikshøj Kro."}, {"type": "para", "text": "Petra og Christian i Solbjerg begyndte at skrante, og i september 1981 kom Christian på hospitalet. Han kom hjem igen og fik et par gode år, inden han døde i oktober 1983 og blev begravet den 22. oktober. Desværre var Petra på det tidspunkt meget senil, og til hans begravelse spurgte hun os, om vi havde kendt hendes mand. Hun kom på plejehjem, hvor vi nogle gange besøgte hende, men hun kunne ikke kende os og sagde engang til Vagn, da han var derude sammen med sine forældre, at han da var blevet stor. Engang, vi havde Lars med derud, spurgte hun ham mange gange, om han var begyndt at gå i skole. Efter Petras død holdt farmor forbindelsen ved lige med datteren Edith, og efter farmors død overtog jeg julekortkorrespondancen. Edith blev enke for nogle år siden, idet Dynes pludselig faldt om og døde en juleaften. Da var de flyttet fra gården og boede i hus i Herning. Nu bor Edith på 84 år i en hyggelig lille andelsbolig i Herning, og vi har lige gjort alvor af at besøge hende (den 16. juni 2012). Vi kom til frokost og havde en dejlig eftermiddag, hvor vi fik snakket om familien, børn, børnebørn og gamle dage. Det var sjovt at se, hvor meget hun ligner sin mor, og det var interessant at se billeder af hendes børn og deres familier."}, {"type": "figure", "caption": "", "page": 64, "file": "assets/images-bog2/p064_01.jpg", "dim": [1015, 697]}]}, {"title": "Fritidsinteresser og traditioner", "blocks": [{"type": "para", "text": "Fastelavn Med det gode sammenhold blev vi automatisk indlemmet i en række traditioner, bl.a.fastelavn. En dejlig tradition var tøndeslagning hos Alice og Reinholt hvert år Fastelavnssøndag, en tradition de havde startet i 1970. I 1980 var mor, far, Per og Jette med. De var på weekend hos os, og det var derfor naturligt, at de fulgtes med os op til fastelavnsfesten. Mor og far var også blevet Alice og Reinholts venner. Der var altid mange gæster, både fra Spørring og familien. Tøndeslagningen foregik udenfor, og bagefter var der kaffe, sodavand og fastelavnsboller i kælderen og film for børnene. Jeg hjalp nogle gange Alice med at komme fyld i bollerne."}, {"type": "figure", "caption": "Lars som sheik i 1985", "page": 64, "file": "assets/images-bog2/p064_02.jpg", "dim": [689, 1015]}, {"type": "para", "text": "I 1982 købte jeg sort tøj til Lars, fordi han skulle være neger til fastelavn, men til festen hos Alice og Reinholt var han kat. Det år spiste vi middag deroppe om aftenen, og jeg havde skrællet kartofler til 25 personer. I 1984 var Lars klædt ud som klovn. Jeg var ikke særlig kreativ og kunne ikke selv sy kostumer, så jeg havde købt et klovnekostume hos BR. Det er senere gået i arv til Lars’ søn William, som havde det på som 2-årig. Da var det lidt for stort til ham, men det gjorde ikke noget. På disse kanter er der tradition for, at børn går rundt som soldater Fastelavnssøndag og synger penge ind ved dørene. Således også i 1986, hvor Lars startede med at gå soldat, og hvor det kun var drenge, der kunne deltage på det store og det bette hold. I en vis udstrækning besøgte begge hold soldater alle husstande i sognet. Der var en konge, en kronprins, en fanebærer og generaler samt en skatmester til at samle penge ind til en fest, som dengang blev holdt på Hotellet. Soldaterne var under optoget pænt uniformerede med sabel, skråbånd og hue i røde og hvide farver med guldbånd, og generalerne holdt styr på tropperne under marchen fra dør til dør. Det første år fik vi et sæt skråbånd og hue af Alice, som havde været Pers, men året efter syede jeg et nyt sæt, og så havde Lars et til søndag og et til festen mandag aften. De penge, der blev sunget ind, gik til fastelavnsfesten på Hotellet mandag aften, og det, der var tilovers efter festen, blev fordelt mellem soldaterne. Typisk startede soldaterne kl. 7.30 med at blive kørt ud til gårdene, og senere gik de rundt i hele Spørring. Sangen lyder således: Fastelavnen nu er kommen og med følge her vi stå synger for, at vi i lommen må en lille gave få."}, {"type": "figure", "caption": "", "page": 65, "file": "assets/images-bog2/p065_01.jpg", "dim": [495, 740]}, {"type": "para", "text": "Til et bal med dans og løjer hvor enhver sig ret fornøjer derfor beder vi jer om ”Gi’ os hvad I synes om”."}, {"type": "para", "text": "Dette vers blev liret af så hurtigt, at man knapt kunne høre, hvad der blev sunget. De skulle jo videre til næste hus og indsamle flere penge. Efter at den glade giver havde ladet sine mønter dumpe ned i skatmesterens store pengetaske, kom takkeverset: Fastelavnssoldat i 1987 Spørringdrenge her vi bringe tak for hvad I givet har højt med glæde nu vi kvæde for nu et hurra, hurra."}, {"type": "para", "text": "For vor konge er vi omme og for prinsen med hurra hurra hurra nu farvel ja farvel og mange tak."}, {"type": "figure", "caption": "", "page": 65, "file": "assets/images-bog2/p065_02.jpg", "dim": [774, 943]}, {"type": "para", "text": "Og væk var de."}, {"type": "para", "text": "Traditionen stammer helt tilbage fra 1920, hvor karlene på gårdene og de ældste drenge dannede optog til hest. Oprindeligt udkæmpedes der kampe mod rivaliserende nabooptog, men i dag går det mere fredeligt for sig. Da Lars deltog, var det kongens og kronprinsens forældre, der stod for middagsmaden, hvorefter drengene traskede videre til kl. 18.30. I 1986 fik det bette hold indsamlet 2000 kr., og efter festen fik hver dreng en kuvert med 112 kr. Året efter var der 120 kr. til hver, og i 1988 var det samlede beløb 2030 kr. Det sidste år, Lars gik, var i 1989, hvor hver soldat fik 168 kr. Festen var vældig højtidelig med indmarch af soldaterne, som var iført sorte bukser med påsyede galoner og nye, rene skråbånd og huer, hvorefter der var tøndeslagning. Det var på forhånd aftalt, hvem af pigerne, der skulle være dronning, kronprinsesse osv., og dansen indledtes med, at drengene i rangorden inklinerede for den udkårne."}, {"type": "para", "text": "Det skete også, at Lars og Klaus klædte sig ud eller Lars og Rasmus Skall. I 1989 var sidstnævnte klædt ud som gamle damer. Det er Lars til venstre i billedet på forrige side."}, {"type": "para", "text": "Syning og håndarbejde Selvom jeg havde gået til syning tidligere, blev jeg som sagt aldrig god til at sy, men jeg kunne godt blive bidt af det, når jeg først kom i gang. I efteråret 1981 syede jeg en nederdel og en vest på min Major symaskine. Året efter syede jeg en vatteret vest, og i 1984 syede jeg badeværelsesgardiner. I 1985 syede jeg endnu en nederdel, men så var det også slut. For eftertiden brugte jeg kun symaskinen til reparationer."}, {"type": "para", "text": "Det var også i 1980’erne, at jeg skar uroer. Jeg havde et stort ringbind med alle mulige skabeloner, og det foregik på den måde, at jeg kopierede modellerne på A4 papir, klipsede papiret fast på karton, og skar med en lille kniv langs kanterne ned på et plastikbræt. Det var en dejlig fritidssyssel, og ofte brugte jeg uroerne som værtindegaver. På det tidspunkt hang der uroer i ethvert hjem. Fransk I 1985, 13 år efter, at jeg havde fået min bifagseksamen i fransk, startede jeg på et FOF-kursus i fransk ved Madeleine Frandsen, som var fransk men dansk gift. Jeg følte, at jeg havde glemte mere og mere af sproget, og det blev til 12 gode år hos Madeleine, indtil hun gik på pension og jeg ikke havde lyst til at begynde hos en ny lærer. Timerne lå om tirsdagen fra kl. 13-15, og jeg nød det virkelig. De fleste på holdet var kvinder, der var ældre end mig, og mange var pensionister. Vi hyggede os gevaldigt og lærte en masse, for Madeleine var utrolig dygtig til at lære fra sig. Hos hende lærte jeg også nye undervisningsmetoder. I starten kunne jeg ikke få mig selv til at sige, at jeg havde læst fransk på universitetet, for jeg syntes virkelig, at jeg var dårlig, men efterhånden som tiden skred frem, kom det, jeg tidligere havde lært, lige så stille op til overfladen igen, og jeg blev mere sikker, når jeg skulle udtrykke mig. Vi læste mange gode bøger og artikler samt så nyheder på fransk, men der var også skriftligt arbejde, som jeg nød. Det, jeg især godt kunne lide hos hende, var, at vi fik lov til at fortælle om vores egne oplevelser, så hun gjorde timerne meget personlige. I pauserne havde vi det hyggeligt med hinanden, selvom der aldersmæssigt var stor forskel. Det eneste, jeg godt kunne have tænkt mig, var at være kommet med på nogle af de ture, hun arrangerede til Frankrig, og som de andre deltog i, men jeg skulle jo passe mit arbejde."}, {"type": "para", "text": "Fiskeri Lars på fisketur med far og morfar august 1982                                Så er der fangst. Morfar ses i baggrunden Vagn havde også sine fritidsinteresser, bl.a. fiskeri. Tage havde købt en båd i 1976, som på et tidspunkt kom til at stå hos os, og den tog de to brødre og barberen fra Svenstrup, Preben, ud i, når de skulle slappe af en lørdag eller søndag. De sejlede ofte ud fra Bæktrup Vig, og kom hjem med stort udbytte. Nogle af rekorderne kommer her: 12. september 1981: 70 fladfisk (isinger/skrubber) 26. september 1981: 150 fladfisk 21. maj 1982: 45 torsk Sommeren 1982: 113 fisk Efteråret 1983: 300 fladfisk 1984: 560 fisk 24. november 1985: 188 fladfisk 1986: 152 fladfisk Vagn og Niels Høj var på fisketur med Lars og Rasmus på Fars Dag i 1989 og fangede 40 fisk. Jagt Vagn havde jagttegn og gik somme tider på jagt i Vendsyssel."}, {"type": "figure", "caption": "", "page": 66, "file": "assets/images-bog2/p066_01.jpg", "dim": [755, 520]}, {"type": "figure", "caption": "", "page": 66, "file": "assets/images-bog2/p066_02.jpg", "dim": [516, 779]}]}, {"title": "Vores hus og tilbygningen", "blocks": [{"type": "figure", "caption": "", "page": 67, "file": "assets/images-bog2/p067_01.jpg", "dim": [1017, 697]}, {"type": "para", "text": "Vi havde jo planer om at skulle have flere børn, så for at være på forkant med pladsen, besluttede vi os for at bygge til huset i 1980. Huset skulle nu være et vinkelhus med kælder under den nye afdeling, og det samlede areal ville være 260 m2. Vagn ville ved samme lejlighed få et stort værksted i enden af huset, hvor også fyret skulle flyttes ud. Den 26. april 1980 blev de 5 spær til tilbygningen rejst, og kælderen blev gravet ud sidst i juni, hvorefter der blev brækket hul i mit værelse, som for eftertiden skulle være trapperum. Jeg ville få et stort nyt kontor med en pragtfuld udsigt ned over markerne og et bøgetræ plantet af Lars samme år. Den sommer var speciel regnfuld, og efter der var gravet ud til kælder, kom der så meget regn, at vi måtte leje en pumpe den 6. juli. Hans Kristensen, Tage og Poul Erik kom og hjalp med at pumpe vand ud af kælderen den 6. og 7. juli. Senere, den 21. juli, kom der 50 mm vand i kælderen svarende til 10.000 liter. To dage senere blev der støbt i kælderen, og den 16. august holdt vi rejsegilde. Vagn og Tage murede selv den nye afdeling, og det gik fantastisk godt og var et sandt mesterværk. Den 9. september blev der slået hul ind til stuen, og nu var der fri bane for musene! Jeg var godt klar over risikoen, men jeg prøvede at abstrahere fra den, og jeg så aldrig en mus – kun deres efterladenskaber. En aften, da vi skulle i seng, lå der muselort på min hovedpude! Forfærdet beklagede jeg mig til Vagn, men han trøstede mig med, at det måtte være noget, der var faldet ned gennem et hul i loftet. Jeg må have været noget naiv for at tro på den løgn, men jeg lagde mig trygt til at sove. Næste morgen, da Vagn skulle tage en skjorte i skabet, fulgte der en mus med, men af hensyn til mig, fjernede han den ligeså diskret og sagde ikke noget. Han mødte også mus andre steder, og hver gang lod han som ingenting. Han frygtede, at jeg ville løbe skrigende bort, hvis jeg så meget som hørte om en mus i mit hus, og hvem skulle så lave mad til ham og arbejdssjakket? På et tidspunkt satte han en fælde op på loftet, af den slags med fire huller, som man binder op. Hans mor havde vist ham hvordan. Næste dag stak han hovedet op på loftet for at se, om der var gået mus i fælden, men snorene stod lige højt, så der var ikke bid – troede han – indtil han kiggede ordentligt efter og så, at der sad fire mus på rad og række."}, {"type": "para", "text": "Det fortalte han mig først længe efter."}, {"type": "para", "text": "Det år var et knokkel for Vagn, og han har senere bebrejdet sig selv, at han havde for travlt til at tage sig af Lars, som var 3 år. Lars syntes nu det var sjovt med det byggeri, og blev der for beskidt, kom han løbende med kost og fejeblad. Der var god hjælp at hente hos Tage, som altid var på pletten, når der var brug for ham, og til at lave strøm havde vi Reinholt, som var udlært elektriker. Den 14. september kom der varme på huset, og Doris og Poul Erik kom og tapetserede for os i slutningen af september. Den 2. november i forbindelse med noget udendørs arbejde slog Poul Erik hovedet og måtte på skadestuen."}, {"type": "para", "text": "Det var mig, der lavede mad, gjorde rent og stillede værktøjet pænt, så Vagn ikke skulle bruge tid på det, og jeg fik også besked på, at det var mig, der skulle ludbehandle lofterne til stuen i slutningen af oktober. Det foregik på den måde, at de først fik en gang lud, dernæst skulle de tørre, så fik de en gang kalk, og til slut skulle det børstes af. Det var et stort arbejde. Den 6. november slog Vagn nyt loft op i køkkenet, og Elbo Knudsen lavede trappen til kælderen og satte den op den 29. november. Den 5. december kom onkel Erik og flyttede fyret fra bryggerset til værkstedet, og nu skulle vi så til at fyre med træ og ikke olie. Det sparede vi efterfølgende mange penge ved, og det var ikke megen olie, der var blevet brugt fra 1980 til vi flyttede i 2009. Den 20. december satte Vagn en foldedør i fra køkken til stue, og så var det jul. Tilbygningen var et stort projekt, som varede det meste af et år. Nytårsdag 1981 slog Vagn loft op i bryggerset og satte ekstra skabe op der, hvor fyret havde stået, så vi nu havde fire høje skabe i stedet for to, og senere på ugen kom Tage og malede i kælderen. Den 1. februar 1981 stod stuen færdig, og vi kunne lakere gulve den 8. februar. Vi havde nu fået en vinkelstue, som var opdelt i gammel og ny stue, selvom de ikke var adskilte. I den nye stue fik vi lagt tæppe, ligesom vi også fik lagt tæpper i resten af det nye og i trapperummet. I kælderen var der et stort og et mindre værelse, et depot og en gang med seks høje skabe. I alt var der nu i huset 36 høje skabe, så det var ikke skabsplads, vi manglede. Vi var rigtig glade for tilbygningen, og vi nød den megen plads, så nu kunne børnene bare komme an. Vi manglede også møbler, så vi kørte ud til Rosborg Møbler og købte to Siesta stole og en Børge Mogensen tremmesofa, som skulle stå i den nye stue. Den gamle grønne Bilka-reol kom i kælderen, og vi købte en stor Hundevad reol hos Karina Møbler i Hørning, hvor vi også købte gyngestol og sofabord i februar 1984. Vi fik 5.000 kr. af Vagns forældre i april 1984, som vi brugte til en Wegner stol, som kostede 4.500 kr. hos Rosborg Møbler."}, {"type": "figure", "caption": "Inge-Marie og Lars 1982", "page": 68, "file": "assets/images-bog2/p068_01.jpg", "dim": [1012, 697]}, {"type": "para", "text": "Så kom turen til terrassen. Den 13. marts gravede Vagn ud til terrasse ved den nye stue, og den 27. marts blev den støbt. Den 17. april kom Tage og lagde slidlag, og den 29. april blev den fuget. Den 5. maj var den helt færdig og overdækket, og vi fik rigtig megen fornøjelse af den i tiden, der kom, men ikke før Grundlovsdag i 1985 fik vi købt møbler til den. Da tog vi over grænsen med Karen Lis og Finn og købte et brunt rundt bord med fire stole, som vi har den dag i dag."}, {"type": "para", "text": "Nu skulle man så tro, at Vagn kunne slappe af i mange år, men nej, der var stadig ting, der skulle vedligeholdes, så i foråret 1986 skiftede han vinduerne i soveværelset. Ved årsskiftet 1986/87 fik vi ny vaskemaskine og opvaskemaskine, og i januar 1987 trængte stuen til at blive malet. Det tog 3 uger. Jeg beklagede mig altid over, hvor langstrakte Vagns projekter var sammenlignet med mange, vi kendte, som kunne male en stue på en weekend, men Vagn gik ikke på kompromis med det, han lavede, så derfor tog det tid. Nu da stuen var nymalet, og vi havde skiftet til den hvide farve igen, efter at stuen havde været nougatfarvet, måtte vi simpelthen have de gamle brune fløjlsmøbler skiftet ud. I februar 1987 solgte vi møblerne for 500 kr., glasbordet for 150 kr. og Lars’ tremmeseng for 300 kr. Desuden solgte vi vores sort/hvide TV for 500 kr. I marts købte vi nye grå lædermøbler (1-2-3) hos Karina Møbler og vores første videomaskine, en B&O, i Hadsten. Senere på året købte vi nye kontormøbler og et akvarium. Nu skulle vi til at holde husdyr, og når moderen hverken ville have hund eller kat, måtte vi nøjes med guldfisk. Det blev en kort fornøjelse. Guldfiskene blev forkølede og døde, og så var det slut med at holde husdyr."}, {"type": "para", "text": "I starten af 1988 malede Vagn kontor, soveværelse og trapperum og indrettede værelse til Lars i kælderen, hvor han flyttede ned den 20. januar 1988. En ny epoke var indledt, fra at sove i soveværelset i vuggen til at flytte på værelse ved siden af med tremmeseng til nu at flytte en etage ned. Næste gang, han flyttede, ville det være ud af huset, selvom han sagde, at han altid ville blive boende, og at det var os, der skulle flytte. 1988 var også året, hvor vi fik stereobænk med B&O radio, CD og søjlehøjtalere til 24.500 kr. I 1989 malede Vagn i badeværelset, bryggerset og køkkenet, hvor vi også fik nye grå gardiner, der kostede en bondegård. Vagn er sidenhen blevet ved med at påstå, at jeg blev snydt i den handel."}, {"type": "figure", "caption": "", "page": 69, "file": "assets/images-bog2/p069_01.jpg", "dim": [1015, 697]}]}, {"title": "Vores lille trekløver", "blocks": [{"type": "para", "text": "På et tidspunkt måtte vi sande, at vi ikke kunne få flere børn, men vi havde jo også verdens dejligste dreng, så hvad mere kunne vi ønske os? Lars har altid været nem, og mange af vores venner og familie sagde, at vi aldrig havde prøvet at have børn. Når mine kolleger talte om deres uvorne unger, og jeg oplevede, når jeg var på besøg hos dem, hvordan børn kunne terrorisere familien, hoppe i møblerne og danse på klaveret, så priste jeg mig lykkelig over det pragteksemplar, jeg havde derhjemme. Det betød også, at                     Lars med sin nye bondegård den 27.3.1980 jeg kunne have Lars med på arbejde engang imellem. Som 6-årig var han med mig på arbejde nogle gange og sad musestille ved et bord og tegnede. Han ville fra 7-års alderen også gerne være alene hjemme, hvis vi bare skulle hen til naboen eller genboen. Så fik han sin livret, som var blodpølse, og han stod ikke og ringede til os om dit og dat sådan en aften, som visse andre børn gjorde til deres forældre."}, {"type": "para", "text": "Lars var sjældent syg og forsømte faktisk aldrig skolen. For nylig, da jeg konfronterede ham med, at jeg syntes, han arbejdede for meget på sin PC om aftenen, fik jeg den lige tilbage: ”Mor, det er fordi I altid har lært mig at være pligtopfyldende”. Så fik vi den."}, {"type": "para", "text": "Han skulle jo have de obligatoriske børnesygdomme, og de kom i følgende rækkefølge: skoldkopper december 1982, mæslinger maj 1985, røde hunde april 1986 og fåresyge maj samme år. Skoldkopper slap han nemt over. Jeg tror, at han kun havde én skoldkop, men den sad til gengæld lige midt i panden, hvor han den dag i dag har et lille ar. Mæslinger, til gengæld, var hårdt ved ham. Han lå med 39,6 i feber for nedrullede gardiner, og mor var virkelig forarget over, at vi ikke blev hjemme og passede ham. I stedet betalte Vagns mester for, at vi kunne hyre en barnepige til at sidde ved ham. Det var op til en weekend, hvor vi fik Heidi (Lars’ dagplejemor Solvejgs svigerdatter, som Lars kendte) til at sidde ved ham fra kl. 7-16 for 200 kr., og jeg var i løbende telefonkontakt med hende for at høre, hvordan det gik. Heldigvis gik det fint, og han sov det meste af tiden. Set i bagklogskabens klare lys havde mor nok ret – jeg burde være blevet hjemme hos ham. Om mandagen blev Klaus indlagt med mæslinger og feberkrampe."}, {"type": "para", "text": "I 3-års alderen legede Lars meget med Legoklodser, og han sorterede alt, lige fra sugerør til ludobrikker. Han var især også glad for at lege med små biler og biltransport. Senere samlede han på frimærker, kapsler, dåser, glansbilleder, fodboldmærker, nøgleringe og klistermærker."}, {"type": "para", "text": "Jeg tænker tit på, om Lars selv synes, at han har haft en god barndom, og om han føler, at han har manglet og mangler søskende. Jeg håber, han synes, at han har haft en ligeså god barndom, som jeg synes, jeg har haft, og jeg var trods alt enebarn, til jeg var 10 år gammel. Jeg var som barn god til at beskæftige mig selv, og det var Lars også. Nogle gange for god. Vi syntes til tider, at han godt kunne opsøge kammerater i stedet for, at de altid skulle komme til ham, og så var det ikke altid, det lige passede ham at lege, hvis han nu lige var midt i at samle Lego eller lave et modelfly. Og så spørger vi jo også os selv, om vi tog os for lidt af ham, når han nu var så nem og ikke krævede underholdning, som mange børn gør i dag. Det, vi ofte hyggede os med, var cykelture. I sommeren 1982 fik Lars en brugt blå cykel, som i foråret 1984 blev skiftet ud med en ny crosser til 800 kr. Om sommeren cyklede Lars og jeg sommetider til Hadsten Svømmebad, hvis vejret var godt. Han elskede vand og var noget af en vandhund. Derfor blev han da også ellevild, da vi fik tilbudt at købe Johns svømmebassin for 100 kr. (herom senere). Det var også altid populært, når jeg ville læse for Lars."}, {"type": "para", "text": "I efterårsferierne havde Lars og jeg altid en dag, hvor vi tog til Århus og hyggede os med shopping, McDonalds besøg og biograftur. Vi har bl.a. set Lille Per, Ronja Røverdatter, Hodja fra Pjort, og Valhalla, og når Vagn og Lars var alene afsted i bio, så de bl.a. Batman og Indiana Jones. Det helt store hit i 1985, før vi selv fik video, var at låne en video plus film af en af Vagns kolleger, Torben, og så hyggede vi os med Sylvester Stallone: ”First Blood” og Dirch Passer film. Vi så dem gerne flere gange."}, {"type": "figure", "caption": "Lars og far i bad 1981", "page": 70, "file": "assets/images-bog2/p070_01.jpg", "dim": [1012, 683]}, {"type": "para", "text": "Det var sjældent, at Lars fik skældud, men engang de havde været til svømning, og Lars og Klaus på vej hjem i bilen blev alt for højrøstede og ikke ville ”skrue ned for lyden”, selvom de fik besked på det adskillige gange, fik Lars en afklapsning, da de kom hjem. Den huskede han længe efter og måske stadigvæk."}, {"type": "para", "text": "Fra Lars var helt lille, nød vi at have ham liggende i sengen imellem os, men da han blev lidt større, gad han ikke mere. Han kunne ligge der nogle få minutter men erklærede så: ”I puster mig i ansigtet”, og så udvandrede han. Men når vi læste for ham, kunne han godt blive liggende. Vi nød alle tre at gå i bad sammen i badekarret. Vi kunne lige være der, Vagn og jeg i hver sin ende og Lars i midten, men da han blev 7 år, sluttede det. Om sommeren tog vi ofte ind til gratis parkunderholdning i Botanisk Have. Det var rigtig hyggeligt, og det var god underholdning både for børn og voksne med Bjørn Tidemand som konferencier. Nogle få gange om sommeren tog vi også i Cirkus, i Friheden eller Djurs Sommerland, og så var der selvfølgelig sommerferierne, som vi nød i fulde drag, men de er nævnt andre steder i bogen. Når der var sne om vinteren, kørte vi i kælk. Især weekendturene med Alice og Reinholt i Knud og Teklas sommerhus i Tranum husker vi som fantastiske med masser af sne og slædeture, hvor vi skiftedes til at trække Lars, og hvor vi på skift drønede ned ad bakkerne til stranden. På de ture spillede vi også spil, både Matador og Danmarksspil.                                                                                     Lars 5 år, foto af  Reinholt Lars’ 5-års fødselsdag: Lars, Winni, Allan, Carsten, Klaus og Sune Vi har altid gjort meget ud af Lars’ fødselsdage, og han har haft kammerater med hjem fra skole. Kunsten var at finde på nogle aktiviteter, som drengene syntes var sjove, og som forhindrede dem i at larme alt for meget. Da Lars fyldte 7 år, kom Per og hjalp til med at underholde drengene. Vi havde lejet nogle lysbilleder om dyr i Afrika, som vi skulle vise på et lærred i kælderen, men drengene var da ligeglad med dyrene, så det var ingen succes. Per snakker om den fødselsdag endnu, så den må have gjort indtryk. Året efter var de 13 drenge fra klassen, og jeg tror, at det var det år, at det gik så hedt til, at nogle smed bluserne og endte med at sidde i deres undertrøjer, og måske var det også det år, hvor Bjørn spiste stearinlysene. Jeg bagte altid brunsviger kagemand med slik, og et år var hele klassen inviteret, også pigerne. Den fødselsdag frygtede jeg, men mor hånede mig lidt, for hun var jo vant til at styre en hel børnehave, så hvad betød en sølle klasse! ”Fint”, sagde jeg til mor, ”så kommer du ned og styrer slagets gang”. Det gjorde hun så, men hun blev overrasket og måtte æde sine ord igen, selv om hun sjældent indrømmede, at hun tog fejl. Vi havde lavet diskotek i stuen, så der skulle danses, og under en dans ville mor lige gå ind i stuen, for at se, hvordan det stod til. Hun var nær blevet væltet omkuld, så da hun kom bestyrtet ud i køkkenet og beklagede sin nød, kunne jeg ikke dy mig for at grine og sige: ”Hvad sagde jeg?”"}, {"type": "figure", "caption": "", "page": 71, "file": "assets/images-bog2/p071_02.jpg", "dim": [557, 831]}, {"type": "figure", "caption": "", "page": 71, "file": "assets/images-bog2/p071_01.jpg", "dim": [1015, 681]}, {"type": "figure", "caption": "1.10.1983 Oldemor prøver Lars’ walkman Agathe fra Norge har Julen 1981, guitar fra Jane og Lene strikket trøje til Lars 1983", "page": 72, "file": "assets/images-bog2/p072_01.jpg", "dim": [683, 1015]}, {"type": "figure", "caption": "", "page": 72, "file": "assets/images-bog2/p072_02.jpg", "dim": [481, 957]}, {"type": "figure", "caption": "", "page": 72, "file": "assets/images-bog2/p072_03.jpg", "dim": [430, 693]}, {"type": "para", "text": "I 1988 gik Lars til musik, korsang, håndbold, svømning, FDF spejder og dans, jo, han var en travl ung mand, men til jul stoppede FDF. Lars havde ellers fået alt det udstyr, der skulle til, og han gik meget op i det, så jeg tror, han var ked af, at kredsen lukkede."}, {"type": "para", "text": "Da Lars fyldte 12 år var det slut med at have hele klassen. I stedet ville han gerne bare have de drenge fra Spørring, han gik i klasse med, foruden Klaus, som jo gik på privatskole i Randers, så ud over Lars og Klaus var der Brian, Rasmus S, Rasmus E og Bjørn. De fik grillkylling med pommes frites og is, og bagefter lavede vi Fup eller Faktum, som Vagn optog på video, som var det en TVudsendelse. Jeg var TV-vært og styrede slagets gang. Jeg tror, drengene syntes, det var sjovt."}, {"type": "para", "text": "I starten af 1987 flyttede vi Lars’ anlæg og legetøj i kælderen, men selvom Lars nu var stor, skulle han stadig puttes af mor, også da han blev 12 år. Det var rigtig hyggeligt."}, {"type": "para", "text": "Lars var med sit lidt beskedne og venlige væsen en populær dreng i skolen, både blandt lærerne og eleverne, og han havde mange venner. Han har aldrig været den, der førte sig frem, hvilket nok stammer fra hans nordjyske rødder, hvor man ikke skal tro, at man er noget. Han var ikke den, der mobbede eller drillede kammeraterne, men han bekymrede sig tværtimod om deres velbefindende. Samtidig var han en blød dreng, der let blev rørt, og det er efter min mening et meget positivt karaktertræk. Nogle gange kunne vi måske godt have ønsket, at han havde været lidt mere udfarende og opsøgende, men han hvilede godt i sig selv og kedede sig aldrig, og på trods af dette, var han alligevel social, når det skulle være. For mig var han enhver mors drøm om en søn. Vi henter juletræ 1981                                        Lars på værkstedet den 1.10.1980. Saven var en gave."}, {"type": "figure", "caption": "", "page": 73, "file": "assets/images-bog2/p073_01.jpg", "dim": [683, 857]}, {"type": "figure", "caption": "", "page": 73, "file": "assets/images-bog2/p073_02.jpg", "dim": [680, 867]}, {"type": "para", "text": "Lars nød også at være sammen med Vagn ude på værkstedet, og tidligt fik han af ham sit helt eget værktøjssæt, så han kunne hamre og save som sin far. Han havde sit eget skab med værktøj og et skab med fiskegrej, som han havde fået i fødselsdagsgave. Fra Lars kunne tale, var det første, han sagde om morgenen, når han slog øjnene op: ”Mor, hvor er far henne?” Han var både en mor- og en fardreng. I juni 1989 kom Lars til skade med en dørplade, som han fik ned over sin storetå. Det gjorde mega ondt, og det dunkede slemt i tåen, hvor der havde dannet sig en blodansamling under neglen. Vagn havde sin helt egen metode til at lette trykket på, omend den var lidt barsk. Han tog et meget tyndt bor og borede forsigtig et hul i neglen. Det lettede på trykket. I oktober samme år skete det igen. Lars var ude på værkstedet med Vagn og skulle kløve noget træ. Trods advarsler fra sin far, ramte han desværre ved siden af og snittede sig i knæet med en økse, så det var afsted til skadestuen – uden mig. Jeg kunne ikke klare at se det. Der blev kun syet to sting, men han kunne ikke komme til dans i en periode derefter."}, {"type": "figure", "caption": "Lars i kælderen med sin PC forår 1989", "page": 73, "file": "assets/images-bog2/p073_03.jpg", "dim": [1012, 697]}, {"type": "figure", "caption": "Juleaften i Spørring 1986 – vores første jul uden far Lars har fået kasket og halstørklæde af Alice, Reinholt og børnene i fødselsdagsgave 1985 (8 år) Danmark kvalificerede sig til VM i Mexico i 1986 (fodbold)", "page": 74, "file": "assets/images-bog2/p074_04.jpg", "dim": [486, 961]}, {"type": "figure", "caption": "", "page": 74, "file": "assets/images-bog2/p074_05.jpg", "dim": [1015, 691]}]}, {"title": "Familien", "blocks": [{"type": "figure", "caption": "", "page": 74, "file": "assets/images-bog2/p074_01.jpg", "dim": [985, 675]}, {"type": "para", "text": "En af de første familiebegivenheder i 80’erne var, da Per blev student den 17. juni 1980 fra Hjørring Gymnasium. Det var en stor dag, og familien var naturligvis samlet, foruden Ditte, Ejvind og Jesper. Per var i en periode ansat i Ejvinds købmandsforretning i sin fritid, og der opstod et varmt forhold imellem Per og købmandsfamilien, hvilket også smittede af på os andre. Per var en dygtig mand for Ejvind, som måske havde håbet, at Per ville have overtaget butikken, men Per ville forståeligt nok noget mere end at drive en købmandsforretning i Thorshøj."}, {"type": "figure", "caption": "", "page": 74, "file": "assets/images-bog2/p074_03.jpg", "dim": [421, 620]}, {"type": "figure", "caption": "", "page": 74, "file": "assets/images-bog2/p074_02.jpg", "dim": [572, 625]}, {"type": "para", "text": "Efter studentereksamen kom Per ind til militæret (Flyvevåbnet), hvorefter han begyndte at læse til Civiløkonom på Handelshøjskolen i Århus den 1. september 1981. I starten boede han hos os i kælderen og betalte 1000 kr./md. for kost, logi, vask og strygning. Det var hyggeligt at have ham boende, og vi havde altid en barnepige. Men der foregik jo ikke så meget i Spørring efter skoletid, så til maj 1982 flyttede han ind på Børglumkollegiet, hvor han også senere fandt sit livs kærlighed i Marianne. Vi holdt en afskedsmiddag for ham den 29. april. I gymnasietiden og som soldat var han som tidligere nævnt kæreste med Jette Vrængmose fra Øster Vrå. De kom sammen i 3 år, men i maj 1982 slog hun op med ham. Det var hårdt for Per, og hele sommeren havde han det skidt. Mor var i perioder bekymret for ham. Senere sås de lidt igen, og da far fyldte 60 år i september 1984, var Jette på banen igen – troede vi. Per var glad, og hun var med til festen og på familiebilledet, men bagefter var det slut. Heldigvis mødte Per hurtigt derefter Marianne, som vi straks kom til at holde meget af. Hun boede også på kollegiet og læste til journalist, og en aften styrtede hun på sin cykel og blev hjulpet hjem på sit værelse. Per tog sig efter sigende pænt af hende, og det udviklede sig. Første gang, vi mødte Marianne, var til mors fødselsdag den 9. marts 1985. Da fandt vi ud af, at Marianne var vegetar, for mor havde stegt duer. Mor troede, at vegetarer spiste fjerkræ, men vi fandt ud af, at det gjorde de ikke, da Marianne på mors spørgsmål, om hun kunne lide fuglen, svarede, at den smagte som lever. Stakkels Marianne. Vi blev ved med at holde kontakten til Jette, som besøgte os, senere sammen med sin kæreste (nu mand) Brian i 1987 og 1988. Senest har jeg mødt Jette til skolejubilæum den 18. september 2010 i Øster Vrå. Det var sjovt at møde hinanden igen. Hun bor i dag med Brian og to voksne børn i Middelfart, hvor hun har en blomsterbutik. Her er jeg med min dejlige bror i Tivoli 1985 Den 25. juni 1984 blev Per civiløkonom, og vi var stolte. Tidligere samme år havde han været i England, og den 3. april 1986 tog han til USA sammen med 6 kammerater, som han havde læst sammen med. Den 10. august 1987 hjalp vi Per med at flytte til København. Han havde fået job som trainee hos SAS og havde sammen med Marianne købt en andelslejlighed i Willemoesgade lige ned til søerne. Mor var pavestolt af sin søn, selvom hun nu sjældnere så ham. I juni 1988 tog Lars og jeg til København til Per og Marianne. Lars blev derovre på ferie og havde nogle fantastiske dage. Han var med Mariannes far Børge i TV-byen (Børge var også journalist), og Per og Marianne tog ham med i Tivoli, Zoologisk Have og i biografen for at se James Bond. Per og Lars var også i Sverige en dag. Som trainee ved SAS skulle Per prøve at arbejde med mange forskellige opgaver og forskellige steder, og et af stederne var USA, hvortil han og Marianne flyttede i efteråret 1989, til Los Angeles i en lejlighed helt ned til stranden. Marianne var blevet ansat som journalist ved Danmarks Radio i 1987 og arbejdede der i nogle år, og vi var stolte, når vi hørte hendes blide røst i radioen, hvor hun rapporterede i nyhederne. Vi kunne altid høre, når det var Marianne. Mor var også stolt af sin svigerdatter."}, {"type": "figure", "caption": "", "page": 75, "file": "assets/images-bog2/p075_01.jpg", "dim": [520, 689]}, {"type": "figure", "caption": "", "page": 75, "file": "assets/images-bog2/p075_02.jpg", "dim": [510, 762]}, {"type": "figure", "caption": "", "page": 75, "file": "assets/images-bog2/p075_03.jpg", "dim": [1015, 694]}, {"type": "para", "text": "På mors fødselsdag den 9. marts 1981 havde vi en grim oplevelse med mormor, mens hun var på besøg hos os i nogle dage. Vi havde alle fire været ude på værkstedet for at bore hul i en kokosnød. Det stormede voldsomt, og da mormor tog i bagdøren, som åbnede udad, kom der et vindstød og blæste døren op og hende omkuld, så hun faldt bagover, ned af trappen og hamrede hovedet ind i husmuren. Lars stak i et skrig, og jeg troede, at mormors sidste time var kommet, for det så virkelig voldsomt ud, og blodet fossede ud af det hul, hun havde fået i hovedet. Men min seje mormor kom på benene og kunne konstatere, at intet var brækket, men hun gik dog med til, at vi kørte på skadestuen med hende. Hun fik et håndklæde viklet om hovedet, og så kørte vi afsted. Jeg husker, at hun sagde til mig, at denne gang var det mig, der skulle holde ved hende, fordi hun havde fået hul i hovedet. 29 år tidligere havde rollerne været byttet om. På skadestuen blev hun limet i hovedbunden, men hun havde ikke engang fået hjernerystelse. Hun tog det hele som en oplevelse og fortalte senere vidt og bredt om, hvordan de på skadestuen havde spurgt til hendes erhverv og slet ikke havde kunnet forstå, at hun snart fyldte 80."}, {"type": "figure", "caption": "Oldemor fylder 80 år, den 26.12.1981", "page": 76, "file": "assets/images-bog2/p076_01.jpg", "dim": [683, 1022]}, {"type": "para", "text": "Engang da hun var her, mens Per boede her i sin studietid, ville hun lave budding til dessert. Jeg havde fortalt hende, at hun skulle røre i mælken konstant, indtil den kogte, for ellers ville den brænde på. Hun var jo vant til andre gryder, som måske var nemmere at koge budding i. Men mormor havde altid været hurtig til sit arbejde og kunne også ”multi-taske” – et begreb, der ikke fandtes dengang. Det havde hun simpelthen været nødt til på Konditoriet, hvor der havde været meget at bestille. Vi havde alle glædet os til budding den aften, men da jeg fik den første skefuld i munden, var jeg lige ved at spytte den ud. Buddingen var i allerhøjeste grad brændt på. Den var uspiselig, og det undlod vi heller ikke at erklære over for hende, for mormor var ikke medlem af diplomatiet, og så behøvede vi heller ikke være det. Per og Lars nægtede blankt at spise den, og jeg havde meget svært ved at få den ned. Men mormor, som sjældent indrømmede et nederlag, erklærede, imens hun skovlede buddingen ind det bedste, hun havde lært, at den smagte upåklagelig, at den kun var meget lidt brændt på, og at det var noget pjat, at vi ikke kunne spise den. Det har vi siden grinet meget af. Budding fik hun ikke mere lov til at lave, men hun var naturligvis god til at bage, idet hun var gammel bager og havde fabrikeret meget brød i bageriet på Konditoriet i sin tid. Hun kunne også lave den herligste æggekage i ovnen og var desuden med på den sidste mode, hvad angik mad. Hun var ikke bange for at prøve nye retter og opskrifter, så det var tit spændende mad, hun serverede, når vi kom på besøg. Første gang, at mormor var indlagt på hospitalet, var den 29. januar 1985, hvor hendes ene lunge var klappet sammen, men hun var hurtigt hjemme igen den 6. februar. Året efter, den 14. januar, brækkede hun albuen ved et fald, men det groede fint sammen, så hun kunne hurtigt genoptage sit håndarbejde. Jeg har noteret, at hun bagte horn, da hun besøgte os sidst i august 1987, og i september 1988 lavede hun is og bagte boller, mens hun var her. Hun lavede den bedste æggekage, så det fik vi tit, når hun var på besøg. Da mormor besøgte os i juni 1989, bagte hun brød og kage, så hun var altid i gang med noget. Da var hun 87 år."}, {"type": "para", "text": "Jeg har endvidere noteret, at Lars var på ferie hos sin mormor og morfar før påske i 1983. I 1985 var han der fra den 30. juni til den 5. juli, og den dag han skulle hjem, faldt han og slog hovedet, så Bedstefar fylder 70 år den 16.1.1981                                               Lars på ferie i Thorshøj juli 1985 de måtte til lægen med ham. Det var heldigvis ikke alvorligt. Da mor blev alene, var Lars på ferie hos hende i sommeren 1987, og året efter var han med hende i Norge og besøge Agathe og familie. Det var helt sikkert en fin tur, og jeg undte mor, at hun skulle have Lars med, for hun var så stolt af ham. Her bagefter fortryder jeg, at mor og far ikke fik lov at have Lars på ferie noget mere."}, {"type": "figure", "caption": "", "page": 77, "file": "assets/images-bog2/p077_02.jpg", "dim": [747, 512]}, {"type": "figure", "caption": "", "page": 77, "file": "assets/images-bog2/p077_01.jpg", "dim": [751, 510]}, {"type": "figure", "caption": "", "page": 77, "file": "assets/images-bog2/p077_03.jpg", "dim": [687, 855]}, {"type": "para", "text": "Jeg husker en gang, hvor vi sagde, at det ikke kunne lade sig gøre. Det var det år, hvor far blev syg og døde, så derfor var det ekstra ærgerligt. Men det var ikke altid nemt at få tingene til at passe sammen, når vi boede så langt fra I 1980 tog Reinholt (og Vagn) dette billede af Vestergård fra et fly     hinanden. Nu forstår jeg dog bedre end dengang, at de så gerne ville have Lars på besøg. Nu er jeg selv blevet farmor, og det er vidunderligt at få lov til at passe sine børnebørn, og sådan havde mor og far det også. De havde jo også kun Lars."}, {"type": "figure", "caption": "Lars og Thomas 1980. Jeg havde købt ens nattøj til dem i England.", "page": 78, "file": "assets/images-bog2/p078_01.jpg", "dim": [503, 641]}, {"type": "para", "text": "Jeg har noteret, at Lars var på ferie i Vestergård fra den 5. til den 10. august 1984, hvor han også var i Thorshøj. Året efter var han sammen med Thomas på ferie i Vestergård fra den 28. juli til den 2. august. Det har helt sikkert været sjovt at have de to drenge sammen. Året efter, 1986, blev Vestergård solgt, og det var slut for drengene med at lege i halmen og tælle korn."}, {"type": "para", "text": "Farmor og bedstefar så på mange huse i Tårs, og nogle gange var vi med. En gang tog Vagn derop for at se på et hus sammen med dem, men det var et i to etager med badeværelse ovenpå. Farmor gik mere op i, at der var nogle pæne møbler i huset, som om de fulgte med, og bedstefar var parat til at købe det, men Vagn satte en kæp i hjulet på grund af badeværelset ovenpå. Hvis en af dem brækkede et ben, ville de ikke kunne komme på toilet. Ejendomsmægleren blev sur og sagde til bedstefar, at han ikke skulle tage sin søn med en anden gang. Heldigvis købte de ikke huset, for bedstefar brækkede benet i sommeren 89. En dag, da vi besøgte Birthe og Djernes, som boede på en sidegade til Blommely, fortalte de, at Blommely 3 var til salg. Det var et dejligt stort dobbeltvinklet hus, hvor farmor kunne have de fleste af sine fine møbler, så vi fik arrangeret et besøg, og det endte med, at de købte det og flyttede ind den 24. maj 1986. Vi var naturligvis alle hjemme og hjælpe til med flytningen, og da vi var færdige, og gården var overdraget til de nye ejere, skulle vi alle samles på terrassen i den dejlige inder-gård, der var ved huset og spise aftensmad. Pludselig udbryder bedstefar: ”Åh, for dælen!” og ta’r sig til brystet. Han stiger op af stolen, farer ud og starter Volvoen. Vi kigger uforstående på hinanden. Da han kort efter kom tilbage, så han meget med Cecilie og Anders, som i dag er en anerkendt violinist lettet ud. Han havde glemt, at han havde gemt 35.000 kr. i en kuvert i skorstenen ved gruekedlen i bryggerset. Det var dem, han havde været tilbage og hente, og heldigvis var de nye ejere endnu ikke flyttet ind. Men reelt set havde han ikke mere at gøre på gården, så han var heldig. Bagefter morede vi os meget over hændelsen. Jeg tror ikke engang, at farmor var klar over, at han havde gemt penge der. Vi var dengang glade for, at de flyttede, og Lars glædede sig over de 6 programmer, de kunne tage på TV, men set i bakspejlet skulle de være blevet boende og have lejet jorden ud. Bedstefar trivedes ikke så godt som byboer, som vi havde håbet. Vi gav ham en fiskestang, så han kunne tage ud og fiske, men det blev ikke rigtigt til noget. Han var rastløs og savnede gården. Men trods det fik de alligevel nogle gode år i huset, og det var godt for farmor at få noget mindre og nemmere at holde, selvom det nye hus også var stort. ."}, {"type": "figure", "caption": "", "page": 78, "file": "assets/images-bog2/p078_03.jpg", "dim": [536, 803]}, {"type": "figure", "caption": "Lars på besøg hos Bjørnstads i 1988. Til højre spiller han sammen", "page": 78, "file": "assets/images-bog2/p078_02.jpg", "dim": [813, 559]}, {"type": "para", "text": "Lars havde som sagt også et godt forhold til sin onkel Tage, og det skete nogle gange som 7- og 8- årig, at han fik lov til at komme med Tage på arbejde og sidde ved siden af ham i den store betonpumpebil. Men i 1988 kom der en kvinde ind i Tages liv, Anna-Lise, og det var det bedste, der var sket for ham. Godt nok fik vi nu ikke så ofte besøg af Tage, men han skulle nu ikke mere leve sit liv alene. Anna-Lise var enke efter Ejnar, som døde i 1987 efter lang tids nyresygdom og transplantation. Anna-Lise og Ejnar var med i Tages kortklub og var med, da Tage fyldte 40 år, så vi kendte godt Anna-Lise, men hun var første gang med hjemme i Tårs den 24. september 1988. Hun faldt godt til i familien og flyttede senere ind hos Tage i 1992 efter at have solgt sit hus på Ørnevej i Svenstrup. Farmor fylder 75 år den 3.8.1989 Alt var ikke lutter lagkage i familien, og i 1984 skulle vi opleve en separation og senere skilsmisse for første gang: Helge og Tove blev separeret den 6. juni 1984. Alt var jo rosenrødt, da de blev gift den 1. september 1962, men de blev aldrig lykkelige, måske fordi de ikke kunne få børn. Vi fandt senere ud af, at det var Helge, der ikke kunne producere børn og ikke Tove, som vi havde troet. Vi havde det bedste forhold til Tove, men hun havde mindreværdskomplekser overfor sine svigerinder og sin svigermor, min mormor. De var jo alle de perfekte husmødre, som kunne diske op med alverdens retter på ingen tid, holde hus og hjem rent og pænt, mens hun ikke duede til noget. Hun havde aldrig lært noget af sin mor, og det var Helge, der skulle lave alting. Vi ved naturligvis ikke præcist, hvad der gik galt, men Tove begyndte at drikke og forsømme hjemmet mere og mere, og Helge sejlede i bogstaveligste forstand sin egen sø, idet han tog på sejlture i deres båd, hvilket Tove ikke havde lyst til, og han morede sig med vennerne, mens hun lå hjemme på sofaen og blev mere og mere forsumpet. Når vi engang imellem så Tove, havde hun altid en rød næse, og vi tænkte vores. Da det blev officielt, at hun skulle flytte, var jeg hos Erik en aften i forbindelse med en censor-tur til København. Tove og Helge kom forbi og snakkede, men stemningen var trykket, for vi vidste alle, at det var ved at være slut. Jeg fik naturligvis sagt farvel til hende, men bagefter var jeg ked af, at jeg aldrig fik hende fortalt, hvor meget vi satte pris på hende. Jeg så hende aldrig igen men hørte, at hun fandt sig en dranker-kæreste og døde af en blodprop, inden hun fyldte 50. Vi besøgte onklerne sammen med mormor den 8. juni 1989 og var også hos Marianne og Per. Vi var på Bakken og på Arbejdermuseet. Det var lige før Marianne og Per skulle flytte til Los Angeles i USA, samme år som San Francisco blev ramt af jordskælv den 18. oktober. Det var mærkeligt på TV at se biler køre i døden på broen, der kollapsede, den selvsamme bro, som vi havde kørt på i juli måned samme år. Marianne rapporterede om jordskælvet i radioen samme dag. Onkel Ib fyldte 60 år den 25. august 1988, og vi var alle inviteret med til fest i Skagen. Lars var det eneste barn, der var med, men det var han vant til, og han kedede sig ikke. Vi havde sammen med Per og Marianne lavet en sang og lagt hver sang i en konvolut, da Ib jo var postbud. Lars var klædt ud som rød post og delte brevene ud til gæsterne under stor jubel. Vi havde lånt stempel og postsæk på Spørring Brevsamlingssted og fået klistermærker på Hovedpostkontoret i Århus. Dragten havde vi lånt af Spørring Dilettantforening."}, {"type": "figure", "caption": "", "page": 79, "file": "assets/images-bog2/p079_01.jpg", "dim": [823, 546]}, {"type": "figure", "caption": "", "page": 80, "file": "assets/images-bog2/p080_01.jpg", "dim": [781, 1152]}, {"type": "para", "text": "I fars familie kom problemerne først senere, så i 80’erne herskede der endnu idyl, og vi begyndte at holde kusinefester. Det var kun halvdelen af familien, nemlig far, faster Aase og faster Grethe med familier, der deltog. Den første fest blev holdt hos min kusine Bodil i Skalborg i 1985 og senere hos Elin i Sæby den 8. august 1987. Jeg var ellers sur over at skulle til kusinefest netop den dag i 1985, for samme dag holdt Torslev Centralskole 25 års jubilæum. Det ville jeg gerne have deltaget i, men mor syntes ikke, vi kunne melde afbud til Bodil og Erik. Igen var det mor, der bestemte. Den 19. august 1989 kom turen så til os, og vi var værter for en fin weekend, for fars familie var jo ikke kedelige at være sammen med. Det var ikke alle, der kunne komme, men jeg tror, vi var 14, så vi kunne lige være omkring spisebordet. De kom til eftermiddagskaffe, som vi drak i haven, da vejret var fint, og til aften fik vi kinesisk mad og spiste med pinde. Hanne og Keld vartede                            Aase og Viggos sølvbryllup den 5.12.1984 op, og Keld spillede på harmonika, så stemningen var god. Grethe og Peter sov i soveværelset, Elin og Kurt havde lejet værelse på Hotellet, mens Bodil og Erik boede i Grete og Pouls campingvogn. Aase og Viggo sov i kælderen, og hvor resten sov, husker jeg ikke."}, {"type": "figure", "caption": "", "page": 80, "file": "assets/images-bog2/p080_02.jpg", "dim": [1168, 797]}, {"type": "figure", "caption": "Lars julebager 1980", "page": 81, "file": "assets/images-bog2/p081_01.jpg", "dim": [660, 1009]}, {"type": "para", "text": "Indtil fars død i 1986 holdt vi altid juleaften i Thorshøj sammen med mor, far og Per. Vi gik normalt ikke i kirke juleaften, for det var ikke noget mor og far havde været vant til hjemmefra, men i 1983 gjorde vi det, og det var rigtig hyggeligt. Den aften var der 122 pakker under juletræet til os 6 mennesker. Det var også det år, hvor Alice, Svend og børnene var til jule-ende i Vestergård, og vi var til juletræ på Hotellet i Spørring 4. juledag. Lars var altid tålmodig juleaften, og da han var i 4-års alderen ville han også gerne have bløde pakker og delte mange knus ud juleaften."}, {"type": "para", "text": "Fra 1986 begyndte vi at holde jul i Spørring med mor, både med og uden Per, men i 1986 var vi der alle. Det år havde Lars sparet ca. 3.000 kr. op til et stereoanlæg, så til jul gav vi ham 1.000 kr., så han nu kunne købe et Philips anlæg med radio, pladespiller og to båndoptagere. I 1987 gav vi Lars en monitor med tastatur og diskettestation, som vi havde købt brugt af John. I 1988 var Per der også, og det var året, hvor Lars fik ny cykel i julegave og Vagn var til en meget våd julefrokost den 23. december. Den 21. december sov jeg for en gangs skyld over, og Lars nåede ikke skolebussen. Det var han ked af, for det var den sidste dag før jul, hvor de skulle have flødeboller og hygge sig. Jeg udstyrede ham derfor med et klippekort og sendte ham ned for at tage bus nr. 117. Lidt efter kom han slukøret hjem. Buschaufføren havde bedt ham stå ud, fordi maskinen ikke ville tage kortet. Der var ikke noget i vejen med kortet, så jeg var rasende. Lars kom ikke i skole den dag, og jeg ringede flux til busselskabet for at få oplyst buschaufførens navn. Det ville de ikke give mig, men de kunne da fortælle, at han skulle køre den samme rute næste morgen kl. 7."}, {"type": "figure", "caption": "", "page": 81, "file": "assets/images-bog2/p081_02.jpg", "dim": [796, 551]}, {"type": "para", "text": "Næste morgen stillede jeg nede ved bussen, og da den kom, steg jeg op i den og forlangte at få en undskyldning. For øjnene af en fuld bus med mange spørringborgere gav jeg chaufføren det glatte lag. Jeg sagde, at han jo var ansat i et servicefag og var til for at hjælpe sine passagerer, og især børn, men han gav mig igen og sagde, at jeg var en dårlig mor, der gav min søn et buskort med, der ikke duede. Sandheden var, at kortet duede, men at maskinen ikke ville klippe det. Han sagde, at Lars jo bare kunne have protesteret, da han smed ham ud, men jeg havde åbenbart ikke lært min søn at lukke munden op. Det må enten have været meget underholdende at være vidne til dette sammenstød eller også meget pinligt, og jeg kunne jo ikke blive stående i bussen og forsinke turen for de mennesker, der skulle på arbejde, men jeg var rasende, da jeg gik derfra. Hvad bildte han sig ind? Jeg gik hjem og ringede til busselskabet igen og klagede over chaufførens opførsel. Senere mødte jeg ham igen i bussen, og de gange, vi mødtes, havde vi en ikke så venlig ordveksling, for jeg havde jo stadig kortet med det klip, som maskinen ikke ville tage. Alle andre chauffører ville have skrevet en bemærkning på kortet i stedet for et klip, hvilket jeg også fik en anden chauffør til. Senere mødte jeg ham ikke mere, og jeg håbede, at han var blevet fyret. Ingen skulle behandle min søde Lars på den måde."}, {"type": "para", "text": "I 1989 var vi åbenbart også kun fire juleaften, for jeg har noteret, at Marianne og Per ringede hjem fra Hawaii, men det var jo også det år, de boede i USA. Per Kjøller og Ruth, Nytårsaften 1983 Nytårsaftnerne i 80’erne var sjove. Vi var kommet ind i en tradition med Alice og Reinholt, kun afbrudt af nytårsaften i 1980, som vi holdt i Vestergård, fordi jeg i julen det år havde aborteret (herom senere). Året efter stod vi for tur, og Alice og Reinholt med børnene Per, Helle og John var hos os. Tage var selvfølgelig også altid med, og bordbomberne fik en ekstra gang konfetti, når vi skulle være hos Alice og Reinholt. De tog revanche til Tages 40 års fødselsdag, hvor de havde bordbomber med. I 1983, hvor det var vores tur igen, blev selskabet udvidet med Ruth og Villy Morgenstjerne, og så gik det på tur de tre steder til og med 1986, hvor vi serverede koldt bord og festede til kl. 3 om natten. Der kom altid nogen forbi, og i 1986, da gæsterne var gået, gik Tage og Vagn op til Else og Jørn Griis. Året efter var der kun os og Tage her, men efter midnat gik vi hen og ønskede Hanne og Keld ”Godt Nytår” og var der til kl. 6. I 1988 var Anna-Lise og Tage her, og i 1989 var vi hos dem."}, {"type": "figure", "caption": "", "page": 82, "file": "assets/images-bog2/p082_01.jpg", "dim": [1012, 697]}, {"type": "para", "text": "Lars var ikke den, der lavede mange nytårsløjer, men han fik altid lov at være ude sammen med de andre børn, og han var til tider øjenvidne til diverse løjer. Som for eksempel det år, hvor Jesper Poulsen sprængte vores ene udendørslampe i stykker. Lars har måske været 6-7 år, og Jesper stak ham en 25-øre for at holde kæft. Det var dog ikke nok, for Lars sladrede til os om hændelsen."}, {"type": "para", "text": "Fra USA var der følgende nyheder: Den 4. januar 1980 ringede Margaret og fortalte, at Martinus var død, knap 78 år gammel. Julius døde den 9. januar 1985, men det tog mange år, inden arven til mor og de andre arvinger blev udbetalt. Grunden var, at Julius havde lånt nogle penge ud, uden at det var registreret. Mor arvede 50.000 kr."}]}, {"title": "Aborter", "blocks": [{"type": "para", "text": "Vi ville jo gerne have flere børn, men så nemt gik det nu ikke. Derfor blev vi også ovenud lykkelige den 3. december 1980, da vi fik at vide, at jeg var gravid. Jeg skulle føde i juni. Det var helt perfekt, at Lars skulle være storebror i en alder af knap 3 år. Men lige op til jul begyndte jeg at bløde. Det var først, da vi var nordpå den 24. december om formiddagen, at jeg konstaterede, at den var gal, og jeg tror ikke, jeg sagde noget, før vi var i Thorshøj lige inden aften. Vi besluttede, at jeg hellere måtte tage den med ro, så juleaften tilbragte jeg på sofaen i håb om, at blødningerne ville stoppe. Jeg var som sådan ikke syg, så vi havde en hyggelig juleaften, selvom jeg inderst inde var nervøs for, hvad der kunne ske. Det år fik Lars et dukketeater af mor og far. Mor havde taget deres gamle fjernsynskasse, hvor al indmaden var pillet ud, og så havde hun, opfindsom som hun var, syet et forhæng, som blev trukket fra, når spillet skulle i gang. Til formålet havde hun strikket handskedukker til Lars. Juledag lå jeg i sengen, og vi var nu spændte på, om jeg kunne komme med ud til mormors fødselsdag 2. juledag, men i stedet kom jeg på hospitalet. Der kom en ambulance efter mig 2. juledag om formiddagen, og jeg blev kørt til Hjørring Sygehus, hvor jeg blev undersøgt af en læge, som viste sig at være min gamle klassekammerat Bent Olsen fra Brønderslev. Vi havde gået i 1.g sammen. Det var sjovt at se ham igen, men det kunne have været hyggeligere under andre omstændigheder, end at have ham til at stå og rode med mit underliv. Resultatet af undersøgelsen var nedslående, så næste dag fik jeg en udskrabning, og så var jeg så god som ny og klar til et nyt forsøg. Jeg græd meget, mens jeg lå der i min ensomhed uden for besøgstiderne, selvom lægen havde forklaret, at der nok havde været noget i vejen med fosteret, og at det var naturens gang, at det skulle udstødes, men at det sikkert ville gå godt næste gang. Mor og far hentede mig inden nytår, og jeg husker fars forbavselse, da det gik op for ham, at jeg ikke mere var gravid. Han havde ikke forstået, at jeg havde fået en udskrabning. I tiden herefter gik jeg rundt som i en glasklokke og syntes ikke, der var noget ved tilværelsen. Heldigvis havde vi Lars, som var et lyspunkt i den triste hverdag. Jeg fik også øjnene op for, hvor stort et hjerte vores nabo i nr. 27 havde. Ellen og Ras var jo flyttet ind et par år tidligere, men jeg var fuld af fordomme over for dem, fordi mange kaldte Ellen en sladderkælling. Nogle få dage efter at vi var kommet hjem oven på min indlæggelse og nytåret, stillede hun stor og mægtig i døren med tre små blomster og et kæmpeknus. Da kunne jeg ikke holde tårerne tilbage, men jeg var også meget hudløs i den tid, og der skulle ingenting til, før jeg tudede. Efter den dag kom jeg til at holde meget af Ellen og Ras. Utroligt hvad tre små blomster og et knus kan gøre."}, {"type": "para", "text": "Den 20. august 1981 fik jeg konstateret, at jeg var gravid igen, og vi var lykkelige. Skulle det endelig lykkes? Men glæden varede kun kort, for den 6. oktober begyndte jeg at bløde. Jeg lagde mig straks på sofaen, og vi meldte afbud til den grænsetur, vi skulle have været på sammen med mor, far, Per, Elbo og Vibeke med børn. Vi havde været afsted før, og det var hyggelige ture, så vi var kede af, at vi ikke kunne deltage. Mor og far kom ind på vejen derned, og de tilbød at tage Lars med hjem efter weekenden. ”Nej, det må I ikke”, hulkede jeg. Jeg kunne ikke klare at undvære ham, men de sagde det jo kun for at hjælpe. Jeg blev igen indlagt og fik fosteret fjernet den 14. oktober. Nu var det virkelig svært at komme ovenpå igen, for nu troede vi nok mindre på, at det skulle lykkes. Jeg syntes, at jeg så gravide kvinder og barnevogne overalt, og jeg var dybt deprimeret. I vinteren 1984 gik jeg til nogle undersøgelser på Gynækologisk Institut for at finde ud af, hvorfor jeg ikke kunne gennemføre en graviditet. Den 5. marts blev jeg indlagt, og man fandt ud af, at jeg havde en godartet muskelknude i livmoderen. Den kunne ikke opereres væk, så jeg var langt nede, da jeg blev udskrevet. Jeg forsøgte med zoneterapi nogle gange, fordi jeg havde læst om en, der var blevet hjulpet på den måde, men der skete ikke noget. Efter endnu nogle behandlinger besluttede vi os for adoption."}]}, {"title": "Adoption", "blocks": [{"type": "para", "text": "Vi havde taget en beslutning: vi ville forsøge at adoptere en pige fra Colombia. Den 5. april 1984 afleverede vi adoptionspapirerne på Adoption Center i Århus. Der gik næsten et halvt år, inden der skete noget. I den tid prøvede vi at forberede os ved at læse bøger om adoption, og jeg inviterede Annie Bach til kaffe for at høre alt om deres adoption af Anja fra Korea. Vi syntes selv, at vi var klar, men det syntes adoptionsmyndighederne åbenbart ikke! Vi var til den første samtale sammen den 28. september 1984 på Socialkontoret og dernæst hver for sig den 29. oktober (Vagn) og den 30. oktober (Merete). Her bagefter kan jeg godt forstå Tove og Helge, når de sagde, at de ikke ville adoptere, fordi man fik hele sit følelsesliv og familieliv krænget ud. Bagefter har vi fundet ud af, at vi var alt for ærlige under samtalerne. Vi blev spillet ud mod hinanden, og de troede, at det var løgn, når vi påstod, at vi altid gik i seng på samme tid, og at vi aldrig havde synderlige konflikter eller skænderier. De hang sig meget i, at jeg havde været på børnehjem og nær var blevet bortadopteret, og de ville have mig til at fortælle dem, hvad jeg følte ved det. Det havde jeg meget svært ved, fordi jeg aldrig havde gået så meget op i det. Jeg kom for skade også til at sige, at min mor ikke var så vild med tanken om adoption, og det hang de sig åbenbart meget i. De kunne åbenbart heller ikke forstå, at vi ingen problemer havde med Lars, så de valgte at slæbe ham igennem flere møder med en børnepsykiater både med og uden vores tilstedeværelse. Vi fik sågar besøg den 25. januar 1985 fra Socialvæsnet, for at de kunne se vores hjem. Det vi senere kunne læse os til i rapporten var, at der var alt for pænt og ryddeligt, og at Lars ikke fik lov at svine ved bordet, men at jeg smurte hans bolle. Derefter var Lars ved børnepsykiater den 5. og 13. november, hvor han blev stillet helt urimelige spørgsmål omkring hans forventninger til et nyt barn i familien. Han var trods alt kun 8 år. Afslutningsvis var vi til et møde med den samme børnepsykiater den 17. december, hvorefter vi fik dommen ”uegnede” sammen med en tyk rapport om hele forløbet og alle interviews. Det var et hårdt slag for os, og efter at vi havde læst rapporten, gik Vagn ud og smed den i fyret. Det gjorde for ondt at have den liggende. Det, de slog på i rapporten som værende årsag til afslaget var, at mor var negativ, at jeg havde for travlt i hverdagen, at vi var for loyale over for hinanden (det var for godt til at være sandt) og at vi ikke havde forstand på at opdrage børn. Sådan tolkede vi det i store træk. Nu skulle vi bare videre, og det kom vi. Året efter fik vi noget andet at tænke på, da far blev alvorligt syg og døde, men herom senere."}, {"type": "figure", "caption": "Legestuen juni 1983. Lars sidder nederst til højre.", "page": 84, "file": "assets/images-bog2/p084_01.jpg", "dim": [697, 480]}]}, {"title": "Lars går i skole", "blocks": [{"type": "para", "text": "Lars blev meldt ind på Bakkegårdsskolen i Trige den 12. januar 1983 og begyndte i børnehaveklassen den 15. august samme år. Året efter, den 13. august, begyndte han i 1. klasse. Oldemor var på besøg i den periode, så hun og jeg fulgte Lars i skole den første dag. Det skulle hurtigt vise sig, at Lars var en mønsterelev, som lærerne var meget glade for. Da vi søgte om adoption, skulle Socialvæsnet bruge en udtalelse om Lars, så hans elskede børnehaveklasselærer og –leder Tove Antvorskov (til venstre i billedet på næste side) skrev den 5. oktober 1984: ”Jeg har haft Lars et år i børnehaveklassen. Lars fungerer godt blandt kammeraterne. Han er tillidsfuld over for voksne og klarer de stillede opgaver tilfredsstillende. Han arbejder selvstændigt og virker moden. Hans fysiske udvikling er alderssvarende. Lars er et roligt, harmonisk og velstimuleret barn.”  Senere på året var vi til forældrekonsultation, hvor Lars blev betegnet som et ønskebarn. I starten var de 6 drenge fra Spørring: Brian, Bjørn, Rasmus E, Rasmus S, Klaus og Lars, men Klaus havde problemer. Han havde krudt i røven og forstyrrede undervisningen. Hans måde at føre sig frem på var ikke populær blandt kammeraterne, så han blev mobbet (ifølge forældrene), og konsekvensen blev, at han blev taget ud af Bakkegårdsskolen og sat i en privat skole i Randers, Randers Realskole. Lars var glad for Bakkegårdsskolen, hvor især Jonna og Torben Bunk var blandt hans favoritlærere. Jonna havde han til engelsk, og Torben til matematik. Den 31. oktober 1988 skete der noget forfærdeligt. Drengene gik i juniorklub i Spørring, og den dag havde Brian leget cowboys med nogle andre drenge på legepladsen. Han var blevet tilbage, efter at de andre var gået, og senere fandt en ansat ham hængende i et reb, bevidstløs. Han havde i sin kådhed over legen leget videre og forøgt at hænge sig, som de gør i Westerns. Det var altså et uheld og ikke et selvmordsforsøg. Brian kom med udrykning på hospitalet og blev lagt i kunstig coma. Børn og forældre var chokerede, og vores tanker gik til Ingrid og Hans Jørgen, Brians forældre. I mange dage gik vi i uvished om Brians skæbne, men endelig ringede en af de andre forældre og sagde, at Brian ville komme over det. Vi var enormt lettede, og en af de efterfølgende dage købte jeg en buket blomster og gik op til Ingrid med. Brian kom over det uden mén og flyttede i sit voksenliv sammen med kæresten Pia ind i Gulla og Leifs hus og blev vores nabo på Østervang.  I 1989 var Lars nr. 1 i Skolebillede fra 5.a.1988-89             klassen. Vi hjalp ham aldrig med lektier eller kontrollerede ham, men var der noget i engelsk, han gerne ville have hjælp til, fik han det naturligvis. Efter vores tur til USA i 1989 holdt Lars et 2-timer langt foredrag om USA i klassen den 3. oktober."}, {"type": "figure", "caption": "", "page": 85, "file": "assets/images-bog2/p085_01.jpg", "dim": [879, 640]}, {"type": "figure", "caption": "", "page": 85, "file": "assets/images-bog2/p085_02.jpg", "dim": [996, 694]}, {"type": "figure", "caption": "", "page": 85, "file": "assets/images-bog2/p085_03.jpg", "dim": [530, 728]}]}, {"title": "Lars og dansen", "blocks": [{"type": "para", "text": "Jeg havde selv gået på danseskole som barn, og derfor var det helt naturligt for mig, at Lars også skulle gå til dans. Gennem dansen lærte man holdning og pli, og det skulle min søn lære. Derfor begyndte Lars at gå til dans i 1982 på Knud Jensens Danseinstitut i lokaler ved Banegården i Århus. I det år, han gik hos Knud Jensen, dansede han med Inge-Marie fra Østervang. Det første afdansningsbal blev afholdt i marts 1983, og mor og far havde taget turen herned for at være med. Det var stolte forældre og bedsteforældre, der sad og beundrede de små poder. Kun et år gik Lars Inge-Marie og Lars 1983                                                Lars klar til afdansningsbal forår 1984 hos Knud Jensen. Så flyttede vi ham til Søren Jensen, hvor vi selv havde gået, men denne gang foregik det på Hadsten Gl. Skole. Søren var rigtig god til børn, og han havde sin kone med, som han viste dansene sammen med. Søren fandt da også hurtigt en partner til Lars, en sød og yndig pige, der hed Vibeke. Hvert år i marts til afdansningsbal kom mor og far og var med, så det var hårdt i 1987, hvor mor måtte tage turen alene uden far, som vi havde mistet i august 1986. Foruden afdansningsballerne var der også nogle få turneringer, såsom Hadsten Skole turnering i 1986, hvor Lars og Vibeke kom i mesterrækken og senere samme år en turnering, hvor de fik en 2. præmie i Arækken. Lars var nu så god til at danse, at han havde lyst til at gå på diskotek, hvilket der var lejlighed til i juniorklubben."}, {"type": "figure", "caption": "", "page": 86, "file": "assets/images-bog2/p086_01.jpg", "dim": [686, 1028]}, {"type": "figure", "caption": "", "page": 86, "file": "assets/images-bog2/p086_02.jpg", "dim": [675, 1028]}, {"type": "para", "text": "I 1987 fik Lars 5-års nålen, og samme år blev de nr. 3 til institutmesterskabet i Hadsten og vandt en hvid porcelænssæl. Det var desværre en aften, hvor vi var forhindrede i at tage med, da vi var inviteret op til Tage, men Lars’ dagplejemor Karen Lis lovede, at de nok skulle tage med Lars, så sådan blev det. Jeg husker endnu, da Lars ringede op til Tage for at fortælle, at de havde vundet. Desværre stoppede Vibeke med dansen i sommeren 1988, da hun i stedet skulle gå til ridning, men det var måske stødet til, at Lars kom videre med dansen på et andet niveau. En ting var jo DOFdans, som Lars havde gået til, noget andet var sportsdans, som han senere kom til at gå til. Turneringerne var vidt forskellige, og det var ikke fri for, at sportsdansere så ned på DOF-dansere."}, {"type": "figure", "caption": "", "page": 87, "file": "assets/images-bog2/p087_01.jpg", "dim": [1015, 683]}, {"type": "figure", "caption": "Vibeke og Lars den 1.2.1986 og Lars med præmie den 8.11.1986", "page": 87, "file": "assets/images-bog2/p087_02.jpg", "dim": [622, 935]}, {"type": "para", "text": "Vi vidste ikke så meget om det dengang, men vi havde hørt, at Ringgård havde en god danseskole i Åbyhøj, så der begyndte Lars i 1988, hvor han i starten dansede med en meget dygtig danser, som hed Sidsel. Hun var fast partner med en anden dreng, der hed Paw, og de var meget dygtige. Det var en god måde for Lars at komme i gang på. Arne Ringgård var også god til at undervise børnene, og han var en meget venlig mand. Efter at have danset en tid med Sidsel, fandt Arne en fast dansepartner til Lars. Hun hed Jane, men efter kort tid ringede hendes mor og sagde, at hun havde fundet en anden partner. Sådan var danseverdenen, hård og kynisk, og det skulle vi lige vænne os til. Man tænkte ikke så meget på andres følelser, bare man selv fik noget ud af det. Den 2. maj 1989 prøvede Lars at danse med en ny pige fra Randers, som hed Anne Berthelsen, og de passede i højde og drøjde godt sammen. Hun var et lille nips, en køn pige med et grønt og et brunt øje, men meget charmerende og sød. Hendes mor var også meget lille og spinkel og hed Betty. Hun havde en frygtelig skinger og gennemtrængende stemme, og hun var hurtig til at pointere, at hendes datter havde vundet sølv ved DM med sin forrige partner. Så havde vi noget at leve op til. Dansen skulle foregå hos Janna Clausen i Randers, og det blev starten på en spændende tid for Lars og os, for Janna var som en mor for børnene og meget imødekommende over for os Sidsel og Lars 1988 forældre. Nu skulle Lars og Anne med til rigtige turneringer inden for sportsdans og de skulle dyste mod de dygtigste dansere i Danmark. Vi købte et sæt brugt latintøj til dem hver i turkisblå til i alt 1200 kr. og en smoking til Lars for 900 kr. I november 1989 var farmor, bedstefar og oldemor med til en danseturnering i Ålborg."}, {"type": "figure", "caption": "", "page": 87, "file": "assets/images-bog2/p087_03.jpg", "dim": [591, 948]}, {"type": "figure", "caption": "Billedet blev bragt i avisen.", "page": 88, "file": "assets/images-bog2/p088_01.jpg", "dim": [766, 1192]}, {"type": "para", "text": "Jane og Lars marts 1989"}, {"type": "figure", "caption": "Anne og Lars giver opvisning i Randersugen august 1989", "page": 88, "file": "assets/images-bog2/p088_03.jpg", "dim": [614, 818]}, {"type": "figure", "caption": "Lars i sin FDF-uniform 1986", "page": 88, "file": "assets/images-bog2/p088_02.jpg", "dim": [456, 821]}]}, {"title": "Lars’ andre fritidsinteresser", "blocks": [{"type": "para", "text": "Udover dansen blev der også tid til andre aktiviteter, og i og med at vi kun havde ét barn, kunne vi altid være med på sidelinjen. I flere år gik Lars og Vagn til svømning sammen i Hornslet under ledelse af Ole Skot-Hansen fra Østervang. Det begyndte i 1983 og sluttede i 1987, men da var Lars også en habil svømmer og noget af en vandhund."}, {"type": "para", "text": "I samme periode gik Lars til FDF i Spørring, men kredsen lukkede i 1988. Forinden nåede Lars at komme med på piltelejr på Sletten den 4. til den 9. juli 1988, hvor vi forældre kom på besøg en aften."}, {"type": "para", "text": "Lars begyndte at gå i juniorklub den 4. oktober 1984. Den 23. juni 1985 skulle de på deres første lejr med sovepose og oppakning, og de skulle med bus fra Hotellet. Som den omsorgsfulde mor, jeg jo var, ville jeg følge Lars ned til bussen, men jeg kunne mærke på ham, at han helst var fri. Da jeg ikke forstod et vink med en vognstang, sagde han følgende: ”Mor, det er altså ikke fordi du er grim eller dum, men de andre børn har ikke deres mor med”. Så faldt tiøren. De var beskidte, trætte og glade, da de kom hjem efter en uge på lejr. Lars kom hjem i den samme træningsdragt, han var taget af sted i, og jeg tror ikke, den havde været af ham. Sæben og tandpastaen var ubrugt og neglene så sorte, at han måtte ligge i blød i flere timer for at blive ren. Men de havde haft det skønt, og det var hovedsagen. Klubben var et dejligt sted, hvor der også blev kreeret kunst. Jeg har flere fade, krus og tre små pingviner, som Lars har lavet i klubben, og Ruth Morgenstjerne instruerede dem i at spille teater, som de turnerede med. De holdt også teaterfestivals, fx den 18. marts 1989. Men af og til gav det også knubs at gå i juniorklub. Den 3. juni 1986 faldt Lars ned fra et tag i skolegården og slog hovedet, men han slap billigt og fik ikke engang hjernerystelse."}, {"type": "para", "text": "I 1987, 1988 og 1989 forsøgte Lars sig med at spille håndbold, men det fængede ikke rigtigt. I håndbold skal man ikke være for flink ved modspillerne, og det var Lars, så det var en kort fornøjelse."}, {"type": "para", "text": "Lars har alle sine dage været en vandhund, så da Alice i 1988 spurgte, om vi ville købe Johns store badebassin for 100 kr., slog vi straks til. Det blev stillet op på plænen ved den nye terrasse og fyldt med vand, og så kan det nok være, at Lars og Klaus boltrede sig, og nogle gange også Inge-Marie. Vagn stillede en trappestige op, hvorfra de kunne springe i vandet. Vi stillede også en balje vand op, som de skulle skylle fødderne i, inden de sprang i vandet, så det ikke konstant skulle renses for græs. Det var et stort arbejde at tømme bassinet, gøre det rent og fylde det med vand igen, og det var tit mor her, der måtte klare det, men det gjorde jeg gerne, for det var en fornøjelse at se dem more sig. Det gjorde de i tre somre, indtil bassinet gik i stykker, men da var de også ved at være for store til den leg. Vi havde fået rigtig megen fornøjelse for de 100 kr."}, {"type": "para", "text": "Lars blev dygtig til at tage video, og jeg har noteret, at han fik 100 kr. af Annie Bach for at optage video ved Allans konfirmation den 24. april 1988."}]}, {"title": "Arbejde og fusk", "blocks": [{"type": "para", "text": "Jeg kunne som sagt godt være blevet fastansat på Ålborg Studenterkursus, hvor jeg arbejdede fra 1976, men vi var ikke indstillet på at flytte, så jeg søgte ind på Ingeniørhøjskolen i Århus (Århus Teknikum), kom til samtale hos rektor Gaunholm og blev ansat som timelærer den 1. august 1980. Jeg skulle varetage engelskundervisningen på Adgangskursus, og jeg blev hurtigt glad for at være der og faldt godt til blandt de mange flinke kolleger. Jeg tror, jeg fik stillingen på grund af min matematiske studentereksamen, for der skulle jo undervises i teknisk engelsk. Det glædede mig, at den eksamen endelig kunne komme mig til gode. Gaunholm var en meget rar mand, og jeg fik et godt forhold til ham. Efter et år blev jeg fastansat på halv tid, for jeg var også ansat på Handelshøjskolen som timelærer. På et tidspunkt havde jeg Jette Vrængmose og hendes kæreste Brian (senere mand) som studerende, og et år havde jeg et HA-hold, hvor Karen Lis’ svigersøn Hans Ole var blandt de studerende. Det var en stor udfordring at undervise på Handelshøjskoleniveau, og jeg følte, at jeg skulle være mere end 100 % forberedt, især på de hold, hvor Jette, Brian og Hans Ole gik, for de skulle jo nødig synes, at jeg var en dårlig underviser. Det tror jeg nu heller ikke, de syntes, for Jette har på et tidspunkt sagt til Per, at jeg klarede det godt, og det var jeg rigtig glad for at høre. Til eksamen skulle jeg også være skarp, for det var somme tider nogle af mine gamle universitetslærere, jeg havde som censorer, fx Torben Kisbye, Frede Østergård og Hans Arndt. I maj 1981 blev jeg spurgt, om jeg ville overtage en kollegas hold. Det viste sig, at en anden timelærer, som hed Ove, og som jeg ofte havde talt med på lærerværelset, var blevet opsagt på grund af alkoholproblemer. Han havde tre HA-hold, som skulle op til eksamen, så det år førte jeg over 100 HA-studerende op til eksamen. Det var en barsk omgang. En anden udfordring på Handelshøjskolen var afløsningsopgaver. De studerende kunne slippe for nogle eksamener ved at læse en hel roman og blive hørt i den på et med læreren aftalt tidspunkt. Således fik jeg læst et væld af romaner, bl.a. ”Saturday Night-Sunday Morning” af Allan Silitoe, ”Jane’s Career” af H.G.De Lesser samt ”Mus og Mænd” og ”Sons and Lovers”."}, {"type": "para", "text": "Jeg har altid gået meget op i mit arbejde og er meget ærekær. Jeg har lært, at man ikke skal blive hjemme fra arbejde i utide, men jeg var nu heller aldrig syg. Eller næsten aldrig. Om morgenen den 26. marts 1984 besvimede jeg to gange ude på badeværelset, men alligevel tog jeg på arbejde. Alice hjalp altid, hvis der var problemer, og da hun fandt ud af, at jeg ikke havde det så godt, lavede hun jordbærgrød til os, men hun skældte mig også ud for at være taget på arbejde. På det område forbedrede jeg mig dog ikke."}, {"type": "para", "text": "80’erne var hårde år arbejdsmæssigt. Udover at det var krævende at have to arbejdspladser, arbejdede jeg to aftner om ugen på Handelshøjskolen (korrespondentstudiet) samtidig med, at jeg fik lov at undervise nogle af mine kolleger på Ingeniørhøjskolen i fransk. Skolen havde så mange penge, at de kunne udbyde kurser for medarbejdere, og da flere gerne ville have det franske genopfrisket, var der en mulighed for mig til at holde dette sprog ved lige. Det skete, at Lars var med mig på arbejde. Så sad han ligeså stille ved et bord og tegnede, mens jeg underviste. Han husker endnu, hvordan jeg slog en studerende oveni hovedet med en bog, fordi han ikke hørte efter. I 1986 begyndte jeg at gå på tekstbehandlingskursus, men det var først i 1994, at jeg begyndte at bruge PC. I flere år underviste jeg også i engelsk på Spørring Aftenskole, og det var kendte spørringborgere, der sad på skolebænken. Herunder forrest til venstre Mogens Lading og Henning Christiansen, bagved Per Kristiansen og Stella, 1994."}, {"type": "figure", "caption": "", "page": 90, "file": "assets/images-bog2/p090_01.jpg", "dim": [1176, 784]}, {"type": "para", "text": "Noget af det, jeg godt kunne lide ved mit arbejde, var at komme ud som censor. I mange år boede jeg hos familie og slog så to fluer med ét smæk. Når jeg var i Odense, boede jeg hos faster Aase, og i København boede jeg hos onkel Erik. Privat havde jeg også elever: Ingrid Sørensen og Herdis Planteskole gik til engelsk, Alice gik til fransk, Helle, en bekendt af malerens, gik til fransk, Tim og Ella fra Voldum gik til fransk, men ikke samtidig, for de var blevet skilt."}, {"type": "para", "text": "Tidligere nævnte jeg Ålborg Studenterkursus, hvor jeg arbejdede to dage om ugen fra 1976 til 1980. Den arbejdsplads betød så meget for mig, at jeg valgte at tage imod en invitation den 9. september 1989, hvor de fejrede deres 50 års jubilæum. Selvom jeg havde været der så kort tid, havde de ikke glemt mig, og det siger også lidt om, hvor god en arbejdsplads det var. Bagefter sendte Rektor Nordhagen mig et brev og takkede mig for, at jeg havde taget turen derop til jubilæet."}, {"type": "para", "text": "Vagn arbejdede i 80’erne for tømrerfirmaet Marstrand-Nielsen, og det var han i det store og hele glad for. Det skete også, at han havde Lars med på arbejde, men det kunne han også roligt have, for han rørte ikke ved noget, han ikke måtte. I dag var det ikke gået på en byggeplads. I påsken 1987 skulle vi have været på weekendophold i Skagen sammen med Vagns familie, men den 15. april brækkede Vagn to ribben på sit arbejde. Afdækningen, som firmaet havde lavet, var for dårlig, så da han hoppede ned på en beholder, der var dækket til, faldt han igennem. Han kørte selv på skadestuen, hvor man i starten var bange for, at milten havde taget skade. Dette betød en lang og rolig påske derhjemme, så rolig og lang, at jeg på et tidspunkt syntes, der skulle ske noget. Da vi næsten lige havde fået video, var det spændende at leje film, hvilket vi normalt aldrig gjorde, da vi ikke havde tid. Jeg gik derfor ned i Brugsen og lejede 3 film, hvoraf de to var komedier. Hvad jeg ikke havde tænkt på var, at det gør vanvittigt ondt at grine, når man har et brækket ribben. Jeg var derfor ikke særlig populær med de film. Det blev en lang sygemelding på godt en måned, hvor Vagn måtte have min hjælp hver morgen til at komme ud af sengen, noget af en festforestilling. Der blev især ryddet op i papirer i den periode, for al legemligt arbejde var bandlyst, men som altid var brormand Tage parat til at hjælpe, så han kom og gravede urtehaven."}, {"type": "para", "text": "Den 16. januar 1989 havde Vagn været i firmaet i 10 år. Det var ikke noget, firmaet markerede, men Lars og jeg havde købt en slipsenål til farmand. 1989 var også det år, hvor Vagn var udstationeret i en måned og kun var hjemme på forlænget weekend. Tommy Krømmel Nielsen og Vagn arbejdede sammen og blev sendt til Ålborg, hvor de arbejdede på TV Nord og Ålborg Stiftstidende. De sov på drømmesenge og havde selv mad med, så de kunne holde sig selv ved kost. Tommy var en herlig fyr med hestehale men ikke særlig pæn i tøjet, og han gik i de samme bukser næsten hele tiden. Han var renlig nok men lidt af en hippie-type. Hans forældre boede i Sønderjylland, og engang var vi inviteret til fest dernede. Jeg morede mig ikke særlig meget, for der var ingen, jeg kendte, men Tommys forældre var utrolig flinke."}, {"type": "para", "text": "1980’erne var en ”storhedstid” for Vagn, hvad angik fusk, men det var absolut ikke noget, han blev fed af, for Vagn var alt for beskeden til at forlange noget for sit arbejde. Der er mange, der har sparet mange penge ved at have Vagns hjælp, og det, han lavede, var altid tip-top og i orden. Jeg lyder nok lidt sur og bitter, når jeg skriver dette, men det kunne ikke undgås, at det gik ud over Lars og mig, for han kunne jo kun være ét sted ad gangen. Det gik ud over tiden med familien samt jagtog fisketure, som var hans yndlings fritidsbeskæftigelse. Men Vagn knoklede løs, og det var ham, der holdt haven, bilen og det udvendige, slæbte træ hjem og passede fyret. I vinteren 1980 malede og tapetserede han i Vestergård sammen med sine søskende, og året efter om sommeren gik Doris og Poul Erik i gang med deres ombygning nr. 2 på Ringduevej 16 i Svenstrup, og det var et stort projekt, som gik over mange weekends. Han overnattede hos Tage, som også hjalp til, for han boede et stenkast derfra. Jeg var sommetider med og kørte så ind imellem hjem til mor og far en tur. Doris og Poul Erik var de perfekte arbejdsgivere. Doris var dagplejemor, men hun fik også tid til alt det huslige, selvom det ikke var lovligt som dagplejemor at lave alt muligt andet samtidig med, at man passede børn. Børnene fik den perfekte pleje, og Doris var kontant og satte grænser, hvilket børnene kunne lide. Poul Erik var også god til børnene, og han var tit hjemme, når de var der, for han var inseminør, som ifølge hans svogre ”kun var et halvdagsjob”. Doris fik som sagt tid til at vaske, stryge, bage, lave mad m.m., samtidig med at hun passede 4 små børn og sine egne 3. Og når børnene var hentet, var der hurtigt som blæst i huset. Også når der var håndværkere. Måltiderne blev prompte serveret, seks om dagen, og når Vagn og Tage var gået hjem kl. 23, gik Doris og Poul Erik i gang med at rydde op og feje, så der næste morgen var som blæst, når håndværkerne mødte kl. 7, al værktøjet lå på rad og række, og morgenmaden stod klar til dem."}, {"type": "para", "text": "Da ombygningen stod færdig, og de blandt andet havde fået et stort, dejligt køkken, forærede de os en udendørs PH-lampe i kobber som tak for Vagns hjælp. Den var vi meget glad for, og nu hænger den her på vores nye hus. Det skal siges, at det ikke var den eneste gang, Vagn fik gaver som tak for fusk."}, {"type": "para", "text": "I 1982 slog Vagn lofter op og fiksede badeværelset hos genboens, hvor han også byggede overdækket terrasse i 1984. Han arbejdede på terrassen den 24. marts, den 12. maj og den 29.-31. maj, hvor den stod færdig. Den blev rigtig dejlig, og jeg må nok sige, at vi har nydt at sidde der mange gange og spise Pouls grillmad, også når det regnede og blæste andre steder, for på deres terrasse var der altid tørvejr, læ og lunt. I januar 1985 var der flere lofter, der skulle slås op hos genboens, og igen i januar 1987."}, {"type": "para", "text": "I 1982 byggede Erik maler oven på deres hus, og i den forbindelse hjalp Vagn ham med badeværelset i november. Belønningen var en flødebolle!"}, {"type": "para", "text": "Hos Marie og Svend i Holme har Vagn også lagt mange timers arbejde, og selvom Svend gerne ville prale af sine mange penge, mærkede vi aldrig til denne overflod, når Vagn havde hjulpet ham. Svend havde mange opgaver til Vagn i 1983 og 1985, og i 1986 var Vagn der i ni perioder, hvor han bl.a. byggede udestue. Også i 1987, 1988 og 1989 arbejdede han for Svend."}, {"type": "para", "text": "Indimellem var der også betalt fusk, for Pouls firma Lyngfeldt havde nogle firmabiler, der skulle beklædes med hylder bagi. Jeg ved ikke, hvor mange biler Vagn har beklædt, men han stod i vores indkørsel og gjorde det, så han var heldigvis hjemme i de perioder, som lå i 1983, 1985, 1986, 1988 og 1989."}, {"type": "para", "text": "I maj 1986 satte Vagn raftehegn op hos mor og far i Thorshøj, samme år som far blev syg og døde. I marts 1988 satte han vinduer i hos mormor i Skæve, og samme sommer ordnede han sternen på mors garage. Efter hun blev alene, var der altid nok til Vagn at lave, når vi kom hjem. Mor havde listen klar."}, {"type": "para", "text": "I 1989 hjalp Vagn Ole Skot med nogle vinduer, og samme år hjalp han Jørn Griis to gange med vinduer."}]}, {"title": "Foreningsarbejde", "blocks": [{"type": "para", "text": "I Spørring har vi en Husmoderforening, som jeg var formand for fra 1983-1989. Jeg startede som menigt medlem af Bestyrelsen på et tidspunkt, hvor Lis Ernstorn var formand, men hun kunne ikke lide at byde velkommen, så det var altid mig, der gjorde det, indtil vi så fandt ud af, at jeg ligeså godt kunne være formand. Det var en dejlig periode, som naturligvis krævede noget arbejde, men bestyrelsesmøderne var hyggelige. De gik på tur rundt hos medlemmerne, men jeg frygtede hver gang, vi skulle være hos Jensigne, som var kasserer. Hun havde to store hunde, som jeg var bange for, selvom hun sagde, at de ikke gjorde noget – det siger alle hundeejere jo. Vi havde mange arrangementer i Husmoderforeningen, og de var oftest godt besøgt. Af succeser var der i november 1985 en aften med visesangerinden Inger Lauritzen fra Lønstrup. Der var ikke et øje tørt, og jeg fik hendes autograf. I 1988 holdt vi et kæmpe modeshow på hotellet med spisning, og 91 personer troppede op. Hvert år var der bankospil, og der var altid fuldt hus på hotellet, hvor jeg somme tider råbte op, men bankospil har aldrig været noget for mig. Jeg stoppede i Husmoderforeningen ved generalforsamlingen den 23. februar1989, og den 29. november samme år blev jeg hyldet i forbindelse med Husmoderforeningens 40 års jubilæum, samme måned som jeg selv var fyldt 40 år. Jeg havde lavet en sang til festaftenen, som blev holdt på Hotellet med spisning for fulde huse. Jeg havde til min fødselsdag af veninderne fået en sort buksenederdel og en bordeauxfarvet trøje med hvid krave, som jeg havde på den aften. Desuden havde jeg fået farvet hår for første gang, så jeg så rimelig godt ud, da jeg blev kaldt op og fik overrakt en stor blomsterkurv for min indsats som formand."}, {"type": "para", "text": "Af andet foreningsarbejde i 80’erne kan nævnes mit kassererjob i FDF/FPF, som stoppede i 1987, hvor Vagn gik ind i Klubbens bestyrelse. Jeg sad også i Byfestudvalget i 1985 og var med til at arrangere byfest."}]}, {"title": "Ferier", "blocks": [{"type": "figure", "caption": "", "page": 93, "file": "assets/images-bog2/p093_01.jpg", "dim": [706, 485]}, {"type": "figure", "caption": "", "page": 93, "file": "assets/images-bog2/p093_02.jpg", "dim": [705, 485]}, {"type": "para", "text": "I 1981 (20.-29. juli) var vi på en dejlig sommerferie sammen med Tage til Fyn, Ærø, Tåsinge og Langeland. Året efter havde vi besluttet, at vi ville spørge vores forældre, om de ville med os på ferie. Vi spurgte først mor og far, om de ville med til Norge. Mærkeligt nok sagde de nej, men vi fandt ud af, at det nok var på grund af pengene. Vi kunne mærke, at far gerne ville afsted, men mor holdt igen – hun havde mere overblik end far over deres økonomi. Det var synd, at de ikke kom ud af busken og gav en begrundelse, for så kunne vi måske have hjulpet dem, men det var nok deres stolthed. Da vi imidlertid spurgte Vagns forældre, om de ville med på en køretur rundt i Jylland, sagde de uden tøven ja. Det havde vi nok ikke forventet. Det blev kun til tre dage i juli, men vi kom til Ringkøbing, Hvide Sande, Blåvand, Ribe, Skærbæk, hvor vi boede på Åblings Hotel, Rømø, Højer, Tønder, en smut til Tyskland til Husum og Friedrichsstad, og til slut til Kruså, Rødding, Billund og Legoland. Chr. Viggo var betaget af sluserne i Højer, og Krista var glad for at se sin gamle højskole i Rødding."}, {"type": "figure", "caption": "", "page": 93, "file": "assets/images-bog2/p093_04.jpg", "dim": [691, 1015]}, {"type": "figure", "caption": "Frokost i det grønne med efterfølgende middagslur for bedstefar og Lars", "page": 93, "file": "assets/images-bog2/p093_03.jpg", "dim": [711, 486]}, {"type": "figure", "caption": "", "page": 94, "file": "assets/images-bog2/p094_01.jpg", "dim": [1009, 697]}, {"type": "figure", "caption": "", "page": 94, "file": "assets/images-bog2/p094_02.jpg", "dim": [686, 1020]}, {"type": "para", "text": "Vi havde fantastisk vejr og indtog hver dag frokosten i det fri. I Friedrichsstad tog vi en sejltur i det dejlige solskinsvejr og nød den hyggelige by set fra vandet."}, {"type": "para", "text": "Samme år tog vi tre en uge på chartertur til Rumænien med Tjæreborg til en pris af 7.168 kr. Lars var så spændt på turen, at han var på toilettet tre gange i Billund og tre gange under den 3 timer lange flyvetur. Vi fløj til Constanta, og det første vi så, da vi steg ud af flyet, var soldater bevæbnede med maskinpistoler. På landingsbanen holdt der en gammel bus med træsæder, som sørgede for, at vi ikke kom på afveje på vej til ankomsthallen, hvor der igen var maskinpistolbevæbnede soldater linet op. Fra lufthavnen var der en times kørsel i bus til Olimp, hvor vi blev installeret på Hotel Banat. På busturen advarede guiden os imod at veksle ”sort”, så vi gik hen til den statslige vekselerer, som sad i hotellets foyer. Vi bad om at få 100 $ vekslet til rumænske Lei, og pludselig stod vi med 1500 Lei og ingen kvittering i stedet for 1100 Lei og en kvittering! På gaden kunne man have fået det dobbelte, men man kunne også risikere at stå tilbage med et sammenrullet bundt penge, der så viste sig at bestå af én pengeseddel og toiletpapir for resten. Sådan var systemet, og det var ikke rart at opleve. Hotellet lå ned til Sortehavet, men Lars ville hellere bade i de to swimmingpools, vi havde adgang til ved siden af hotellet. Vi var dog også tit ved stranden, hvor Lars legede i sandet med strandlegetøj, som vi købte på stedet. Vi nød at være sammen og slappe af, og vi oplevede en masse, men det, der var værst, var at se fattigdommen og de børn, der hver dag stod uden for hotellets køkken og fik resterne af vores mad. Vi kunne slet ikke spise op. Vi var på fuld pension og spiste fire retter to gange om dagen. Det var kæmpe portioner på tunge tallerkner, så servitricen arbejdede hårdt. Det var ikke al maden, der var lige lækker, men Lars skovlede ind det bedste, han havde lært, og der var ingen muggen."}, {"type": "figure", "caption": "", "page": 94, "file": "assets/images-bog2/p094_04.jpg", "dim": [718, 485]}, {"type": "figure", "caption": "", "page": 94, "file": "assets/images-bog2/p094_03.jpg", "dim": [706, 485]}, {"type": "para", "text": "Det, der også prægede Rumænien, var, at tingene ikke blev holdt i orden, og meget var i stykker og fungerede ikke. Vi ville gerne have lejet en bil og selv kørt rundt, men det frarådede guiden os, for vi kunne risikere, at den bil, vi lejede, ikke var i orden og brød sammen efter få km. Når vi var tørstige, var det svært at få noget at drikke, og det eneste, vi så endelig kunne få, var Pepsi. Desuden var der systemet med ”dollarshops”. En dollarshop var en forretning, hvor man kun kunne betale med dollars eller anden vestlig valuta, så kun turisterne havde adgang til disse, hvor man kunne købe dagligvarer, som fx sæbe, tandpasta, slik, tyggegummi og cigaretter, så disse varer havde rumænerne ikke adgang til. En dag var vi virkelig tørstige, så vi vovede os ind i en dollarshop og fandt tre sodavand, men da vi skulle betale, kunne de ikke give tilbage på en 20-dollar seddel, også en typisk situation. Aftensmaden bestod altid af bl.a. tør ost, hvilket var det eneste, Lars ikke kunne lide på turen, men det kunne vi andre nu heller ikke. Lars nåede dog at spise ost to gange uden at vide det. Efter aftensmaden gik vi altid en tur på stranden, og tog så et spil kort eller Memory på værelset, inden vi skulle i seng. Vi boede på 10. etage, så vi skulle med elevator, som ikke altid fungerede. Så måtte vi tage de 250 trin op eller ned. Lars var altid først inde i elevatoren, men en dag nåede vi ikke ind efter ham, så han tog turen alene op på 10. sal. Der fandt vi ham i et hjørne lidt forknyt, men ikke mere end at han var frisk på at tage turen igen. Om dagen spillede vi ofte minigolf, og Lars brugte til tider lidt specielle kneb for at få bolden i hul."}, {"type": "para", "text": "Vi havde købt fire udflugter, og den første gik med fly til hovedstaden Bucharest (50$). Flyet var en gammel propelmaskine, der larmede voldsomt, og sæderne var af træ og meget ukomfortable. Heldigvis varede turen kun 45 min. Vi så mange historiske monumenter i hovedstaden, og Lars blev fotograferet sammen med en bevæbnet vagt, som sikkert stod og kedede sig. Det var svært at købe noget, for man skulle holde sig på behørig afstand af varerne i varehusene, og overalt var der køer af rumænere. Kød og frugt var en mangelvare, så hver rumæner måtte kun købe 500 g kød om måneden, og kaffe kostede 300 kr./kg. Lars charmerede alle på sin vej, og på denne tur var det Lars, der gav drikkepenge. Først til det orkester, der spillede mens vi spiste aftensmad, og dernæst til buschaufføren, som kvitterede med et kys. Det var også på denne tur, at vi mødte bankdirektøren for Vendelbobanken i Brønderslev. Han hed også Vagn, og de to Vagn’er kendte hinanden fra Tårs. Selvom vi først var hjemme på hotellet ved midnat, stod vi næste dag op kl. 5.30 for at tage på en ny tur. Lars klarede det fint, for han kunne sove i bussen, og denne dag skulle vi køre 2½ time i bus, så han sov på bagsædet hele vejen. Vi kørte til Tulcea, kun 15 km. fra den russiske grænse, og her steg vi på et dejligt skib med plads til 80 passagerer. Det skulle sejle med os i 7 timer på Donau, dog afbrudt af en 2-timers sejlads på en smal strækning, hvor vi sejlede i små pramme. Undervejs blev vi trakteret med ægte kaviar, og vi så pelikaner, som man ikke altid er heldig at se. Lars blev gode venner med en rumænsk dame, som gav ham en Pepsi. Det var på høje tid, at vi kom tilbage på Aegyssus, som skibet hed, for Lars skulle tisse. Ombord fik vi en dejlig middag, hvor vi sad sammen med to ældre ægtepar fra Danmark. Det ene par kendte vi fra dagen før, så dem var Lars helt fortrolig med. På hele turen så vi ibis, storke, hejrer, isfugle, pelikaner og snepper. Vi sejlede i alt 140 km, hvoraf de 36 km foregik i små både. Det var ikke så sært, at Lars sov hele vejen tilbage i bussen. Efter to heldagsture nøjedes vi med en halvdagstur om søndagen, en såkaldt kysttur, og den sidste tur var en vin-tur, hvor hele bussen til sidst var i ganske opløftet stemning efter at have smagt på 7 forskellige vine. Lars fik lemonade og blev rigtig gode venner med et ungt par fra Mors, og da han var det eneste barn i selskabet, tog guiderne sig også ekstra meget af ham. Da vi kom hjem til Danmark, ringede mor og var så bekymret for os, for hun havde læst en rigtig dårlig anmeldelse af en ferie i Rumænien. Overskriften var ”Trøstesløs og kan ikke anbefales”, men vi kunne kun sige, at vi havde haft en dejlig ferie, selvom det nok ikke var et sted, vi ville besøge igen."}, {"type": "para", "text": "I sommeren 1983 tog vi en lille uge til Skagen. Vi havde glædet os til at nyde sommeren i Skagen, men vejret blev langtfra godt, og det regnede og blæste. Vi boede i moster og Ibs campingvogn i deres indkørsel, og tog så ud derfra hver dag og legede turister. Vi fik set en masse museer men var også sammen med moster og Ib om aftenen. Her siger vi farvel den 4. august."}, {"type": "figure", "caption": "", "page": 96, "file": "assets/images-bog2/p096_01.jpg", "dim": [1017, 691]}, {"type": "para", "text": "En ferie, vi aldrig glemmer, var turen med Vagns familie til Costa del Sol i efterårsferien 1984. Farmor var fyldt 70 år den 3. august, hvor hun holdt stor fest, men alligevel ville hun give alle sine børn, svigerbørn og børnebørn en chartertur. Og hun og bedstefar skulle selvfølgelig med. Turen var bestilt hos Falke Rejser og kostede for 11 personer med halvpension i en uge 23.295 kr. + et depositum på 250 kr. pr. person + Tage og Jens Christian, som af uforklarlige grunde var på en regning for sig. Vi skulle flyve fra Billund, så farmor og bedstefar kom ned og overnattede hos os aftenen før, og så kørte vi 5 sammen til Billund næste morgen. Lars var lige fyldt 7 år og havde været oppe at flyve tidligere, så han syntes, det var vildt mærkeligt, at farmor og bedstefar aldrig havde vært oppe i et fly. De var trods alt 10 gange så gammel som ham. I Billund mødte vi Svenstrup-familien, Tage, Doris, Poul Erik, Jens Christian, Charlotte og Thomas, som ville fylde 6 år på turen den 17. oktober, så vi have flag og gaver med i kufferten. Flyveturen gik fint, vi ankom til Malaga kl. 21.00 og tog straks videre til Hotel Los Patos, hvor vi ankom en time senere. Temperaturen udenfor var 17 grader celcius. Vi havde lejet 4 værelser med altan og bad på 7. og 8. etage, og da vi åbnede dørene, så vi, at der stod en flaske champagne på hvert værelse som en velkomst til os. Vi stuvede os sammen på farmor og bedstefars værelse, for det skulle fejres, at vi nu var kommet til Spanien. Jeg husker endnu, at bedstefar knap havde drukket den sidste slurk, før han foreslog, at vi skulle lukke flaske nr. 2 op, og da han havde drukket lidt mere, faldt han bagover i sengen. Jeg tror, han sov godt den nat, selvom han jo helst ville sove i sin egen seng hjemme på gården og sjældent sov andre steder. Vi fejrede ankomsten til kl. 01.30. Hotellet var et rigtigt familiehotel med alle mulige former for aktiviteter, såsom minigolf, tennisbane, legeplads, swimmingpool, gymnastik, bordtennis, TV-anlæg og dans om aftenen. Hele vejen omkring poolen var der drømmesenge og parasoller, men man skulle være vaks om morgenen og lægge sit håndklæde der, hvis man ville have en drømmeseng. Det sørgede Poul Erik for de dage, vi var på hotellet."}, {"type": "figure", "caption": "", "page": 96, "file": "assets/images-bog2/p096_02.jpg", "dim": [967, 689]}, {"type": "para", "text": "Vi var rigtig heldige med vejret den uge, for vi havde sol fra morgen til aften og 25-30 graders varme, så vi boltrede os ved poolen eller stranden, hvor især drengene var i deres rette element. Ind imellem var vi på ture arrangeret af rejseselskabet, og jeg tror vi blev temmelig kendte blandt de andre turister, fordi vi var så mange. Den ene af guiderne hed Bente og havde gået i Tårs Skole, så verden er lille. En aften gik alle vi unge og børnene i Tivoli, hvor vi bl.a. prøvede en mægtig frygtindgydende maskine, hvor man hang med hovedet nedad. Jeg blev også lokket med op i rutsjebanen, hvor jeg lå og skreg i bunden af vognen. Vi spiste på en dansk restaurant, Københavnerrestauranten. Både store og små morede sig den aften og var først hjemme kl.0.30. Om dagen var der så varmt, at bedstefar måtte smide de lange underbukser og smøge benklæderne op, men farmor døjede med varmen og måtte blive i sengen en dag på grund af svimmelhed og kvalme. Doris havde hjemmebagt rugbrød med til hele ugen, og vi havde spegepølse og ost med, så vi kunne holde os selv ved frokost, idet vi kun var på halvpension. Det fungerede perfekt, og den dag, vi skulle hjem, spiste vi det sidste rugbrød. Allerede om mandagen var vi på en halvdagstur, som hed Appelsinturen. Den kostede 90 kr. for voksne og 60 kr. for børn, men det var naturligvis bedstefar, der betalte. Vi startede kl. 9, og turen var på 140 km. På turen så vi sukkerrør samt oliven-, mandel- og figentræer. Efter at have været på et grønsagsmarked, fandt vi en café, hvor vi drak lumumba (cognac og varm kakao), hvorefter vi besøgte en appelsinbonde og spadserede gennem appelsinlunden. Vi spiste melon, og bedstefar fodrede et æsel med melonskræl, mens Lars og Thomas så beundrende til. Vi var inde og se en keramikforretning, hvor Vagn købte en skildpadde til sin skildpaddesamling, som vist snart var oppe på 100 skildpadder fra forskellige lande. Vi så også en af de mange ”hvide byer”, der ligger i området. Om aftenen gik vi ”unge” på diskotek på hotellet, mens farmor og bedstefar underholdt børnene. Hver dag var en ny oplevelse, og vi nød solen ved poolen, badede, spillede tennis og minigolf, nød en drink, og en eftermiddag tog nogle af os bussen ind til Torremolinos og shoppede. Den 16. oktober om aftenen holdt vi Thomas’ 6- års fødselsdag, selvom det først var den 17. oktober, han fyldte år. Grunden var, at vi den dag skulle på heldagstur til Afrika. Vi havde flag og pakker med, og vi fik kaffe, te, sodavand, chokolade, kage og småkager. Farmor og Doris havde bagt. Lars gav Thomas en Adidas rygsæk og en Lassie bog. Vi piger havde også strikketøj med, og pindene var denne aften glødende."}, {"type": "figure", "caption": "", "page": 97, "file": "assets/images-bog2/p097_01.jpg", "dim": [553, 814]}, {"type": "figure", "caption": "", "page": 98, "file": "assets/images-bog2/p098_01.jpg", "dim": [1009, 689]}, {"type": "para", "text": "Den 17. oktober startede vi efter morgenmaden kl. 7.15 på vores Afrikatur. Turen kostede 425 kr. for voksne og 280 kr. for børn, men igen betalte bedstefar og farmor. Vi kørte først en kyststrækning på 125 km. Dernæst sejlede vi fra Algeciras over Gibraltarstrædet med de dengang 42 aber på Gibraltar, som er engelsk. Vi ankom til Ceuta frihavn kl. 11.45. Her var der på det tidspunkt stor hashtrafik, men kun 5 % blev opdaget. Det var den næststørste færgeoverfart efter Hong Kong. Mellem Spanien og Marokko er der en strimmel ingenmandsland, hvor folk uden pas sad og ventede på at komme ud af landet. Vi så en ung mand få prygl af politiet, hvilket ikke var usædvanligt på det sted. Vi spiste cous-cous, Marokkos nationalret, på et fint hotel, Karia Hotel (4 stjerner). Cous-cous består af hirse- eller semuljefrø, kikærter, løg, gulerødder, tørrede rosiner og kamelkød. Vores marokkanske guide havde tre koner og var på jagt efter en fjerde. Han ville godt give 100 kameler for en kone, men hun skulle veje over 60 kg. – heldigvis! Vi kørte videre og gjorde stop ved en kamelstation, hvor bl.a. Lars og jeg fik en tur på kamelryg sammen. Vi kørte videre til byen Tetuan i Marokko, hvor tiden var sat tilbage til år 1404. Her var vi kl. 14 og kom bl.a. på en gåtur inde i Medinaen, hvor der bor 80.000 mennesker, og hvor bl.a. Lars, farmor og bedstefar blev fotograferet med en slange om halsen. Farmor var ikke stolt ved situationen, men hun var frisk på at prøve. I Medinaen var der meget beskidt, og der lugtede fælt. De solgte alt muligt, men vi fik at vide, at vi ikke måtte stoppe op og handle, for hvis vi blev væk fra hinanden, ville vi ikke være i stand til at finde ud igen, og der var vist ingen af os danskere, der havde lyst til at blive. Det var før vi fik mobiltelefon. Slagtervarer hang i solen og tiltrak sig fluer, men da vi tog et billede, blev slagteren sur. Lars ville den dag gerne holde os i hånden, og bedstefar havde et godt tag i farmor og hendes taske, for vi var vist kommet et farligt sted hen. Vi var inde i et stort te-hus, som hed Restaurant Palace, hvor vi drak pebermyntete, mens vi så på mavedans, men til stor skuffelse for mændene havde mavedanseren masser af tøj på. Ved udgangen af Medinaen mødte vi en flok skolebørn i uniformer, der lignede hvide kitler, og de grinede ad os og pegede op på Lars, som sad på Tages skuldre, et sjældent syn for dem. Vi blev fulgt til bussen af gadehandlere, og det lykkedes os at prutte os til en god pris for to læderkameler. Doris og Poul Erik købte en dejlig rejsetaske. Vi var tilbage på hotellet kl. 22.15, hvor der stod en kold anretning og ventede på os. En dejlig og spændende dag var forbi."}, {"type": "para", "text": "Turen havde nok været for meget for farmor, for næste dag var hun skidt tilpas og måtte blive i sengen til op ad formiddagen. Den aften var Tage og Jens Christian, som delte værelse, til grisefest og kom lidt sent hjem. Næste dag skulle vi på en Safaritur, og de to ungersvende så lidt klatøjede ud, men det sjoveste var, da vi sad på en fortovscafé og Doris slog et skvalder op. Hun havde fået øje på, at Tage havde taget to forskellige strømper på. Og Tage, der ellers var selveste Mr. Perfect! Den måtte have været høj aftenen før! Safarituren kostede 180 kr. for voksne og 90 kr. for børn, og den foregik i mindre biler. Hele gruppen kørte i 7 Ford Fiestaer, og vi kørte forrest sammen med guiden Bente. På turen så vi kaktus og citrontræer, vi var på grønsags- og fiskemarkeder, og nogle i selskabet badede i Turón Søen. I Ardales spiste vi en dejlig frokost, som bestod af den spanske nationalret Paëlla med skaldyr. Vi kørte videre ud til et elværk og nogle høje klipper, og inden turen sluttede kl. 18, stoppede vi et sted, så farmor kunne give en is. Om aftenen var vi i danserestauranten, også farmor og bedstefar."}, {"type": "figure", "caption": "", "page": 99, "file": "assets/images-bog2/p099_01.jpg", "dim": [832, 511]}, {"type": "para", "text": "Sidstnævnte mødte op i sutsko."}, {"type": "para", "text": "Senere på aftenen gik de to ældste og de to yngste i seng, og vi andre gik på diskotek længere nede ad gaden til kl. 2.30. Jens Christian og Tage førte an, for de havde været der natten før. Næste aften kl. 20.30 forlod vi hotellet. Det var helt vemodigt, for vi havde haft en kanon ferie. En anden gæst tog et billede af os på trappen til hotellet, familien ”Los Patos”, som vi blev kaldt."}, {"type": "para", "text": "Dette var desværre den eneste chartertur, vi oplevede med farmor og bedstefar, men en gentagelse ville heller ikke have været mulig, for en sådan succes ville ikke have kunnet gentage sig. Og så havde vi næsten flere penge med hjem, end da vi tog afsted, for farmor betalte også vores lommepenge."}]}, {"title": "Campinglivet begynder", "blocks": [{"type": "para", "text": "Vores interesse for campinglivet startede så småt i 1983, hvor vi i pinsen tog med Karen Lis og Finn på camping på Mols. De havde haft campingvogn i nogle år, og vi havde Vagns gamle telt med, hvor vi tre skulle sove. Vi hyggede os rigtig meget sammen med Karen Lis og Finn og deres piger Jane og Lene, og Lars nød det. Derfor var vi også hurtigt med på den, da de foreslog, at vi året efter skulle følges ad til Jugoslavien, hvor de før havde været. Vi havde ganske vist ingen campingvogn, men Grete og Poul havde en lille 3-personers Hobby, som de tilbød vi kunne låne, fordi Vagn havde hjulpet dem med lofter m.m. Det takkede vi ja til."}, {"type": "para", "text": "Forinden skulle vi lige prøve campingvognen af, og det foregik i juni, hvor Grete, Klaus, Lars og jeg tilbragte nogle dage på en campingplads på Mols. Mændene skulle køre os derud efter arbejdstid og hjælpe os med at blive installeret, men Poul var som sædvanlig sent hjemme fra arbejde, så vi nåede lige at få snuden inden for på campingpladsen, inden bommen gik ned og det næsten var mørkt. Mændene gik i gang med at stille fortelt op, og det var lidt af en festforestilling, for jeg tror ikke, Poul havde prøvet at stille det op før. Det var der i hvert fald noget, der tydede på, for da de troede, at det var stillet op, fandt de ud af, at de havde vendt vrangen ud. Hvis der er andre campister, der har siddet bag gardinet og kigget med, må de have fået sig et billigt grin og tænkt: ”Sikke nogle amatører!” Jeg husker en banden og svovlen fra Poul, og det blev sent, inden forteltet stod, som det skulle. Og så skulle vi jo lige have en bid brød og en øl, inden mændene kørte hjemad igen. Jeg husker det som nogle hyggelige dage, hvor drengene heldigvis kom godt ud af det med hinanden, og Grete og jeg fik snakket godt sammen."}, {"type": "para", "text": "Vores første campingvogn var en brugt Bürstner, som Finn og Vagn kørte til Kolding og købte den 9. februar 1985. Det var spændende at have sin egen campingvogn og ikke skulle låne mere, men der var en speciel lugt i den, som vi aldrig blev kvit, lige meget hvor grundigt vi gjorde den ren. Derfor besluttede vi også, at den næste vogn skulle være ny. Det skete den 5. april 1986, hvor vi i Hasselager købte en Knaus og gav 25.000 kr. i bytte. Ingen af de to vogne havde toilet, men der var et lille rum til formålet, så vi købte et toilet, et såkaldt Potti-Potti, for det var rart ikke at skulle ud, hvis man vågnede og skulle på toilettet om natten. De campingvogne, vi har haft, har været ca. 4,60 m. lange. Vi solgte Knaus’en privat den 9. august 1988 til en mand fra Tårs, og det var ikke, fordi vi var blevet trætte af campinglivet, at vi solgte den, men vi havde planlagt en tur til USA året efter, hvor vi ikke ville få brug for den, og vi havde planer om at købe en ny, når vi igen ville campere. Hvad vi ikke havde forventet var, at der skulle gå 7 år, inden det blev en realitet. Den første campingtur, vi gjorde i vores egen campingvogn, gik til Ebeltoft sammen med Karen Lis og Finn den første weekend i maj 1985. Den første weekend i august samme år var vi der igen sammen med mor og far. Lars havde været på ferie i Thorshøj, så mor og far ville komme og aflevere ham og samtidig tilbringe weekenden sammen med os i campingvognen. Vi ville stille forteltet op, inden de kom, så alt var klar til modtagelsen, men det stormede så meget, at vi måtte opgive, så vi var 5 mennesker med bagage i den lille campingvogn. Mor havde en lagkage To bare numser ved Vesterhavet i sommeren 1988                   med, som vi måtte opbevare under den ene seng, for der var ikke plads andre steder. Vi var i nogle år på camping pinseture sammen med Karen Lis og Finn, Else og Jørn Griis og Ruth og Ras, bl.a. i 1988 på Mols Camping. Året efter var selskabet udvidet med Karen og Børge, Anne og Niels, og Jette og Leif, og turen gik til Rørbæk Sø. Jeg husker, at vi lørdag aften var mindst 19 i Ras’ fortelt. Der var liv og glade dage, og der blev snakket, skrålet og skålet på livet løs. På et tidspunkt gad børnene ikke være der mere, så de gik hen i TV-stuen på campingpladsen. Efter et stykke tid kom Rasmus og Lars tilbage, lidt oprørte, og Rasmus fortalte, at der var en mand, der havde lagt hånd på Lars henne i TV-stuen. Der var ingen synlige mén, men Lars var lidt tavs, og jeg var straks oppe i det røde felt. Der var ingen, der skulle gøre min søn noget! Rasmus fortalte, at der havde været lidt uenighed om kanalvalget på TV, og en pige ville se noget andet end drengene. Lars havde på et tidspunkt skiftet kanal, og pigen havde sladret til sin far, som så var gået amok, havde skældt ud og rusket i Lars. Vi var enige om, at faderen skulle konfronteres her og nu, men den eneste, der tilbød at gå med Vagn, var Ras. Jeg husker ikke så meget om, hvad de fik ud af mødet, men næste formiddag kom faderen på besøg for at give en form for forklaring/undskyldning. Han var vist gået lidt over stregen, og vi kunne kun give ham ret."}, {"type": "figure", "caption": "", "page": 100, "file": "assets/images-bog2/p100_01.jpg", "dim": [991, 750]}]}, {"title": "Campingture til Jugoslavien", "blocks": [{"type": "para", "text": "Karen Lis og Finn havde været i Jugoslavien med campingvogn nogle gange, så de lokkede os til at tage med i sommeren 1984 i tre uger. Vi havde som tidligere nævnt lånt genboens lille Hobby campingvogn, så vi rullede afsted den 8. juli med 3.692,50 kr. i tyske DM. Lars nød at være sammen med Jane og Lene på 14 og 15 år. De var som storesøstre for ham, og de betragtede også Lars som deres lillebror. Selv køreturen gennem Tyskland på Autobahn var en oplevelse, for vi holdt jo ind på rastepladserne, når vi skulle spise og holde drikkepauser, og pauserne kunne være lange, for vi skulle også nyde det. Dette år var der hedt på vej ned gennem Tyskland, Østrig og Italien, og under en af drikkepauserne tog børnene en vandkamp. Vi overnattede også på disse rastepladser og ”slog benene ned”, inden vi stillede an til natmad med efterfølgende aftentoilette på rastepladsens toiletter. Det var, før der var toilet i campingvognene. Hundredevis af andre turister gjorde som os, men det mest irriterende var larmen fra de tunge lastbiler, der kørte forbi om natten udenfor. Og så var det gratis at ligge der og ikke forbundet med den fare, det er i dag. Dengang tænkte man ikke på indbrud og risikoen for at blive gasset og frarøvet sine værdier."}, {"type": "figure", "caption": "", "page": 101, "file": "assets/images-bog2/p101_01.jpg", "dim": [1017, 691]}, {"type": "para", "text": "Vores første stop i Jugoslavien efter at have været undervejs i næsten tre dage og kørt 1600 km. var Bled på Istrien. Der havde Jensens ligget før, og det var en dejlig campingplads i en skov og tæt på en stor kunstig sø, hvor man kunne bade. Der var ingen afmærkede pladser som i Danmark. Man fandt bare en plet, der var ledig, og folk lå tæt. Vi endte med at komme til at ligge ved siden af affaldsspandene og toiletbygningen, men vi tog det hele som en oplevelse. Dette var vores debut som campister i udlandet, og vi nød det i fulde drag: varmen, friheden, det fremmede, godt selskab og en kold øl til at slukke tørsten. Det var livet. Og vi var helt afskåret fra Danmark, idet vi jo ingen mobiltelefoner havde dengang. Karen Lis ringede slet ikke hjem under hele ferien. Det var et princip, de havde, men det var nu heller ikke nemt at komme til at ringe hjem fra Jugoslavien, så vi gjorde det heller ikke. Set i bakspejlet var det meget forkert, for der kunne jo ske noget, mens vi var væk. Men når man er ung, tænker man ikke så langt. Børnene nød søen, og det gjorde vi voksne også, enten på luftmadras eller i Jensens gummibåd, som de altid havde med på ferie sydpå. Det var lige noget, Lars kunne bruge. Efter tre dage i Bled gik turen videre, denne gang til Postojnegrotterne (tre timers kørsel). Et elektrisk tog kørte os 2 km ind i grotterne, hvor temperaturen var 8 grader. Det var et fantastisk syn at opleve disse stalagtitter og stalagmitter i et 23 km langt kanalsystem, det største hulesystem i Europa. Efter 2½ times guidet tur var vi ude i den varme luft igen. Tre timer senere ankom vi til vores feriemål, den største jugoslaviske ø i Adriaterhavet, Krk, som Jensens også havde været på tidligere. Øen har 24.000 indbyggere, og den største by hedder også Krk. Campingpladsen var bestemt ikke noget særligt, og der var fyldt af mennesker. Vi ville gerne have haft en plads med havudsigt, men de var alle optaget. Vi fandt dog en plads, hvor vi godt mente, at vi kunne være alle sammen, men der var fyldt med langt græs og tidsler, som skulle mejes ned, inden vi kunne installere os. Vagn og Finn gik i gang med at hugge tidslerne ned med den bedste erstatning de havde for en le, nemlig deres skovle, men da de var færdige, havde de tjære langt op ad benene. Det undrede vi os over og troede et kort øjeblik, at de tidsler og græs, de havde jokket oveni og skåret ned, var nogle specielle tjæreholdige planter, indtil det gik op for os, at vores nylig undervognsbehandlede bil jo havde kørt hen over dem. Der havde vi forklaringen på mysteriet. Men heldigvis havde de ikke lange bukser på, så det sorte stads kom af uden problemer. Der var simpelthen for varmt til lange bukser, og varmen var stikkende. Vi havde kørt i lang tid og var tørstige, og efter det med tjæren var tolerancetærsklen ikke særlig høj. Pigerne blev sendt afsted til kiosken for at købe nogle drikkevarer, for vi havde ikke noget koldt i campingvognen. Vi ventede og ventede, og utålmodigheden steg samtidig med, at vi begyndte at blive bange for, at der var sket pigerne noget. Langt om længe kom de tilbage uden drikkevarer, for der havde været kø! Og det var, hvad vi skulle til at vænne os til på denne ø. Her bagefter kan man undre sig over, hvad der gjorde denne feriedestination så tiltrækkende, for man kan nævne mange negative aspekter: en lang og varm køretur uden air kondition, bagende og stikkende varme, dårlig hygiejne på campingpladserne (der var tit afføring på toiletbrædterne), dovent rengøringspersonale (de lå ofte og sov på bænkene på toiletterne i stedet for at gøre rent), misligholdelse af faciliteterne (defekte ting blev aldrig lavet), kø til brusebad, toilet og butik, stenstrand m.m. Karen Lis elsker stadig at fortælle om dengang Lars blev sendt alene afsted til toilettet for at vaske sig og børste tænder. Han var hurtigt tilbage, og på spørgsmålet om hvorfor, svarede han prompte: ”Der var kø!” Alle disse irriterende faktorer, som vi valgte at tage som en oplevelse, blev dog opvejet af de skønne varme aftner, hvor det var behageligt at sidde ude, og hvor vi hyggede os med Yatzi og fik ordnet verdenssituationen, samværet, det varme badevand, god og billig mad, vin og øl, sydlandsk stemning, en hyggelig havn i byen Krk, som vi kunne spadsere ind til om aftenen m.m. Vi havde den ordning, at vi spiste på restaurant hver anden aften, og hver anden aften spiste vi dåsemad, som vi havde med hjemmefra. Vi havde ikke lyst til at købe kød i butikkerne. Det så ikke appetitligt ud, og en dag så vi en hare med pels i en frysedisk!"}, {"type": "figure", "caption": "", "page": 101, "file": "assets/images-bog2/p101_02.jpg", "dim": [1009, 702]}, {"type": "figure", "caption": "", "page": 102, "file": "assets/images-bog2/p102_01.jpg", "dim": [1007, 697]}, {"type": "para", "text": "Karen Lis og Finn havde snakket så meget om Plitvice Søerne og Nationalparken, som de havde set tidligere, og det syntes de også, at vi skulle opleve. Vi bestemte derfor en dag, hvor vi skulle køre den lange vej til den storslåede turistattraktion. Det ville tage 5 timer at køre de 200 km. hver vej, da vejene var meget dårlige, så vi skulle starte kl. 9 om morgenen. Vi tænkte dog ikke på, at der kunne blive dårligt vejr, for det havde vi indtil videre ikke oplevet i Jugo, som vi populært kaldte Jugoslavien, og vejrmeldinger var en by i Rusland. Da dagen oprandt, så der lidt gråt ud i horisonten, men pyt, det ville da naturligvis klare op senere. Vi blev imidlertid klogere. Jo længere vi kom på turen, des mere gråt og blæsende blev det. Én oplevelse havde vi dog undervejs, hvor vi stoppede hos en familie, der havde en tam brunbjørn i lænker. Vi fik lov at tage billeder, og Lars prøvede at klappe den. Da vi nåede vores mål, stod regnen ned i stænger, og det var koldt. Og så sad vi der i hver vores bil og kiggede ud på den silende regn. På et tidspunkt kommer Karen Lis løbende over til vores bil for at holde familieråd. Vi beslutter os for at gå ind i en butik, købe noget frugt og dernæst vende næsen hjemad. Vejret ser ikke ud til at ændre sig, og vi har ikke noget ud af at se parken i regnvejr. På vej ind i butikken løber vi for at blive mindst muligt våde, for vi har ingen regntøj med og er alle iført shorts og solbluser. Pludselig glider jeg på den glatte sti og falder med bagdelen ned i en kæmpe vandpyt. Det har sikkert set sjovt ud, men lige på det tidspunkt er der ikke nogen, der kan se komikken. Nå, vi kommer ind i butikken og styrer lige mod bananerne, som er det eneste, der kan lokke i den butik. Men det er ikke meningen, at man selv tager varerne, så Karen Lis går hen til disken og siger på dansk: ”Otte bananer, tak!” uden at tænke over, at hun ikke er i Danmark. Måske er det vejret, der et øjeblik får hende til at tro, at hun er det. Vi køber de 8 bananer og kører de 5 timer tilbage til campingpladsen, jeg kun iført trusser og bluse på grund af mit uheld. Da vi kommer tilbage til Krk, kan vi se, at det slet ikke har regnet der. Vi drukner skuffelsen i 2 liter vin. Bagefter har vi tit grinet af, at vi kørte i 10 timer for at købe 8 bananer."}, {"type": "figure", "caption": "", "page": 103, "file": "assets/images-bog2/p103_01.jpg", "dim": [996, 699]}, {"type": "para", "text": "Efter 4 dage fik vi pludselig besøg fra Spørring: Else og Jørn med børnene Helle og Lone samt Anne og Niels med børnene Rasmus og Rikke. De fandt en plet ikke langt fra os, og det var rigtig hyggeligt, for så kunne vi alle 15 (familien Danmark) gå på stranden sammen og gå ud og spise sammen om aftenen. Vi havde altid stole og luftmadrasser med til stranden, for der var mange sten og umuligt at ligge direkte på dem, og Lars havde ofte redningsvest på for en sikkerheds skyld. Rasmus og Lars var jævnaldrende, så de legede sammen. Vi havde ingen fortelt med, og det gjorde det jo nemt at installere sig, men vi havde solsegl, som det tog Vagn og Finn nogle dage at få sat op. Det er utroligt, så lidt man overkommer på en sådan ferie. Men man kunne stille alt muligt uden for vognen, fodtøj, strandlegetøj og luftmadrasser uden at der nogensinde blev stjålet noget. Det gjorde man bare ikke. En aften blev børnene malet inde i byen for 100 kr. pr. billede, og vi havde i mange år Lars’ portræt hængende. Efter tre dage skulle de andre spørringgensere videre, men vi havde en sidste hyggelig aften sammen, hvor vi samlet gik ind til byen, spiste ”mismas” isanretning og drak øl på en fortovscafé. Senere tog vi til bal i skovpavillonen, hvor vi sad ved ét langt bord under åben himmel og drak øl til tonerne af et danseorkester, men det var ikke de store balløver, vi havde med. Mens vi voksne drak øl, kvalte børnene en del colaer. 8 fadøl og 7 colaer kostede 70 kr. Kl. 23.30 gik vi hjem og smurte tun-madder, og vi sad alle ude til kl. 1.30. Næste dag tog vi afsked med de to familier."}, {"type": "figure", "caption": "Venstre side: Rikke, Helle, Lars, Jørn, Else, Karen Lis & Finn Højre side: Jane, Lone, Lene, Rasmus, Anne, Niels & Merete", "page": 104, "file": "assets/images-bog2/p104_01.jpg", "dim": [1009, 694]}, {"type": "para", "text": "Vi opholdt os dagligt ved stranden fra kl. 14 til 18.30. Det bedste for Lars var, når han kunne ligge og flyde på en luftmadras iført redningsvest og trukket af båden. Senere på dagen drak vi øl på campingpladsen og købte varme brød af bageren, der kørte rundt på pladsen. Der var 35 grader i skyggen, og om aftenen kunne temperaturen sagtens komme op på 37 grader i campingvognen. Om aftenen og om natten kunne der godt blive uvejr, men næste morgen var der atter sol og varme. Vi blev dog kølet af på hjemturen, hvor vi gjorde holdt i Østrig. Vi kom, lige som der havde været haglvejr, og vi fandt hagl på størrelse med bordtennisbolde. Et held, at vi ikke havde været der under haglvejret, for flere biler og campingvogne var blevet ødelagt. Vi havde nogle dejlige solskinsdage i Østrig med tur til bl.a. Grossglochkner, Østrigs højeste bjerg på 3.798 m., hvor vi bl.a. så murmeldyr. Her var vi med en lift op til en gletsjer, og som det sig hør og bør, spiste vi en af aftnerne en kæmpestor wienerschnitzel. I Tyskland fik vi jägerschnitzel og champagne den sidste aften for at fejre, at vi havde haft en kanon ferie. Vi havde i alt kørt 4.335 km."}, {"type": "para", "text": "Heldigvis fik vi set Plitvice Nationalpark året efter, hvor vi igen tog til Jugoslavien sammen med Jensens, denne gang i egen campingvogn og sammen med Tage, og turen gik via Split til Dubrovnik, hvor vi var to ud af de tre uger, vi var afsted. Vi fik to fine pladser på den dejlige campingplads med udsigt over havnen, så der var altid noget at kigge på. Finn og Vagn havde købt ens Puma joggingsæt, så det var et par flotte fyre, vi havde med. Pladsen havde 515 enheder, hver på 70 m2, og der var fine faciliteter: bank, bankboks, telefonkiosk, supermarked, snack bar, aviskiosk, frugt- og grønsagsbod, tennisbaner, bordtennis, basketball, volleyball, fodbold, vandski, wind surfing, kano- og bådsejlads, bådekskursioner, restauranter, barer, danserestauranter, diskoteker, benzintanke og et shoppingcenter. Desuden var der moderne sanitære faciliteter (toiletter, brusere, vaskekummer, vaske- og opvaskefaciliteter), vaskemaskiner, strygerum og transportable køleskabe. Om dagen var der meget varmt, men om natten kunne det blæse så kraftigt op, at mændene måtte stå op og tage overseglene ned. Strandbredden og havbunden bestod af fint ral, så det var en klar forbedring fra tidligere. Lars havde snorkel, dykkerbriller og svømmefødder på, når han gik i bølgerne. En dag tog vi ind til Dubrovnik for at gå på bymuren, den stærkeste bymur i Europa. Bymuren var blevet bygget og genopbygget fra 1453 til 1660, og den indre mur var nogle steder 25 m høj. Fra landsiden var den 4-6 m tyk men fra søsiden kun 1½-3 m tyk. Den var forstærket af 3 runde og 12 aflange tårne, 5 bastioner og 3 forte. Murene var et symbol på middelalderlig magt og poesi. Det var en varm omgang at gå på muren i den stegende hede, så vi nød at komme tilbage til campingpladsen og stranden senere på dagen. Men det er sørgeligt at tænke på, at Dubrovnik blev ødelagt nogle få år senere på grund af krigen, og at ingen turister turde tage til Jugoslavien i mange år på grund af dette. Det var hyggeligt at have Tage med – det syntes Lars bestemt også. De to sov sammen i den ene ende af campingvognen. Der blev spillet pilespil og andre spil, kørt med svævebane, badet og sejlet i gummibåd, og en dag havde mændene forvildet sig ud forbi en nudistlejr – hvordan mon det kunne ske? Det var meget billigt at gå ud og spise: 30 kr. pr. person med vin. Den sidste aften gav Tage mad på en restaurant. Det kostede ganske vist 50 kr. pr. person, men så var det også inkl. 4 flasker vin. På vej fra Dubrovnik var vi inde og se Plitvice Søerne og Parken, som blev erklæret for nationalpark i 1949. Parken dækker et areal på 19.700 ha, hvoraf 13.500 ha er skov, 6.000 ha er mark og 200 ha er vand. Vejret var perfekt, og vi havde en fantastisk dag derinde. Vi både sejlede og kørte med tog i parken, og vi så fantastisk natur, bl.a. mange flotte vandfald. Vi begav os videre, og efter den dag at have kørt 459 km fandt vi en dejlig campingplads i Radstadt i Østrig. Her var vi i to dage i dejligt vejr, hvor vi bl.a.var på en dejlig tur til Gosausee med udsigt til den evige sne. Her delte vi os i to lejre: Jensens ville sejle på søen, og vi ville op i højderne. Vi tog svævebanen et stykke op og klarede resten af turen til fods op til 3000 m.o.h. Vi var virkelig kommet til Østrig med den smukke natur og fantastiske udsigt, og om aftenen spiste vi naturligvis en kæmpe wienerschnitzel og drak øl af krus, for senere at gå ind til byen og opleve underholdning med tyrolermusik. Børnene nåede lige en tur i campingpladsens swimmingpool, inden turen gik videre næste dag."}, {"type": "figure", "caption": "", "page": 104, "file": "assets/images-bog2/p104_02.jpg", "dim": [1020, 697]}, {"type": "figure", "caption": "", "page": 105, "file": "assets/images-bog2/p105_01.jpg", "dim": [1001, 691]}, {"type": "para", "text": "Traditionen tro sluttede vi ferien af med en shopping-tur i City Grossmarkt og senere en god middag på en fin restaurant i Flensborg. Jo, en sådan ferie skulle sluttes af med manér. Vi kom hjem afslappede, glade og meget solbrændte."}]}, {"title": "Camping i Frankrig 1987", "blocks": [{"type": "para", "text": "I 1986 skulle vi have været sammen med Jensens til Ungarn, men da far blev syg, valgte vi at blive hjemme, hvilket vi aldrig har fortrudt, for far døde i august samme år (herom senere). Men året efter var vi på banen igen, og denne gang ville vi til Frankrig, hovedsagelig Bretagne, og det blev en dejlig ferie. Som noget nyt havde begge piger kærester med og kørte sammen i Hans Oles bil. Hans Ole var Lenes kæreste, og han var 9 år ældre end Lene og havde egen bil. Han er for øvrigt uddannet på Handelshøjskolen og havde mig som lærer en overgang. Jane var kæreste med Niels, som var lidt af et legebarn, hvilket kom Lars til gode, for Niels var rigtig god til at tage sig af ham. I dag er Lene og Hans Ole gift og har sønnerne Simon og Victor, mens Jane og Niels har tvillingerne Nana og Peter. Jane og Niels holdt pause i ægteskabet men fandt sammen igen. I dag er de dog skilt og lever begge som singler. Det var hyggeligt at have de unge med."}, {"type": "figure", "caption": "", "page": 106, "file": "assets/images-bog2/p106_02.jpg", "dim": [832, 683]}, {"type": "figure", "caption": "", "page": 106, "file": "assets/images-bog2/p106_01.jpg", "dim": [485, 814]}, {"type": "para", "text": "Vi startede ferien den 2. juli i Osnabrück, hvor vi besøgte nogle af Karen Lis og Finns tyske venner, Ilse og Manfred Buhl, som havde en datter Michaela. Efter at have set Manfreds vinduesfirma og installeret os med vores campingvogne i firmaets overdækkede gård med fine toiletter, inviterede de os med ud at spise på en græsk restaurant, hvor vi fik så meget mad, at vi måtte levne. Desuden insisterede Manfred på, at Lars skulle have isdessert, og det sagde han ikke nej tak til. Jo, de var meget gæstfrie. Efter middagen gik vi en dejlig tur inde i den gamle, meget smukke bydel, inden vi ”drønede” hjem til Ilse og Manfred og fik drinks på terrassen. De havde to store schæferhunde, der holdt vagt ved firmaet, så der var ingen fare for, at der skete os noget om natten. De var heldigvis buret inde om dagen. Næste morgen spiste vi morgenmad i privaten, et overdådigt måltid, som vi kunne køre langt på. Lars var meget imponeret over Manfreds nye Mercedes 500, som vi havde fået nogle ture i dagen før. Man blev suget helt fast i sæderne, når Ilse lettede, og det var fuld fart, bremsen i, over 200 km/t på Autobahn. De havde for en flaske whisky fået lavet en speciel nummerplade med OS (Osnabrück). Lars blev fotograferet i bilen og fik sågar lov til at sidde på køleren som kølerfigur, dog uden træsko. Det havde været en dejlig oplevelse at besøge dem. På vej til Frankrig overnattede vi tæt på Bruxelles og var næste dag inde og se Atomium, Manneken Pis, Grand Place og EF-Bygningen, som den hed dengang. Næste dag gik turen til Paris, hvor vi havde bestilt plads på en campingplads lidt udenfor ved navn Maisons-Laffitte. Vi ankom ved aftenstid og fik os installeret på denne dejlige plads, hvor vi grillede om aftenen. Frankrig var spændende, og jeg kunne kommunikere med dem på et rimeligt niveau, selvom mit franske var blevet lidt rustent med årene, fordi jeg ikke havde brugt det. Næste dag gik vi 10 min. til stationen og tog toget til Paris, og ½ time senere stod vi på Concordepladsen. Vi havde i mellemtiden skiftet til Metro på Gare St. Lazare. Vi gik lidt rundt og så bl.a. Tuillerihaven, Notre Dame og Eiffeltårnet, hvor Lars ikke måtte komme ind med bar overkrop. Han fik sin bluse på, og så kunne vi klatre til tops. Derefter sejlede vi en tur på Seinen, men da var Lars så træt, at han faldt i søvn. Vi ville være blevet lidt længere i Paris om aftenen, men pludselig begyndte det at regne, så vi styrtede afsted til den nærmeste Metrostation og tog tilbage til campingpladsen, hvor det slet ikke havde regnet. Næste dag kørte vi alle til Versailles Slottet, hvor der var kilometerlang kø for at komme ind. Vi nøjedes derfor med at gå rundt og se på alle parkerne udenfor. Vi var tilbage ved aftenstid og kunne grille bøffer og sidde ude til kl. 1. Kun Vagn måtte gå tidligt i seng, da han ikke kunne deltage i samtalen på grund af blærer i munden. De blev dog hurtigt kureret med Finns brintoverilte. Næste dag delte vi os i tre lejre. Finn mente, at han i hvert fald havde set Paris, så han og Karen Lis ville blive hjemme. Vi andre mente ikke, at vi var færdige med Paris, bortset fra Lars, så han fik lov at blive hjemme, og han og Finn byggede modelbil. De unge mennesker tog afsted for sig selv, og Vagn og jeg tog toget til Paris kl. 10. Vi så Forum les Halles, Pompidoucentret og Triumfbuen, vi spiste frokost på en fortovscafé og spadserede ad Champs Elysées, indtil vi tog toget hjem og var tilbage på pladsen kl. 18. Næste dag forlod vi Paris og satte kursen mod Bayeux, hvor vi var inde og se det berømte Bayeux tapet, som gjorde stort indtryk. Kl. 20.30 nåede vi Cancale i Bretagne, ikke langt fra Mont Saint-Michel, og vi kom til at ligge på en 3-stjernet campingplads med opvarmet swimmingpool, hvor alt fungerede til forskel fra Jugoslavien. Vi havde ikke langt til stranden, så det benyttede vi os jævnligt af. Alle steder solgte de østers og muslinger, og vi skulle naturligvis også prøve, men jeg husker østers som en slimet klat saltvand, som man havde fornøjelse af længe efter. Også den voldsomme forskel på ebbe og flod gjorde specielt indtryk på os danskere. Der kunne være 10 til 15 meters forskel på høj- og lavvande, og nogle steder forsvandt havet helt ud i kimmingen, når det trak sig tilbage, og enorme områder lå tilbage, ofte oversåede med lyst- og fiskerbåde. Pandekager med al slags fyld var også en specialitet i Bretagne, så det skulle vi naturligvis også prøve. En dag tog vi ud på Mont Saint-Michel, en sælsom klippeø, hvor der er en lille by, et kloster og en klosterkirke. En 1800 meter lang dæmning forbinder øen med fastlandet. Bugten har Frankrigs voldsomste tidevand med en forskel på flod og ebbe på 15 meter, og to gange i døgnet kommer flodbølgen skyllende ind over vadehavet. Desværre er den lille bys gamle gader stærkt skæmmet af et utal af souvenirboder, men stedet er alligevel et besøg værd, hvis man kan mase sig frem i trængslen. Om aftenen grillede vi, og alle var i swimmingpoolen, også Finn. Næste dag var slappe-af-dag. Vi havde det rigtig hyggeligt i vores lille lejr, der bestod af to campingvogne med to solsegl, to telte til de unge mennesker og tre biler. Vi læste, spillede bold, tennis, badminton, vælte-flaske leg og minigolf, og Lars dystede med Niels og Hans Ole om at være den bedste til at spille på Lars’ nye røde bip-bip spil. Det var også Lars’ største beskæftigelse, når vi kørte i bilen, så han var rigtig god til det. Derfor vandt han over drengene. Men det irriterede ham, hvis vi kørte gennem en tunnel, for så blev alle hans point slettet, og så kunne han begynde forfra igen. En aften var vi i St-Malo, hvor der var et hyggeligt marked. Niels og Lars blev karikaturtegnet. Den 13. juli om aftenen så vi et kæmpe fyrværkeri ud over havet, og det var næsten ikke til at trænge igennem menneskemylderet. Den 15. juli brød vi op og kørte 540 km til øst for Nevers. I Chatillon en Bazois fandt vi kl. 21 en Camping Municipal, hvor vi overnattede for 12 F. Vi slog os ned omkring en campingvogn, hvis franske ejere var i byen. Da de kom hjem, blev de meget sure, så vi fortrak inden døre med vores drinks. Næste dag kørte vi igennem Jurabjergene, som er meget flotte, hvis man ellers kan lide bjergkørsel, og det kom vi til fulde til at opleve den dag. På grund af vejarbejde var der omkørsel, og vi kom på gale veje. Vi kørte efter Bellegarde, og ligesom vi troede, vi var der, var vi et helt andet sted på kortet. Vi fandt dog en 3-stjernet campingplads mellem Bellegarde og Frangy, hvor vi skulle opleve at være spærret inde i vognene i to dage på grund af regn. Det var lige fra bikini til regntøj. Pludselig skulle vi bare ud trods det dårlige vejr, så en dag tog vi til den hyggelige Annecy, der er kendt for sine kanaler og mange blomster. Samme aften holdt vi afskedsfest, da Lene og Hans Ole skulle rejse næste morgen. Vi sagde godnat og gik hver til sit, men lidt senere bankede det på vores dør. Udenfor stod Niels, og han ville have kaffe. Vi havde fået lidt inden for vesten, så vi fik hurtigt kaldt på Jensens, og så gik snakken til kl. 4 om morgenen. Da vi gik op på toiletterne, måtte vi ustandseligt tysse på Niels af frygt for, at han skulle vække de andre campister med sin højrøstede stemme. Næste morgen, søndag den 19. juli, stod vi op kl. 6.30 for at vinke farvel til Lene og Hans Ole, men vi fandt hurtigt tilbage til dynerne og kom først selv afsted kl. 10.30. Vi måtte forlade denne dejlige campingplads uden at have været i swimmingpoolen, men det var den første regn, vi havde haft i 14 dage, så det var billigt sluppet. Vi kørte 129 km til Chamonix, hvor vi slog os ned mellem bjergene på en campingplads med udsigt til sne på toppen af Mont Blanc. Det var en fin plads med gode badeforhold, men jeg kunne ikke klare deres toiletter, som var to fodspor og et hul i jorden. Hver dag kom bageren kørende rundt på pladsen med frisk brød. Snart fik vi regelmæssigt besøg af naboens lille kattekilling, og så kan det nok være, at Lars kunne komme ud af sengen om morgenen. Vi kaldte den Misti, og hver gang kom ejeren, en lille fransk dreng, eller drengens far og hentede den. Det var fantastisk at vågne op om morgenen og kigge ud på de sneklædte bjerge, der omgav os. En dag tog vi toget fra Chamonix til Montenvers og stod af ved endestationen i 1909 meters højde. Vi så gletsjeren, Mer de Glace, samme navn som vores campingplads, og vi foretog den stejle og lange nedstigning til is-grotten, en tunnel, der er boret ind i selve gletsjeren, og hvor man kan få et indtryk af den blågrønne gennemsigtighed. Inde i grotten var alt inventaret lavet af is: I stuen var møblerne og pejsen af is, og man kunne for 40 F få taget sit billede der. Der var soveværelse med is-senge, badeværelse med is-toilet og ditto badekar, et is-køkken og endelig en isbjørn af is. Behøver jeg at sige, at der var meget koldt i grotten. Derfra tog vi svævebanen op undtagen Lars og Vagn, som spadserede med deres rygsække. Vi har et billede, hvor Lars er fotograferet foran gletsjeren med den lille hund, han købte i souvenirboden. På vej ned med toget gik Lars helt grassat med kameraet og tog bl.a. et billede ned over vores campingplads, hvor man kan se Finns orangefarvede solsegl. Dagen efter kørte vi et smut over grænsen til den italienske by Aosta, hvor der var en flot gammel bymur og masser af spiritusforretninger med billig sprut. Det siges, at der altid er varmt i Aostadalen, og det var der så sandelig også den dag. Den aften tog vi til en lille by, Argentière, hvor vi spiste en lækker middag, suppe, pålægsanretning, steak og is for 58 F pr. person. Vi sluttede aftenen af med rødvin på campingpladsen. Næste dag tog Lars og Vagn i svømmebad i Chamonix, mens jeg handlede i byen, og om aftenen drak vi champagne, da det var vores sidste aften der. Den 23. juli forlod vi denne dejlige plet efter at have haft 4 overnatninger der til 248 F. Vi kørte gennem det disede Schweiz videre til Heidelberg, hvor vi fandt en skøn, lidt indeklemt plads lige ned til Neckar floden, en biflod til Rhinen. Vi havde egentlig bestemt, at vi ville ud at spise, men vi syntes, der var så dejligt, at vi besluttede os for i stedet at åbne en dåse. Senere på aftenen gik vi hen til sluserne for at se, hvordan skibene blev sluset igennem. Dagen efter betalte vi 18 DM til campingfatter, en rigtig led kommandant og paragrafrytter, og vi fik ingen kvittering. Om aftenen kørte vi væk fra Autobahn og fandt en hyggelig landevejskro på Lüneburger Heide. Behøver jeg at sige, at menuen stod på wienerschnitzel? Og så gik det derudaf igen i vores røde Volvo, til vi nåede den sidste rasteplads før grænsen. Her var der andre end os, der ville overnatte, men vi fandt med besvær to pladser, når vi koblede bilerne fra. Det var den 24. juli, så vi ringede hjem til Per og gratulerede ham med de 27 år. På denne tur havde vi ringet hjem jævnligt, for vi havde jo året forinden oplevet, at der kunne ske noget. Vi havde også først på turen ringet hjem til Per, fordi vi var spændte på at høre, om han havde fået arbejde. Han var blevet færdig som cand.merc. og havde søgt job hos SAS som trainee. Glade blev vi, da vi hørte, at han havde fået jobbet og skulle være trainee i tre år, hvor han ville komme til at arbejde i forskellige sektorer og også blive udstationeret. Det blev starten på en lang og spændende karriere for Per, og det bragte ham til Stockholm, Los Angeles, Hong Kong, Bangkok og London, for til sidst at ende i Danmark. Sidste år, 2012, sagde han op efter mere end 25 år, og nu søger han nye udfordringer."}, {"type": "figure", "caption": "", "page": 107, "file": "assets/images-bog2/p107_01.jpg", "dim": [784, 1028]}, {"type": "figure", "caption": "", "page": 108, "file": "assets/images-bog2/p108_01.jpg", "dim": [1163, 797]}, {"type": "figure", "caption": "", "page": 109, "file": "assets/images-bog2/p109_01.jpg", "dim": [1171, 797]}]}, {"title": "USA-turen i 1989", "blocks": [{"type": "para", "text": "Vi kendte egentlig ikke Hanne og Keld særlig godt i 1989, selvom de havde boet på Østervang 15 siden før vi flyttede til Spørring (vi boede i nr. 25). De havde i 1972 mistet en datter på 9 mdr. på grund af en hjertefejl, men de havde heldigvis Pia på 17 år. Hanne var bankuddannet og havde i flere år siddet i banken i Spørring, og Keld var sælger. Vi var sammen ved flere lejligheder, men vi kom som sådan ikke sammen med dem. En aften faldt snakken på USA, og jeg kan ikke huske, hvem der spurgte hvem, men vi fandt hurtigt ud af, at vi godt kunne tænke os hinandens selskab på en sådan rejse. Og det fortrød vi så sandelig ikke!"}, {"type": "para", "text": "Det var Keld, der ordnede alt med Maersk (Rejsebureau OP), og det var han god til. Turen blev bestemt et år, inden vi skulle afsted, så vi havde god tid til at forberede os. Vi besøgte også Hanne og Keld i deres sommerhus i Fjerritslev et år før for at planlægge, og vi deltog i et FOF kursus om New York i oktober 1988, så vi var parate til at møde the Big Apple. Vi havde mange hyggelige møder med Hanne og Keld inden afrejsen. Vi skiftedes til at give mad, og så blev der snakket ferie til den store guldmedalje. Vi skrev og ringede sammen med Jacque i Denver, for vi havde planer om at besøge hende og familien der. Jeg ville gerne vise Lars, hvor jeg havde boet. Selve flyrejsen, både udenrigs og indenrigs kostede for os tre 21.000 kr. Inden vi skulle rejse, sendte mor en pakke til Lars. Det var en t-shirt med navn og logo fra Bødkergården, den børnehave, hun arbejdede i, og som Lars også havde besøgt ved flere lejligheder, når han var med sin mormor på arbejde. Det var en rigtig sød tanke. På kortet skrev mor: ”Kære Lars. Ja, så sender jeg dig en Bødkergårdstrøje, som jeg håber du bli’r glad for. Ja, så er det lige før, at du skal til at pakke tandbørsten. Jeg ønsker du får en god tur, det er jo ikke alle 11-års knægte, der får sådan en tur sammen med sin mor og far, jeg håber du tænker over det. Da jeg var 11 år, var det største, man kunne opnå, nok en cykeltur til Sæby sammen med sin mor og far, og madpakken var pakket i skotøjsæsken. Ak ja, du forstår det nok ikke, det forlanger jeg heller ikke, men nyd din tur. Hils mor og far og giv dem et knus fra mig. Tusinde knus fra mormor. Jeg tænker på jer hver dag.” Det var bare mor i en nøddeskal. Jeg får helt tårer i øjnene nu, hvor jeg sidder og læser kortet. Lars var hendes et og alt. Pengemæssigt var der sket noget nyt, i og med at man nu kunne få et kreditkort i banken. Jeg havde lige fået et Visa/Dankort med billede, så det var en helt ny verden, der åbnede sig for os, og også for banken. Det viste sig, at de klokkede i det, så vi de sidste tre dage ikke kunne bruge vores dankort, da det uvist af hvilke årsager var blevet spærret, og det var op til en weekend. Det var rigtigt irriterende, for der var et par støvler, Lars gerne ville have. Vi lånte derfor lidt penge af Keld, som havde et Eurocard med. Noget andet nyt var også, at vi havde købt videokamera. Vi havde talt om at deles om det, men det endte med, at vi købte det, og det blev til 26 timers video, som vi kortede ned til 15!"}, {"type": "para", "text": "Vi pakkede flere uger i forvejen, og alt blev gjort klar og lagt op på gæsteværelset. Endelig oprandt dagen, hvor vi skulle rejse. Vi drak morgenkaffe kl. 7 hos Hanne og Keld, og kl. 8 startede vi fra Spørring. Reinholt kørte os til Tirstrup, mens Pia og hendes daværende kæreste Carsten kørte for Hanne og Keld. Rejseplanen var, at vi skulle rejse fra Tirstrup den 28. juni kl. 9.30, selv håndtere vores bagage i Kastrup og tjekke ind igen til new York. Hanne og Keld havde foreslået, at vi skulle tage en madpakke med til New York, og hvor blev vi glade for den idé. Vi skulle flyve med SAS, hvor Per jo arbejdede, så i Kastrup kom Per og ønskede os god rejse og fulgte os ud til Gate 35. Per havde desuden sørget for Business Class pladser til os og sørget for, at Lars fik en flot børnemenu i en stor kasse, hvor der også var spil i. Det var lige noget, Lars kunne bruge, og desuden viste de ”Rainman” på storskærm. Vi spiste to gange på turen og fik sågar varme håndklæder. Alle klappede, da flyet rørte jorden i New York kl. 14.55 NY tid. Vi kom hurtigt igennem Newark Lufthavn og tog en taxa til Paramount Century Hotel, hvor vi ankom kl. 16.30. Taxaen kostede 40 $ inkl. drikkepenge. Vi fik anvist værelser på 12. etage – ikke luksus men mellemklasse og rent – i hvert fald sengene. Prisen for 4 nætter for os var ca. 3.000 kr. Det første, Lars gjorde, var at tænde for TV og skifte mellem de 13 kanaler, han fandt. Vi delte en flaske champagne og fejrede, at vi var kommet til KAMERIKA, som vi yndede at sige. Og her var det så, at vores medbragte mad vakte lykke. For vi orkede rent ud sagt ikke at skulle ud og finde et sted at spise. Det her var meget hyggeligere, så vi satte os på sengen og nød ægge- og leverpostejmadderne fra Danmark, samtidig med at Hanne indimellem lige skulle cykle med benene for at få gang i blodcirkulationen efter at have siddet så længe i et fly. Vi boede lige i hjertet af Manhattan, ikke langt fra Times Square og Broadway. Om aftenen gik vi en tur og så en rotte på Times Square, sikkert en Globerotte (vi kaldte os selv globetrotter, så vi lavede lige et ordspil). Vi travede og så meget i New York og var bl.a. på en sejltur med Circle Line omkring Manhattan, en flot tur. Desuden var vi oppe i Empire State Building, hvorfra bilerne lignede små legetøjsbiler og der var udsigt til Tvillingetårnene, hvor vi en aften tog elevatoren op til 107. etage. Det var en fantastisk fornemmelse at træde ud på taget i mørke og se alle New Yorks lys – det kan ikke beskrives. Mærkeligt at tænke sig, at tårnene ikke er der mere. Hanne havde sine små særheder, som vi jokede meget med. Fx skulle hun på toppen af Empire State Building ned at ligge på gulvet for at få benene i vejret, og hun gik altid rundt i sin røde regnjakke, selv i 30 graders varme. Desuden skulle hun altid bytte plads med Keld, når vi endelig havde fået os sat. Det trak altid der, hvor Hanne sad, men så havde hun jo den røde jakke! Hanne var tilpas nysgerrig, og på den måde fik vi andre også nogle sjove oplevelser. Hun gik helt tæt på mærkelige typer for at fotografere dem, og tæt ved vores hotel så vi en dag nogle hjemløse ligge på en trappesten i nogle papkasser. Dem skulle Hanne også lige hen og fotografere. Hun kunne godt blive gal på Keld, selvom han var den mest tålmodige, man kunne tænke sig, men han gav hende altid ret, og så kom den diskussion ikke videre. ”Du er også så dum, Keld!”, kunne hun sige, hvortil Keld replicerede: ”Ja, Hanne.” Den dag, vi var i Central Park, havde Hanne allerede slidt så meget på sine sorte espadrilles, at hun måtte skære sålerne af. Til sidst endte de deres dage i en skraldespand. Vi slentrede ned ad Fifth Avenue med de dyre butikker, så Rockefeller Center, St. Patrick Kirken, var oppe i Frihedsgudindens krone og så det tilhørende museum. Vi var i Wall Street, Seaport, Fulton Street Market, Little Italy, Soho, Greenwich Village og Chinatown. Vi var ude at gå på Brooklyn Bridge, og mændene var på et hangarskib, Sea Air Space, mens Hanne og jeg købte t-shirts på Times Square. Elektronik var også dengang billigt i USA, så Lars købte en walkman. På vores mange spadsereture i New York kom vi også forbi Carnegie Hall, the Metropolitan Museum of Art, the Metropolitan Opera og Lincoln Center. Grundet Hannes nysgerrighed stak vi hovederne inden for i nogle af bygningerne. Det, der også var dejligt med Hanne og Keld, var, at vi ikke absolut skulle ud og spise hver aften. Tit købte vi noget mad og spiste hjemme på værelset, og så sluttede vi aftenen af med en rom og cola, som blev vores favoritdrink, eller vi købte noget pålæg og brød og satte os på en fortovskant i et vejkryds midt i New York og nød en cola dertil. Lars hyggede sig også i deres selskab, og de var rigtig søde ved ham og pjattede vældigt med ham. For som Hanne tit sagde: ”Vi skal grine”. Og det gjorde vi meget på den tur."}, {"type": "figure", "caption": "", "page": 111, "file": "assets/images-bog2/p111_01.jpg", "dim": [1176, 781]}, {"type": "para", "text": "Den største oplevelse, vi havde i New York, var nok turen til Harlem. Vi ville gerne til en gudstjeneste og havde spurgt på hotellet, om det var forsvarligt at tage derud. De mente nok det kunne gå, når det var en søndag morgen, for ”så ligger de fleste og sover”! Det var sandelig betryggende. Hanne pressede på, for her var der noget spændende og lidt farligt, så hendes nysgerrighed skulle stilles. Vi andre var med på idéen. Vi var jo 5, så mon ikke vi skulle kunne klare det. Vi havde udtrykkeligt fået at vide på hotellet, at vi under ingen omstændigheder måtte tage en sort taxa hjem derudefra. Den skulle være gul, for de sorte kørte os bare et sted hen og rullede os for penge."}, {"type": "para", "text": "Vi tog derfor en gul taxa kl. 9 til Abyssenian Baptist Church i Harlem (14 $). Gudstjenesten var først kl. 11, så vi var i rigtig god tid og stod længe udenfor og betragtede menigheden, der lidt efter lidt kom kørende dertil i taxaer. De var alle sorte (altså menigheden), og ud steg de, den ene finere pyntet end den anden, som om de skulle til en stor fest, og de små farvede børn var virkelig nuttede. Kl. 10 gik vi ind i kirken og satte os bagest på balkonen, selvom Hanne gerne ville have siddet på første række. Ud af en menighed på ca. 700 var vi kun ca. 25 hvide. Vi blev budt pænt velkommen af en meget præsentabel kvinde, der kom hen og gav os hånd. Præsten var ny-indsat og præsenterede sin familie og fortalte om sin barndom. Han havde en dialog med menigheden, og til spørgsmålet, om der var udlændinge blandt den, råbte vi, at vi var fra Danmark, og så blev vi budt velkommen med et af de mange ”Haleluja’er”, som menigheden med mellemrum spontant brød ud i. Jo, det var en utrolig stor oplevelse, som jeg nødig ville have været foruden. Vi blev desværre nødt til at gå lidt før slutningen, midt i en af de mange negro spirituals, som blev sunget af det store 40-personers mandskor, for vi skulle videre med tog til Washington samme eftermiddag. Nu havde vi så problemet, for der var ikke en gul taxa at spotte i miles omkreds, og nu var folk stået op og stod og hang på gadehjørnerne, og her kom vi med vores kameraer om halsen og lyste langt væk af turisme. Vi var ikke stolte ved situationen, men for Lars’ skyld undgik vi at vise, at vi var lidt utrygge. Endelig så vi en gul taxa, men den var optaget, og det var den næste også. Det var bagende varmt, og gaden var skummel og beskidt. Hvad skulle vi gøre? Vores redningsmand var fra Jamaica. Han kørte en gul taxa, holdt parkeret i den modsatte kørebane og var ved at købe en kæmpe vandmelon af en handlende. Mellem os og taxaen var der en midterrabat, og jeg har aldrig set Keld spæne afsted med en sådan fart. Heldigvis var taxamanden ledig og ville køre os tilbage til civilisationen. Vi fik en vældig sludder med ham, og jeg husker, at han flere gange sagde: ”New York is crazy!” Han kunne ikke lide at bo der. Han havde en kuglepen siddende i en af sine mange krøller, og det kunne Hanne ikke stå for, så hun tog et billede af ham. Vi sagde farvel til ham ved hotellet og gik op for at hente vores kufferter. Da vi kom ned igen, stod vores ven fra Jamaica der igen – med Hannes sorte jakke (ikke den røde), som hun havde glemt på bagsædet. Helt utroligt, at han var kommet tilbage med den, og da Hanne ville give ham penge, takkede han nej. I stedet fik vi ham til at køre os til Pen Station, hvor vi skulle med toget til Washington DC for at fortsætte vores eventyr. Vi tog Amtrak kl. 14.20, og vi sad i kupé med en rigtig sød negerfamilie med to søde børn. Jeg husker, at de spillede UNO, et spil som også var populært hos Lars. Det var interessant at følge landskabet de godt tre timer, det tog at køre strækningen med ankomst 17.44. Vi har aldrig set så meget marmor, som vi så på Union Station i Washington. Per havde skaffet os værelser til en rimelig pris på det fashionable Hyatt Regency, 250 $ for 3 nætter for os tre. Det var store flotte værelser med King size senge, så brede, at vi, som Keld sagde, skulle have samtaleanlæg for at komme i kontakt med ægtefællen. Lars havde sin egen store seng, og det passede ham fortrinligt. Hvad der også passede ham godt var, at der var 23 TV-kanaler. Vi andre nød de bløde tæpper og møbler, den fantastiske udsigt fra 12. etage, det flotte interiør og moderne kunst, telefon og radio med vækkeur. På badeværelset var der også et tykt gulvtæppe, lækre håndklæder, hårtørrer og dufte-godt. Veletableret på værelset tog vi en rom og cola og skålede for Per. Hver dag fik vi en avis, kaffe, chokolade og bolsjer. Jo, vi sendte mere en én gang en kærlig tanke hjem til ham. Den aften spiste vi fint på restaurant Orleans House, men det var meget varmt, og klimaet var fugtigt. Morgenmaden indtog vi på 2. etage og fik anvist et bord til 5, hvor der mindst kunne være 10 personer, så vi måtte næsten sidde og råbe til hinanden. Der var meget flot i restauranten med bløde sofaer med blomstret stof, blomster og grønne stofservietter. Næsten inden vi havde fået os sat, kom der en tjener med kaffe og juice, den ægte appelsinjuice, som man får i USA, og så gik vi ellers i gang med æg, bacon, kartofler, toast og hele svineriet, og der var refill på kaffen. Andre tjenere kom 4 gange og fyldte op, og hver gang sagde de: ”Excuse me”, som var de én stor undskyldning. Vi blev ved morgenmaden betjent af 5 forskellige tjenere, men da vi skulle betale de 21,25 $ for os tre, koksede det. Vores kort blev hele tiden afvist, så Keld måtte træde til med sit kort, og efter at 4 mennesker havde været involveret og skrevet forkert m.m., fik vi endelig betalt."}, {"type": "para", "text": "Vi tog en Tourmobile Sightseeing tur rundt for at se Lincoln Memorial, Washington Monument, Capitol, Thomas Jefferson Memorial og Arlington Kirkegård, hvor vi så John F. Kennedys grav. Det var helt underligt at stå der ved den evige ild. Der var også to små plader på graven, én over et dødfødt barn og én over et barn, der blev to dage gammelt i august 1963. Robert Kennedys grav var mere beskeden, og ud over en plade og et kors lå der kun en vissen rose. Vi så vagtskifte på den ukendte soldats grav, men for os så alle vagterne ens ud, høje flotte fyre med solbriller og karseklippede under kasketterne. Blandt de 250.000 hvide gravsten på kirkegården fandt vi én, hvorpå der stod Christensen."}, {"type": "para", "text": "Den 4. juli havde vi sat næsen op efter den helt store oplevelse, nu da vi befandt os i Washington DC. Vi vidste jo, at amerikanerne var eksperter i parader, men desværre druknede det hele i regn. Dagen startede så nogenlunde tør, og vi tog en metro til Capitol, hvor der allerede var mange mennesker, der havde slået sig ned på plænerne med frokostkurve, tæpper, stole, ja en familie havde endda en lille swimmingpool med. Det havde de ikke behøvet! Vi havde ikke set ret meget af optoget, da det begyndte at regne, og pludselig åbnede sluserne sig og folk styrtede op mod the National Gallery of Art, hvor vi fik lov at stå i tørvejr i lobbyen, men da var vi allerede gennemblødte, selvom vi havde regnjakker på. Heldigvis havde jeg en tør trøje til Lars i tasken, for hans trøje kunne vrides. Vi blev der i en time, hvor regnen væltede ned. Museet har garanteret aldrig haft så mange besøgende på én gang. Selv efter vi forlod museet, kom der byger, så vi måtte stå i læ, og vi tog en taxa til Georgetown og kiggede på de karakteristiske huse i engelsk stil, gik over Key Bridge og tilbage mod hotellet. Men inden vi gik op, var vi på en burgerbar, Roy Rogers, og spise lækker kylling, pommes frites, salat og brød for kun 20 kr. pr./person. Der så vi en familie, hvis kroppe væltede ud over stolene, nok de fedeste mennesker, vi nogensinde har set. Jo, vi var virkelig kommet til USA. Senere på aftenen gik vi op på broen og så 37 minutters fyrværkeri fra Capitol, så dagen sluttede da af med manér. Senere på aftenen, da vi skulle have vores obligatoriske drink, fandt vi ud af, at der var en ismaskine på gangen, hvilket der var på næsten alle de hoteller, vi boede på. Herefter blev Lars vores faste ismaskine-mand."}, {"type": "para", "text": "Næste dag splittede vi os op, for Vagn og jeg ville gerne ind og se Det Hvide Hus. 7.30 tog vi metroen, og kl. 8.00 stod vi bagest i en kilometerlang kø. Kl. 8.15 havde vi to gratis billetter til Det Hvide Hus til kl. 10.35. Vi tog metroen tilbage til hotellet, pakkede færdig, betalte og tog afsted igen kl. 9.15. Mens vi ventede på at komme med på tur nr. 5, var der sørget for underholdning i bedste amerikanske stil. På turen gennem Det Hvide Hus så vi 10 værelser, bl.a. den sal, hvor John F. Kennedy havde stået på ”lit de parade”, og det ovale værelse. Turen varede 45 minutter og var vældig interessant. Præsident George Bush var hjemme, men han kom desværre ikke ud og tog imod os. Vi så mange subsistensløse ligge på bænkene i parken lige overfor – en voldsom kontrast, men USA er jo kontrasternes land. Mens vi havde været væk, var Hanne gået en tur for sig selv. Da hun ikke kom tilbage som forventet, begyndte Keld at blive nervøs, for han vidste aldrig, hvad hun kunne finde på med den nysgerrighed hun besad, men pludselig dukkede hun op, og så kunne vi komme videre. Der var længere til Dulles Lufthavn, end vi havde forventet, så det kostede os 33 $ for de 40 km. – værsgo’ og spis! Lidt efter sad vi i flyet til Denver. Kl. 17 Denver tid landede vi (20 min. før planen). Vi hentede bagagen men kunne ikke finde Jacque, som skulle komme og hente os. Vagn og jeg efterlod de andre udenfor i i 40 graders varme, og så gik vi ellers rundt i den store lufthavn og ledte. Så skete der det, at vi efterlyste hinanden i højttaleren samtidig, så vi troede, at det var vores egen efterlysning, vi hørte. Det føltes som om vi gik rundt i lang tid, men pludselig fik Vagn øje på Jacque, som var på vej op ad en rullende trappe. Jeg har aldrig set nogen løbe så hurtigt den forkerte vej på en rullende trappe. Gensynsglæden var stor. Vi havde aldrig mødt Dick, og deres to drenge var også med, Jeff på 4 år og Tim på 8 år. De kørte i en stor Van, som vi alle 9 kunne være i plus al bagagen. Hjemme på deres terrasse på 6428 Ingalls Ct. i Arvada fik vi kolde øl og drinks, og det var lige hvad vi trængte til. Vi gik alle i bad og skiftede til shorts. De havde varmerekord i den periode med 100 grader Fahrenheit. Der var ingen optræk til aftensmad – amerikanerne er jo meget afslappede på det område. De spurgte os, om vi var sultne, men det var vi for beskedne til at sige ja til, og i den varme havde vi heller ikke behov for en masse.  Først kl. 21 var der optræk til noget i form af, at Jacque hev et kæmpe fad ud af køleskabet med pålæg, ost og grøntsager, og så kunne hver især smøre sig en sandwich og tage den med ud på terrassen. Vi havde gaver med, og det var en stor succes: to lysestager med lys, Gammel Dansk, taske, som mor havde syet, Karolines Kogebog på engelsk, to bøger om Danmark, papirklip, lommetørklædeetui, to store kasser Lego, H.C. Andersens Eventyr på engelsk og kassettebånd med dansk musik. Dick vidste ikke, hvordan man drak Gammel Dansk, så han lod bare flasken gå rundt, så alle kunne tage en mundfuld. Men hvordan skulle han også vide det.  Hanne og Keld sov i et meget mørkt værelse i kælderen, ”bunkeren” kaldte vi det, Lars sov på en madras på gulvet i det store legerum i kælderen, og Vagn og jeg sov på en sovesofa i stuen. Hver morgen kl. 7.30 kom Jeff på 4 løbende ind i stuen og råbte: ”Wake up, you guys!” Han var sød men lidt hyperaktiv, og han gik tit sin far på nerverne. Dick havde været med i Vietnamkrigen, hvor han havde været nødt til at skyde for at overleve, og der var ingen tvivl om, at han havde psykiske mén fra den tid. Det resulterede i, at han kunne råbe utrolig højt og ubehersket ad børnene, hvis de irriterede ham. Og det gjorde de ofte, især Jeff. Vi havde 5 fantastiske dage hos familien i Denver, og de gjorde alt for os. Det, der var så befriende, var, at de ikke stod på hovedet i køkkenet for at lave mad til os. Vi jokede bagefter med at sige, at den eneste mad, de lavede i køkkenet, mens vi var der, var at koge et æg. Forklaring følger: Vi spiste enten ude, havde pålæg og brød med på picnic eller grillede, og morgenmaden bestod af en kæmpeæggekage, som de havde lavet i forvejen. Den dag, vi skulle på picnic, manglede der et kogt æg, så da måtte der en gryde på for at koge ét æg.  Vi oplevede meget, bl.a. var vi inde og se ”The Mint”, Capitol, Civic Center og the Mall, og mændene og drengene var ude og spille lidt golf på en golfbane. En dag startede vi om morgenen på en udflugt op i bjergene, hvor vi spiste medbragt morgenmad ved Clear Creek, et skønt sted. I Blackhawk var vi inde og se et gammelt hus, som var restaureret med originale ting fra guldgravertiden, bl.a. et klaver med ægte elfenbenstangenter, som kustoden på det strengeste understregede, at børnene ikke måtte røre. Jeff var helt ustyrlig, og kustoden tabte flere gange tråden på grund af dette. Højdepunktet var Central City, en gammel guldgraver-by, som er meget turistet men sjov. Især syntes mændene, at det var spændende at putte dollarsedler ned i barpigernes kavalergange, når vi sad på de udendørs beværtninger og nød en øl til tonerne af fed 60’er musik. Vi sluttede dagen af helt på toppen af Mt. Evans i 4 kilometers højde. Her blev vi kølet ned fra de 40 grader Celcius, der fortsat herskede i Denver. Lars var meget fascineret af bjergene. På vej ned så vi rådyr, elsdyr og en enkelt bjergged."}, {"type": "figure", "caption": "", "page": 114, "file": "assets/images-bog2/p114_01.jpg", "dim": [1174, 784]}, {"type": "figure", "caption": "", "page": 115, "file": "assets/images-bog2/p115_01.jpg", "dim": [472, 787]}, {"type": "para", "text": "Om søndagen stod vi tidligt op og klædte os pænt på, for vi skulle alle i kirke. Dick og Tim skulle være kirketjenere i deres egen kirke, mens vi andre kørte til Emmaus Lutheran Church, som var min gamle skole og kirke. Det var sjovt for mig at se mit gamle nabolag, og jeg var glad for at vise det til Lars. Vi fandt 2837 Federal Blvd., hvor jeg havde boet, men jeg var skuffet over at se, hvor misligholdt det var. Det var sjovt at se skolen igen – meget lidt havde ændret sig. Præsten kendte jeg ikke, men han var vældig rar og gav Lars en sølvmønt. Vi fandt vores gamle klasseværelse, hvor der var gang i søndagsskole for voksne. Døren stod på klem, og jeg kunne se, at det var min gamle matematiklærer, Mr. Rathe på 76, der forestod søndagsskolen. Jacque gik ind og hentede ham, og da han så mig, fik jeg en kæmpe omfavnelse. Det var 13 år siden, vi sidst havde set hinanden. Senere fik jeg et knus af Mrs."}, {"type": "para", "text": "Rathe, og jeg hilste på andre bekendte lærere, forældre til børn jeg havde gået i klasse med, som huskede mig, og jeg mødte også en fyr fra min klasse, Gary Cupp, som fortalte, at han var ugift skuespiller og arbejdede i en restaurant. Vi var nedenunder og se kantinen, spisesalen og køkkenet, og alt så ud som i 1963. Jeg hilste også på Jacques mor, Bette, en flot dame på 70 år, som lever den dag i dag. Under gudstjenesten blev Jeff pacificeret med to poser slik, men alligevel skulle han tisse midt i det hele. På vej hjem i bilen fik han ros for at have været ”a good boy in church”! Præsten startede med at nævne mit navn og byde mig, min familie og mine venner velkommen, og vi skulle rejse os op, så alle kunne se os. Bagefter talte vi med mange mennesker udenfor, og Hanne og Keld fik også en vældig sludder med nogle af kirkegængerne. Efter kirke tog vi på picnic med mad fra KFC, som vi spiste tæt på Buffalo Bills grav. Jeff skulle igen tisse, hvortil Dick sagde: ”Go wet a bush”, hvilket knægten gjorde, hvorefter han fik skældud. Det var nu heller ikke nemt at være lille Jeff. På museet købte vi to Davy Crocket huer til Jeff og Tim, og det var alle pengene værd at se deres ansigter, da de fik huerne. Videre til red Rocks Theatre, hvor der er en stor amfiteaterscene til koncerter. På vej ned så vi dinosaurusfodspor, hvilket var stort for Lars."}, {"type": "para", "text": "Vi havde erklæret, at vi 5 ville give middag den sidste aften, og det skulle være et fint sted. Det blev det også, nemlig Brittany Hill, en restaurant som Svend Sønderup havde anbefalet. Jacque trængte til en aften uden Jeff, så han havde barnepige, men Tim var ”a big boy”, som skulle have lov at komme med, så han følte sig virkelig stor. Vi fik suppe, salat, tournedos med bagt kartoffel, og drengene fik kylling og resten med hjem i en ”doggy bag”. Det var en dejlig aften, hvor vi nød kaffen udendørs med udsigt over Denver ”by night”, en dejlig afslutning på nogle spændende dage. Jeg var jo også kommet for at hente min arv efter Margaret. Om fredagen havde jeg været oppe på advokatens kontor, men han kunne meddele mig, at Margarets søster Agnes havde mine penge, 570,21 $ (1 % af Margarets formue). Agnes havde skrevet til mig, at hun ville give middag. Det blev senere ændret til morgenmad for så igen senere at blive aflyst, da hun skulle noget andet. Samtidig havde hun meddelt, at jeg kunne hente pengene søndag kl. 17.15. Lars, Vagn og jeg var på pletten til tiden, dvs ved Margaret og Martinus’ hus på Grove St., hvor en anden søster Rose nu boede. Der fandt vi også Agnes. Vi snakkede med dem under en time uden at få så meget som et glas vand, og temperaturen var stadig 40 grader. Det var helt tydeligt, at hun kun var ude på at få os ud af huset igen. Alt så ud, som da Margaret og Martinus boede der, bortset fra at der nu var endnu mere rodet. Der flød med blade, aviser og papirer overalt. Vi havde købt en buket blomster til Margaret og Martinus’ grav, og da de ligger på en kæmpestor kirkegård, havde vi brug for en til at vise os, hvor de lå. Agnes kørte i sin egen bil derud, for så var hun jo fri for at have os med tilbage. Da man ikke er vant til at sætte friske blomster på gravene i USA, havde hun medbragt en plastikdunk med vand, så hun havde da vand i huset. Gravstedet var en metalplade på en græsplæne, og det var lidt vemodigt at være der, men jeg var glad for at kunne sætte blomster til de to mennesker, som havde betydet så meget for mig, og uden hvem mit liv nok havde formet sig anderledes. På vej hjem kørte vi ind og fik den største cola, vi kunne få. Jeg tror aldrig, jeg har været så tørstig. Jacque og Dick var gymnasielærere på hver sin High School, Dick på Columbine High, som flere år senere blev udsat for det største skoleskyderi i USA’s historie. Kort derefter gik Dick på pension. Han var geolog og samlede på sten, og inden vi rejste, forærede han Keld, Vagn og Lars tre plader med forstenede fisk, som var 230 millioner år gamle. Senere, når jeg besøgte dem, og han skulle hente mig i lufthavnen, sagde han altid om min kuffert: ”What are you carrying? Rocks?”"}, {"type": "figure", "caption": "", "page": 116, "file": "assets/images-bog2/p116_01.jpg", "dim": [1179, 784]}, {"type": "para", "text": "Mandag den 10. juli sagde vi farvel og kørte videre i vores lejede sølvgrå Buick. Det var for mig en vemodig afsked, og Jacque og jeg tudede om kap. Jeg vil aldrig glemme de ord, hun sagde og måden, hun sagde dem på: ”You are my good friend”. Heldigvis fik vi lov til at gøre gengæld mange år senere, nemlig i sommeren 2009, hvor de var hos os i en uge, men før den tid fik jeg mulighed for at besøge dem nogle gange, enten privat eller i forbindelse med mit arbejde."}, {"type": "para", "text": "Herefter gik turen til Colorado Springs og Taos, New Mexico, hvor vi besøgte en indianerlandsby, videre til Santa Fe, Grants og Flagstaff, hvor mændene købte cowboyhatte og alle købte t-shirts. På denne tur var t-shirts med motiv og navn den store dille, og vi havde rigtig mange med hjem af slagsen. Af store naturoplevelser kan nævnes den Malede Ørken, den Forstenede Skov og Grand Canyon. Det er svært at finde de rigtige ord til at beskrive et så enestående stykke natur, et af denne verdens vidundere."}, {"type": "figure", "caption": "Familien Will klar til at gå i kirke", "page": 117, "file": "assets/images-bog2/p117_01.jpg", "dim": [1171, 784]}, {"type": "para", "text": "Vi boede oftest på dejlige moteller med swimmingpools og ismaskiner, og ofte købte vi mad og spiste på værelserne. Hvis vi gik ud og spiste, var det ofte på Denny’s."}, {"type": "para", "text": "Turen gik videre til Hoover Dam og Las Vegas, hvor vi boede på et af de mindre hoteller, The Algiers, på The Strip. Her var varmen også overvældende, og selv om aftenen var der over 30 grader. Om aftenen spiste vi stor buffet på Circus Circus til 3,89 $ inkl. drikkevarer. Det var et sandt gedemarked men sjovt at opleve. Fornøjelsen med at spille i spilleautomater blev dog kort, for Lars måtte ikke være med, men da vi ikke er de store spillefugle, gjorde det ikke så meget. Vi nød lysreklamerne og nogle gratis shows, inden vi gik i seng. Næste dag forlod vi den larmende by og kørte videre mod Los Angeles. Her fandt vi et lækkert motel med pool og boblebad, men nu trængte vi også til at slappe af. Det var her, vi første gang stiftede bekendtskab med drive-in burgerbarer."}, {"type": "para", "text": "Overfor var der en Carl’s Jr. burgerbar, og når vi kiggede derover, så det grangiveligt ud, som om kunderne talte med et skab. Senere fandt vi ud af, at det var en drive-in burgerbar. Men vi brugte herefter talemåden: ”Er der nogen, der har talt med skabet i dag?” Vi besluttede os for at blive der et par dage, og det gav Lars, Vagn og mig muligheden for at køre til San Diego og opleve Sea World. Hanne og Keld ville have en slapper, så vi kørte alene tre til San Diego. Det var faktisk skønt at være alene lidt, men ikke fordi vi på nogen måde var trætte af deres selskab. Vi havde bare behov for at være os selv, og det havde Hanne og Keld garanteret også. Sea World var en kæmpe oplevelse. Vi så 7 shows og mange udstillinger, og jeg husker, at jeg under det første show, hvor der blev spillet Beach Boys musik, fik kuldegysninger og tænkte: ”Nu er vi godt nok langt hjemmefra”."}, {"type": "para", "text": "I Los Angeles var vi i Universal Studios allesammen – lige noget for Lars, hvorefter turen gik videre til Santa Barbara og den danske by Solvang. Her boede vi på Hotel Kong Frederik, hvor vi også skulle komme til at bo 8 år senere. Lars var altid den første i poolen, og denne dag gik vi andre på Mortensens Konditori og spiste danske tørkager. Byen har bindingsværkshuse med stråtag, en dansk kirke, en mølle, danske flag overalt, en statue af H.C.Andersen og plastikstorke på taget, men få taler dansk. Der er dog en hyggelig atmosfære i byen, og der er rart at være. Derfra gik turen videre til San Simeon, Big Sur og Redwood National Park med kæmpe træer, der var over 2000 år gamle. Næste stop var San Francisco, hvor vi var i 4 dage og så næsten alt, hvad der er at se der. Vi havde ikke forestillet os, at der tre måneder senere skulle komme et jordskælv. Vi boede lidt uden for centrum i et negerkvarter, så vi sørgede for at holde dørene låst. Det hændte, at vi boede på samme værelse alle 5, og dette var tilfældet her. Den første nat vågnede vi ved, at der var nogen, der bankede på. Keld sprang ud af sengen og spurgte, hvem det var, mens Hanne råbte: ”Du lukker ikke op – du lukker ikke op!” Keld kiggede ud af spionhullet og fandt ud af, at det var en familie, der havde taget fejl af værelserne. Hanne, som var nysgerrig, ville også kigge ud men var for lille til at kunne nå, så Keld måtte løfte hende, så hun kunne få sin nysgerrighed stillet. Det så virkelig morsomt ud. Keld var ikke uden humor. Næste dag ringede de hjem til Hannes mor, naturligvis fra en telefonboks, og de undrede sig over, at de kunne snakke så længe uden at skulle putte penge i, men til slut bad telefondamen dem dog lægge 6 $ i. Det gjorde de, men pengene kom retur, så de tog pengene og gik. Om natten ringede telefonen på værelset. Keld tog den, og det viste sig at være forkert nummer, men da vi spurgte ham, hvem det var, sagde han: ”Nå, det var bare telefondamen, der ville have sine penge”."}, {"type": "para", "text": "En dag kørte vi op i Napa Valley vindistriktet og besøgte en del vingårde, bl.a. Robert Mondavi, og det er blevet en af vores yndlingsvine. Klimaet var og er skønt i det område, og det, der var hyggeligt var, at man nogle steder kunne købe en flaske vin og sidde og nyde sin medbragte mad, eller man kunne købe brød og ost til vinen."}, {"type": "figure", "caption": "Til højre: Alice, Gordon, Hanne, Keld, Merete, Vagn & Olga", "page": 118, "file": "assets/images-bog2/p118_01.jpg", "dim": [779, 519]}, {"type": "figure", "caption": "Kirsten, 4 børnebørn og Lars", "page": 118, "file": "assets/images-bog2/p118_02.jpg", "dim": [640, 535]}, {"type": "para", "text": "Vi havde aftalt med Alices søster Kirsten, at vi skulle komme til Loomis og besøge dem nogle dage. Vi ankom den 24. juli om aftenen og gik straks ud for at spise pizza sammen med resten af familien: Kirsten, Gordon, datteren Anne Marie og dennes to døtre, og Olga på 93 år, som havde boet hos Kirsten i 9 år, siden hendes hus brændte. Olga var emigreret fra Bornholm i 1925 og var en lille vims dame, som denne aften ikke gik af vejen for at nedsvælge nogle øller, så hun måtte have en hjælpende hånd af Lars ud til bilen. Vi sov alle 5 hos Kirsten og Gordon i to nætter, og Lars hyggede sig med Kirstens 4 børnebørn, alle piger, hvoraf nogle var på hans egen alder. Den anden aften holdt vi en dejlig havefest, hvor også datteren Alice og Mrs. Torris kom. Der blev stegt en hel kalkun i kuglegrillen, og vi sad ude i mørket og snakkede og pjattede til langt ud på aftenen. Der var en meget afslappet atmosfære, og folk gjorde, hvad de havde lyst til. Børnene så TV sammen med svigersønnerne, sønnen Peter og dennes kæreste, så dem så vi ikke meget til, men vi kunne heller ikke være flere omkring havebordet. Vi havde gaver med: tre flasker vin til Kirsten og Gordon fra Napa Valley, 5 $ til hver af børnebørnene, Alice, Anne Marie og Mrs. Torris fik lommetørklædeetuier, som mor havde syet, Mrs. Torris og Kirsten fik mit hjemmelavede papirklip, og Olga fik en bog om Danmark. Næste morgen skulle vi aflevere bilen i San Francisco Lufthavn og flyve til Orlando i Florida."}, {"type": "para", "text": "Vi havde været på farten i 4 uger, så alle var ved at være lidt møre, men humøret var stadig højt det meste af tiden. Hanne og Keld besluttede sig for at skippe Disney World, så vi tre drog af sted alene. Vi havde den fordel, at Vagn og jeg havde været i Disneyland i LA, så vi kendte nogle af forlystelserne og kunne derfor vælge de bedste ud, bl.a. ”Pirates of the Caribbean”, ”Jungle Cruise”, ”Mission to Mars”, ”Skyway”, ”Big Thunder Mountain Railroad”, ”20,000 Leagues Under the Sea”, ”Magic Journeys”, ”Walt Disney World Railroad”, ”Tom Sawyer Island” og ”Grand Prix Raceway”, og Lars blev fotograferet sammen med Chip (eller også var det Chap) og Mickey Mouse. Paraderne kl. 15 og kl. 21 var fantastiske, for det var året, hvor man fejrede Mickeys 60 års fødselsdag. Vi var også inde og se en film i 3D, hvilket var en stor oplevelse. Vi forlod parken ved 22-tiden og nåede lige at få det flotte fyrværkeri med. Det havde været en fantastisk dejlig dag. Selvom vi først kom i seng kl. 1.30, var vi friske til at tage i Epcot Center med Hanne og Keld næste dag på vores 16-års bryllupsdag. Vi brugte meget af dagen i Showcase, hvor man går fra land til land og oplever en hel masse forlystelser og shows, men højdepunktet var nok, da Disney-bussen kørte ind på showpladsen med alle figurerne, og der var musik, sang og dans af dem alle. Det forstår amerikanerne. Bagefter kunne man få autografer og få taget billeder sammen med figurerne. Det lykkedes Lars at få 12 autografer, bl.a. Mickeys og Minnies, så dagen var reddet. Dagen sluttede med et flot lasershow kl. 22, og Vagn gav mig i dagens anledning en rose med lys i. Næste dag lejede vi en rød Lincoln og kørte til Kennedy Space Center, hvor vi var på en 2-timers bustur rundt i området, bl.a. til affyringsramperne, forskellige raketter og rumkapsler og til stedet, hvor astronauterne træner. Vi så også film om nedtællingen til Apollo 11 landingen på månen 20 år tilbage. De sidste dage af ferien tilbragte vi i Fort Lauderdale. Lars boltrede sig i poolen, og vandet ved stranden var ca. 30 grader, noget så lækkert. Da mit nye Visa kort hele tiden blev afvist, måtte vi klare os med de kontanter, vi havde tilbage, samt Kelds Eurocard. Vi købte et par Reebok støvler til Lars for de sidste penge. Dem var han rigtig glad for."}, {"type": "figure", "caption": "", "page": 119, "file": "assets/images-bog2/p119_01.jpg", "dim": [609, 894]}, {"type": "para", "text": "Vi havde gaver med hjem til familie og venner, og 19 t-shirts til os selv, foruden skjorte, kjole, shorts, kasket, 17 nøgleringe, som Lars samlede på og skildpadder, som Vagn samlede på, smykker, parfume og meget, meget mere."}, {"type": "para", "text": "Den 31. juli fløj vi fra Miami over New York hjem. Per havde igen reserveret billetter til os på Business, så det var vild luksus. Da vi lettede fra New York, fældede jeg en tåre, idet jeg kastede et sidste blik på millionbyen. Nu var denne dejlige ferie slut, og jeg skulle forlade mit andet fædreland. Der føler jeg mig hjemme, folk jeg møder er venlige og interesserede, alt kører på skinner, og i det land har jeg min gode veninde Jacque."}, {"type": "para", "text": "I Tirstrup gik vi gennem rusk og regn ind i ankomsthallen, hvor Pia og Sigrid (Hannes mor) kom løbende i sidste øjeblik. Karen Lis og Finn havde kørt vores bil derud, så vi skyndte os at komme af sted til Spørring, hvor Hanne og Keld gav kaffe ovenpå en fantastisk ferie."}, {"type": "para", "text": "I Spørring øsede det også ned. Grete og Alice havde sat små flag udenfor, stillet blomster frem, lavet tærte og jordbærgrød, og Klaus og Rasmus kom ud med flag og skralder i rødt og hvidt tøj og gav os en knuser. Mor havde sendt blomster igennem Alice. Det var sødt af dem alle, og det varmede. Senere snakkede vi med hele familien i telefonen, og nogle af naboerne kom forbi. Der er nu også mange søde mennesker i Danmark, og det var dejligt at se dem alle igen."}, {"type": "para", "text": "Den 4. august fik Vagn fjernet to store ”mus” i højre albue på Ortopædisk Hospital. Han startede først på arbejde igen den 28. august efter at have holdt fri i 9 uger."}, {"type": "para", "text": "To måneder senere kom jordskælvet i San Francisco."}, {"type": "para", "text": "Få dage før vores USA-rejse, den 24. juni, var bedstefar blevet indlagt på sygehuset, men da det ikke lod til at være noget alvorligt, var der ingen grund til at lave om på ferien. Det havde vi afklaret med farmor. Et kort øjeblik fik vi dog et sug i maven på hotellet i New York den første dag, da der lå en besked til os. Kunne det være noget med bedstefar? Heldigvis var det kun en besked fra hotellet omkring betaling. Han blev heldigvis udskrevet kort tid efter og havde det fint, da vi kom hjem igen."}]}, {"title": "Udflugter", "blocks": [{"type": "para", "text": "Som sagt var vi meget sammen med Tage, og det var da også ham, vi tog på tur med fire dage i forbindelse med Grundlovsdag og Pinse i 1981, hvor Lars var 3 år. Turen gik til Henne Strand og Fanø, og vi havde i forvejen lejet os ind i ferieboliger begge steder. Den første aften kunne Lars slet ikke forstå, at vi ikke skulle sove i vores egne senge, men han indrettede sig hurtigt og nød at være sammen med onkel Tage. Under turen kunne han sige navnene på alle de biler, vi mødte, også hvis der kom en bil af samme model som onkel Tages. På Fanø var vi på restaurant lørdag aften, og da vi skulle betale, fik Lars lov til at gå op til servitricen med pengene (det har sikkert været en check dengang). Hun kunne ikke stå for den lille gut, og hentede et æble til ham. Lars tog imod det med følgende bemærkning: ”Er det skyllet?” Servitricen sagde: ”Ja, men jeg gør det lige igen”. Det morede vi os meget over, og Lars’ spørgsmål blev for eftertiden brugt, hver gang vi spiste et æble. Da vi 2. pinsedag skulle med færgen hjem, holdt Vagn på, at vi skulle skynde os at blive færdige og komme til færgelejet. Tage og jeg var derimod enige om, at det da ikke hastede, men Kloge-Åge havde ret, og vi kom til at holde flere timer ved færgelejet, da alle turisterne skulle hjem efter den forlængede weekend. En anden weekendtur, som jeg tydeligt husker, fandt sted midt i september 1983 i et sommerhus i Hou i Nordjylland. Mors yndlingskusine Lisbeth og dennes mand Bent havde et varmt venskab med mor og far. De boede i Göteborg og havde en søn, Jesper, som var politibetjent, og en datter Lotte, som havde en datter på Lars’ alder, Erika. Mor og far havde været med til Jespers bryllup, men ægteskabet havde ikke holdt. Faderen til Erika var heller ikke mere inde i billedet, men Lotte havde en kæreste Jesper, mor, mig, Lisbeth m. Lars og Erika, Lotte+ kæreste, Bent & far med. Vi var altså 9 voksne og 2 børn, der mødtes til familietræf den weekend, og det skulle vise sig at blive meget festligt. Lørdag eftermiddag fik vi besøg af Lisbeths søster Lissie og dennes mand Arvid. Lissie var uhelbredeligt syg af kræft, og de måtte da også tage hjem efter kort tid, da Lissie efter et toiletbesøg var begyndt at bløde fra underlivet. Hun blev begravet på min fødselsdag den 12. november samme år. Oven på dette triste indslag kommer vi så til det mere muntre, for mor havde lavet dejlig kyllingegryde til om aftenen, og vi fik selvfølgelig vin til maden, og derefter drinks og cognac til kaffen. Stemningen var rigtig god, og vi havde det sjovt."}, {"type": "figure", "caption": "", "page": 120, "file": "assets/images-bog2/p120_01.jpg", "dim": [1009, 699]}, {"type": "para", "text": "Højdepunktet var, da far, som normalt ikke havde en tone i livet og aldrig sang med juleaften, rejste sig og sang første vers af den svenske nationalsang. Der var ikke et øje tørt. Det viser bare igen, hvor intelligent, han var. Ingen af os kunne teksten til den sang, men han havde hørt den nogle gange og kunne huske den, selv i beruset tilstand. Jeg tror ikke, at far kom op i den øverste køje den nat. Bent er for længst død, men Lisbeth bor stadig i Göteborg og ringer nogle gange til jul, når hun har modtaget mit julebrev. Hun er den samme at snakke med som altid, men jeg tror, at hun er ensom. Hun foreslog for nogle år siden, at vi skulle gentage succesen med weekendturen, men jeg lod hende forstå, at det ikke kunne lade sig gøre fra vores side, og Per, som ikke var med i 1983, var heller ikke interesseret. Desuden var det på det tidspunkt, hvor Marianne og Per var ved at købe hus i Danmark, og vi skulle i gang med at bygge, så det blev aldrig til noget. Vi ville heller aldrig kunne gentage succesen fra dengang uden tre af de vigtigste personer, som ikke er her mere. Det ville være for trist."}, {"type": "para", "text": "I mange år var der tradition for at mødes i Vagns fars familie 2. pinsedag til familietræf. Det foregik som regel i Solsbækhytten i Sæby, og hver især havde deres egen mad med. Var der fint vejr, spiste vi udenfor, men regnede det, var der god plads i hytten til de ca. 90 familiemedlemmer, vi som regel var. Jeg har noteret, at vi deltog i 1983, 1986 og 1987. I 1985 blev familiefesten henlagt til den 25. oktober i Hørmested Forsamlingshus som en aftenfest med spisning og dans bagefter. 80 personer var mødt op."}]}, {"title": "Kultur", "blocks": [{"type": "para", "text": "Vi var nok ikke særligt kulturelle i 80’erne, men det blev da til nogle få koncerter. Vi var to gange til Roger Whittaker koncert sammen med Karen Lis og Finn i 1984 og 1989. I 1989 var vi til Wienerkoncert i Musikhuset sammen med Hanne og Keld. Samme år i januar var vi til Wienerbal i Ålborghallen. Det var noget af et tilløbsstykke med Børge Wagner, Ulrik Cold og Tove Hyldgård. Vi var et helt bord fra Svenstrup, og vi havde det fine tøj på. Jeg havde lang kjole på, men det var før Vagn fik smoking, så han havde sorte bukser og en sort velourjakke på samt butterfly. Der var mange i smoking, og nogle af damerne havde sågar handsker og hatte på, bl.a. Bente Ejlersen, som var der sammen med sin mand Flemming. Der var virkelig stil over den aften, og vi fik danset meget, også wienervals. Ved hver kuvert lå der et balkort, som man kunne anvende. Da vi jo var venner med Ruth og Villy Morgenstjerne, og Villy spillede i Centralværkstedets Orkester, CO, var vi også til tider til CO koncerter. Det var meget fornøjeligt, og vi lærte også nogle par at kende derigennem."}, {"type": "para", "text": "I juni 1981, samme weekend som Doris og Poul Erik startede deres ombygning, var vi til halfest i Svenstrup, hvor Birthe Kjær optrådte. Samme år den 4. juli, hvor Vagn arbejdede på omtalte ombygning, kom mor, far og mormor og hentede mig i Svenstrup, hvorefter vi kørte til Rebild-fest, hvor hovedtaleren var Pat Boone, så vi så både Pat Boone og Dronningen, som også var der. Af lokalkultur kan nævnes dilettant hvert forår i Spørring, som vi troligt troppede op til, enten lørdag eller tirsdag aften. Lørdag aften var der dans bagefter, mens tirsdag var mere beregnet på børn og pensionister. Brugsens generalforsamling var ofte også et tilløbsstykke med smørrebrød, vin og dans en onsdag aften, og da det var gratis, kom der rigtig mange."}, {"type": "para", "text": "1981 var også året, hvor alle sad klæbet til fjernsynet og så Matador, som blev genudsendt i 1985 og flere gange senere. I 1981-82 så alle Dallas på TV, som i 1984 blev afløst af Dollars."}]}, {"title": "Vores biler", "blocks": [{"type": "para", "text": "Samme år som Lars blev født, købte vi en beigefarvet Volvo 242 Lux (den 17. marts) og gav 22.000 kr. i bytte med den karryfarvede ditto, men allerede den 27. december samme år solgte vi den og købte en rustfarvet Volvo. Vi var gået hen og blevet Volvo-fans. Vi havde også en kort periode to biler, hvor bil nr. 2 var en gammel Mascot (6. marts 1978), som den 17. februar 1980 blev afløst af en Volvo varebil fra 1971 til 3.000 kr. Vi fandt dog hurtigt ud af, at vi sagtens kunne klare os med én bil. Den rustfarvede Volvo blev den 14. maj 1982 afløst af en ny havblå Volvo 242, så nu var det slut med at køre i brugte biler. Samme år i september købte vi trailer. Helt slut var det dog ikke med gamle biler, men den næste Volvo, som var rød, var kun 3 mdr. gammel og havde kun kørt 10.000 km. Vi købte den i januar 1987 og gav 97.000 kr. i bytte. Den havde vi i 7 år, og det er den bedste bil, vi nogensinde har haft. Vagn nærmest græd den dag, vi solgte den, og han påstår, at han en dag holdt ved siden af den i Aarhus, for der gik ikke så mange af slagsen, og det er jo klart, at enhver mor kan kende sit barn. Han taler stadig om den."}, {"type": "figure", "caption": "", "page": 122, "file": "assets/images-bog2/p122_01.jpg", "dim": [1176, 779]}]}, {"title": "Fester og gæster", "blocks": [{"type": "para", "text": "Vi har altid haft en stor omgangskreds og mange gæster, men det er nok noget, vi har arvet hjemmefra, for begge hold forældre nød stor selskabelighed og var gode værter hver især. Der var aldrig nogen, der gik ud af deres døre uden at være blevet budt på noget, ja så skulle det da lige være Jehovas Vidner, men de kom nok slet ikke ind. I dag kan jeg dog ikke overskue de store selskaber, som jeg kunne én gang. Som et eksempel kan nævnes, at vi den 19. maj 1982 havde inviteret 25 gæster, bl.a. 14 overnattende vendelboer, og jeg lavede selv al maden: Fiskecocktail af selvfangede fisk, indbagt mørbrad og ananasfromage. Det var i den periode, hvor Per boede hos os, for han og Alice var i køkkenet den aften. Tre dage senere havde vi igen 25 gæster, bl.a. mor, far, Per, Jette, Vibeke, Elbo, familien fra Svenstrup, Alice og Reinholt og andre naboer. Jeg havde igen lavet al maden, og denne gang havde jeg Anna-Lise Grosen i køkkenet, som også var min rengøringshjælp en gang om ugen og havde været det siden januar 1978. Vi havde ryddet stuen i forbindelse med de to fester, for der skulle jo også være plads til at danse. Jo, vi gik til den, når der skulle festes, og folk morede sig."}, {"type": "figure", "caption": "", "page": 123, "file": "assets/images-bog2/p123_01.jpg", "dim": [535, 812]}, {"type": "para", "text": "Vagn fyldte 40 år den 12. august 1988. Om morgenen tidligt blev der ringet på døren, og udenfor stod der 16 gæster med en stor oppustet lagkage i plastik. De havde selv kaffe og morgenbrød med, så det var ingen sag at dække op til 19 mennesker. Det blev efterhånden meget brugt at holde surprise morgenkaffe hos runde fødselarer, så det kom nok ikke helt bag på os. Dagen efter, om lørdagen, havde vi inviteret vores familier (16 personer) til frokost i Papegøjehaven i Aalborg med efterfølgende kaffe i to hytter på den nærmeste campingplads. Vi havde forinden solgt vores campingvogn, så vi måtte ty til hytter i stedet for. Vejret var desværre ikke det bedste, så det var lidt koldt, men de mest barske sad ude og drak kaffe. Vi blev dog bagefter enige om, at det skulle være sidste gang, vi gjorde noget sådant, for stemningen var ikke den allerbedste. Det kunne nogenlunde gå på restauranten, men bagefter var vi delt op i to grupper, de barske, som sad ude, og de mindre barske, som sad inde i den meget primitive hytte. Til sidstnævnte hørte vores forældre, og de skulle naturligvis ikke sidde alene, så jeg satte mig ind til dem, men jeg tror simpelthen, at det var savnet af far, der gjorde, at mors humør ikke var godt."}, {"type": "figure", "caption": "", "page": 123, "file": "assets/images-bog2/p123_02.jpg", "dim": [697, 697]}, {"type": "para", "text": "Mor var ofte toneangivende for stemningen, og hvis hun var i dårligt humør, smittede det af på mig. Vi savnede alle far, men det var ærgerligt, at det skulle gå ud over denne dag, som havde kostet os både mange penge og kræfter at arrangere."}, {"type": "para", "text": "Man må sige, at Vagn blev fejret med manér, for den efterfølgende fredag var vi 24 til ta’ selv bord om aftenen på Østervang 25, denne gang venner fra Spørring og omegn."}, {"type": "para", "text": "Pernille 2 år på morgenvisit"}, {"type": "para", "text": "Jeg fyldte 40 år den 12. november 1989, en søndag. Mor kom om torsdagen og hjalp med forberedelserne, og lørdag den 11. november var vi 20 piger til frokost. Vi havde lavet al maden selv, og Tage, Poul Erik og Vagn var i køkkenet. Der var fire sange, bl.a. én hvor jeg efter hvert vers blev udstyret med forskellige effekter, så jeg til sidst lignede en gammel kone iført en gammel frakke, med en gammeldags taske over armen, store briller og friluftsgebis. På selve fødselsdagen var der åbent hus, hvor der kom 20 uindbudte gæster mellem kl. 10 og 18. Om aftenen havde vi mor med på Bøf España. Jeg syntes, det var hårdt at fylde 40 år, fordi jeg i den periode havde en tennisalbue, bronkitis og blærebetændelse. Jeg tænkte: ”Er det sådan at fylde 40?”"}, {"type": "para", "text": "Samme år som Vagn blev 40, var Poul, vores genbo, også fyldt 40 den 20. april. Han holdt sin fødselsdag i Ødum Forsamlingshus, og til den lejlighed havde Alice og jeg skrevet en sketch, som vi opførte til stor morskab for gæsterne og vist også for fødselaren. Vi havde øvet os meget forinden, og vi opførte den helt uden manuskript og lidt improviseret, hvilket gav en god effekt. I sketchen er vi klædt ud som to gamle sladderkællinger, der mødes foran Pouls hus. Vi havde lånt udklædningstøj hos Spørring Dilettantforening, og jeg havde været inde i en gammel trikotageforretning i Aarhus og købt to par tykke nylonstrømper, som kunne sidde i ål. Jo, vi så autentiske ud med frakke, hat, taske og ål i strømperne. Vi skulle stå og sladre om Poul, og i den forbindelse nævnte vi, at deres have så pæn ud, men det nok var, fordi Ragnhild, Pouls mor, lige havde været der. Sagen var nemlig den, at Ragnhild, når de var på ferie, altid gav hus og have en overhaling, så der var fint, når de kom hjem fra ferien. Vi andre var nok lidt misundelige, for vi boede så langt væk fra vores mødre, at det ikke kunne ske, men selvom vi havde boet tættere på, var det nok ikke sket alligevel. Men Ragnhild var speciel. Hun passede Klaus, inden han kom i dagpleje, og hun passede både Klaus og Pernille, hver gang Grete og Poul skulle noget. Det var aldrig Gretes mor. Og Ragnhild bagte og syltede for dem, vaskede og strøg, så hun var meget flittig. Derfor skreg folk også af grin, da vi nævnte Ragnhild i forbindelse med haven. Vi nævnte også, at grunden til, at Pernille, som var knap 2 år dengang, stadig ikke kunne sige far var, at Poul ikke var så meget hjemme – også dengang arbejdede han meget for sit firma Lyngfeldt. Om Grete sagde vi, at hun var så smart i tøjet, og at Poul købte meget af hendes tøj, når han var ude at rejse eller til fødselsdag. Jo, den sketch indhøstede mange klapsalver, og Lars optog det hele på video."}, {"type": "figure", "caption": "", "page": 124, "file": "assets/images-bog2/p124_01.jpg", "dim": [683, 1015]}]}, {"title": "Kobberbryllup den 28. januar 1986", "blocks": [{"type": "para", "text": "Vi havde nogle få gange været på camping pinsetur sammen med venner fra Spørring, og vi havde døbt vores klub ”Pinsebevægelsen”. Vi havde det altid hyggeligt og sjovt, så hvorfor ikke holde et sammenskudsgilde med pølsebord. Det skulle være hos os fredag den 25. januar, selvom vi tre dage senere kunne fejre kobberbryllup. Men vi skulle have pølsebordet udefra, så vi skulle bare lægge hus til. Foruden os selv var vi: Karen Lis, Finn, Else, Jørn, Anne, Niels, Ruth og Ras. Det blev en sjov aften, hvor flere af de isterninger, der skulle have været i drinksene, endte under bluserne. Ruth holdt sig ikke tilbage, og på et tidspunkt måtte vi op på gæsteværelset og sy hendes hjemmestrikkede bluse, der havde lidt overlast. Vi festede til kl. 5 om morgenen. Om søndagen kom Anne og Niels for at sige tak for sidst, og mens vi sad og drak kaffe, tænkte jeg: ”Her sidder nogle af vores bedste venner, og de skal ikke engang med til vores kobberbryllup”. Men det lå ikke i kortene, for bekendtskabet var ret nyt, og der var ingen, der fandt det mærkeligt, at det kun var Karen Lis og Finn fra det sjak, der skulle med. Da de gik, ønskede de os til lykke med kobberbrylluppet næste dag, vel vidende, at de selv ville være der for at sige til lykke, men det vidste vi bare ikke."}, {"type": "para", "text": "Næste morgen vågnede vi kl. 5 ved en bankelyd og en ringen på dørklokken. Vi skyndte os ud af sengen, tog tøj på og styrtede ud for at lukke op. Udenfor stod vores gæster fra om fredagen sammen med deres børn, og da de begyndte at synge for os, og vi så, at de også havde stillet en halv æresport op med skjold og det hele, kunne jeg ikke holde tårerne tilbage. De havde selv kaffe og rundstykker med. Vi fik hurtigt en dug og nogle kopper på bordet, og så blev der grinet og snakket til kaffen, morgenbrødet og en lille én dertil. De havde en gave med, en meget flot hvid firkantet syltetøjskrukke, som vi stadig har. Grunden til, at de vækkede os kl. 5 var, at de skulle gennemgå samme procedure kl. 6 hos Jette og Leif, som er gift samme dag som os. Senere udviklede venskabet sig endnu mere, og herefter var de altid inviteret med til vores fester."}, {"type": "para", "text": "Vi tog en lille tur på arbejde den dag, vi havde kobberbryllup, for jeg kunne naturligvis ikke aflyse undervisningen på grund af det. Da vi kom hjem om eftermiddagen, kom vores nabo Mary over med en buket blomster. Det var pænt af dem, for de skulle heller ikke med til festen. Det skulle være en ung fest, og vi syntes slet ikke, at Mary og Rasmus passede ind der. Det var noget andet med vores egen familie. Om aftenen havde vi bestilt bord på Spørring Hotel hos Grethe og Egon, for vi skulle prøvesmage menuen til festen, som først skulle holdes den 22. marts, når vejret var bedre. Vi havde en hyggelig aften på Hotellet, dog afbrudt af TV nyhedsudsendelsen om, at Challenger rumfærgen var eksploderet og 7 astronauter omkommet. Derfor kan jeg altid huske datoen for den tragedie. Der var mange forberedelser til festen, selvom den skulle holdes ude. Vi skulle være 58, hvoraf de 23 skulle overnatte. Først var der indbydelserne, der skulle sendes ud. Dernæst ville jeg gerne selv lave en velkomstsang. Jeg var lige begyndt at interessere mig for at lave sange, så det var nok min debut. Vi havde desuden besluttet, at der skulle være en form for præsentation af gæsterne, men de skulle selv stå for den. Vi skrev nogle sjove linjer om hver af gæsterne, og så skulle de selv rejse sig og læse dem op. Desuden var der bordkortene, som også skulle fabrikeres. Det blev papirklip af to katte, der sidder i et hjerte, og farven var min yndlingsfarve på det tidspunkt, nemlig koboltblå. Tre dage før festen var vi til en forældreaften i Klubben, hvor Lars gik. Ved den lejlighed skulle vi se en film, og pludselig under filmen sank Vagn sammen. Filmen blev stoppet og lyset tændt, og der blev ringet efter en ambulance. Da ambulancen kom, var han kommet til sig selv og ville egentlig ikke med, men falckmanden, som sjovt nok var Finns søsters mand Børge, insisterede på, at han skulle ind og tjekkes, og sådan blev det. Heldigvis var der ikke noget galt. Han havde bare fået et ildebefindende på grund af for mange mennesker i et lille lokale. Det har han aldrig haft det godt med. Et øjeblik frygtede jeg, at vores fest skulle aflyses."}, {"type": "figure", "caption": "", "page": 125, "file": "assets/images-bog2/p125_01.jpg", "dim": [774, 1165]}, {"type": "para", "text": "Festen blev en stor succes, ikke mindst takket være orkestret ”Mors Drenge”, som satte liv i kludene. Næste morgen havde vi 23 gæster til morgenmad. Alle vendelboerne havde lejet en bus, så de kørte hjem efter festen."}]}, {"title": "Fars sygdom og død", "blocks": [{"type": "para", "text": "Fra far fik dommen ”uhelbredeligt syg af kræft”, indtil han døde, gik der knap to måneder, som var fyldt med sorg, fortvivlelse og afmagt. For mig døde min far om aftenen den 28. juni 1986, for fra den dato, da han fik dommen, holdt han næsten op med at spise og snakke, men jeg bebrejder ham det ikke."}, {"type": "para", "text": "Far blev fyret fra DLG den 20. maj 1985, men vi fik det først at vide nogle dage senere. Et halvt år forinden havde hans chef holdt en flot tale ved hans 60-års fødselsdag, hvor han i fine vendinger roste ham til skyerne. Hykler! Fyringen tog hårdt på far, og der gik flere dage, før han fortalte det til mor. Han lod i flere dage, som om han tog på arbejde, for han kunne ikke få det sagt. Mor tvang ham derefter til at ringe til os og fortælle det. Det var en svær samtale."}, {"type": "para", "text": "Herefter gik det ned ad bakke med helbredet, men det prøvede han også på at skjule. Efter hans død fandt mor ude i vaskehuset nogle kapsler, som havde indeholdt smertestillende piller. Han havde taget dem mod mavesmerter. Til sidst kunne han ikke holde smerterne skjult længere, men vi troede alle, at det var mavesår. Den 12. juni 1986 havde far en tid til undersøgelse på sygehuset Ålborg Syd. Resultatet var, at de ville have ham indlagt. Jeg tog til Thorshøj sammen med Lars den 25. juni og kørte far til Ålborg Syd dagen efter, om torsdagen, til indlæggelse. I weekenden skulle vi til spisning i Svenstrup hos Doris og Poul Erik, og på vejen derud kiggede vi lige ind til far på sygehuset. Han mente stadig, at det var mavesår, men han var ved godt mod og i godt humør, og vi snakkede og grinede, så alt var vel, troede vi. Under middagen hos Doris og Poul Erik, hvor også Lars var med, blev Vagn kaldt til telefonen. Det var mor, der ringede, og hun var godt klar over, at hun skulle snakke med Vagn og ikke med mig. Da havde de ringet fra sygehuset til hende og fortalt, at far havde kræft i maven, og at de ikke kunne gøre noget for ham. Vi kunne komme og hente ham næste dag. Den besked havde de givet far uden at bede os om at være til stede. Det var utilgiveligt. Den stakkels mand. Da Vagn fortalte mig det, besvimede jeg næsten, og det stak i mit hjerte. Jeg kunne ikke fatte det. Min far skulle dø, og han lå der helt alene uden nogen af os ved sin side. Hvad var det for nogen mennesker, der var ansat på det sygehus? Havde de slet ingen følelser? Vi lod Lars være i Svenstrup og kørte straks hjem til mor, som hun gerne ville. Vi troede, at vi skulle have været ude hos far, men først næste formiddag hentede vi ham, og da var han en slagen mand. Han havde fået et chok over meddelelsen. Men mor var stærk, og hun gav sig til at læse alt om kræft. Der måtte være en metode, der kunne hjælpe far. I den efterfølgende tid var det meget svært at være sammen med far, fordi vi ikke vidste, hvad vi skulle snakke med ham om. Havde han været indelukket før, var han det endnu mere nu."}, {"type": "figure", "caption": "", "page": 126, "file": "assets/images-bog2/p126_01.jpg", "dim": [683, 1012]}, {"type": "para", "text": "Det første, mor fandt på, var at prøve med ændret kost, og hun havde læst om en dame, der hed Julie Vøldam, som holdt kurser om kost. Den 6. juli kom Vibeke og Elbo med mor og far (far kørte ikke mere bil), og vi kørte dem til færgen til Kalundborg, hvor de skulle på en uges helseophold hos Julie Vøldam. Vi benyttede lejligheden til at tage på campingtur med Lars og Thomas til Give, hvor vi bl.a. var i Givskud og Legoland. Det var rart at komme væk fra det hele, men vi ringede hver dag til mor for at høre nyt. Nu var der trods alt et lille håb, troede vi. Ugen efter tog vi på camping i Sæby for at være tæt på far. Det år gik vi Vesterhavsmarch den 13. juli. Det var godt at få tankerne blæst igennem. Vi boede også i Thorshøj noget af ferien, og jeg mindes at vågne op om morgenen og tænke: ”Det må have været en ond drøm, at far er syg” for så hurtigt at finde ud af sandheden."}, {"type": "para", "text": "Nogle aftner satte jeg mig på fars sengekant og tog ham i hånden. Jeg bad ham kæmpe for vores skyld, og jeg fortalte ham, hvor højt jeg elskede ham. Det havde jeg nok aldrig rigtigt fortalt ham før, men jeg tror, han vidste det."}, {"type": "para", "text": "Det næste var, at mor i et helseblad havde læst om en tysk læge, der havde helbredt kræftpatienter ved indsprøjtninger i maven. Han hed Günther Haase, og mor fandt ud af, at han havde sommerhus på Samsø. Jeg lovede at ringe til ham, hvilket jeg gjorde den 19. juli. Han ville godt se far, så allerede dagen efter kørte mor, far og jeg til Samsøfærgen. Vi tog ikke bilen med over, da vi ville blive hentet af taxa og kørt til det hotel, hvor mødet skulle finde sted. På færgen fandt vi et bord, men på et tidspunkt fik far det dårligt og måtte ned og ligge, hvilket betød, at han optog tre pladser i stedet for én. Han var jo tynd i forvejen, og sygdommen havde ikke gjort det bedre, så han så dårlig ud. To damer, som åbenbart havde ondt af, at han optog så megen plads, begyndte at stå og hviske om, at han nok var fuld. Jeg rejste mig op og råbte ind i hovederne på dem: ”Kan I da ikke se, at manden er syg!” Det lukkede munden på dem. På hotellet blev vi vist op på et værelse, hvor Günther Haase havde indrettet sin konsultation, og far kom ned og ligge på sengen. Jeg husker, at han spurgte far, om ikke han ønskede at blive 80 år. Det ville være for godt til at være sandt. Hr. Haase skulle have 60.000 kr. for kuren, som bestod af en række behandlinger på hans klinik i Uetersen i Nordtyskland. Så mange penge havde mor og far ikke, men mormor trådte til og lånte dem pengene, og jeg husker, at mor beordrede far til at ringe til mormor for at takke hende. Allerede den 23. juli kørte Vagn og jeg mor og far til Uetersen og fik dem installeret i en lejlighed, hvor de delte køkken og bad med en dansk dame, der var der med samme formål som far. Allerede samme dag fik far den første behandling, og vi var med ham på klinikken. I det mindste følte vi, at der blev gjort noget, og vi fortrød aldrig, at vi tog den beslutning, for alternativet ville have været at sidde og vente på, at far skulle dø. Vi ringede tit derned og snakkede med far, og mor prøvede at holde modet oppe. Den 7. august hentede jeg en kørestol i Vendsyssel til far, og den havde vi med ned til ham to dage senere, hvor vi tilbragte weekenden dernede (det tog 4 timer og 15 min. at køre turen). Han kunne næsten ikke gå, så på denne måde kunne vi køre ture i byen med ham. På et tidspunkt syntes mor, at Vagn skulle køre en tur med far, og det gjorde han naturligvis, men det var svært for Vagn at finde på noget at snakke med far om. Vagn har dog senere fortalt, at far sagde til ham, at det var mærkeligt at vide, at man snart skulle dø. Det var første og eneste gang, at far nævnte døden over for os. På et tidspunkt kom Günther Haase på besøg i lejligheden og greb far i at ryge en cigaret. Far havde udtrykkeligt fået besked på, at hvis kuren skulle virke, skulle han kvitte cigaretterne. Günther Haase skældte far ud, hvilket jeg syntes var synd, for det var den eneste fornøjelse, far havde tilbage, og det gjorde jo ingen forskel. Det var en hård weekend, hvor mor og jeg græd, når far ikke så det."}, {"type": "para", "text": "Mens alt dette stod på, var Per i USA. Han var rejst sammen med 6 kammerater lige efter vores kobberbryllupsfest i marts. Han vidste naturligvis godt, at far var syg men ikke hvor alvorligt, for vi ville ikke ødelægge hans rejse. Men kort efter vores weekend i Tyskland, blev fars tilstand kritisk, og han blev indlagt i Åbenrå. Vi ringede til Per, som besluttede at rejse hjem, lidt før tiden. Senere har jeg tænkt, at det var synd for Per, at han ikke blev kaldt hjem noget før, mens far var ved fuld bevidsthed, men Per bebrejdede os det aldrig."}, {"type": "para", "text": "Den 13. august kl. 8 hentede jeg Per i Århus. Vi kørte ned til far om aftenen, og jeg husker, at Per sov det meste af vejen på bagsædet, da han jo havde jetlag ovenpå den lange rejse. Det må have været et chok for Per at se far, som var så træt og helst ville sove. Mors nerver var nu efterhånden godt flossede, og jeg husker, at hun af en eller anden årsag råbte af lægen. Vi kørte derned igen næste dag, og den 15. august kørte Vagn og jeg til Tyskland og hentede mor og fars ting og besøgte far på hjemvejen. Vi var først hjemme kl. 3.15. Den 16. august (lørdag) blev far flyttet til Hjørring Sygehus. Vi var deroppe i weekenden. Onsdag den 20. august kørte vi derop til aften, og da fik jeg et chok og måtte gå ud på gangen for at afreagere. Vi kunne nu ikke længere komme i kontakt med far, og han lå hele tiden og klagede sig. Far døde den nat, den 21. august kl. 3.45, mens Vagn sad vagt. Vi havde besluttet at skiftes til at sidde vagt. Vagn skulle tage den første vagt, mens jeg lå på et værelse og sov, men han havde syntes, at det var synd, at jeg skulle vækkes, så han var blevet siddende. Nu så far fredfyldt ud, og det var på en måde en lettelse, når det ikke kunne være anderledes. Dagen efter fik vi ordnet alt med bedemand og præst. Lars var hos Alice og Reinholt, mens dette stod på, og nu skulle vi hjem og fortælle ham, at han havde mistet sin elskede morfar. Men børn har en vis intuition, og Lars var forberedt, så det kom ikke som et chok for ham. Han var naturligvis meget ked af det, ligesom os andre, men nu kunne vi måske igen komme til at leve et normalt familieliv. Vi kørte alle tre igen nordpå fredag den 22. august for at forberede bisættelsen, som skulle være onsdag den 27. august. Om lørdagen bagte Per boller, og Vagn var i haven. Om søndagen var mor, Vagn og jeg i Skæve Kirke, hvorfra bisættelsen skulle foregå. Mor ville først have dødsannoncen i avisen efter bisættelsen, men der kom alligevel 125 i kirken og 75 til kaffe bagefter på Tryvej 10. Vi samledes først i kapellet i Hjørring, hvor far lå i kisten. Vi sagde et sidste farvel til ham, inden låget blev lagt på. Jeg rørte ved hans kind, som var så kold, og strøg ham over det silkebløde grå hår. Min elskede far var død – det var ikke til at fatte. Fars søskende sad der på første række i kapellet, klar til at bære kisten, men mor havde bestemt det anderledes. Når de ikke kunne besøge far, mens han var syg, skulle de heller ikke have æren af at bære ham til graven. Det blev i stedet Per, Vagn, Helge, Erik, Ib og Elbo. På vej til Skæve Kirke, stoppede rustvognen og følget uden for Tryvej 10, hvor mor havde stillet levende lys i vinduerne. Det så smukt ud. Mor havde spurgt Pastor Larsen, om han ville forrette bisættelsen, selvom han ikke længere var præst, og det ville han gerne."}, {"type": "figure", "caption": "", "page": 128, "file": "assets/images-bog2/p128_01.jpg", "dim": [869, 607]}, {"type": "para", "text": "Han have viet mor og far i sin tid. I kirken sang vi bl.a. fars yndlingssalme, ”Nu falmer skoven trindt om land”, men jeg blev skuffet, da jeg hørte, at det var den forkerte melodi, der blev spillet. Det skulle have været den gamle og ikke den nye melodi. Det havde vi ikke tænkt på. Kirken var smukt pyntet med lyng, som Bente havde plukket. Mor og far elskede lyng, så kisten var også pyntet med lyng, meget smukt og enkelt, et symbol på nøjsomhed. Ejvind og Jesper spillede trompet i kirken: ”Nærmere Gud til dig” – det lød meget smukt. Mor, mormor, Lars og jeg lagde blomster på kisten, inden de kørte med far, og vi fulgte alle rustvognen hen til udkørslen. Vejret var trist og passede til lejligheden. Der var 30 buketter, 20 kranse og dekorationer, hvoraf 6 var med bånd. Per takkede i kirken og holdt en kort tale, og jeg holdt en tale under kaffen. Om aftenen spiste vi, de allernærmeste, hos mormor. Pers kæreste Marianne var i udlandet på det tidspunkt, og vi prøvede at få fat på hende, dog uden resultat, for det var jo før alle gik rundt med en mobiltelefon. Derfor var Marianne ikke med til bisættelsen."}, {"type": "para", "text": "Mor kom ned til os den 30. august og var her til den 3. september. Hun skrev alle takkekortene i hånden, mens hun var her. Efter fars død kom mor tit til Spørring, og det nød vi meget. Hun bagte, strøg, vaskede broderier og meget andet, og så kunne hun jo også være sammen med sit barnebarn, som hun forgudede. Det er mærkeligt at sige, at jeg fik et bedre forhold til mor efter fars død. Mor var klar over, at hun skulle holde sig gode venner med os og ikke brokke sig alt for meget, og hun blev nærmest engleblid. Mor satte selv urnen med fars aske ned på Skæve Kirkegård den 6. september, men vi var naturligvis også til stede. Hun syntes, at vi skulle finde en natursten fra fars barndomshjem, og således gik det til, at vi besøgte fars bror Peter og dennes kone Inga, som havde Sillebak, for at finde en sten i marken, der kunne bruges. Det lykkedes, og tanken var da også smuk, men stenen er ikke særlig pæn mere og meget vanskelig at holde ren for alger."}, {"type": "para", "text": "Kort tid efter fars død, begyndte Vagn at klage sig over smerter i maven, og det endte med, at han blev sendt til undersøgelse på sygehuset. Heldigvis var der ikke noget galt, og lægen sagde nærmest til ham, at han skulle tage sig sammen. Vagn troede simpelthen, at han også var blevet syg ligesom far, så hele fars forløb havde taget hårdt på ham. Det havde taget hårdt på os alle, og vi havde tabt os. Mor var tynd og grå, så det var dejligt, da hun meddelte, at hun ville på charterferie på Tenerife om foråret sammen med onkel Erik. Mor klarede fint at være alene, men hun savnede far meget, også mere end vi var klar over."}]}, {"title": "Husmoderlige pligter", "blocks": [{"type": "para", "text": "I 80’erne dyrkede vi mange grøntsager og megen frugt i haven, og der måtte jo ikke gå noget til spilde, så jeg plukkede ribs og lavede rysteribs til fryseren, jeg plukkede ærter, blancherede dem og lagde dem i fryseren, og sågar pærer syltede jeg. Rabarber var også noget, vi kunne lide, enten som grød, kompot eller i kage. Jeg bagte meget i 80’erne, også til mine klasser på sidste skoledag. Så skar jeg kanterne af til Vagn og Lars – intet måtte jo gå til spilde. Jeg tog også ud og plukkede jordbær de steder, hvor der var selvpluk, og det blev ofte til mere end 20 pund til fryseren. Men dengang fik vi også altid eftermad, så jordbærgrød var tit på menuen. Det var sjældent, at jeg lavede saft og syltetøj."}]}, {"title": "Mode og gaver", "blocks": [{"type": "para", "text": "Igennem årene har jeg haft mange forskellige frisurer, lige fra helt kort og glat til afrohår med krøller, men oftest korte frisurer. På Østervang boede vi i mange år skråt over for Gitte, som vi kaldte Gitte damefrisør. Det var nemt at gå derover, og hun gav forskellige behandlinger: vandondulation, mini-vague, permanent og afrohår. Jeg havde svoret, at jeg aldrig skulle have mit hår farvet, men man skal aldrig sige aldrig, for i 1985 fik jeg lyse totter i håret for første gang, og omkring min 40-års fødselsdag, hvor jeg måske var kommet i panikalderen, fik jeg håret farvet kastanjebrunt. Jeg følte mig som en helt ny kvinde, og der var flere, der roste mit nye look."}, {"type": "para", "text": "Jeg har altid gået meget op i tøj, og nogle få køb har jeg noteret i mine dagbøger: I sommeren 1982 købte jeg en selskabskjole til 446 kr., til min fødselsdag i 1983 gav Vagn mig et par lysebrune skindbukser, som jeg stadig bruger. Det var højeste mode dengang. I 1986 fik jeg en koboltblå skindnederdel i fødselsdagsgave af Vagn og var så heldig året efter at finde en jakke i samme skind og farve til 1800 kr. Den måtte jeg absolut have. Til min fødselsdag i 1988 gav Vagn mig en sort ulden frakke og en støvsuger – det skulle ikke være luksus alt sammen. Det må have været først i firserne, at jeg fik huller i ørerne. Jeg havde længe gerne villet have det, da jeg elskede at gå med smykker, og ørenringe til huller var mere behagelige at gå med, men jeg turde ikke. Heldigvis fik jeg i julegave et år et gavekort af Vagn til at få lavet huller, så nu var der ingen vej udenom. Heldigvis mærkede jeg næsten ikke noget, da nålen blev skudt igennem øret, og jeg kom aldrig til at døje med betændelse, så det var en dejlig gave at få. Jeg har i det hele taget altid fået mange gaver og er blevet meget forkælet af mine nærmeste, også på Mors Dag, og Lars husker det stadigvæk. I 1984 fik jeg et marguerittræ til haven på Mors Dag."}, {"type": "para", "text": "Før Vagn mødte mig, var han rigtig god til selv at købe tøj, men jeg overtog det nok lidt, da vi mødtes. Jeg har noteret i mine dagbøger, at Vagn fik en grøn Nanok jakke i 1982 til 862 kr. Det var mange penge dengang, men det var også et dyrt mærke. I 1984 fik han en habit med vest til 1288 kr., og i 1989 fik han sin første smoking. Vagn købte sine første briller den 25. marts 1986."}]}, {"title": "Historiske begivenheder", "blocks": [{"type": "para", "text": "• Blekingegade-sagen bliver afdækket • CNN er blandt de første til at lave 24-timers nyhedskanal • Glasnost og perestrojka i Sovjetunionen • Berlinmurens fald Kanal 2 begynder at sende • • TV2 etableres i Danmark John Lennon skydes ned på gaden foran Dakota-bygningen i New York af den • sindsforvirrede fan Mark David Chapman og dør. Lennon-væg bliver lavet i Prag og vedligeholdt af fans af John Lennon Mordforsøg på den amerikanske præsident Ronald Reagan • • Mordet på den svenske statsminister Olof Palme MTV startes og ændrer musikindustrien • • PC’en udbredes Steven Spielbergs ”E.T. the Extra-Terrestrial” får biografpremiere • • Firkløverregeringen gennemfører kartoffelkuren i Danmark for at fremme opsparing og mindske gæld • Tjernobylulykken i Ukraine, Sovjetunionen • Udbredelsen af AIDS Prince Charles gifter sig med Lady Diana Spencer, der bliver kendt som Prinsesse Diana • • EF-valg den 14. juni 1984 Storkonflikt den 25. marts 1985 (Vagn strejker) • • Danmark får Oscar for Pelle Erobreren den 30. marts 1989"}]}]}, {"id": "1990erne", "title": "1990’erne", "chapters": [{"title": "Livet i Spørring i 90’erne", "blocks": [{"type": "para", "text": "I 1990 boede der ca. 800 mennesker i Spørring. Vi var stadig et lille landsbysamfund, der kæmpede mod lufthavn, skydebane og motocrossbane. Det var dog ikke alt, vi kunne holde på afstand. Et landsplandirektiv pålagde i 1984 alle kommuner at udarbejde varmeplaner for landsbyer som Spørring, og vi valgte naturgas, selvom de fleste frygtede store lugtgener. I 1992 blev det derfor besluttet, at der skulle etableres et biogasanlæg ved Spørring. Der har i perioder været kraftige lugtgener, og man er blevet opfordret til at ringe og klage til kommunen, når det skete. Forholdene er blevet forbedrede, og det er i dag sjældent, at man kan lugte anlægget."}, {"type": "para", "text": "Der blev også etableret et Vindmøllelav i 1993, som vi var medlem af. Den 7. maj 1997 lukkede Spørring Vandværk på grund af pesticider, og vi kom under Aarhus Kommunale Værker, men senere kom det frem, at det havde været så forsvindende lidt forurening, der havde været, at der ikke havde været grund til at lukke vandværket."}, {"type": "para", "text": "Byfesterne havde holdt pause, men savnet var for stort, og behovet for byfester steg. Derfor kom der igen grøde i sagen fra 1997, og konceptet har holdt lige siden. Der var kirkekoncert om torsdagen, fællesspisning og revy om fredagen, optog, boder, grill og musik om lørdagen, og morgenkaffe, gadefodbold og kræmmermarked om søndagen. Det skal dog siges, at siden Torben Ernstorns død, har der ingen revy været. I 1997 deltog både Vagn og jeg i gadekampe, hvor Østervang vandt."}, {"type": "para", "text": "I 1994 startede Menighedsrådet med at holde sangaftner i den Gamle Skole. Det var rigtig hyggeligt at mødes og synge både gamle og nye sange, akkompagneret af Anne Marie, som var kirkens organist. Vores nabo Mary og jeg fulgtes tit ad, ligesom vi også fulgtes ad i kirke nogle søndage. Det skete også, at Alice var med."}, {"type": "para", "text": "Når vi skulle bruge en lejlighedssang, spurgte vi altid Alice, for hun var ferm til at lave sange. Lidt efter lidt fik jeg også smag på denne hobby, og den første rigtige sang, jeg lavede, var til Klaus’ konfirmation. Det var mærkeligt, at jeg bad Alice lave sang for os til Lars’ konfirmation, men jeg syntes ikke, jeg var god nok til at lave den, og den skulle i hvert fald være i orden. Fra 1991 til 1997 lavede jeg 13 sange, og det fortsatte efter den tid. Jeg bildte mig dog ind, at jeg kun kunne lave en sang til folk, jeg kendte, så jeg ville aldrig kunne leve af det."}, {"type": "figure", "caption": "", "page": 131, "file": "assets/images-bog2/p131_01.jpg", "dim": [787, 1171]}, {"type": "para", "text": "Af andre hobbyer kan nævnes, at jeg skar uroer, og vi havde dem hængende overalt. Jeg lavede selv udskårne kort til gaver, og skulle vi i byen, lavede jeg hurtigt en uro som værtindegave. I dag har jeg smidt alle mine mønstre ud."}, {"type": "para", "text": "Jeg fik ny cykel i 1987, og i sommeren 1990 cyklede jeg i gennemsnit 10 km om dagen. I de efterfølgende år blev det til mange cykelture, også hjem fra arbejde. Vi havde cyklen med om morgenen på en fin dag, og på vej hjem om eftermiddagen fik jeg min motion. Jeg skulle helst have et mål, når jeg cyklede, og helst musik i ørerne. I sommeren 1996 cyklede jeg 370 km. Der var også nogle år, hvor jeg cyklede sammen med Vagn i sensommeren, når vi kom hjem fra arbejde. Så smurte vi en madpakke og cyklede ud i det blå. Måske sad vi op ad en høstak på en mark og spiste eller inde på en bænk på en kirkegård. Det var skønt."}, {"type": "para", "text": "Thomas med sangskjuleren den 3. maj 1992 Da computeren kom frem, svor jeg, at jeg aldrig skulle have en sådan, for jeg havde jo min elektriske skrivemaskine. Men da Lars fik ny PC til 10.000 kr. i starten af 90’erne, overtog vi hans gamle maskine, og så gik det virkelig løs."}, {"type": "para", "text": "Fiskeri var også noget, der fyldte i vores liv i 90’erne. I mine dagbøger har jeg noteret nogle højdepunkter. Den 2. august 1991 havde vi fætter Thomas med på fisketur til Mårup Put & Take, hvor Vagn skulle lære Thomas at fiske. Man betalte pr. kg fanget ørred, og det blev hurtigt klart for Vagn, at denne tur ville gøre ham til en fattig mand. Thomas fangede 10 store ørreder, og Lars fangede 3, og selvom vi forærede 2 væk, kom vi alligevel af med 414 kr.!"}, {"type": "para", "text": "Det skrev jeg også om i Thomas’ konfirmationssang, og sangskjuleren var en fiske-sø med fisk, og en fiskestang. 12 dage senere, den 24. august 1991, fangede Vagn en torsk på 11,5 kg på det Gule Rev. Der var mange, der var søsyge på turen. Fra 1992 til 1997 var Vagn på mange fisketure sammen med Tage og Preben, og Lars var sommetider med. Der blev tit taget mellem 45 og 65 fladfisk på en sådan tur, og mændene var flinke til selv at tage det groveste, så jeg kun skulle rense fiskene og skylle dem. I maj 1993 fangede Lars 3 store ørreder og Vagn 3 ørreder i Put & Take. Når mændene var afsted, lavede vi piger tit noget andet, såsom at drikke kaffe eller tage på shopping. Vagn fiskede også sammen med Finn, Niels og Leif, og et par gange var vi tre i Put & Take sammen med Ingrid, Hans Jørgen og Brian."}]}, {"title": "Lars’ konfirmation den 21. april 1991", "blocks": [{"type": "para", "text": "Lars begyndte at gå til præst den 26. september 1990 hos Walther NielsenRefs, som havde været sognepræst i Spørring siden 1984. Spørring Kirke er opført i sidste halvdel af 1100-tallet og er noget af det første, man får øje på, når man kommer kørende til Spørring. Det var manges opfattelse, at Walther var bedre på en fodboldbane og i festligt lag, end Rasmus E, Bjørn, Ulla, Tanja, Rasmus S, Brian, Lars & Walther                     han var på prædikestolen, men jeg tror, at han var god til at omgås de unge konfirmander, for Lars var glad for ham til konfirmandforberedelse, og han leverede en af sine bedste taler den dag, Lars blev konfirmeret. Da vi kun skulle opleve at holde konfirmation én gang, skulle der ikke være noget overladt til tilfældighederne. På et tidligt tidspunkt lejede vi Ødum Forsamlingshus og bestilt en musiker, Poul Erik, og da vi kom godt ind i det nye år, begyndte vi at se på tøj. Vi var til konfirmand modeshow sammen med Anne og Rasmus i Magasin den 6. februar 1991, hvor Lars vandt et gavekort til en frisør, og derefter begyndte vi seriøst at kigge på det. Sidst i februar fik Anne-Mette og Lars tjansen at give danseopvisning og gå mannequin hos Vagn Larsen i Randers. De fik hver et gavekort på 300 kr., som naturligvis skulle bruges i butikken, så der købte Lars en flot andendagsjakke i blå ruskind (som den brune han går mannequin i på billedet) og det øvrige andendagstøj blev lyse lærredsbukser (Lars kunne dengang ikke lide cowboybukser, som næsten alle drengene købte), t-shirt og mønstret trøje. Selve konfirmationstøjet blev mørkeblå bukser, hvid skjorte, blåligt slips med diskret mønster og hvid jakke, og det kostede 2000 kr. Lars’ mormor var med ude og købe det. Derudover skulle der også købes sko."}, {"type": "figure", "caption": "", "page": 132, "file": "assets/images-bog2/p132_01.jpg", "dim": [1325, 985]}, {"type": "figure", "caption": "", "page": 133, "file": "assets/images-bog2/p133_02.jpg", "dim": [1176, 776]}, {"type": "para", "text": "Jørn Griis, som var typograf, lavede indbydelser og bordkort, som havde en silhuet af Lars (klippet af mor). Alt var i orden, når Jørn lavede noget, men det tog sin tid, for alting skulle vendes og drejes og drøftes, så det blev til mange møder, inden det færdige resultat lå der. Indbydelserne blev sendt ud den 10. marts. Den 21. marts var vi til hyggeaften hos præsten, og vi gik i kirke alle tre nogle gange inden konfirmationen. Der var ikke som i dag en regel om, at konfirmander skal gå x antal gange i kirke. Jeg købte en rød stropløs kjole til 699 kr., og Vagn skulle have sin smoking på med rød butterfly og lommetørklæde, der matchede min kjole. For første og eneste gang i mit liv brugte jeg selvbruner, som jeg fik Vagn til at hjælpe mig med at smøre på, og det så virkelig pænt og naturligt ud, uden striber. Vi havde fået anbefalet en kok af Anne. Han hed Max Jørgensen og boede i Hadsten, og første gang vi havde en aftale med ham, brændte han os af. Det så ikke lovende ud, men vi lavede en ny aftale, og så tegnede det godt. Det var godt, at vi ikke i forvejen vidste, at han havde problemer med alkohol, for så havde jeg nok ikke sovet roligt om natten. Han tog da også for sig af de våde varer, da han havde lavet maden, så han gik dinglende derfra. Jeg var glad for, at han nåede at få maden overstået, inden han gik til flasken."}, {"type": "figure", "caption": "", "page": 133, "file": "assets/images-bog2/p133_01.jpg", "dim": [708, 954]}, {"type": "figure", "caption": "", "page": 133, "file": "assets/images-bog2/p133_03.jpg", "dim": [768, 999]}, {"type": "figure", "caption": "", "page": 134, "file": "assets/images-bog2/p134_01.jpg", "dim": [781, 519]}, {"type": "figure", "caption": "", "page": 134, "file": "assets/images-bog2/p134_02.jpg", "dim": [789, 519]}, {"type": "para", "text": "Heldigvis havde vi hyret et stærkt hold af tjenere: Lone og Helle Griis, Jane Jensen, Pia Henriksen og Per Kjøller. De fik hver 500 kr. for at servere. Vi lavede også en folder og menukort til festen."}, {"type": "para", "text": "Sangskjuleren var meget speciel og forestillede et podium med et dansepar, to Barbiedukker i smoking og en lilla dansekjole syet af Hanne i Vejle af resterne fra Anne-Mettes kjole. Selv rygnummeret var nedfotograferet fra et ægte rygnummer, som Lars havde haft på til JM i standard, nr. 66. Gulvet, de stod på, var parketgulv som til turneringerne, og inden i podiet var der plads til en walkman, der skulle spille en Strauss Wienervals, når sangen kom ind. I podiet var der plads til, at sangene kunne ligge. Vagn havde lavet to ens sangskjulere, for Anne-Mette skulle konfirmeres samme forår. Vi var ude og leje lyseblå stofduge og ditto servietter hos Hadsten Dampvaskeri, samt det service, der manglede. Mor kom fredag den 19. april – hun skulle hjælpe om lørdagen med borddækning og pyntning af forsamlingshuset, som godt kunne trænge til at blive piftet lidt op. Vi startede lørdagen med at tage til frisør i Randers, både Lars, mor og mig. Dernæst hentede vi dekoration og blomster hos Toves Blomster og dækkede borde. Vi havde købt det store årskrus til Lars og havde fået graveret i bunden, og det fik vi pyntet, så det kunne stå foran ham på dagen. Mor var meget kreativ, så hun lavede fire store buketter med grene til at stå på gulvet og pyntede dem med 100 hvide fugle, som hun havde klippet. Der blev også sat blomster og trearmede lysestager i vinduerne, så alle mine hvide urtepotteskjulere og lysestager var i brug udover alle dem, vi lånte os frem til. Vagn optog det hele på video. Om aftenen kom Marianne, Per, Erik, Lene, Lasse, Edith, Ib & oldemor til at spise. Erik, Lene og Lasse boede hos Hanne og Keld, og resten boede hos os. Moster og Ib havde bagt to flotte kransekager til festen. Så oprandt det store øjeblik, søndag den 21. april kl. 9.30 i Spørring Kirke. Der var sol og blæst, og senere blev det snevejr. Der var ikke plads til alle gæsterne i kirken, men følgende var med fra familien udover os selv: mor, farmor og bedstefar, Doris, Poul Erik + børnene, Anna-Lise og Tage. Lars havde fået salmebog af farmor og bedstefar. Efter kirken var vi 20 på Østervang til at drikke kaffe og spise kringle, som Mary havde bagt."}, {"type": "figure", "caption": "", "page": 135, "file": "assets/images-bog2/p135_03.jpg", "dim": [814, 535]}, {"type": "para", "text": "I Ødum stod bordene flot dækkede, og de 52 gæster strømmede til. Vi fik champagne til velkomst, og menuen, som Lars selv havde sammensat, bestod af rejecocktail med flutes, let røget, sprængt strip loin m. sauce bordelaise, hasselbachkartofler, minimajs, slikærter og grøn salat med hvidløgsdressing. Til dessert fik vi fest-is i form af hestesko overtrukket med chokolade."}, {"type": "figure", "caption": "", "page": 135, "file": "assets/images-bog2/p135_02.jpg", "dim": [784, 519]}, {"type": "para", "text": "Lars selv bød velkommen, og derudover var der taler af mig, mor, Keld og Vagn, som til sidst sagde velbekomme og tak. Der var 7 sange, og den første var naturligvis fra os."}, {"type": "figure", "caption": "Lars blev meget rørt, glad og overrasket over vores projekt, som jo mange havde del i:", "page": 135, "file": "assets/images-bog2/p135_01.jpg", "dim": [556, 850]}, {"type": "para", "text": "Alice havde lavet sangen, Jørn havde sat teksten, ElseMarie havde lavet billederne, jeg havde sat det hele sammen, og trykkeriet på Ingeniørhøjskolen havde trykt sangen. Sangskjuleren var lavet af Vagn, Hanne havde syet kjolen, og Erik maler havde hjulpet lidt med malingen. Der var også sange og flotte sangskjulere fra mor, Per og Marianne (SAS nøgleringe), fra Vagns familie (computer), fra Klaus (balloner), fra Hanne og Keld (amerikanerhat), fra Alice og Reinholt (computer) og fra Lars selv (2 hjertekagedåser med vores portrætter på). Alice havde altså lavet tre sange til den lejlighed, alle forskellige og gode. Jeg tror, at mor havde ofret sine kagedåser på denne flotte sangskjuler."}, {"type": "para", "text": "Keld Henriksen tog video under hele middagen, som varede helt til kl. 17.30. Forinden havde vi ringet efter Anne-Mette og mor Kirsten, for som en overraskelse til gæsterne skulle Lars og Anne-Mette give danseopvisning. Det blev en stor succes, og bagefter var der kaffe og kransekage og til skrub-af-mad hønsekødsuppe. Da Anne-Mette den 26. april blev konfirmeret, gentog vi successen med danseopvisningen."}, {"type": "para", "text": "Lars fik 30 gaver, 5 blomster, 87 telegrammer og 9.405 kr. Af os fik Lars en fluefiskestang, en tegning af Spørring Kirke lavet af Pia Henriksen, årskrus 1977 og 2500 kr. Resten af gaverne er skrevet ned i Lars’ konfirmationsalbum."}, {"type": "para", "text": "Festen i Ødum sluttede kl. 22, hvorpå vi skulle have al maden kørt hjem. Hjemme kom vi først af med de sidste gæster kl.0.30. Det var Københavnerne, som skulle med en sen færge."}, {"type": "para", "text": "Næste dag var vejret desværre dårligt til Blå Mandag. Jeg havde fri, og Vagn kom hjem på grund af dårligt vejr. Det var meget heldigt, for så kunne han køre med mor og mig til Ødum, så vi kunne få ryddet op efter festen og gjort rent. Jeg var dødtræt ovenpå det hele, men vi var glade for, at alt var gået godt. Det var hele umagen værd, men da jeg om tirsdagen skulle til morgenbesøg hos Ruth og Ras, som havde sølvbryllup, undrede det mig, at min nederdel sad så løst. Det viste sig, at jeg havde tabt mig 3 kilo i forbindelse med konfirmationen."}, {"type": "figure", "caption": "", "page": 136, "file": "assets/images-bog2/p136_01.jpg", "dim": [1179, 787]}, {"type": "para", "text": "Efterfølgende var der efterkonfirmationer. Vi havde selv efterkonfirmation for dem, der havde givet på Østervang den 2. maj og 14 andre gæster den 16. maj, og vi holdt en fælles efterkonfirmation med de andre 4 drenge fra Spørring, hvor vi forældre lavede maden og samledes sammen med børnene hos Ingrid og Hans Jørgen den 12. maj. Vi var til efterkonfirmation hos Inge-Marie den 25. april og til konfirmation med Klaus den 28. april. Klaus lånte Lars’ hvide jakke til kirken, fordi Grete og Poul var trætte af at investere i en jakke, som han kun skulle have på i en time."}, {"type": "figure", "caption": "", "page": 136, "file": "assets/images-bog2/p136_02.jpg", "dim": [1044, 657]}, {"type": "para", "text": "Lars skrev takkekort med billede og sendte dem ud den 7. maj. Jørn Griis var med os ude og købe PC til Lars den 22. maj til 10.000 kr., så det var alle konfirmationspengene, der gik til den. Den 2. juni var vi med Lars i kirke, hvor han gik til alters for første gang."}]}, {"title": "Naboer, venner og familie", "blocks": [{"type": "para", "text": "Selvom man har en dejlig familie, kan man ikke undvære venner. For vores vedkommende har familien altid været langt væk, så vi har været lykkelige for at have gode venner i nærheden. Vores bedste venner har uden tvivl været Alice og Reinholt. Det er meget mærkeligt at skrive om dem nu, den 6. april 2014, for det er kun to dage siden, vi mistede Reinholt, efter at han i lang tid havde været syg af kræft. Reinholt blev 80 år. Det er hårdt at miste gode venner, og det er, hvad Alice og Reinholt har været for os. Vi har altid kunnet hente hjælp hos dem, og vi har haft mange oplevelser sammen, bl.a. vores mange ø-ture, som desværre sluttede, da Reinholt blev for dårlig til at gå ture. Udover at Alice arbejdede i Brugsen i mange år, uddannede hun sig til zoneterapeut i april 1991 og åbnede egen praksis, som Vagn leverede briksen til. Lige for tiden går jeg til zoneterapi hos hende en gang om måneden for mit velværes skyld. Jeg tror på, at det hjælper mit immunforsvar, så jeg ikke bliver så nemt syg. Vi har en aftale om, at jeg betaler 100 kr. pr. gang."}, {"type": "para", "text": "Samme vinter (1991) lånte vi Knud og Teklas sommerhus i Tranum, hvor vi tilbragte en fantastisk weekend med masser af sne. Lars havde lige den alder, hvor han syntes, det var sjovt at være med, og Alice trak af sted med ham på kælk ned til stranden, hvor han og vi andre så skiftedes til at drøne ned ad bakkerne på kælken. Lars havde også ski med, men vi havde ikke tradition for at tage på skiferie, så det var først senere, at Lars heldigvis fik rigtig smag og flair for den sport. Vi hyggede os også inden døre med at spille Lifestyle. Året efter skulle vi derop igen uden Lars og med trailer, for vi skulle have brænde med til pejsen og megen proviant (kasse med øl, sodavand, gryde med kartofler, sengetøj m.m.) Poul havde lovet at reparere traileren, men som det så ofte skete, når Poul lovede noget, så blev det ikke til noget sådan lige med det samme, men han havde bedyret, at der ikke blev problemer. Men det blev der, for traileren gik i stykker, og vi måtte stille den på en gårdsplads og skrive en seddel til beboerne, at vi ville hente den igen senere. Det, der kunne læsses ind i bilen, blev læsset ind, så Alice og jeg sad klemt mellem brænde, sengetøj og mad, og så var der alligevel noget brænde, der ikke kunne være der."}, {"type": "para", "text": "I maj 1995 inviterede Alice og Reinholt os i Mindeparken med efterfølgende middag på Navigator og kaffe derhjemme. To år senere kvitterede vi med en tur til Ebeltoft og Jernhatten. Vi hyggede os altid meget i hinandens selskab. Vi vil komme til at savne Reinholt meget. Venskabet med genboerne Grete og Poul var også godt. Vi havde (og har) det vældig hyggeligt, når vi var sammen, og vi pjattede og grinede, som for eksempel da vi fejrede vores 25 års jubilæum den 10. maj 1994 ved at tage ud og spise i Kaløvig Bådehavn. De er nogle rigtige selskabsmennesker, og Grete er eminent god til at gøre nar ad folk, så vi ligger flade af grin. Der kunne dog gå lang tid, hvor vi ikke så hinanden, og det var som regel mig, der skulle gå derover. Drengene var meget forskellige, og de havde ikke altid de samme interesser, men fodbold kunne de godt hygge sig med at spille og se. Klaus tog på High School i USA i august 1994 og var væk i 10 måneder. Det var en hård tid for Grete, især også fordi Klaus ikke havde det godt derovre. Han var hos en mormonsk familie, som havde meget strenge regler. Omkring den tid så vi ikke så meget til hinanden, men i dag har vi et fint forhold. Vi sidder dog ikke lårene af hinanden, som vi gjorde i vores unge dage. Kirsten og Erik maler hørte stadig med til den nærmeste vennekreds. De solgte deres hus på Østervang i august 1990 og flyttede ned i det nye Spørringgård bagved Brugsen. Vi sås af og til, men ikke så ofte som da de boede på Østervang. Ellen og Børge Bonne var også en del af vennekredsen, og de inviterede fast en gang om året naboer og venner til middag, hvor der bestemt ikke manglede noget. Hanne og Keld, som vi var i USA sammen med, havde vi af og til nogle sjove oplevelser sammen med, såsom dengang vi i vinteren 1993 kørte ud til Kalø, stillede bilen og gik tur i skoven. Da vi kom tilbage til bilen, varmede vi pølser i det fri og spiste hot dogs. Hyggeligt men koldt. De holdt en dejlig sølvbryllupsfest den 25. april 1990, hvor vi havde lavet sang om USA-turen og holdt tale. Det kom som et chok for os, da de fortalte, at de havde solgt deres hus og ville flytte til Risskov i nybygget hus. De flyttede ind i 1995, og vi har det stadig hyggeligt sammen med dem, bare ikke så ofte."}, {"type": "figure", "caption": "", "page": 138, "file": "assets/images-bog2/p138_01.jpg", "dim": [628, 1012]}, {"type": "figure", "caption": "", "page": 138, "file": "assets/images-bog2/p138_02.jpg", "dim": [779, 993]}, {"type": "para", "text": "I 1995 blev vi optaget i en eksklusiv klub i Spørring, som blev kaldt ”Århus Kommunale Værker (ÅKV)”. Vi var fra starten 10 par: Karen Lis & Finn, Anne & Niels, Jette & Leif, Ruth & Ras, Gerda & Torben, Tulle & Alex, Karen & Børge, Ewa & Zdzislaw (polakker), Else & Jørn og os. Vi havde to faste arrangementer om året, en grillaften i august og en bowlingaften i marts, og vi skiftedes til at arrangere. På et tidspunkt blev Jørn uvenner med Finn og Niels, og senere Alex, og vi tror, at det skyldes, at de ikke ville skrive under på, at omfartsvejen ikke skulle gå ud i Jørns indkørsel. Det hele gik i hvert fald i en hårdknude, og det var pinligt hver gang, vi skulle mødes til noget, for der skulle altid tages hensyn til, at de stridende parter ikke kom til at sidde sammen. Til slut trak Else & Jørn sig helt ud af sjakket, og vi så ikke så meget til dem. Vi var dog aldrig uvenner med dem, og her for få måneder siden er vi begyndt at se dem igen. Senere blev polakkerne skilt, og Zdzislaw er nu død. Efter Niels’ og Alex’ død er vi 14 tilbage."}, {"type": "para", "text": "Vi så en del til Else og Jørn i 90’erne, ligesom vi også så mere til nogen end til andre i gruppen. Vi så mest til Karen Lis og Finn, Anne og Niels samt Jette og Leif."}, {"type": "para", "text": "Vi havde nogle vennepar, som vi kun så en gang om året, men det var også hyggeligt, og vi manglede aldrig noget at snakke om. Det drejer sig om Vivi og Frode fra Auning, Lis og Ole fra Risskov og Lisbet og Ulrik fra Hobro. Vennerne nordpå kneb det også med at få tid til at besøge, men vi holdt kontakten, især til Anne Marie og Poul, Anette og Søren samt Alice og Svend."}, {"type": "figure", "caption": "Til venstre: Frode og Vivi med deres børn, sølvbryllup den 22. juli 1992 Til højre: Svend og Maries guldbryllup den 8. december 1990 på Frederikshøj Kro. Vi havde sammen med Mie og Poul lavet æresport og forærede dem et maleri", "page": 139, "file": "assets/images-bog2/p139_01.jpg", "dim": [665, 784]}, {"type": "figure", "caption": "", "page": 139, "file": "assets/images-bog2/p139_02.jpg", "dim": [520, 676]}, {"type": "para", "text": "Else-Marie og Henning hørte vel mere med til familien, og vi sås i Svenstrup af og til, foruden når vi inviterede hinanden."}, {"type": "para", "text": "Marie og Svend Sønderup holdt et fint guldbryllup på Frederikshøj Kro den 8. december 1990, hvor de også holdt deres efterhånden mange runde fødselsdage, og derudover var vi ret flinke til at besøge dem. Lars sagde somme tider til mig: ”Mor, tror du, der er nogen, der vil besøge dig, når du bliver gammel?”, og det kan han måske have ret i. Men vi har altid haft det i os, at vi ikke må glemme de gamle. Vi havde Marie og Svend med på en søndagstur nordpå, så de kunne se, hvor vi kom fra, og vi fik besøgt både Vagns forældre, mormor og mor. I august 1993, efter mors død, inviterede de os ud at spise stegte ål på Norsminde Kro, og Svend og Vagn fik sig nogle snapse til."}, {"type": "figure", "caption": "", "page": 139, "file": "assets/images-bog2/p139_03.jpg", "dim": [784, 1168]}, {"type": "para", "text": "I juni 1993, samme år som mor var syg, genoptog jeg forbindelsen med min barndomsveninde Ulla, som boede og stadig bor i Rødovre. Vores mødre havde mødtes i bussen og talt om os, og det gav anledning til, at jeg kontaktede Ulla efter 26 år. Det er blevet til flere besøg siden, og jeg har lige læst korrektur på Ullas erindringsbog, som hun har skrevet efter inspiration fra min første bog."}, {"type": "para", "text": "Hvad familien angik, flyttede Marianne og Per til USA (Los Angeles) i 1989 i forbindelse med Pers job som trainee hos SAS. Det var en spændende tid for dem, og mor fik sit livs rejse over til dem i 1990. Fra april til september 1994 boede Marianne hos os. Hun skulle læse på Journalisthøjskolen i Århus, og vi nød at have hende boende. Senere skulle hun læse i Bruxelles, hvor Per så boede alene i lejligheden ved Søerne. Her besøgte vi dem i maj 1996, hvor vi startede med bold i Parken (AGF vandt), bowling, og italiensk restaurant, og dagen efter var vi på rundvisning i Chr. 7. Palæ samt på Kronborg. Det var altid hyggeligt og sjovt at besøge Marianne og Per, og Lars elskede det. Der skulle altid ske noget, og vi kunne aldrig sidde hjemme med benene oppe. Vores teori var, at de var blevet rastløse af at rejse så meget, og sådan er det stadig. Men hyggeligt er det. Vi havde en sjov oplevelse, da vi skulle ind og se Chr. 7. Palæ. Vi skulle være der til en bestemt tid, da vi havde bestilt rundvisning, men først skulle Marianne komme hjem fra Bruxelles. Det gjorde hun også, men vi kom lidt sent ud af røret. Vagn overlod rattet til Per, som var bedst kendt og derfor kunne få os hurtigst frem til bestemmelsesstedet. Pludselig befinder vi os inde midt på Amalienborg Slotsplads blandt garderne, som er midt i et vagtskifte, så det kan nok være, vi blev gelejdet ud. Det lykkedes Per at finde en P-plads, så vi var på pletten som de sidste i selskabet, men lige i tide. I september samme år fik Per job hos SAS i Hong Kong, og de flyttede begge derover. Nu startede for alvor et liv i luksus med tjenestefolk, chauffører og dyre vaner. Vores mor ville have været stolt."}, {"type": "para", "text": "Jeg har noteret i min dagbog, at mor tog en bustur til Prag sammen med moster og Ib i sommeren 1992. Det var dejligt, at de kunne tage afsted sammen, for det skete ikke så tit. Bussen skulle samle folk op i Århus ved Musikhuset den 24. juli, så Lars og jeg besluttede, at vi ville give de tre en overraskelse. Jeg havde købt nogle blade og godter og lavet tre pakker, en til dem hver, og til hver pakke havde jeg skrevet et kort. De gjorde da også store øjne, da vi stod i Århus for at ønske dem en god tur, og de var glade for gaverne, som de først måtte lukke op senere. En anden overraskelse fik de i Prag, hvor Marianne og Per pludselig stod i døren til mors hotelværelse. De havde booket en rejse dertil for at overraske hende og selvfølgelig også for at opleve Prag."}, {"type": "para", "text": "Den 1. september samme år havde mor 20-års jubilæum på Bødkergården, men ingen af os deltog."}, {"type": "para", "text": "På Vagns side købte Doris og Poul Erik sommerhus i Lille Norge ved Saltum i 1992, og i dag er det Poul Eriks faste hjem. Vi lånte det på en af vores weekendture sammen med Alice og Reinholt i 1995. Senere fik Doris og Poul Erik lyst til at flytte fra Svenstrup og deres dejlige hus, så de købte en gammel rønne i Godthåb, 2 km fra Svenstrup, og totalrenoverede den. Vi rystede på hovedet af dem, og deres børn syntes vist også, det var tåbeligt. De fik solgt deres hus og flyttede ind i det nyrenoverede hus i august 1994. Vi måtte indrømme, at det var blevet dejligt, men der gik desværre kun 6 år, inden sygdommen ramte Doris, og hun døde i maj 2001. Doris og Poul Erik fik deres første barnebarn i november 1993. Jens Christian havde fået en kæreste, Dorthe, og de fik Camilla. Desværre holdt forholdet ikke, og Doris og Poul Erik så ikke meget til Camilla, før Doris blev syg. Det var godt for Doris, at hun fik kontakt til Camilla, inden hun døde, men i dag er der desværre igen ingen kontakt."}]}, {"title": "Vores hus, bil og campingvogn", "blocks": [{"type": "para", "text": "Den 4. januar 1994 var vi ved at blive skilt på grund af en ny bil! Vagn skulle hente vores nye sølvgrå metallic Volvo 460DL og hente mig på Banegården, efter at jeg havde været ude som censor. Jeg glædede mig til at få en tur i den nye bil. Idet jeg står og venter på ham, kommer der en bekendt forbi, og vi står og snakker. I mellemtiden er det blevet mørkt, og jeg har svært ved at se, hvilke biler der kører forbi, men da jeg har stået der i en halv time og ventet i bidende kulde, går jeg ind til en telefon og ringer hjem. Jo, han havde da været på Banegården, men jeg stod ikke der, hvor vi havde aftalt. Så blev jeg sur, smækkede røret på og gik ned og tog bussen hjem. Jeg var så gal og så kold, at jeg rystede som et espeløv, og da jeg kom hjem, talte vi ikke til hinanden i lang tid. Indtil Vagn kom og spurgte, om jeg ville have en tur i den nye bil. Så tøede jeg op, og idyllen blev hurtigt genoprettet. Vi har senere forsøgt at rekonstruere hændelsen, men det ender altid med, at Vagn påstår, at jeg stod det forkerte sted, så det skal nok passe. Han har oftest ret."}, {"type": "para", "text": "Selvom det var en Volvo, så blev vi aldrig rigtig glade for den, og vi skiftede den ud 6 år senere til en Peugeot 406, som vi stadig kører rundt i."}, {"type": "para", "text": "I 1995 fik vi lyst til at prøve campinglivet igen, så vi købte en ny Hobby Elegance i Ålum i april. Den havde vi i 15 år."}, {"type": "figure", "caption": "", "page": 141, "file": "assets/images-bog2/p141_01.jpg", "dim": [786, 520]}, {"type": "figure", "caption": "", "page": 141, "file": "assets/images-bog2/p141_02.jpg", "dim": [781, 519]}, {"type": "para", "text": "Vagn har altid været god til at vedligeholde huset. Det var altid ham, der malede. Jeg bildte mig ind, at jeg ikke kunne gøre det godt nok, men lysten var der heller ikke. Mens Lars og jeg var i Skotland til dans i påsken 1990, malede Vagn i gæsteafdelingen. Det var selvfølgelig dejligt, men da vi kom hjem, var hele huset beskidt, så der var noget at gå i gang med. Godt nok malede han, men det var mig, der skulle gøre rent bagefter. Senere på året malede han udvendigt samt vinduer og døre, og sidst på året fik den lange gang en tur. I foråret 1992 flyttede Lars om i kælderen og fik soveværelse i det mindste værelse. Han købte også en CD-afspiller samme forår. Den sommer holdt vi kun to dages sommerferie. Vi tog et hotelophold på Fyn, mens Lars og Anne-Mette var på træningslejr. Resten af sommeren gik med at lave en lillebitte udbygning, nemlig en karnap ud til vejen. Vagn startede den 18. juli og var færdig den 27. juli. Den 16. august indviede vi den, idet vi havde inviteret 20 gæster. Det var nok ligeså meget for at markere, at vi havde boet i huset i 20 år. Helle og Lone Griis hjalp til og fik 300 kr. hver."}, {"type": "para", "text": "Samme år fik mor og jeg hvert sit 14” TV til køkkenet i julegave. Mor fik desværre ikke megen fornøjelse af sit, idet hun døde året efter. I april 1993 blev der gravet ud til en ny terrasse ved køkkenet. Folk troede, at vi skulle have en swimmingpool, så stort var hullet, men det blev en terrasse med klinker i stedet for de havefliser vi havde haft før. Og så blev den støbt. Samme forår købte vi nye hvide plast havemøbler med koboltblå hynder."}, {"type": "para", "text": "Og fornyelserne fortsatte: I november 1993 fik vi skiftet tæppet ud i kontoret, og i stedet for det kedelige grå kom der et pænt støvet blåt tæppe på. Året efter syede jeg, tro det eller ej, gardiner til badeværelset, og Vagn friskede strygeværelset (Lars’ gamle børneværelse) op med nye elementer og bordplader, i køkkenet fik vi ny bordplade og nye fliser, og garagen fik nyt tag. I foråret 1995 solgte vi alle de udendørs fliser for 2000 kr. og købte nye, hvilket pyntede gevaldigt. Vi købte ny videoafspiller hos Hadsten Radio samme forår. Prisen var 12.400 kr., men vi fik den for 10.600 kr., og vi købte nyt videokamera."}, {"type": "para", "text": "Efter sommerferien kunne vi ikke forstå, at vi havde brugt næsten et års forbrug af strøm sommeren over. Det viste sig, at kælderpumpen var defekt, så vi fik Reinholt til at skifte den. Efter den tid tjekkede Vagn strømforbruget jævnligt. I 1996 var det kælderens tur til at få lidt fornyelse: Vi købte nyt tæppe til det store værelse i kælderen magen til tæppet i kontoret, og væggene blev malet lyseblå. For en gangs skyld blev jeg betroet dette job. Lars selv lavede nye stikkontakter, da han i en tidlig alder viste talenter inden for elektrikerfaget. Han kunne faktisk være kommet i lære i elektrikerfirmaet Deleurans Efterfølger, der arbejdede for Arkitektskolen, for det skete, at Lars var med sin far på arbejde, og Ivan Pedersen, som ejede firmaet, havde spottet hans evner, men knægten ville noget andet. Jeg fik ”Det Hvide Hus” til at sy koboltblå gardiner til kældervinduerne, og hængte dem så selv op. Lars købte et 25” TV til 5.000 kr., og nu var kælderen blevet til en rigtig hyggelig ungdomsbolig, hvor Lars tilbragte meget af sin fritid."}, {"type": "para", "text": "I 1997 købte vi nyt Vestfrost køleskab, fordi det gamle var gået i stykker, og vi købte tæppe til at ligge under sofabordet og tilsvarende løber, der kunne ligge tværs over gulvtæppet der, hvor vi gik mest og samtidig dække over nogle pletter, som vi ikke formåede at fjerne. Samtidig solgte vi vores markise for 1500 kr., som vi havde købt brugt af Alices forældre i Tårs for 1600 kr. Året efter købte vi to nye gule markiser for nogle af vores sølvbryllupspenge, for solen var for kraftig på vest-siden, når der skulle laves aftensmad."}, {"type": "para", "text": "Den 6. september 1997 holdt Anna-Lise og Tage deres 1-års bryllupsdag i form af en stor fest, og mens vi festede, brød nogen ind i vores hus. Da vi kom hjem om søndagen, kunne vi mærke luften fra den åbentstående dør ved pengeskabet i trapperummet. En dør vi aldrig selv brugte. Indbrudstyvene havde brugt den som indgang og som flugtvej ned over markerne. De havde blandt andet taget videokamera, kamera, decodebox og guldsmykker. Det er rigtig modbydeligt at komme hjem og opdage, at nogen har gennemrodet sit hus og fjernet ting, der betyder noget for en. Og det værste af det hele var, at selvom vi havde billeder af smykkerne, så fik vi ikke det for dem, som de var værd. Vi købte et nyt videokamera senere på året. I november 1997 malede Vagn stuen, og i december malede han gæsteværelset. I foråret 1998 lavede Vagn stern på huset og havde blandt andet et 25 m stillads ved indgangssiden."}]}, {"title": "Arbejde, fusk og foreningsliv", "blocks": [{"type": "para", "text": "I starten af 90’erne havde jeg stadig to jobs, hvilket betød mere end fuldtids arbejde, og også arbejde om aftenen. Jeg ville gerne være fuldtidsansat på Teknikum, som det hed dengang, og i 1994 hjalp den daværende leder af Adgangskursus, Ole Olesen, mig til at få min drøm opfyldt. Jeg kunne nu vinke farvel til Handelshøjskolen, og selvom de senere henvendte sig og ville have mig tilbage, holdt jeg fast i min beslutning om kun at have én arbejdsplads. Ole Olesen var et elskeligt menneske. Han var høj og slank, og han levede meget sundt og motionerede. Men på trods af dette, fik han kræft og besluttede sig derfor for at gå af i efteråret 1996. Han havde også hjulpet mig til at blive lektorbedømt i 1994, og dengang blev man det ikke bare automatisk. Jeg skrev en ansøgning, hvor jeg skulle gøre rede for min undervisning og undervisningsmateriale i alle årene, og efterfølgende var jeg til tre samtaler, hvor bl.a. Ole Olesen og min tillidsmand var til stede. Her skulle jeg så gøre mundtligt rede for de metoder, jeg havde brugt og det materiale, jeg havde fremstillet. Samtidig blev der foretaget evalueringer af mig i mine klasser. Det hele resulterede i, at jeg kunne kalde mig lektor med dertil hørende lektortillæg fra den 19. maj 1994. Ole Olesen havde også været elev hos mig, da jeg kørte mine franskkurser på Teknikum, og han var en dygtig elev, der stillede mange spørgsmål. Da han så holdt afskedsreception, var vi 8 kvindelige kolleger, der på skift rejste os op og holdt tale for ham samt gav ham en rød rose hver. Han døde kort tid senere, den 21. december 1997, 61 år gammel."}, {"type": "para", "text": "Ud over min undervisning havde jeg også mindre og større opgaver på Teknikum. Jeg kørte i tre år franskkurser for ansatte, jeg underviste i engelsk på åben uddannelse om aftenen og havde i 1997 Cambridge kurser på Teknikum. I 1992 blev jeg spurgt, om jeg ville oversætte de forskellige afdelingers studieordninger til engelsk. Det var et større arbejde, og jeg kendte på det tidspunkt ikke til brugen af PC. Jeg havde min elektriske skrivemaskine, og den tjente mig fint dengang. Jeg havde ikke forestillet mig, at jeg kunne omstille mig og komme til at skrive på computer. Jeg tjente naturligvis ekstra ved alle mine opgaver, og pengene kunne vi jo godt bruge. Jeg har altid elsket at oversætte, så de opgaver var en slags hobby for mig. Vi havde i 90’erne en rektor, der hed Harry Svanhede Pedersen. Første gang, jeg talte rigtigt med ham, var til Teknikums 75-års jubilæum, den 1. november 1990. Da var der fest på skolen, og ægtefællerne var inviteret med. Festen sluttede med en fantastisk Henning Stærk koncert i festsalen. Denne aften gik den 47-årige Svanhede rundt med en form for borgmesterkæde (rektorkæde) om halsen, og han kom hen og hilste på Vagn og mig. Dette blev optakten til et nærmere bekendtskab, og selvom han for flere år siden gik af, møder jeg ham engang imellem og har lige fået en hilsen fra ham. Efter vores møde sendte han flere gange bud efter mig, hvis han skulle holde en tale eller skrive noget på engelsk. Han var ikke dårlig til engelsk, men han følte sig mere tryg, hvis jeg havde været inde over. Der skabtes derved et tillidsforhold mellem os, som senere kom mig til gode, mere præcist den 12. maj 1997. Den eftermiddag ringede min telefon på mit kontor, og en stemme sagde: ”Det er Harry Svanhede. Ved du godt hvem jeg er?” (det var hans form for humor). Han bad mig komme ned på sit kontor til en snak, og da jeg få minutter senere stod der, tilbød han mig jobbet som International Koordinator. Jeg vidste ikke, at der fandtes en sådan på skolen, for internationaliseringen var i sin spæde start. Det var indtil da en tjans, som Fagrådsformanden på Elektroafdelingen Herluf Houlberg havde haft ved siden af sin rigtige stilling. Vi havde kun nogle få udenlandske studerende dengang, og ikke mange tog til udlandet. Det kom derfor som en overraskelse, at jeg fik tilbudt jobbet. Tænk, at man på denne mandsdominerede arbejdsplads tilbød jobbet til en kvinde, og så tilmed en humanist. Da Svanhede til mit 25-års jubilæum i 2006 holdt tale for mig, afslørede han, at det havde været hans idé. Jeg vidste ikke, hvad jeg skulle sige, for jeg var ikke helt klar over, hvad jobbet indebar. Dog vidste jeg, at det var administrativt, og det havde jeg ikke prøvet før, så her lå der en stor udfordring. Jeg gik hjem og tænkte over det i et par dage og snakkede med Vagn og Lars om det, og så takkede jeg ja. Det har jeg aldrig fortrudt. Jeg var dog meget nervøs over, hvordan den første tid skulle gå, og om jeg i det hele taget ville få noget at lave, men det havde jeg ikke behøvet at bekymre mig om. Selvom jeg havde mange møder med Svanhede og Houlberg op til sommerferien, så blev jeg slet ikke lært op. Houlberg sagde, at jeg selv skulle forme mit job, men jeg kunne nu godt have tænkt mig at have fået lidt flere staldfiduser, inden Houlberg samme sommer gik på pension. Men herefter var Svanhede en stor støtte for mig, og det var også ham, jeg refererede til. Jeg var på flere rejser sammen med ham, og udover at være dybt professionel, så var han også en meget hyggelig mand, og jeg tror, han havde stor respekt for mig. Han var gift med den lidt ældre Ilse Svane, som sad på økonomikontoret, men der gik mange år, før jeg fandt ud af den sammenhæng, for de viste sig ikke ret tit sammen. Ilse cyklede og Svanhede kørte i bil på arbejde, men år senere besøgte Vagn og jeg dem i deres sommerhus i Hune."}, {"type": "para", "text": "I starten af min nye periode underviste jeg 50 %, hvilket jeg var glad for. Jeg elskede mine AKklasser, og jeg fik altid gode eksamensresultater. Det bedste resultat opnåede jeg i 1997, hvor gennemsnittet i en klasse var 9,7. Jobbet som lektor medførte også, at jeg to perioder om året var ude som censor, hvilket var meget inspirerende. Jeg boede som regel privat og kunne derved slå to fluer med ét smæk. Når jeg var i Ballerup, boede jeg som regel hos onkel Erik i Hundige og senere hos min veninde Ulla i Rødovre eller Marianne i Willemoesgade. Hvis jeg var i Odense, boede jeg hos Aase og Viggo i Glamsbjerg, hvor jeg også så min kusine Lenette, som fik sin første søn Aleksander i november 1994. Alle sproglærere ved de danske teknika holdt et årligt sprogseminar, og her lærte vi hinanden godt at kende og udvekslede erfaringer, og vi havde altid en eller flere oplægsholdere. Jeg har flere gange holdt oplæg, bl.a. i 1996, hvor jeg holdt et 50-min. oplæg om Takt og Tone. Mens Storebæltsbroen blev bygget, læste vi i teknisk engelsk om arbejdet, og den 4. oktober 1995 arrangerede jeg en ekskursion for 50 studerende til Storebælt for at se projektet. På Teknikum skulle der i 1995 ansættes en ny sproglærer, og jeg skulle sammen med en kollega, Annemarie Larsen, være med i bedømmelsesudvalget. Vi havde flere til samtale, men valget faldt på Lene Vinten Madsen, som underviste i både tysk og engelsk. Hun blev en god kollega og ven, men hun satte os også på en hård prøve ind imellem, idet hun var meget dominerende og manipulerende. Hun var dog inderst inde et meget sødt menneske, og jeg holdt, synes jeg selv, en meget god og ærlig tale her i december 2013, da hun i en alder af 65 år gik på pension. Desværre ville skæbnen, at hun samtidig med beslutningen om at stoppe fik konstateret lungekræft, og det har nu bredt sig til milt, lymfer, ryg og hoved. Hun er i gang med en kemokur, men der skal mirakler til for at redde hende. Det havde hun ikke fortjent."}, {"type": "para", "text": "Det var også i 1995, at vi dannede en pigeklub på Teknikums Adgangskursus. I starten besøgte vi hinanden til små hyggelige middage eller ostebord, men senere blev klubben udvidet til at dække hele skolen, og nu skulle vi gå i biografen og være kulturelle. Teknikum havde også en motionsklub, som jeg benyttede mig af i nogle år, hvor jeg cyklede 10 km hver tirsdag eftermiddag. Mit nye job som koordinator indebar også, at jeg skulle rejse ind imellem, men det havde jeg ikke noget imod. Faktisk var jeg et år før min nye stilling på et kursus sammen med Annemarie i Bruxelles og Luxemburg for at besøge de forskellige europæiske instanser, såsom EU-Parlamentet og NATO. Det var en rigtig god tur arrangeret af Sproglærerforeningen, og den foregik med bus i vinterferien. Allerede det første semester i mit nye job var jeg på tre rejser. Den første gik til Berlin, hvor jeg var til møde sammen med andre europæiske koordinatorer i et netværk, den anden gik til Kempten i Sydtyskland, hvor jeg besøgte vores samarbejdspartner, og den tredje gik til Manchester, hvor jeg var på en uges kursus på universitetet og samtidig besøgte vores partner i Salford lige uden for Manchester. Kurset hed ”Tæt på Manchester”, og det skulle give os et indblik i engelske samfundsforhold og byen Manchester. Det var en meget lærerig uge, hvor jeg kom til at kende de 9 andre kursusdeltagere fra andre institutioner, men vi boede alle privat. Det er altid sjovt at se et lands kultur fra et privat hjem, men i mit tilfælde var det en prøvelse. Familierne fik penge for at have os boende, så bagefter nævnte jeg i evalueringen, at den familie, jeg havde boet hos, Caroline & Mark Swindells, ikke burde have nogen boende i fremtiden. De var et ungt par med tre børn, men selv om konen var hjemmegående, havde de slet ikke overskud til at tage sig af en logerende. Vi blev hentet af vores værtsfamilier på et opsamlingssted midt på aftenen, og vi havde ikke fået aftensmad. Derfor forventede jeg, at der stod mad på bordet, når vi kom frem. Men da vi kom frem, fik jeg anvist mit værelse på første sal, og så var det bare godnat. Jeg havde gaver med til familien, en bog om Danmark, to æsker LEGO og en bamse til den mindste. Nu har de engelske huse ikke ord for at være alt for godt isolerede, og det var i oktober måned, hvor det blæste en del. Mit værelse var så koldt, at jeg måtte tage 5 lag tøj på, når jeg opholdt mig der, og der var faktisk lige så koldt i resten af huset. Det var ikke så sært, at ungerne rendte rundt med snottet hængende ud af næsen. Der var badeværelse på første sal – uden nøgle, men jeg kom aldrig i bad, da badekarret var fyldt op med legetøj, og jeg ville heller ikke gå i bad uden at kunne låse. Der var en lille vaskekumme med koldt vand på mit værelse, så her vaskede jeg mig nødtørftigt, også håret, men spejl var der ikke noget af. Maden var et kapitel for sig, og jeg har aldrig smagt lignende hundeæde. Jeg sørgede for det meste for at have en aftale med de andre om at gå ud og spise om aftenen, men det skete, at jeg var hjemme og måtte tvinge den afskyelige føde i mig. Caroline og Mark var dog meget søde, og jeg prøvede da også på at lade som ingenting. Samtidig oplevede jeg en masse uden for hjemmet."}, {"type": "figure", "caption": "", "page": 144, "file": "assets/images-bog2/p144_01.jpg", "dim": [774, 1168]}, {"type": "para", "text": "Vi var på tur til Haworth, hvor vi så Brontë-søstrenes hjem og gik rundt på heden, hvor de tre søstre har gået i deres lange gevandter og med kyser på hovedet. Det var meget spændende. Vi var til kurser og forelæsninger på universitetet, vi spiste frokost på pubs, vi var på besøg på en bomuldsfabrik, hvor vi hørte om Manchester og den industrielle revolution, og vi var på rådhuset og blev modtaget af en af rådmændene. Der blev lavet et orienteringsløb for os i Manchester, hvor vi skulle svare på spørgsmål ved at interviewe de lokale, og vi gik i teatret en aften. Jeg var også på besøg alene, bl.a. i The Magistrate’s Court, hvor jeg fulgte en retssag, samt i Crown Court, og vi var tre piger der var på et center for misbrugere. Den sidste aften, jeg var hos familien, var der Halloween, og her blev jeg inviteret med over til en anden familie på vejen, som holdt fest for gadens børn. Det var sjovt at opleve den tradition. Om aftenen tog jeg afsked med familien, for de havde ikke til hensigt at stå op næste morgen og sørge for, at jeg kom afsted med taxa. Jeg lånte deres vækkeur, og så måtte jeg selv komme op kl. 4.15. Det var skønt at komme hjem til Vagn og Lars, til mit dejlige varme hus, mit eget badeværelse og den gode mad."}, {"type": "para", "text": "I foråret 1998 var jeg på en rejse til Rouen i Frankrig sammen med Svanhede, og senere til Valencia, begge gange for at besøge universiteter."}, {"type": "para", "text": "Spørring havde en aftenskole, ledet af Mary Jensen. Her underviste jeg i nogle år (1992, 1993, 1994, 1995 & 1996). Jeg havde tidligere undervist ovenpå i den gamle skole, men i denne periode foregik undervisningen i forhuset. Eleverne var velkendte ansigter, såsom Anna-Lise Jørgensen, Inge Lise og Ove Rasmussen, Henning Christiansen, Mogens Lading, Leo Dahl, Hans Ørsnæs osv. Det var hyggeligt, og vi sluttede altid sæsonen af med en frokost. I 1996 var der en, der havde glemt smørret, så jeg tilbød at køre hende hjem efter det. Vi stiger snakkende ind i bilen, og uden at se mig for eller tænke mig om bakker jeg lige ind i Mogens Ladings bil og ødelægger hans kofanger. Der var næsten ikke noget til syne på vores Volvo, men hvor var jeg gal på mig selv. Det kostede os 4900 kr. Det skete også, at Hyggeklubben hyrede mig til at holde foredrag om rejser, bl.a. om vores rejse til Gambia. Her hjalp Lars mig med oplægget, som jeg holdt i januar 1998."}, {"type": "para", "text": "Også i hjemmet på Østervang underviste jeg i perioder, en eller to elever ad gangen. I 1993 gik Alice til fransk hos mig. Hun syntes, det kunne være spændende at lære lidt fransk, og hun var også en dygtig elev. I 1997-1998 underviste jeg Ewa og Zdislaws datter Patricia i fransk, da hun havde problemer med at følge med i skolen. Hun kom en gang om ugen i en time, og jeg tror jeg fik 100 kr. om måneden for det."}, {"type": "para", "text": "I starten af 90’erne arbejdede Vagn for tømrerfirmaet Marstrand-Nielsen, og Lars var somme tider med sin far på arbejde. Således også i uge 6 i 1991, hvor Lars var i forældrepraktik. Bagefter skulle de skrive en rapport i klassen om ugen, der var gået, og Lars sluttede af med at skrive, at nu havde han fundet ud af, hvad han ikke skulle være. Efter 16 år i samme firma, fik Vagn job hos et mindre firma ejet af Sten Hansen, og der startede han den 1. august 1994, men det var et lille firma med en ung mester, som kun så på pengene, så det var hårdt, og Vagn var ikke altid enig med Sten. Vi begyndte også så småt at komme sammen privat, for Stens kone Lene var rigtig sød.  Året efter så Vagn en annonce i avisen, hvor Arkitektskolen søgte en fagbetjent i et nyt job. Stillingen gik ud på, at vedkommende skulle vedligeholde bygningerne og bl.a. hjælpe til ved udstillinger. Det tiltalte herren, og vi fik strikket en ansøgning sammen, som han sendte afsted. Der var over 70 ansøgere til stillingen, og Vagn blev kaldt til samtale. Han spurgte mig lidt til råds om, hvad han skulle sige, hvis de spurgte ham, hvorfor han havde søgt jobbet. Dertil svarede jeg: ”Du skal bare sige, at det lige er dig”. Sådan svarede han, og han fik jobbet og kunne begynde den 23. oktober 1995, noget af det bedste, der er sket for Vagn arbejdsmæssigt. I juli samme år fik han tilbudt formandsjobbet i sit gamle firma Marstrand-Nielsen, men han takkede heldigvis nej."}, {"type": "para", "text": "På Arkitektskolen fandtes der en lille eksklusiv herreklub, som Vagn blev optaget i. Første gang, de var hos os, var den 31. januar 1998, og de var kun 5 (administrator, skoleforvalter, bygningsforvalter, skolebetjent og Vagn). Jeg serverede 7 retter mad til frokost, og efter maden blev der budt cigarer rundt og drukket cognac til kaffen. Jeg var modstander af det med cigarerne, men det skulle der til, fik jeg at vide. Det var værst med røgen, for man skulle skære sig igennem den. Jeg måtte flere gange ind i soveværelset og trække frisk luft. Klubben består stadig, selvom nogle af medlemmerne er skiftet ud og døde, men cigarerne er heldigvis afskaffet."}, {"type": "para", "text": "Vagn havde imidlertid ikke kun sit job at passe. Han var stadigvæk den flinke mand, der ikke kunne sige nej, når familie og venner spurgte ham, om han ville hjælpe med dit og dat. Og nu kommer der en liste over nogle af de projekter, han påtog sig fra starten af 90’erne til 1998, hvor denne bog slutter."}, {"type": "para", "text": "Når vi kom hjem til mor, var der næsten altid noget, der skulle laves, og det havde Vagn ikke noget imod. Hun havde som regel lavet en liste til ham. Desværre fik det en brat ende, da mor jo døde i 1993. i foråret 1990 isolerede han i Thorshøj, og året efter hjalp vi alle til med at male stue og badeværelse samt gå i haven og klippe hæk. Vagn var tit i haven, når vi besøgte mor i weekenderne. Svend Sønderup havde også altid nogle projekter til Vagn, fx i august 1990 og oktober-november 1991. Jeg har ham mistænkt for at finde på nye projekter, fordi han elskede at have Vagn derude, næsten ligesom en søn. Han skulle bare have tænkt på at skønne lidt mere på det og måske betale lidt for det, for han havde penge nok. Heller ikke da de døde, fik vi de par ting, de havde sagt, vi skulle have. Vi ville gerne have haft et minde om Marie og Svend, men så langt tænkte arvingerne ikke, og Svend havde ikke fået skrevet noget ned."}, {"type": "para", "text": "Jørn Griis havde også brug for hjælp, således i juni og juli 1990, juli 1994 og 1997."}, {"type": "para", "text": "Grete og Poul fik nye lofter i soveværelset og i stuen i april 1991, som Vagn slog op, og i 1998 satte han nyt køkken op derovre."}, {"type": "para", "text": "Pouls søster Birgit og dennes mand Hans hørte også til vennekredsen. De boede i Hornslet, og i foråret 1991 byggede Vagn en udestue for dem, som vi indviede ved en fest den 20. juli samme år. Vagn var ikke sen til at hjælpe sin bror Tage, for hjælpen gik begge veje. I juni 1995 satte han nye skabe op på deres badeværelse, men kronen på værket var den flotte udestue, de byggede deroppe i 1997, nok den flotteste udestue, vi nogensinde har set. I februar 1996 stod den på nye bordplader hos Tage. Der var ikke penge mellem de to brødre, og jeg husker ikke, om vi har givet Tage noget for al den hjælp, han ydede hos os, men efter udestueprojektet fik Vagn af Anna-Lise og Tage en stor og flot skildpadde i sten til at stå ude i haven. Vi tog den altid ind om vinteren og havde den stående i stuen, for vi syntes, det var synd, at den skulle stå ude i al slags vind og vejr."}, {"type": "para", "text": "Tages nabo Preben, som var frisør og Vagns tidligere fiskekammerat, var ikke særlig fingernem. I flere år klippede han Vagn gratis, når det kunne passe sig, så Vagn stillede også gerne op, når Preben havde brug for hjælp. I oktober 1991 skiftede Vagn vinduer for Preben, og i februar 1993 skulle salonen have en ansigtsløftning, hvorefter der skulle skiftes vinduer et andet sted i marts 1995."}, {"type": "para", "text": "Alice og Reinholt havde tit mange gæster i kælderen, så Reinholt kom med en opgave til Vagn i marts 1992: 4 borde, der ikke måtte fylde for meget, når de var stillet op og som kunne klappes sammen og nemt opbevares. Den opgave løste Vagn til perfektion, og de borde har været brugt et hav af gange, både hos ejermanden men også andre har lånt dem ved festlige lejligheder. Vi var dog dem, der havde førsteret på at låne dem."}, {"type": "para", "text": "Vores nabo Mary nød også godt af at have en tømrer som nabo. Vagn slog loft op i hendes bryggers i november 1993, og da han ville holde lidt sjov med Mary og sagde, at det jo blev dyrt at få lavet tømrerarbejde en søndag, replicerede hun prompte, at han da bare kunne være kommet en hverdag. Jo, Mary kunne være hurtig i replikken og kunne godt lide, når Vagn lavede sjov med hende. Niels Høj hørte også med til vennekredsen, og ham hjalp Vagn med at isolere i november 1991, lige som han også hjalp Niels i august 1995 med en gavl og igen i 1996. Og selvom Leif Nilaus var meget handy selv, hjalp Vagn også ham med to vinduer i juni 1995."}, {"type": "para", "text": "Doris og Poul Erik fik nye vinduer i stuen i december 1992, som Vagn monterede."}, {"type": "para", "text": "I 1995 og 1996 lavede Vagn dueslag til post ude i danseklubben ÅS, hvilket han fik betalt. Desuden lavede han flere gange indvendig beklædning i biler for Lyngfeldt, bl.a. i juni 1992, 1994 og to biler i 1996, også mod betaling."}, {"type": "para", "text": "Den eneste gang, Vagn har sagt nej til at hjælpe nogen, var da Lars fra ÅS og hans kone Pia spurgte, om han ville hjælpe dem med at bygge hus i 1994. Det var en klog beslutning."}, {"type": "para", "text": "Vi var ikke længere så aktive i foreningslivet. I september 1990 blev jeg valgt ind i klasserådet i Lars’ klasse, og samtidig kom jeg i bestyrelsen for støtteforeningen i dans. I 1995 kom jeg i Sportsudvalget i ÅS, og året efter blev jeg valgt til revisor for Spørring Husmoderforening, en post jeg stadig bestrider."}]}, {"title": "Ferier og vejr", "blocks": [{"type": "para", "text": "Den 14. juli 1990 drog vi 7 personer afsted på fiskeferie i Skotland. Det var de tre fiskekammerater Vagn, Tage og Preben, og de havde inviteret deres koner og Lars med. Vi kørte i tre biler, hvilket var det mest praktiske, og så var vi også uafhængige. Vi var blevet advaret mod dårligt vejr i Skotland, men det skulle vise sig, at vi fik 16 dage med fantastisk flot vejr (vi fik en enkelt regnbyge den første aften), alt for varmt til at fiskene ville bide på, men det kommer vi tilbage til. Vi sejlede Esbjerg-Newcastle med Winston Churchill kl. 19.30 og havde kahytter i bunden af skibet. Vi skulle have haft en svensk dame inde i vores kahyt, men hun ville absolut ikke dele kahyt med Vagn, så efter megen snak frem og tilbage forbarmede vi os over hende og lavede en damekahyt og en herrekahyt. Vi havde bestilt bord i restauranten, hvor vi fik det store kolde bord, og bagefter gik vi i danserestauranten indtil kl.0.30. Da vi kom ned i kahytten, sov den svenske dame trygt. Næste dag kl. 15 var vi i land."}, {"type": "para", "text": "Det gik fint med at finde vej, og dengang var der ikke noget, der hed GPS. Vi havde gode kort med, og vores bil kørte forrest. Tro det eller ej, jeg var kortlæser, og vi kørte ikke forkert én eneste gang, på trods af at jeg også havde gang i strikkepindene. Vi kørte gennem Northumbria Nationalpark, og pludselig var vi i Skotland. Vi nåede Edinburgh, parkerede bilerne og spadserede til slottet, hvor de var i gang med at stille an til Tattoo i august. Hvert år starter de med opstillingen i juni og er færdige med at pille ned i oktober. Fra Batteriet var der et betagende vue, og herfra affyres hver dag kl. 13 et enkelt skud, som byens indbyggere kan stille deres ure efter. Men hvorfor ikke på slaget 12? Skotternes svar er ligetil: Det er billigere at affyre et enkelt skud kl. 13 end 12 skud ved middagstid! Vi var inde og se Scottish United Services Museum, hvor der var uniformer, våben og rustninger fra de skotske regimenter, og vi så the French Prisons, hvor fanger fra Napoleons hær havde ridset graffiti i de gamle mure. Vi var meget imponerede over slottet. Vi gik ad The Royal Mile, der løber næsten 2 km fra slottet til kongepaladset Holyrood House, og undervejs købte Anna-Lise en flot kilt."}, {"type": "para", "text": "Vi boede på B&B, hvor vi kunne få vores køleelementer frosset ned, så vi altid havde kolde øller. Næste dag spiste vi frokost ved Loch Lomond, en sø der er godt 36 km lang og 8 km bred. Derfra havde vi en meget flot køretur til Oban, som vi nåede om eftermiddagen i bagende varme. Vi var kommet til Skotland og havde sat næsen op efter at kunne nyde en whisky på en pub, hvor der var udeservering i det gode vejr, men der blev vi skuffede. En pub var et mørkt og skummelt hul, hvor der var adgang forbudt for børn, så vi måtte finde et cafeteria for at få noget at drikke. I Oban fandt vi et B&B med plads til 7 personer, så det var perfekt, og vi havde fået billetter til underholdning om aftenen. Underholdningen varede i 2 timer og bestod af et 3-mands orkester, to dansende piger i skotskternede dragter og en sækkepibespiller i kilt. En time havde været rigeligt, og Vagn udvandrede sammen med mange andre før tid, idet ”larmen” var øredøvende. Vi andre holdt ud til den bitre ende – man er vel dannet."}, {"type": "para", "text": "Folk, der udlejede B&B, flyttede ofte selv ud af huset, og i dette tilfælde havde vi hele dagligstuen for os selv. Vi brugte at se det video, vi havde optaget om dagen, og det var naturligvis Lars, der fandt ud af teknikken."}, {"type": "para", "text": "I Oban så vi næste dag et glasværk og sejlede ud til en sælkoloni. Byen er kendt som ”Gateway to the Isles”, og med sine 7.000 indbyggere er den vestkystens største havneby og det livligste turistrevir ude vestpå. Især på kajen herskede der en varm og hyggelig stemning med masser af liv, når de mange færger stævnede ud til øerne i Indre og Ydre Hebrider. Vi så naturligvis også Oban Distillery. Vi blev så gode venner med vores værtinde, at vi forærede hende to hjemmelavede papirklip, da vi sagde farvel."}, {"type": "para", "text": "Turen gik nu videre til Fort William, hvor vi gjorde et stop, og videre til Loch Ness, som under sin mørke og hemmelighedsfulde overflade gemmer et af verdens største uløste mysterier – ”Nessie”. Vi stod længe og spejdede ud over den 37 km lange, 1,5 km brede og 200 m dybe sø, men intet skete. Vi har et billede, hvor jeg står og spejder efter uhyret, men Lars mente, at jeg med mit krøllede afrohår måtte være uhyret. Han kunne godt lide at drille sin mor, og jeg må da også indrømme, at lignede jeg ikke et uhyre, så lignede jeg en puddelhund."}, {"type": "para", "text": "Vi fik tre lækre værelser på et fint hotel, Loch Ness Lodge Hotel, til kun 15£ pr. person med morgenmad, og Lars var gratis, men så måtte han også sove imellem os i dobbeltsengen, hvilket var varmt og trangt. Den aften spiste vi en dejlig middag i restauranten. Næste dag så vi en mekanisk model af Loch Ness uhyret, og på afstand så det meget livagtigt ud. Drumnadrochit, hvor vi boede, har vundet berømmelse overalt i verden for sit Loch Ness Centre – Skotlands officielle søuhyreudstilling. Her findes alle beviserne for, at Nessie gemmer sig et sted derude."}, {"type": "para", "text": "Vi kørte videre til Inverness, Højlandets hovedstad med 40.000 indbyggere. Vi var inde og se Castle Stuart, hvor vi også kunne have lejet os ind på B&B (75£). I Nairn fik vi B&B for 12£ og halv pris for Lars hos et ældre ægtepar, der havde orden i sagerne. Der var utroligt rent og pænt, og vi fik lov til at sidde i baghaven og drikke kaffe og spise aftensmad. På trods af, at kirken lå lige ved siden af, fik vi både øl og snaps til maden. Nairn har takket være en velgørende kombination af sol, hav, gyldne strande og fortrinlige golfbaner udviklet sig til en af Skotlands mest populære feriebyer. Lars var ved stranden og bade inden aftensmaden, og efter maden spillede vi kort og så video. Lars førte regnskab over kortspillene og lagde til slut alle point sammen. Det viste sig, at han selv blev vinderen. omkreds Vores mål var Grantown-On-Spey, hvor vi havde lejet tre mobil homes på en campingplads. Vi kunne godt have nøjedes med to, men igen satte vi privatlivet i højsæde, og det skulle være sådan, at man kunne trække sig tilbage, når man havde lyst. Det var virkelig en luksusbolig, vi havde lejet, med masser af plads og helt ny. Der var en stor stue med en hjørnesofa, hvor der snildt kunne sidde 15 mennesker, foruden at der var to værelser, køkken med ovn og grillovn til toast og bacon, og badeværelse med badekar og bruser. Lars havde sit eget værelse med dobbeltseng, så han kunne rigtigt brede sig. Campingpladsen var flot og ren, og der var en dejlig rolig atmosfære. Man kunne nemt spadsere ind til byen, som var meget hyggelig med pæne forretninger og flinke mennesker. Mændene var inde i den lokale fiskesportsforretning og købe det manglende udstyr, og de fik at vide, at de for at kunne fange laks, skulle bruge ”small hooks”. Det lød mærkeligt, at man skulle bruge små kroge for at fange store fisk, og i starten troede de, at det betød, at de skulle tage små hug med fiskestangen. De var nu også svære at forstå, de skotter."}, {"type": "figure", "caption": "27. juli, Lars med dagens fangst: 2 kg, 63 cm og 28 cm i", "page": 149, "file": "assets/images-bog2/p149_01.jpg", "dim": [766, 1192]}, {"type": "figure", "caption": "", "page": 149, "file": "assets/images-bog2/p149_02.jpg", "dim": [633, 660]}, {"type": "para", "text": "Søndag den 22.7. kørte vi på the Whisky Trail, hvor vi besøgte det berømte Glenfiddich Distillery Guiderne have naturligvis kilt på, og vi havde en dansk guide, vild luksus. Turen sluttede af med whiskysmagning, dog ville de ikke servere whisky for vores to chauffører, så de fik et glas vand på stedet og en miniflaske whisky med sig. Preben samlede på glas med logoer på, og mens vi sad og nød whiskyen (de, der nu kunne lide whisky), hviskede Preben til mig, om jeg ikke ville putte et glas ned i min rygsæk. Jeg var ikke meget for det, men jeg indvilgede og ville forsigtigt liste glasset ned i tasken med det resultat, at jeg kom til at slå det mod bordkanten, så alles opmærksomhed blev rettet mod mig og min forbrydelse. Da alle var færdige med at glo, luskede jeg ligeså stille glasset ned i tasken. Det var både første og sidste gang, jeg stjal glas til Preben, som efter whiskybesøget fik et andet ønske opfyldt, nemlig at se en flok ægte skotsk højlandskvæg, som gik og græssede lige over for destilleriet."}, {"type": "para", "text": "Det var meningen, at mændene ville have hyret en fiskeguide (Ghillie) til at tage med dem på fiskeri om mandagen, men da han var optaget netop den dag, besluttede de at droppe ham og selv prøve at finde ud af fiduserne. Mandag morgen kl. 4 tog Vagn og Lars på fiskeri i River Spey. 4½ time senere kom de hjem uden fisk. Senere på dagen fik Lars en spinnerstang – måske det kunne hjælpe. Om aftenen tog mændene og Lars afsted igen, og vi piger hyggede os hos Anna-Lise. Da jeg gik hjem kl. 23, løb kaninerne om benene på mig, men det havde vi vænnet os til. Jeg tog nattøj på, børstede tænder og tændte op i pejsen. Så tog jeg en dyne ind på sofaen og lå og så TV, indtil fiskerne kom hjem kl. 0.30 – med 4 små ål!"}, {"type": "para", "text": "Næste dag tog vi piger til Inverness med en gammel skrammelbus og shoppede i 4 timer, mens mændene igen prøvede lykken. Vi havde lovet at købe orm til mændene, selvom de også selv havde gravet nogle op på campingpladsen. Busturen varede en time hver vej. Denne aften fiskede Vagn og Lars i 3½ time uden fangst, og næste morgen fiskede Vagn i 5 timer uden fangst. Samme eftermiddag kørte vi ind og fik Lars’ fiskestang byttet til en større til Vagn, og Preben købte hat og waders. Om aftenen var de igen afsted, mens jeg satte mig ude i det gode vejr og skar uroer. Jeg havde mit grej med. Dagens fangst: 0 fisk."}, {"type": "para", "text": "Natten til torsdag stod Vagn op kl. 3.30, og han tog på fisketur sammen med sine to fiskekammerater. Kl. 10 kom de hjem med to ørreder og en ål. Ørrederne var en foræring fra nogle skotter, der havde haft medlidenhed med de stakkels uheldige lystfiskere. Om eftermiddagen tog Ellen og jeg med ud og så, hvor mændene fiskede. Lars vekslede mellem at fiske og bygge sandslotte, og vi piger slikkede solskin og holdt øje med, om der var bid. Vi kunne tydeligt se, at fiskene sprang. Anna-Lises kilt Om aftenen var vi ude og spise på Spey Valley Hotel, hvorefter vi tog hjem og så video."}, {"type": "figure", "caption": "Tage og Preben har købt skotske kasketter,  mens Vagn låner", "page": 150, "file": "assets/images-bog2/p150_01.jpg", "dim": [652, 649]}, {"type": "para", "text": "Natten til fredag var det ”same procedure” for Vagn, og kl. 10 kom han hjem, helt knust. Han havde haft en kæmpe ørred på krogen, men den var sluppet væk! Det kan enhver lystfisker jo komme og sige, men vi troede på ham."}, {"type": "para", "text": "Den samlede ”fangst” blev 4 ørreder og nogle ål. Den ene ørred vejede 2 kg, målte 63 cm i længden og 28 cm i omkreds. Alle 4 ørreder var en foræring, og den største fik Vagn af den ”gamle” fisker. Fisken var fejlkroget og skulle derfor have været smidt ud igen. Alle fiskene kom i campingpladsens fryser, men hvordan skulle vi løse problemet med dem på hjemturen?"}, {"type": "para", "text": "Lørdag den 28. juli, vores 17-års bryllupsdag, pakkede vi og forlod denne dejlige plet. Vi gjorde holdt i Aviemore og handlede, og undervejs plukkede vi det flotteste lyng, som holdt sig meget fint. Vagn var ivrig efter at plukke en buket til mig netop denne dag. I Pitlochry så vi en berømt fisketrappe ved en dæmning og kraftværk, og gennem glasruder kunne man følge laksens langfærd til gydepladserne. I Dunbar fandt vi et B&B til 10£, ikke så fint og rent, men der var en stor fryser til vores fisk, og det var det vigtigste. Da værtinden åbnede døren, var vores første spørgsmål, om hun havde plads til 7 personer i huset, og det næste spørgsmål var, om hun havde plads til 4 fisk i fryseren. Vi måtte gerne bruge opholdsstuen og haven, og begge steder var der fyldt op af nips og havenisser. Vi var meget spændte på, om vi også kunne få fryseplads om bord på færgen næste dag, men der var ingen problemer, så vores fisk kom helskindede hjem. Vi havde bestilt én kahyt med 4 senge, så Vagn og Lars sov i det fælles soverum, mens vi andre sov i kahytten, Preben og Ellen i den samme seng. Kl. 15 næste dag var vi i land i Esbjerg, og inden vi skiltes og sagde tak for en dejlig ferie, fik vi en afskedswhisky på kajen."}, {"type": "para", "text": "I august samme år fløj mor og jeg til Oslo og besøgte Agathe og Harald i 5 dage. Det var rigtig hyggeligt, og de to ”gamle” penneveninder havde meget at snakke om. Vi kørte også en dag til Lillestrøm og besøgte Agathes far, Bjørnstad."}, {"type": "figure", "caption": "", "page": 151, "file": "assets/images-bog2/p151_01.jpg", "dim": [1139, 797]}, {"type": "para", "text": "I sommeren 1991 lånte vi Griis’ campingvogn i 12 dage, som vi tilbragte på Hanstholm Camping, vores yndlingscampingplads med de flinkeste værter. Lars var med os, hvilket han også var i 1994, hvor turen gik til Sverige. Per boede på det tidspunkt i Stockholm, hvor han arbejdede for SAS, og det var ham, vi ville besøge. Vi sejlede Grenå-Halmstad den 12. juli om morgenen, hvor vi spiste morgenmad på dækket i strålende solskin. Vi spiste frokost ved en sø og kørte til Växjö og videre til Lenhovda, hvor vi fik et hotelværelse. Det var en usædvanlig varm sommer, og bagefter fortrød vi, at vi ikke i stedet for hotelværelser havde lejet os ind i hytter, efterhånden som vi kom frem. For på hotellerne var der ikke mulighed for at sidde ude og spise, og det kunne vi godt have tænkt os. Det var næsten klaustrofobisk at sidde inde i restauranten og bagefter på det varme værelse. Næste dag kørte vi ind i Glasriket, hvor vi besøgte Målerås, Orrefors og Kosta Boda. I Målerås købte vi to flotte grønne skåle til Anette og Lars (Elbo og Vibekes Anette), som vi skulle til bryllup med samme sommer, og vi købte en elefant til Per. I Kosta Boda købte vi en flot grøn vase til os selv og to snebolde (lysestager) til Else og Jørn Griis, som vi skulle til sølvbryllup med samme sommer. I Orrefors købte vi en flot vase til vores nabo Mary. Vi fik et hotelværelse i Valdemarsvik på Hotell Viken, og her fortrød vi virkelig, at vi satte os ind i restauranten. Trods det at vi var de eneste gæster, tog det en time at få mad, og så var min laks oven i købet rå. Vi gik en tur efter aftensmaden, for vi skulle bare ud og have noget luft, idet vi senere på aftenen skulle se VM i fodbold på TV (fra Brasilien). Sverige skulle spille semifinale mod Brasilien om natten, så vi så TV til kl. 3.30. Sverige tabte 1-0. Til gengæld var morgenmaden fin. Torsdag den 14. juli ankom vi til Pers lejlighed i Stockholm kl. 16. Vi låste os selv ind på 3. sal, for Per kom først hjem fra arbejde kl. 18. Heldigvis var der kolde drikkevarer i køleskabet, så vi forsynede os og slog os ned på altanen. Lejligheden var hyggelig. Per tog os med ind i SAS-bygningen og viste os rundt i dette nye flotte glaskompleks, som også husede forretninger, caféer, restauranter, en tennisbane, swimmingpool, frisør m.m. Bagefter kørte vi ind til Stockholm, hvor Per gav middag på Ulla Winbladh Restaurant. Det var et fint sted, og det var rigtig hyggeligt at sidde udenfor og spise. Om fredagen kørte vi på egen hånd til Mariefred og så Gripsholm Slot, og Lars tog video af det hele. Da Per kom hjem fra arbejde, pakkede vi en madkurv og tog på picnic ude ved en sø, hvor Per og Lars efterfølgende badede. Madkurven bestod af dejlig kylling, salat, flutes, ost og naturligvis vin. Der var eventyrligt dejligt – varmt og stille. Bagefter kørte vi til Vaxholm, hvor vi tog med en gratis færge. Da vi kom hjem kl. 22, var Marianne kommet, og hun havde bagt kage. Vi snakkede til kl. 1. Næste dag lørdag kørte vi til Stockholm og parkerede bilen, og kl. 14 sejlede vi over til Drotningholm Slot, hvor det svenske kongepar bor. Slottet minder lidt om Versailles, og det var pragtfuldt at gå rundt i parken i det gode vejr og se den flotte havearkitektur, som både er fransk, engelsk og kinesisk inspireret. Vi oplevede også et brudepar gå om bord på en båd sammen med deres gæster og nogle spillemænd. Da vi kom tilbage til bilen, havde Per fået en P-bøde. Vi gik en tur i Gamla Stan og var hjemme tids nok til at se Sverige vinde bronze over Bulgarien med 4-0, mens vi fik taco-menu, chips og drinks. Søndag kørte vi ind og så Vasa-museet – en stor oplevelse. Vi så det enestående kongeskib, der kuldsejlede på sin jomfrurejse i 1628. Skibet er 62 m langt og 53 m fra køl til mast, det vejer 1300 t og har 64 kanoner på to dæk. Gustav den 2. Adolf ville ikke stå tilbage for Danmarks Christian den 4., så han lod bygge dette skib og beordrede et ekstra dæk. Skibet endte 30 m nede på bunden af Stockholms havn, hvorfra det 333 år senere blev hævet. Derefter tog vi på Skansen, verdens ældste frilandsmuseum: 300.000 m2 park med dyr, blomster og gamle huse. Vi drak kaffe og spiste kæmpe soft ice. Skansen har 150 bygninger fra 50 til 600 år gamle og hentet fra forskellige dele af Sverige. Mange af dem er gjort levende med håndværkere og beboere i lokale dragter. Om aftenen så vi finale i TV, hvor Brasilien vandt over Italien 3-2 ved straffesparkskonkurrence. Om mandagen tog vi selv toget til Stockholm, hvor vi så fodbolddrengene komme hjem med SAS og blive hyldet på deres tur igennem Stockholms gader. Sidst på eftermiddagen mødtes vi med Marianne og Per og sejlede ud til Vaxholm i Skærgården. Vejret var stadig fantastisk, så vi sad ude på Vaxholm Hotell og spiste alle de rejer vi kunne – og det var ikke så lidt. De serverede rejebuffet, så der var rejer i alle afskygninger. Samtidig fejrede vi Pers 34-års fødselsdag, og vi gav ham en Gant t-shirt, som vi havde købt i Stockholm samme dag. Vi sejlede hjem ved 22-tiden og sluttede aftenen af med at spille kort – Bedstemor med Slaw i. Om tirsdagen tog vi afsked med Marianne og Per efter nogle helt fantastiske dage, og vi fandt et dejligt hotelværelse i Karlsborg, hvor vi kunne sidde udenfor. Vi boede lige ned til kanalen, hvor der sejlede skibe hver halve time. Byen var egentlig tænkt som Sveriges reservehovedstad. Et centralt forsvar var en stor del af idéen med at bygge Göta-kanalen. Byen er utrolig dejlig og flot, og vi har senere besøgt den igen. Om onsdagen den 20. juli, inden vi forlod byen, kørte vi ud til fæstningen, et kæmpestort forsvarsværk bygget på en odde. Fra landsiden kunne man forsvare sig bag en 678 m lang forsvarsmur med 263 kanonporte. I tilfælde af krig skulle kongehus og regering flyttes hertil fra Stockholm. Det tog 88 år at bygge værket (1832- 1908), og da var det forældet! Vi kørte videre til HJO, hvor vi så et akvarium og sommerfugleudstilling, og i Borås fandt vi et hotel efter Lars’ smag. Han havde hele tiden ønsket, at vi kunne komme til at bo på et Scandic Hotel, og nu skete det så, at vi fandt et. Vi blev installeret på et dejligt værelse, og mens Lars benyttede sig af swimmingpoolen og TV, kørte vi ud i Knalleland for at handle. Her var alt utroligt billigt, så vi købte både bukser, bluser og sko. Da vi kom tilbage, lå Lars i sengen og så TV. Han havde lige været i bad efter en tur i poolen. Vi spiste aftensmad uden for vores værelse, den eneste gang på turen vi havde brug for vores bord og stole. Kl. 19.30 besluttede vi os for at ringe til farmor. Det havde vi gjort hver dag i ferien, for bedstefar var på plejehjem og sengeliggende, da vi tog på ferie. Det var godt, vi ringede, for vi fik den meddelelse, at bedstefar var død for en time siden, og farmor kunne ikke få fat på nogen. Alle var jo på ferie. Vi ændrede straks færgebilletten, så vi skulle sejle fra Varberg i stedet for Halmstad senere samme aften (23.30). Vi gik op i receptionen og sagde det som det var, og tænk, vi skulle ikke betale noget. Vi havde trods alt brugt både swimmingpool, seng og brusebad. Det var en flot gestus. Vi var i Grenå næste morgen kl. 7, og da vi kom hjem, havde Marianne, som boede hos os i den periode, stillet en bakke frem med rødvin og chips og skrevet et kort: ”Kære alle tre. Ude godt, men hjemme også dejligt. Håber I har haft en god tur. Vedlagt programmet for festugen, så I kan få planlagt jeres næste store tur. Kærligst”. Det var sødt af hende, men desværre havde vi ikke tid til at nyde det – vi skulle straks nordpå (herom senere). Vi havde kørt 1890 km i ferien."}, {"type": "figure", "caption": "", "page": 151, "file": "assets/images-bog2/p151_02.jpg", "dim": [562, 707]}, {"type": "figure", "caption": "", "page": 152, "file": "assets/images-bog2/p152_01.jpg", "dim": [1179, 779]}, {"type": "para", "text": "Det år, mor døde, havde vi ikke lyst til at fejre jul. Vi spurgte derfor Lars, hvad han ville sige til, at vi i stedet tog på en ferie til Gambia og sløjfede julegaverne. Det var han med på, så den 23. december 1993 rejste vi med Spies til Vestafrika. Forinden var vi blevet vaccineret mod gul feber, leverbetændelse og havde fået malariapiller. Afgang fra Billund 9.10, flyskifte i Kastrup, mellemlanding i Las Palmas og ankomst i Banjul kl. 18.30 lokal tid i 30 graders varme. Den effektive flyvetid var knap 8 timer. Vi havde jo droppet julen, men det første, vi så, da vi gik ombord på flyet, var juledekorationer over vinduerne. Bedre blev det ikke, da vi kom ind på hotellet, for der stod et forkølet grantræ, hvor halvdelen af nålene var faldet af. Vi fik noget af et kulturchok, da vi landede, for lufthavnsbygningen lignede mest af alt en barak, og rundt om os flokkedes de indfødte for at få lov til at bære vores kufferter hen til bussen. De forventede naturligvis drikkepenge. I stedet for at komme ud på et bagagebånd, blev vores kufferter placeret på den bare jord. Hotellet lå i et indhegnet område, og vi fik besked på, at vi ikke måtte forlade området efter mørkets frembrud. Det var betryggende! Vi besluttede os derfor for at spise julemiddagen på hotellets restaurant sammen med 200 andre turister. Vores lejlighed lå fint placeret ikke langt fra stranden, og vi havde en fin balkon med udsigt. Vi havde et stort soveværelse, en stor garderobe, badeværelse, stue med opredning, spisekrog og køkken, men det bedste var næsten den dejlige krog, vi havde ude på balkonen, hvor vi tilbragte megen tid. Vi sad blandt andet derude og spillede kort om aftenen til stearinlysenes skær. Der var tre små supermarkeder ved hotellet, men alt var meget dyrt, dog ikke cigaretter og spiritus. Vi havde selv rugbrød og spegepølse med, og i køleskabet var der morgenmad til hele ugen. Hver morgen fik vi frisk brød leveret. Stranden var dejlig, og vandet var 22 grader varmt. Den unge mand, der gjorde rent hos os, talte næsten flydende dansk. Det havde han lært ved at tale med turister. Vi gav ham en af de første dage 50 Dalasis (40 kr.) i drikkepenge for at gøre rent hele ugen."}, {"type": "para", "text": "Kl. 14.30 blev der holdt jul ved poolen. Det var en mærkelig oplevelse at se de indfødte klædt i nissetøj danse om juletræet sammen med de små skandinaviske børn, til dansk og svensk julemusik. Julemanden havde taget maske på. Tjenerne serverede varm gløgg, brune kager og pebernødder. Lars ville dog hellere ligge ved poolen, og vi trak os også tilbage efter et stykke tid. Vi havde forladt Danmark og julen og var taget til Gambia for at være fri for den."}, {"type": "para", "text": "Maden om aftenen var en blandet fornøjelse. Der var stillet en stor buffet an ved poolen, og der var alt lige fra sylteflæsk, grisehoveder, ribbensteg og and til brun sovs, rødkål og kartofler. Jeg mistede helt appetitten, da jeg så al den mad og de mange mennesker, der flokkedes om den. Desuden havde jeg noget forkølelse/influenza i kroppen, så jeg spiste ikke ret meget. Heldigvis fik vi et bord for os selv, for vi havde ikke lyst til at fejre juleaften sammen med en fremmed familie. Vi trak os efter kort tid tilbage til vores lejlighed for at hygge os der, og selvom vi havde dømt nul julegaver, havde vi besluttet, at vi måtte købe en enkelt til hver. Lars fik et armbåndsur, et vækkeur, to bøger, en flaske vodka og en pose tyrkisk peber af os. Så kunne han selv lave ”sorte svin”, som var en meget populær drik det år. Jeg fik ørenringe og en bog af Vagn, og Lars havde købt en toilettaske, som jeg stadig bruger. Vagn fik en bog. Lars fik desuden to par strømper, en bog og ærmeholdere af Anne-Mette. Mens vi pakkede gaver ud, drak vi rødvin og spiste småkager og chokolade, som Alice havde givet os med. Vi spillede kort, gik en tur og var i seng kl. 23. En anderledes juleaften, men en juleaften, vi altid vil huske."}, {"type": "figure", "caption": "", "page": 154, "file": "assets/images-bog2/p154_01.jpg", "dim": [776, 1187]}, {"type": "para", "text": "Juledag havde jeg det stadig lidt træls, men vi tog på en spændende tur til et naturreservat, hvor vi hele tiden skulle være på vagt for at se aber, slanger og krokodiller. Løverne og hyænerne var heldigvis hegnet inde. Guiderne var meget søde og dygtige, især Charlotte, som vi havde mest med at gøre, og Abdul, den dansktalende afrikaner. De handlende var meget påtrængende, hvilket irriterede os, og mange drenge kom hen til os med deres adresser i håb om, at vi ville skrive til dem. Et typisk bybillede var nogle faldefærdige huse og en rød jordvej, hvor kvinder kom gående med tunge krukker på hovedet. Om aftenen gik jeg tidligt i seng med to albyler, og næste dag havde jeg det meget bedre. Imod al sædvane deltog vi i diverse lege og konkurrencer sammen med de andre danskere og svenskere, og det var Danmark mod Sverige. Lars var bl.a. med til pool-basket, men hans hold tabte til Abduls hold, sikkert fordi sidstnævnte lavede en masse sjov med dem. Vi satsede også penge på to krabber i et krabbe-race ved poolen om aftenen, jo, der blev arrangeret meget for turisterne."}, {"type": "para", "text": "3. juledag startede vi kl. 8.15 i to åbne biler, danskere i den ene og svenskere i den anden. På turen besøgte vi en skole, som var meget primitiv. Da vi kom udenfor, kom der en dreng rendende hen til os. Han hed Abdoulie, og han gav os sin adresse og et stykke papir, en såkaldt Club Book med 11 navne på. Det var påfaldende, at 8 ud af de 11 børn på listen hed Bojang til efternavn. Enten var navnet ligeså almindeligt som Jensen i Danmark, eller også var de alle i familie, måske endda søskende. Det sidste var nærliggende at tro. Dernæst besøgte vi tre familier. Den første boede meget fattigt i en slags jordhytte med to soverum, da herren i huset havde to koner. Den anden familie var mere velstående, hvilket sås på, at de havde deres egen brønd, billeder på væggene og et par trælænestole. Vi gav moderen 10 Dalasis (ca. 8 kr.). Den tredje familie havde nogle få svin og geder, som de lukkede ind i løvhytten om natten. Denne dag kom vi tæt på grænsen til Senegal, og vi besøgte en fiskerlandsby, hvor de røgede fisk lå på lange rækker, både ude og inde. Denne stank skulle indbyggerne leve med hver dag! Det var helt tydeligt, at det var kvinderne, der lavede det meste af arbejdet, og det var utroligt, hvad de kunne bære på hovedet. Vi så en kvinde, der havde et barn på ryggen, en balje fisk på hovedet og en stor stak brændsel oven på det hele. Kvinderne var smukke og børnene uimodståelige."}, {"type": "para", "text": "Vi blev gode til at handle. En dag købte vi en stor og en lille træelefant og en lille skildpadde for 450 Dalasis (360 kr.). De ville købe Lars’ t-shirt, solbriller og badesko, men det kunne der ikke være tale om. Vagn bar nu rundt på den store elefant, og vi kom hen til en anden handlende, som ville sælge en stor træskildpadde, men han ville have 225 Dalasis og Vagns t-shirt. Sidstnævnte var i mellemtiden blevet helt sort foran af elefanten, så den tog han gladelig af og gav den unge fyr, og vi fik skildpadden. Samme fyr gav Lars et smykke men ville så til gengæld have Lars’ shorts og kasket. Det fik han ikke, men Vagn blev den dag brændt på maven. På samme tur mødte vi to unge afrikanske kvinder på stranden. De solgte os først 10 bananer for 20 Dalasis. Da de så spurgte, om de skulle lave tre fletninger på mig, troede jeg, at det var med i prisen. Men de forlangte 150 Dalasis. Vi pruttede prisen ned til 30 Dalasis for 4 fletninger, og så gik pigerne i gang. Vagn blev så betaget af dem, at han spurgte den ene, om hun ville med til Danmark, men hun vidste ikke, hvad Danmark var. En gambianers mindsteløn var 400 kr. om måneden. Vores ”stuepige” tjente 640 kr. Vi var på en aftentur (Romantic River) en dag til et delta, hvor vi sejlede med en luksuspram. Det var eventyrligt at sidde der på soldækket og nyde naturen, fuglesangen og solen, og vi oplevede en meget flot solnedgang. Vi sejlede i et par timer og kom ud til en lodge, Lamin Lodge, som var bygget på pæle i vandet. Her blev vi mødt med fakler og bongotrommer. Vi blev bænket i mørket ved små petroleumslamper, og så var der fin buffet med efterfølgende kaffe/te og æbleskiver med bananfyld. Meget lækkert. Bagefter måtte vi lægge øre til bongotrommernes monotone rytme, ledsaget af en ligeså monoton dans, der med jævne mellemrum blev afbrudt af en skinger fløjten. Vagn blev budt op til dans af en af de indfødte kvinder."}, {"type": "para", "text": "Den 31. december landede vi i Billund kl. 4.15, men der gik en time, inden vi kunne få bilen ud af garageanlægget, da vagten havde sovet over sig. Derfor fik vi de godt 300 kr. refunderet. Det havde været en dejlig ferie, hvor vi tre havde hygget os meget sammen, og den samlede pris, alt iberegnet, var 29.000 kr."}, {"type": "figure", "caption": "", "page": 156, "file": "assets/images-bog2/p156_01.jpg", "dim": [1166, 797]}, {"type": "para", "text": "Somrene 1995 og 1996 tilbragte vi i Danmark på camping. I 1995 var vi tre på Åbyskov Strand Camping ved Svendborg, hvor vi fik besøg af Marianne og Per (billedet) og på Hanstholm Camping, og året efter var vi tre på Fyn, hvor vi besøgte Aase og Viggo i Glamsbjerg. Vi boede igen på Åbyskov Strand Camping, hvor vi bl.a. fik besøg af Jette og Leif Nilaus, og vi kørte til Tyskland og købte bilradio. Senere på sommeren var vi i Hanstholm uden Lars."}, {"type": "para", "text": "1997 var året, hvor ”drengene” skulle til Florida og fange ”Big Marlin”, og drengene var Tage, Preben og Vagn. Vi havde sat penge til side til en USA-tur, og vi piger og Lars skulle med. Beslutningen blev taget i august 1996. Det var os, der stod for at planlægge og arrangere turen, som vi bestilte hos FDM den 3. februar. Planlægningen begyndte allerede i januar, og den første weekend i februar samledes vi hos os for at komme i den rette amerikanske stemning. Vi tog på ”Bones” lørdag aften og spiste amerikansk mad, og søndag morgen lavede vi amerikansk morgenmad. Vagn og jeg tog også til en USA-aften i Vejle, arrangeret af FDM, for at få nogle gode fif. Den 5. maj bestilte vi to biler, som vi skulle leje i USA, og det sidste blev ordnet den 23. maj. Jeg var på FDM for sidste gang den 2. juni – troede jeg. Den 16. juni ringede Anna-Lise og fortalte, at Tage var faldet fra en pumpe ned på et betongulv, da han var ved at gøre pumpen ren ovenpå. Han havde brækket hoften! Det var et hårdt slag for os alle, men værst var det naturligvis for Tage, som nok var den, der havde glædet sig mest til turen. Vi talte frem og tilbage om, hvorvidt vi skulle aflyse turen. Det ville Tage ikke have, men hvor havde vi ondt af ham, for det var jo for Tages skyld, at vi havde planlagt bl.a. besøg på Kennedy Space Center og mange af de andre seværdigheder, vi skulle opleve. Det ville ikke blive den samme tur uden dem, og Lars havde også glædet sig til at skulle se USA sammen med onkel Tage. Vi besluttede os alligevel for at gennemføre turen, men nu skulle der ændres på planerne, fx skulle vi nu kun have én bil. Jeg husker, at vi besøgte Tage på hospitalet, og da vi skulle sige farvel, kneb alle en tåre. Det hjalp dog lidt, at Anna-Lise prøvede at muntre os op ved at sige, at vi jo skulle være glade for, at der ikke var sket mere med Tage, og at USA jo ville blive liggende, hvor det lå. Anna-Lise så altid nøgternt på tingene og var ikke sådan at slå ud. Heldigvis kom vi afsted med dem i 2004 og havde en dejlig tur, desværre uden Lars."}, {"type": "para", "text": "Den 28. juni fløj vi fra Billund over Frankfurt til Miami, hvor vi havde booket et hotel lige ned til vandet. Vi fandt hurtigt feriehumøret frem, men vi savnede Anna-Lise og Tage. Næste dag kørte vi over 7-Mile Bridge til Key West. Lars havde printet hele ruten ud, hvilket var en stor hjælp. Key West er et helt fantastisk sted, der er en charmerende og afslappet atmosfære, og det var her, vi indledte vores storindkøb af t-shirts. Vi skulle helst have en fra hvert sted, vi besøgte. Om aftenen, da vi var kommet i seng, hørte vi flere gange en bilalarm, og vi tænkte: ”Sikken en idiot!” Indtil vi næste morgen fandt en seddel i forruden, hvorpå der stod, at alarmen var gået i gang hver 20. minut, og at de efter flere henvendelser havde været nødt til at slå den fra under bilen. Alternativet ville have været at fjerne bilen. Vi afleverede senere brevet til Alamo og fik som kompensation nogle rabatbilletter, som ikke var det fjerneste værd.  Bilen var i øvrigt en Chrysler, et nummer større end bestilt. Næste dag var vi ude at sejle med en glasbundsbåd, hvorfra vi kunne se fisk og koraller, og senere var vi på Sloppy Joe’s Bar, hvor også Hemingway havde haft sin gang. Vi så næste dag Hemingways Hus – meget spændende efter at have læst og hørt så meget om legenden, der skrev mange af sine berømte bøger i dette hus. Han ejede huset i 10 år, indtil kort før sin død i 1961. Der var katte over alt, efterkommere af Hemingways katte, som lå begravet på grunden. Herefter gik turen til The Everglades, hvor vi bl.a. sejlede i luftbåd og så alligatorer, og Lars fik lov til at holde en alligatorunge."}, {"type": "figure", "caption": "", "page": 157, "file": "assets/images-bog2/p157_01.jpg", "dim": [787, 1173]}, {"type": "para", "text": "I Fort Lauderdale hyrede vi straks en båd til næste dag, så mændene kunne komme på deres fisketur. Det var jo det, vi var kommet for. De skulle sejle 12.30 næste dag, og Ellen og jeg fulgte dem derned og ønskede dem en god tur. Heldigvis havde de Lars med som tolk. Imens gik vi på stranden, men efter to timer blev der overskyet og regn, ligesom dagen før. Fisketuren kostede 80 $/person, og normalt tog de kun afsted, hvis der var 6 personer, så man må sige, at det var ”special price”. Vi gik ned for at tage imod dem, da de kom ind. Det havde været en fin tur, og de havde fanget 3 kingfish, 1 delfinfisk (60 cm) og nogle makrel. Fangsten gik til skipper, efter at der var blevet taget billeder. Næste dag så vi Kennedy Space Center, hvor vi har været tidligere. Lars var jo 19 år og voksen, så det hændte, at han gik sine egne veje. Det fandt vi naturligt, for han var en fornuftig fyr. Her mange år efter tør jeg knap nok tænke på, hvad der kunne være sket. Vi har senere hørt om unge mennesker, der bliver bortført. Heldigvis skete der ikke noget, men vi havde jo ikke engang en mobiltelefon dengang."}, {"type": "figure", "caption": "", "page": 157, "file": "assets/images-bog2/p157_02.jpg", "dim": [779, 1173]}, {"type": "para", "text": "I Orlando havde vi bestilt motelværelser i 4 nætter, for vi skulle opleve alle forlystelserne: Epcot Center, Universal Studios og Seaworld. Det var åbenbart regntid i Florida, for hver dag kl. 16 åbnedes skyerne, og regnen stod ned i stride strømme. Den første dag købte vi gule regnslag, som vi fik brug for de andre dage. Der opstod flere problemer undervejs, foranlediget af FDM, såsom at de havde givet os de forkerte motelkuponer til Orlando, så receptionisten i første omgang ikke ville give os værelserne. Det var altid mig, der skulle løse problemerne, da jeg bedst kunne tale sproget, og da der blev problemer med udlejningsbilen, skulle jeg også ringe til Alamo."}, {"type": "figure", "caption": "Jacque, Lars & Tim", "page": 158, "file": "assets/images-bog2/p158_01.jpg", "dim": [1023, 654]}, {"type": "para", "text": "Fra Orlando fløj vi til Denver, hvor Jacque tog imod os. Jeg skulle flyve til Denver og besøge Jacque, når de andre tog hjem, så for at komme af med noget af bagagen, havde vi taget den største kuffert af Preben og Ellens, en hård plastkuffert, og fyldt den med mit tøj og gaver til forskellige i Denver, og den skulle Jacque tage med hjem, så den var der, når jeg kom.  I lufthavnen skulle vi hente en bil hos Alamo, og nu begyndte problemerne igen. Først fik vi at vide, at der ikke var tegnet forsikring. Da det så var ordnet, blev Prebens visa-kort væk. De fandt det senere på gulvet! Så skulle vi betale 20 $ ekstra pr. dag, selvom vi havde en upgrade voucher, men så endte det med, at vi fik en større bil end Chrysleren, en Lincoln Town Car, men vi skulle skifte bil to gange, før vi fik den rigtige, da der var problemer med vinduet og noget andet, så det tog sin tid. Da vi havde tjekket ind på Motel 8, kørte vi alle i Jacques bil Downtown og spiste frokost på Croc’s. Vi så lidt af Denver, inden vi tog tilbage til motellet og hvilede os. Om aftenen havde vi inviteret Jacque og Dick, Tim (16 år) og Jeff (12 år) ud at spise på Baby Doe’s Restaurant med udsigt over Elitches forlystelsespark og Downtown. Desværre var vi ikke så sultne oven på den enorme frokost, men det var hyggeligt. Ellen og Preben blev på hotellet. De havde i mellemtiden fået nyt værelse, da deres WC var utæt og stoppet."}, {"type": "figure", "caption": "", "page": 158, "file": "assets/images-bog2/p158_02.jpg", "dim": [787, 911]}, {"type": "para", "text": "Vi sov elendigt på grund af en kompressor, der larmede. Da vi klagede, fik vi 15 $ retur. På vej ud af Denver var vi forbi 2837 Federal Blvd. og Emmaus Lutheran Church, og så gik turen mod nord. Vi kørte forbi Crazy Horse, som på det tidspunkt ikke var færdigbygget, og gjorde stop ved Mt. Rushmore, som jeg så første gang i 1962."}, {"type": "para", "text": "Vi lejede os ind på et værelse med udsigt til hovederne, og om aftenen kørte vi tre tilbage til stedet, hvor vi sammen med 4000 andre på amfiteatret oplevede en halv times show, hvorefter alle rejste sig og sang nationalsangen, mens hovederne blev oplyst. Meget, meget smukt og gribende."}, {"type": "para", "text": "Nu var vi nået frem til den 9. juli, hvor vi kom til staten Wyoming og kørte gennem de imponerende Badlands, et eroderet canyonlandskab med farverige klippeformationer, og Big Horn National Forest, et befriende og besynderligt landskab. Næste dag kom vi til Yellowstone National Park, hvor vi var så heldige at se en del dyr: to elge, en coyote prærieulv, mange bisonokser, en grizzly bjørn, hjorte og egern. Ulven var vi ret tæt på, idet vi havde parkeret bilen et sted, hvor vi ville spise frokost, indtil vi så, at der lige ved siden af bilen stod en ulv. Nu var vi pludselig ikke sultne mere. Yellowstone er en perle. Der findes næppe noget andet sted i verden, der inden for sine grænser har så mange vilde dyr og sære naturfænomener. Parken er på størrelse med Sjælland og Lolland-Falster tilsammen. Vi ville gerne have boet i parken om natten, men alt var optaget, så vi fandt en hytte lige udenfor, så vi kunne komme igen næste dag, for vi var slet ikke færdige med at se det, vi ville se. Næste morgen kl. 7 var vi tilbage i parken i 10 graders ”kulde” ved Mammoth Hot Springs, hvor varme kilder har dannet terrasser i alle tænkelige former og farver. Det var et meget betagende syn, og det lugtede helt vildt af svovl. Vi oplevede også den gamle trofaste gejser, Old Faithful, som blev opdaget i 1870. Lige siden har den ca. 22 gange i døgnet sprøjtet ca. 25.000 liter spilkogende vand ca. 40 m i vejret – 56 m, hvis den er i godt humør. Jeg købte en del postkort fra parken og fik dem sendt. I alt sendte jeg ca. 60 postkort hjem. Videre til Idaho Falls, Big Rock Candy Mountain og Ruby’s Canyon tæt på Bryce Canyon. Vi boede tæt ved en Western by, hvor vi var så heldige at opleve et Rodeo Show om aftenen, Bryce Canyon Rodeo at Ruby’s Inn.  Den 13. juli oplevede vi et af de mest fascinerende naturfænomener nogensinde: Bryce Canyon i staten Utah. Den består af røde klipper, der står som mænd i en pibehoved-formet canyon og er eventyrlig smuk. De røde eroderede kalkstensklipper former de utroligste figurer, og man går i al ydmyghed mellem søjlerne – helt tæt på. Lars, Vagn og jeg gik et stykke ned i kløften, og der var en fortryllende atmosfære og en guddommelig stilhed mellem de majestætiske klipper. Ja, man blev helt religiøs. Vi kunne godt have tænkt os at komme helt ned i bunden, men Ellen og Preben havde hverken lyst eller kondition til dette. Et andet problem var Prebens tand. Preben havde tandlægeskræk, så han havde ikke sørget for at komme til tandlægen inden afrejsen. Nu var der en tand, der begyndte at murre, og det påvirkede humøret og appetitten, men i og med at vi flyttede os hver dag, havde vi ikke mulighed for at finde en tandlæge og bestille en tid. Det måtte derfor vente til Las Vegas. Ud over en tandlæge var vi også konstant på jagt efter indianere. Det tætteste, vi kom, var et indianermonument, der bestod af nogle ruiner efter en indianerkoloni. Det var smukt, især fordi vi besøgte det en tidlig morgen, men vi så ikke skyggen af en indianer. Næste mål var Grand Canyon, og det var hverken første eller sidste gang vi var der, men hver gang er den lige fascinerende. Det samme kan siges om Hoover Dam og Las Vegas, hvortil vi kom tirsdag den 15. juli ved middagstid. Vi havde bestilt værelse på verdens største hotel med 5009 værelser: MGM Grand. Hotellet åbnede i 1994 og har også verdens største kasino, 8 restauranter, 4 teatre, 3 pools og 1 temapark, med andre ord, det er en hel by. En ”valet” kørte vores bil i en underjordisk garage, og en anden tog vores kufferter. For at man ikke skulle kede sig, når man stod i check-in-køen, var der sørget for underholdning af tegneseriefigurer. På Ellen og Prebens værelse stod der, sikkert ved en fejltagelse, en kurv med alskens lækkerier, men rengøringsdamen sagde, at vi bare skulle nyde den, så det gjorde vi. Fra vores værelse kunne vi se dele af Manhattan med Frihedsgudinden, ganske vist i miniformat. Vi fandt hurtigt en tandlæge i telefonbogen, og jeg fik ringet og bestilt tid til Preben næste dag kl. 8.30. Det første, vi herefter gjorde, var at gå i poolen, den største pool, vi nogensinde havde set, og vi kunne få drinksene serveret ude i poolen. Næste morgen tog jeg med Preben til tandlægen, som boede på den gade, hvor vores hotel lå. Det var en lang gade, så vi tog en taxa. Preben var rystende nervøs, og han kunne slet ikke sidde stille, mens de tog røntgenbilleder. Det lykkedes dog til sidst, og dommen var, at tanden skulle ud. Udover at agere som tolk, holdt jeg også nærmest Preben i hånden og hviskede trøstende og opmuntrende ord til ham, og han var synligt lettet, da det hele var overstået, så nu glædede han sig til igen at kunne spise 1½ m revelsben. Prisen var ca. 1000 kr., som de fik dækket af forsikringen. Samme dag forlod vi Las Vegas og kørte ind i Dødens Dal, hvor vi kunne have spejlet et æg. Vi ristede faktisk brød, for da vi skulle have frokost, nåede brødet at blive hårdt, inden der kom pålæg på. Temperaturen blev målt til 120 grader F (49 grader C) – ja, der var så varmt, at det løb os koldt ned ad ryggen. En flok guldgravere forsøgte i 1849 at skyde genvej gennem dalen til guldminerne, men de kom hurtigt til at mangle mad og vand, og i desperation spredtes de i alle retninger på flugt fra den golde ørkendal. Flere døde, før de nåede minerne."}, {"type": "figure", "caption": "", "page": 159, "file": "assets/images-bog2/p159_01.jpg", "dim": [1166, 789]}, {"type": "para", "text": "Næste stop var Santa Barbara, hvor vi spiste frokost. Preben, som var storryger, havde tit problemer med at få lov til at ryge, og selvom vi sad ude og spiste på restauranten, måtte han kun ryge uden for stakittet. Ofte forlangte han ikke-ryger værelse men røg der alligevel, hvilket vi fandt uacceptabelt. Herfra gik turen til Solvang, hvor vi fik værelser på samme hotel som sidst: Best Western King Frederik Inn, og ligesom sidst stilede vi straks mod Mortensens Bageri, hvor vi bestilte chokolade med flødeskum og kager. Vi fandt en Gant forretning, hvor mændene gik helt amok, fordi alt var så billigt. Om aftenen ville Preben ud og spise andesteg. På vej hen til restauranten, kiggede han nysgerrigt ind i en smøge til en gård, hvor der var optræk til en fest. Vi andre (minus Ellen) blev også nysgerrige og gik derind. Preben kom straks i snak med en dame, som talte dansk, og det viste sig, at det var en dansk klub, der var ved at gøre klar til en fest. Folk havde nationaldragter på, og vi kunne se fade med smørrebrød og kringle. Damen spurgte Preben, om vi ikke ville spise med, men han ville jo have sin andesteg, og ude på gaden stod Ellen og råbte: ”Kom nu, Preben”. Preben hev lige en løgn ud af ærmet og sagde, at vi havde spist. Ærgerligt, at vi ikke tog imod invitationen. Det kunne have været sjovt at snakke med de danskere, og så havde vi sparet aftensmaden, som ved gud ikke var noget særligt. Man skal aldrig spise andesteg i sommervarmen. Inden vi forlod Solvang næste dag, var vi inde og se den danske kirke, som vi også så sidst, vi var der. Ved siden af kirken lå der en børnehave, og den ville Ellen gerne se, da hun selv arbejdede i en børnehave. Hun ville have mig til at spørge, om vi måtte komme ind og se den. Jeg var lidt kostbar på grund af episoden aftenen før, for da kunne hun jo være kommet i snak med danskere, men jeg fik tilkaldt en ansat, og vi blev budt indenfor. Den dame, der viste os rundt, talte dansk og havde sin farmor boende i Hadsten. Det var, mens vi var i Solvang, at Ellen fik den tvangstanke, at hendes mor var død! Det kom sig ved, at familien hemmeligholdt for Ellen, at hendes mor var faldet og kommet på sygehuset. Ellen kunne ikke forstå, at hun ikke kunne ringe sin mor op. Da hun så fandt ud af, at de havde holdt det hemmeligt for hende, bildte hun sig selv ind, at så kunne hendes mor jo dø, uden at hun fik noget at vide. Den sidste dag på ferien var hun langt nede, fordi hun bildte sig selv ind, at hendes mor både var død og begravet, inden hun nåede at komme hjem. Det var ikke sjovt for os andre, når Ellen var i det humør. Hun var ofte sur og tvær, og det var Preben, der holdt humøret oppe. Men moren var hverken død eller begravet, da de kom hjem. Hun levede såmænd i mindst 10 år derefter."}, {"type": "para", "text": "Herfra gik turen til Hearst Castle, hvor vi tre tog en rundvisning. Hearst Castle er virkeliggørelsen af en ufatteligt rig mands vanvittige drøm, aviskongen William Randolph Hearst. På det over 1000 km2 store landområde omkring slottet opbyggede Hearst verdens største privatejede zoo med aber, giraffer, elefanter, bisonokser, zebraer, kvæg og hundredevis af heste. I dag er der kun zebraer og kvæg tilbage. Indtil sin død i 1951 brugte Hearst meget af sit 88-år lange liv på at udvide og samle skatte til sit slot. Han havde brugt 1 million $ om året i en 50-årig periode. I 1958 forærede familien slottet til staten til minde om Hearst."}, {"type": "para", "text": "De næste byer var Carmel, hvor Clint Eastwood havde været borgmester, Pacific Grove og Monterey, hvor vi var inde og se Monterey Bay Aquarium. Vi overnattede i John Steinbecks by, Salinas, og kørte videre til Hollister, hvor Ellen og Prebens Lise havde været et år, og vi spiste morgenmad på en restaurant, hun havde anbefalet. I Gilroy fandt vi nogle kæmpe factory outlets, hvor vi købte en del tøj og gaver. Lars købte Nike sportstøj, og vi købte Benetton taske og pung til Lars’ dansepartner Anne-Mette."}, {"type": "para", "text": "I San Francisco fandt vi et hotel på hjørnet af Turk og Polk, ikke noget særligt men en fin beliggenhed. Næste dag kørte vi 49-mile-turen. Vagn og Preben skiftedes til at køre det meste af tiden. Jeg tror, det hang sådan sammen, at Ellen helst ville, at Preben kørte, og jeg helst ville, at Vagn kørte. Der var ingen tvivl om, at Vagn var den bedste chauffør. Vi var oppe i Coit Memorial Tower, vi kørte på verdens mest snoede vej, Lombard Street, vi krydsede Golden Gate Bridge og var i Chinatown. Senere på dagen gik Lars en tur alene, og om aftenen spillede vi tre kort. Næste dag stod den på Cable Car, Fisherman’s Wharf og Pier 39, og senere havde vi billetter til Alcatraz, som indtil 1963 var et af USA’s bedst bevogtede fængsler, der har huset personligheder som Chicago’s Al Capone og Machine Gun Kelly. I Santa Rosa nord for San Francisco havde jeg bestilt værelser på Motel 6, og næste dag kørte vi op i Napa og Sonoma vindistrikterne. Vi havde været der før, og vi glædede os til at gense området, som er virkelig behageligt med en dejlig temperatur. Vi besøgte vingårdene Benziger, Robert Mondavi og Edgewood. Derefter gik vi tur i den Forstenede Skov, hvorefter vi kørte tilbage til hotellet. Vi havde fundet os et godt spisested, Tony’s, hvor vi spiste alle vores måltider. Næste dag kørte vi til John Muir Woods, som kun er et par km2 stort, men det er et godt sted at få et lille indtryk af de gigantiske redwood-træer. De højeste træer i parken var 75 m høje og havde en diameter på 3,4-4,0 m."}, {"type": "para", "text": "Den 25. juli skulle jeg flyve til Denver, mens de andre skulle flyve hjem fra San Francisco. Det var lidt vemodigt at skulle sige farvel efter en dejlig ferie. I Denver var Jacque og drengene i lufthavnen for at hente mig, og det var Tim, der kørte. Det var en varm periode, og denne dag var der 30 grader C. Hos Jacque ventede Ellen og Prebens kuffert på mig. I den var jo det tøj, som Ellen og Preben ikke havde haft brug for samt nogle gaver og andet, som jeg først skulle bruge i Denver. Idéen var god nok, men de havde bare glemt at fortælle mig, hvad koden var, så jeg kunne ikke åbne kufferten! Det tog mig 1½ time at prøve de 999 kombinationsmuligheder, og ikke én af dem duede! Det stressede mig, for næste dag skulle jeg bruge noget af indholdet. Jacque og jeg gik tur med hunden Orio efter aftensmaden. De havde fået den opereret, så den ikke kunne gø. De kaldte det, at den var ”debarked”, så i stedet for gik den og stønnede. Jeg har aldrig før hørt om det fænomen. Næste dag ringede jeg hjem, og det var dejligt at høre, at turen hjem var gået godt. Ellen og Preben havde heller ikke koden til kufferten, da det var deres datters kuffert, men det lykkedes mig endelig at få den: 109. Dejligt, så kunne forberedelserne til ”class reunion” begynde. Vi satte tre borde op på terrassen, et til mad, et til drikkevarer og et til gamle albums og billeder, som man skulle medbringe, samt 10 stole. Maden bestod af 50 barbecue vinger, to slags kiks, to slags ost, tacochips med to slags dressing og bread rolls med bacon og parmesanost. Susan havde kiks, Philadelphia ost og syltetøj med. Drikkevarerne bestod af øl, iste, rødvin og lemonade. Fra min klasse kom følgende: Susan, Cathy, Janice, Stephanie og Jim samt vores gamle matematiklærer Mr. Rathe og dennes kone. Jeg holdt en lille tale og gav hver en nål (det danske og det amerikanske flag), som jeg havde købt i Solvang. Alt var en stor succes, og vi snakkede rigtig meget og havde det hyggeligt. Flere havde meldt afbud på grund af arbejde eller ferie, og Mr. & Mrs. Harms kunne ikke komme på grund af sygdom. Senere på dagen kørte vi alle ud til en spiritusforretning, hvor en af klassekammeraterne Vickie arbejdede. Det var hyggeligt at hilse på hende. Hun var i gang med tredje ægteskab og havde 6 børn mellem 7 år og 26 år! Der var noget, der tydede på, at dagen havde været en succes, for festen var sat til at skulle vare fra kl. 14 til 17, men den sidste gæst kørte først kl. 20. Jacque spurgte, om jeg ville prøve hendes boblebad (jettub), men hun begik en fejl. Hun hældte sæbe i, og så skulle jeg ellers selv lukke for vandet. Jeg havde aldrig prøvet noget sådant før, så jeg stillede mig op i badekarret og ventede, til det var næsten fyldt op. Så lukkede jeg for vandet, men nu var boble-mekanismen jo sat i gang, så det skummede helt vildt. Jeg kunne slet ikke sidde ned, for så ville jeg være helt dækket til af skum. Det var så voldsomt, at det boblede ud over kanten og ned på gulvet, og jeg stod bare der helt magtesløs. På et tidspunkt bankede Jacque på for at spørge, om alt var OK. Jeg ville ikke være bekendt at sige, at jeg havde problemer, selv om det var hende, der havde forårsaget dem, så jeg sagde bare, at alt var vel. Jeg ved ikke, hvordan det lykkedes mig at få alt skummet lukket ud og gulvet tørret rent, men håndklædet var også meget vådt bagefter. Det må have været et sjovt syn. Jeg kunne ikke lade være med at fortælle Jacque om mine genvordigheder, og det grinede vi meget af. Senere på ugen prøvede jeg det igen – denne gang uden sæbe."}, {"type": "figure", "caption": "", "page": 162, "file": "assets/images-bog2/p162_01.jpg", "dim": [962, 691]}, {"type": "para", "text": "Næste dag var det søndag, og så skulle jeg i min elskede Emmaus Lutheran Church. Der mødte jeg Jacques mor, Bette Michel, som på det tidspunkt var en flot dame på 78 år. Jeg kendte hende godt og huskede hende som en sød dame. Det var dejligt at synge med på de kendte salmer og bede bønnerne. Til sidst kom præsten med en lang række sørgelige meddelelser: Om torsdagen havde han mistet sin mor, han havde for nylig mistet sin tante, hans svigermor var på hospitalet, og hans kone havde 15 minutter før kirkegang fået at vide, at hun havde cancer i ryggen. Han forlod kirken grædende, og folk græd, da de hørte meddelelserne. Vi måtte alle hilse på ham og sympatisere. Jeg mødte min gamle klassekammerat Claudia, som stod og solgte donuts sammen med sin mand, og jeg hilste på Gary Fischers mor og Barbaras far samt Mrs. Moore (sekretær) og Mrs. Rathe. Senere besøgte vi Mr. & Mrs. Harms. Mr. Harms led af en sygdom, der hed ”spinal stynosis”, og havde haft en hjerneblødning. Han var svag og tynd men åndsfrisk, og det var hyggeligt at snakke med dem i en times tid. Ugen før var han faldet, så han havde ikke været i kirke de sidste to søndage. Mr. Harms havde været min engelsk- og historielærer, og han havde gjort alt for mig, da jeg gik i skole på Emmaus. Derfor var det sørgeligt at se ham i den tilstand men alligevel dejligt, for det var sidste gang."}, {"type": "figure", "caption": "", "page": 163, "file": "assets/images-bog2/p163_01.jpg", "dim": [967, 682]}, {"type": "para", "text": "Den dag fik vi et kæmpe-måltid grillmad: steaks, majs, kartofler, sovs og salat (det var ikke altid, vi fik lige meget at spise hos Jacque og Dick). Dick var hurtigt færdig med at spise og sad og bøvsede og ventede på, at vi andre skulle blive færdige. Sådan kan amerikansk madkultur også være. Om eftermiddagen kørte vi til Butterfly Pavillion, hvor vi så mange interessante sommerfuglearter, hvoraf nogle satte sig på os, især på dem, der havde farverigt tøj på. På grund af den overdådige frokost, fik vi kun en portion is til aftensmad."}, {"type": "para", "text": "På dette tidspunkt var jeg så småt begyndt at lære e-mailens kunst at kende, og jeg havde sendt en mail fra Jacques computer til Marianne og Per, som svarede således: ”Kæreste Merete. Jeg er dybt imponeret over at have en søster, der hacker sig ind på diverse PC’ere rundt omkring i verden og sender mails, som om hun aldrig havde gjort andet. Håber du nyder at have USA lidt for dig selv, nu hvor du har sendt drengene hjem til sommervarmen. Vi er i dag, søndag, lige kommet hjem fra Borneo, hvor vi har fejret min 30+ fødselsdag med noget af det bedste dykning vi nogensinde har gjort – glæd jer til at se videoen…. Tak for kortet. Vi ses søndag den 10. august i Århus, vi har via postkort booked middag i Spørring. Kærlig hilsen Per. Også en stor hilsen fra Marianne. Vi glæder os til at se jer”.  Mon det var på denne tur, at Per friede til Marianne under vand?"}, {"type": "para", "text": "Næste dag mandag besøgte vi Arvada High School, hvor Jacque underviste, og så stod den ellers på shopping. Vi var gode til at shoppe sammen, og vi levede begge op til mottoet: ”Shop till you drop”. Hvis Jacque så meget som gisnede om, at jeg gik efter en bestemt gave eller ting, var der ingen grænser for, hvad hun ville gøre for at opfylde mit ønske. Som hendes mor engang sagde: ”Jacque will climb the moon for you!”"}, {"type": "para", "text": "Senere på dagen havde vi bestemt, at vi skulle køre på kirkegården med en buket blomster til Margaret og Martinus’ grav. Der var bare det ved det, at blomsterhandlerne ikke lå på ethvert gadehjørne, og man bruger ikke sådan at sætte blomster på gravene. I 1962 kom jeg til at kende en gartner i Denver, som hed Gudmund Jensen, og hans kone hed Grethe. De havde tre døtre, hvoraf den ældste hed Karen. I telefonbogen fandt vi Jensen’s Flowers, som nu ejedes af Karen. Det kunne være sjovt at købe blomster der, så vi kørte derud og blev mødt af et skilt, hvorpå der stod: ”CLOSED. OUT OF BUSINESS. ” Der gik en dame og lugede, og det viste sig at være Karen. I starten var hun ikke særligt imødekommende, men hun inviterede os dog indenfor og solgte os en fin buket lilla nelliker til 3 $. Vi fik også en god snak. Derfra gik turen til Crown Hill Cemetary. Vi gik først ind på kontoret og fik en plan over området, for det er så stor en kirkegård, at man kører rundt i bil derinde. Vi vidste, at de skulle ligge i Block 50. Til trods herfor kunne vi ikke finde pladen med deres navne på, og det begyndte at regne. Vi kørte tilbage til kontoret og tjekkede igen, og tilbage til Block 50, men nu blev det uvejr. På et tidspunkt overvejede vi at lægge blomsterne på en tilfældig grav, men så besluttede vi os for at køre ud til Jacques mor for at få lidt varme og hilse på søster Debbie, der var på besøg med mand, to børn og svigerforældre. Da vi kom, sad de og spiste aftensmad, men de var mægtig søde, og vi blev bænket og fik dejlig mad: kyllingeret med frugtsalat og is til dessert. Debbie og hendes mand skulle til en baseball kamp sammen med Tim og Dick. Kl. 19 kørte vi tilbage til kirkegården, men da regnede det så meget, at vi tog vores sko af, tog regnslag på og vadede rundt i græsset for at lede – uden held. Vi kørte hjem og satte blomsterne i køleskabet til næste dag, og så hyggede vi os sammen med Jeff, slik og Robin Hood på video. Næste dag tirsdag var det tørvejr igen. Jacque og jeg hentede hendes mor, og vi kørte på tur i bjergene. Vi besøgte Rocky Mountain National Park og var helt oppe over trægrænsen, og da vi kom hjem, havde vi kørt 184 miles. Vi havde en fantastisk dejlig og hyggelig tur, hvor vi også spadserede rundt om Bear Lake og Sprague Lake. Bette og jeg var ligesom veninder, og hun var utroligt sød. På vej hjem stoppede vi i Estes Park, hvor jeg købte guldsmykker, og vi fandt en Danish Ice Cream Cone Factory, hvor jeg gav isvafler. Jeg gav Bette en nål med et dansk flag, en af de nåle, jeg havde købt i Solvang. Den aften fik vi ingen aftensmad, så jeg vågnede kl. 2 og var sulten. Heldigvis havde jeg et stykke chokolade, jeg kunne spise."}, {"type": "para", "text": "Onsdag kørte vi på kirkegården igen, men denne gang havde vi to af de ansatte med til at finde graven for os. Vi satte blomsterne og kørte hen og fandt Jacques fars grav efter lang tids søgen. Det viser også, at de ikke har tradition for at besøge kirkegårdene. Jeff ville gerne have haft blomster med til sin morfar, men det havde Jacque ikke tænkt på, så han plukkede i stedet nogle tusindfryd i en græsplæne og lagde på graven. Det er tanken, der tæller. Senere kørte vi på picnic til Dillon Lake, men på grund af regnvejr måtte vi spise i bilen. Vi var også i et factory outlet i Dillon, hvor der var billigt GANT tøj. Jeg købte T-shirts til Vagn hos Gant og Brandy til Svend Sønderup hos Apple Jack. Da vi kom hjem, havde de andre spist, så da fik vi heller ingen aftensmad, bortset fra det flutes, der var tilbage fra turen. Jeg havde fået telefonnummeret på Grethe og Gudmund Jensen, så den aften ringede jeg og fik en god snak med dem. Den dag havde vi kørt 150 miles. Vi spillede ofte spil med drengene om aftenen, hvilket var rigtig sjovt. Torsdag den 31. juli skulle jeg rejse hjem. Jeg havde haft gaver med til familien: t-shirts til alle, kasketter til børnene, spiritus til Dick og en halskæde samt nål med dansk/amerikanske flag til Jacque. Vi var i lufthavnen en time før afgang, men der var lang kø ved check-in, så det blev noget af et mareridt at komme igennem den store lufthavn. Vi fik endda lov til at komme til en speciel check-in skranke, da vi var i tidsnød. Jeff, Dick og jeg blev sendt afsted, og Jacque skulle komme med bagagemærker. Vi skulle også med en shuttle, så til sidst løb vi bare afsted og havde slet ikke tid til at tude, da vi sagde farvel. Der var 5 minutter til take-off, da jeg kom til gaten. Da jeg så forpustet sad i flyet, blev det meddelt, at vi ville blive 45 minutter forsinket, men så fik jeg lov til at komme ud og se cockpittet. Den var ikke gået i dag."}, {"type": "para", "text": "Jeg kom godt hjem, og det var dejligt at komme hjem til ”drengene”. Jacque mailede til mig den 5. august og skrev bl.a.: ”Dear Merete, I already miss you. Thank you for the beautiful week of friendship and good times. Your friendship is a priceless gift”."}, {"type": "para", "text": "På vores ferie i USA havde vi fem tilbagelagt 7.338,8 km. Men vi var ikke tilfredse med FDM, og jeg skrev et klagebrev til dem. Vi var heller ikke tilfredse med deres svar og skrev frem og tilbage med dem, og det endte med, at vi meldte os ud af FDM."}, {"type": "para", "text": "Mens vi havde været væk, var Charlotte blevet gift med sin søde kæreste Jette, en borgerlig vielse med efterfølgende frokost ved en sø (billede på næste side)."}, {"type": "figure", "caption": "Den 26. juni 1997 fik Charlotte og", "page": 165, "file": "assets/images-bog2/p165_02.jpg", "dim": [1158, 797]}, {"type": "para", "text": "Jette papirer på hinanden"}, {"type": "para", "text": "I 90’erne har jeg noteret mig følgende i forbindelse med vejret: Den 28. februar 1994 var alt lukket på grund af snestorm, og det samme gjorde sig gældende den 31. januar året efter. Der var åbenbart en streng vinter i 1995, for også den 8. januar frarådede man al udkørsel. Vi trodsede alligevel vejrguderne og kørte til Ålum og så på campingvogn. Jeg husker, at det var meget glat. Samme år havde vi en forrygende sommer, især august var varm med 25-32 grader. Da vi så kom hen til december samme år, kom den strenge vinter igen. Ja, allerede den 17. november havde vi snestorm, og igen den 22. december. Vi var til Reinholts fødselsdag, og jeg husker, at Lars og Klaus blev enige om at tage i biografen på trods af vejret, så de tog bussen til Århus. De kom da også hjem igen planmæssigt, så buskørslen var ikke indstillet. Den værste snestorm siden 1971 havde vi dog den 19. februar 1996, og det år havde vi også en forrygende sommer. Jeg cyklede meget den sommer, også hjem fra arbejde. Nogle gange havde vi min cykel med om morgenen, og om eftermiddagen cyklede jeg så ud til Egå strand, helt ud til Åkrogen, hvor vi gik til bal som unge. Så iførte jeg mig badedragt og tog et dejligt bad i det efterhånden godt opvarmede badevand. Jeg beholdt badedragten på og cyklede hjem, mens jeg tørrede. På en af disse ture syntes jeg lige, at jeg ville slå et smut omkring min frisør Lis i Todbjerg. Jeg kom ind i salonen iført badedragt, cykelhjelm og walkman, som jeg altid brugte, når jeg cyklede. Jeg må have set komisk ud, for hun hentede sit camera og tog grinende et billede af mig. Om hun allerede dengang pønsede på, hvad billedet skulle bruges til, ved jeg ikke, men Lis var meget kreativ og kunne se det sjove i mange situationer. Hun brugte billedet to år senere til vores sølvbryllup. Hun havde fået det forstørret og sat i en ramme, og under den lille tale, hun holdt, sagde hun bl.a., at jeg så forrygende ud og lignede en dronning i min smukke kjole (det var også Lis, der havde sat mit hår og lagt min make-up), men at jeg også kunne se anderledes ud, og så præsenterede hun billedet og sendte det rundt, så alle gæsterne kunne se mig i sommerantræk. Det var meget underholdende."}, {"type": "figure", "caption": "", "page": 165, "file": "assets/images-bog2/p165_01.jpg", "dim": [581, 831]}, {"type": "para", "text": "Snestormene kunne også ramme, når man mindst ventede det, som fx den 18. marts 1997 og den 3. april 1998. Sidstnævnte dato skulle jeg over til Lis og klippes. Hun boede som sagt i Todbjerg, men ikke i selve byen, lidt udenfor på en ejendom, så man skulle et stykke ud ad en smal vej. Det gik godt nok med at køre derud, men da jeg skulle hjem, var jeg ikke stolt ved situationen, så hendes mand Bent kørte foran mig og banede vejen ud til Randersvej. Men da jeg kørte ind ad den første indkørsel til Spørring, kunne jeg ikke komme igennem den kæmpe snedrive, der havde lagt sig i svinget, så jeg måtte vende om og tage en anden indkørsel. Næste dag skulle jeg flyve til Frankrig (arbejde), men da var snestormen heldigvis ovre."}]}, {"title": "Weekendophold og pinseture", "blocks": [{"type": "para", "text": "Vi har altid kendt mange med sommerhuse, som vi har kunnet låne. Det er bare ikke meget, vi har benyttet os af det, dels har vi ikke haft tiden, og dels fik vi campingvogn igen i 1995, og så ville vi hellere bruge den. Men uden for campingsæsonen har vi nogle gange benyttet os af det.  Moster og Ib havde sommerhus på Mågevej i en plantage mellem Skagen og Ålbæk. Det var et gammelt hus, de havde købt, og Ib havde selv gået og repareret på det. Han var dygtig nok med hænderne, men stilen var meget gammeldags, og huset var fyldt op med alskens nips, så man ikke kunne få øje på de få pæne ting, huset rummede, såsom hans malerier. Moster og Ib var meget stolte af huset, og de blev vældig glade, da vi spurgte, om vi måtte låne det fra den 9. til den 11. oktober 1992 sammen med mor, Per og Marianne. Det blev en hyggelig weekend, hvor vi spillede Trivial Pursuit, var på tur til Råbjerg Mile og drak kaffe på Hjorths Hotel. Vi var glade for turen, som blev den sidste sammen med mor."}, {"type": "figure", "caption": "Til kaffe på Hjorths Hotel Per laver sit ske-trick på næsen", "page": 166, "file": "assets/images-bog2/p166_01.jpg", "dim": [1179, 781]}, {"type": "para", "text": "Et år senere blev vi inviteret til at tage med Hanne og Keld op i Hannes brors sommerhus på Mors. Denne gang havde vi ikke Lars med, for han havde nu nået den alder, hvor kammeraterne trak, og han havde ikke noget imod at være alene hjemme. Huset var oprindeligt gammelt og lillebitte men hyggeligt og fint renoveret. Hannes bror Lars er arkitekt, så han havde selv lavet det hele, og jeg mener også, at huset senere fik en pris af kommunen. Desværre var vejret ikke med os, og det styrtregnede, da vi kom derop. Vi trodsede vejret og tog regntøj og gummistøvler på, og så begav vi os ud i regnen for at se på området. På et tidspunkt var vi nødt til at skyde genvej, og det blev hen over en roemark, som krævede, at man krøb under et hegn. Vi måtte derfor ned på alle fire og rulle os ind under hegnet på en meget smattet mark. Man kan derfor forestille sig, hvordan vi så ud bagefter, men vi grinede meget, hvilket vi altid gør, når vi er sammen med Hanne og Keld. De er ikke kedelige at være sammen med. Om søndagen gik Hanne og jeg i kirke."}, {"type": "para", "text": "Vi var også nogle gange med Alice og Reinholt ude på Mols i Skjødes sommerhus (tidligere brugsuddeler), bl.a. fra den 25. til den 27. februar 1994, hvor det blev snestorm og alt lukkede, lige efter vi kom hjem. Samme år i maj var vi tre dage på tur med Anne, Niels, Jette, Leif, Karen Lis og Finn til Ristinge på Langeland. Vi havde lejet to hytter, og vejret var fantastisk flot. Det blev nogle hyggelige dage med bl.a. besøg hos Leifs forældre i Svendborg, shopping og aftensejltur med middag om bord."}, {"type": "para", "text": "Efter vi fik campingvogn, fik vi en tradition med pinseture, hvor vi altid en dag havde besøg af moster, Ib og onkel Alfred (mormors bror). Det startede faktisk i 1994, hvor vi stadig havde mors hus. Vi tog derop engang imellem og ordnede have og tjekkede, at alting var i orden. I pinsen 1994 tog vi derop alle tre, og pinsedag inviterede vi moster, Ib og Alfred til frokost. Det var naturligvis underligt at være der uden mor, men det havde vi efterhånden vænnet os til. I 1995 havde vi fået vores nye campingvogn og tilbragte pinsen på Sæby Camping. Det blev dog ikke så afslappende, som vi havde håbet, men det skyldtes, at vi havde lavet for mange aftaler. Lørdag hentede vi farmor, og Pinsedag kom moster, Ib og Alfred. Alt imens vi sad i forteltet og spiste frokost, dukkede Marianne og Per uventet op. Det var en dejlig overraskelse, og vi fik straks lånt nogle stole, så de kunne sidde ned. Mad var der nok af, men jeg måtte spise med en pålægsgaffel. Da de var taget afsted ved aftenstid, besluttede vi os for at gå en tur på havnen, og hvem møder vi der? Vagns fætter Kaj og dennes kone Aase, som havde deres båd liggende i havnen. Vi skulle da med om bord. Så kunne vi også hilse på Kajs Søster og dennes mand Henning. Der røg den hyggeaften i campingvognen. Næste dag pakkede vi sammen, for vi skulle spise frokost hos Vibeke og Elbo sammen med Marianne og Per. Det var nu mægtig hyggeligt, men vi havde ikke haft megen tid for os selv."}, {"type": "para", "text": "I maj 1995 var vi også på camping sammen med Karen Lis og Finn på Sølystgård ved Ebeltoft. Lars havde indvilget i at tage med, hvis han også kunne få sin PC med, og det kunne han naturligvis. Jeg mener også, at Jane kom på besøg, og det var jo et ekstra plus for Lars, som var blevet passet hos Karen Lis og næsten havde været en del af familien. Samme efterår camperede vi i Mariager, som også var en af vores yndlingspladser."}, {"type": "para", "text": "I pinsen 1997 gentog vi succesen i Sæby og havde inviteret moster, Ib og Alfred, og 1998 var det i Sindal, vi holdt træffet. Her besøgte vi også Vagns gudmor Esther. På det tidspunkt kom Lars sammen med Marianne, og da vi sagde farvel til Alfred, gav han os en kuvert med 1000 kr. som vi skulle give til Marianne og Lars. Det var ikke den eneste gang, han gav Lars penge, og vi fik også til tider en skilling."}]}, {"title": "Kultur", "blocks": [{"type": "para", "text": "Den 8. januar 1990 stod jeg i kø i 45 minutter for at købe billetter til Cliff Richard koncert den 6. maj til Alice og mig. Vi er begge to Cliff Richard fans og har været til nogle af hans koncerter. Billetterne kostede 270 kr.pr. person. Godt nok er vi fans, men vi er ikke den type, der står ved scenekanten og smider røde roser op til ham. En dag i 1995, hvor jeg havde fri og gik og hørte radio, fandt jeg ud af, at man kunne ringe ind til Cliff og stille spørgsmål i et bestemt tidsrum. Han var i Danmark og sad denne dag på BT. Skulle man vove det? Det ville nu være sejt at kunne fortælle Alice, at jeg havde talt med Cliff, men jeg måtte have beviser, så jeg riggede min båndoptager til og gjorde mig klar ved telefonen. Samtalen skulle båndes. Men der var åbenbart også andre end mig, der havde fået den idé, for jeg kom aldrig igennem. Det var vel nok ærgerligt. En anden gang kunne man ringe ind til radioen og fortælle om en speciel oplevelse, man havde haft på et fly, og jeg ringede ind og fortalte om dengang jeg som 12-årig stod af i Chicago på vej til Denver. Jeg kunne så få et musikønske opfyldt, og jeg ønskede et nummer med Cliff. Det kunne jeg ikke få, så jeg fik Kim Larsens ”Kvinde Min”. Bagefter følte jeg, at jeg havde overvundet en grænse ved at turde ringe ind til radioen. Der var også flere af mine bekendte, der havde hørt mig. Per mente dog, at det var dårlig reklame for SAS, at jeg havde nævnt dem som værende ude af stand til at passe på mig på turen. Per arbejdede jo for SAS dengang, så det forstår jeg godt. Jeg vil dog ikke drages til ansvar for SAS’ røde tal på bundlinjen."}, {"type": "para", "text": "Alice og Reinholts søn John var begyndt at synge professionelt, og han var i maj og oktober det år med i en forestilling på Gjellerupscenen, som jeg var med ude og se. I maj var vi også med til en koncert med Centralværkstedets Orkester. Det var et orkester, som Villy Morgenstjerne havde spillet i, og efter hans død blev Reinholt fanebærer for CO. Vi kendte nogle af medlemmerne og kunne godt lide deres musik. Om sommeren var der stadig gratis Parkunderholdning, som vi deltog i, når det kunne lade sig gøre. I august 1990 var vi alle tre til Shubidua koncert i Klostergade, og i Århus Festuge var vi til Niels Hausgård koncert med Hanne og Keld. Vi fik også den tradition i nogle år at være til Festugerevy sammen med Hanne og Keld. Vi kunne godt lide at more os sammen."}, {"type": "para", "text": "Til festugen i 1991 havde vi besøg af Ditte, Ejvind og mor, og de syntes, at det var sjovt at gå rundt inde i Århus sammen med alle festugedeltagerne. Vi var blandt andet inde og se et stand-up show med Lars Hjortshøj. Det var en helt ny genre, og Lars Hjortshøj var ukendt. Nede bagved sad der nogle meget larmende fulderikkere, som kom med tilråb flere gange. Det blev så slemt, at Lars Hjortshøj måtte forlade scenen. Det ville ikke være sket for ham i dag, hvor han er mere erfaren. Den 10. maj 1992 skulle vi jo fejre vores årsdag. Vi havde kendt hinanden i 23 år, og det havde Grete og Poul også, så vi tog til gospel koncert med Etta Cameron i Christianskirken. Samme år den 31. maj var vi tre til koncert med Elton John på Østerbro Stadion. Vi havde Vagns kollega Tommy og dennes kæreste Gry med i bilen til København, da de skulle til den samme koncert. Vi boede hos Marianne og Per. Koncerten var forrygende, og vejret var perfekt. Om lørdagen var vi i Tivoli med Per og spiste på Promenaden, og om søndagen var vi i Dragør og senere til kaffe hos onkel Erik. Samme år den 13. juni var vi til Open Air Koncert i Tangkrogen sammen med genboens, hvor Lars og Klaus var med. Vi havde 4 stole med til vi voksne, da Poul havde brækket anklen og ikke kunne stå op. Under Shubidua koncerten stod vi dog op, og drengene stod helt fremme. Vejret var fint, og det støvede meget, så især drengene var beskidte, da de kom hjem. Den 4. juli samme år tog vi til Rebild fest sammen med Hanne og Keld. Hovedtalerne var Frits E. Lawaetz og Kulturminister Grethe Rostbøll. Vejret var skønt, og vi havde frokost med, som vi nød uden for bakkerne, inden vi gik ind."}, {"type": "figure", "caption": "", "page": 168, "file": "assets/images-bog2/p168_01.jpg", "dim": [1181, 792]}, {"type": "para", "text": "Vi købte hatte, og morede os gevaldigt, mens vi sad i bakkerne og overværede al underholdningen, og vi mindedes vores dejlige tur til USA tre år tidligere. Vi var også sammen med dem året efter i maj til koncert med De Nattergale og senere til festugerevy."}, {"type": "para", "text": "Kulturen kom også til Spørring, arrangeret af både Husmoder- og Borgerforeningen. I marts 1993 havde vi besøg af Lotte Heise med fuld sal på Hotellet, og det var ikke kedeligt. Året efter kom der en irsk folkesanger, og i januar 1995 hørte vi et spændende foredrag af forfatteren Bjarne Nielsen Brovst. Samme år kunne vi også opleve Johannes Møllehave på Hotellet og Ancher Buch i kirken. Mens jeg sad i kirken og lyttede til Ancher Buchs violinspil, tænkte jeg tilbage på min gymnasietid, hvor han var musikvikar i vores klasse, og hvor ingen af drengene gad lytte til hans musik eller hvad han sagde men i stedet sad og spillede kort. Det var også på denne tid, at byfesten blev genoptaget i Spørring. En anden interessant foredragsholder var Niels Malmros, som jeg hørte på Ingeniørhøjskolen i maj 1994."}, {"type": "para", "text": "Vores ÅKV klub havde købt billetter til Bamses Venner i Trige Hallen den 11. november 1995, og det blev noget af et tilløbsstykke. Vi var 600 mennesker, der blev bespist, og så snart maden var fjernet og dansegulvet var blevet gjort klar, lød det fra Bamse: ”Wil do dans med mig?” Som skudt ud af en kanon kom folk på dansegulvet, og der blev danset uafbrudt hele aftenen. Kl. 24 blev Børge og jeg fejret med sang, hurraråb, gaver og champagne, idet vi begge fyldte 46 år. Efter festen gav Børge og jeg rundstykker hos os. ÅKV tog også sammen til festuge i 1995, hvor vi besøgte Tyrolerteltet."}, {"type": "para", "text": "I forbindelse med en campingtur sammen med Else og Jørn Griis i juni 1996 i Silkeborg, var Else og jeg til Cliff koncert på stadion der. Samme år var jeg til Rebild Fest med Svend Sønderup. Hovedtalerne var Ambassadør Edward E. Elson og H.K.H. Prins Joachim. Svend og jeg hyggede os i bakkerne, og vi var enige om, at det måtte være den kommende prinsesse Alexandra, der sad under en stor hat ved siden af prinsen, indtil vi senere hørte, at hun slet ikke var med. Det var Svend, der kørte."}, {"type": "para", "text": "Vagn og jeg kunne godt lide country musik, og vi sørgede altid for at komme ind i Country Teltet i festugen. I 1996 var vi inde og høre Tamra Rosanes."}, {"type": "para", "text": "I januar 1997 var vi inde og høre Finn Nørbygård i Musikhuset sammen med Karen og Børge. Showet hed ”Mig og Elvis”. Samme år gav Vagn mig billetter til Linie 3 Show, som vi oplevede i januar 1998."}]}, {"title": "Fester og gæster", "blocks": [{"type": "figure", "caption": "", "page": 169, "file": "assets/images-bog2/p169_01.jpg", "dim": [782, 519]}, {"type": "figure", "caption": "", "page": 169, "file": "assets/images-bog2/p169_02.jpg", "dim": [657, 472]}, {"type": "para", "text": "En af de større fester, vi var med til at arrangere, var mine svigerforældres guldbryllup den 23. februar 1990. Den blev holdt i Tårs Forsamlingshus med 110 gæster, bl.a. mor og mormor var inviteret med. Vi havde købt radio, båndoptager og lydbånd til dem i gave fra os alle sammen, og vi havde naturligvis lavet sang fra børnebørnene. Doris og jeg holdt en tale på skift, hvor Doris fortalte om tiden, indtil jeg kom ind i billedet, og jeg fortalte om mine oplevelser med dem. Vi havde sat talerne med billeder ind i to hæfter, som var bundet ind i guldpapir, og dem fik de overrakt. Vi syntes selv, det gik godt. Vi lavede to æresporte, en til huset og en til Forsamlingshuset. Naboerne hjalp til, og om aftenen, da vi havde fået puttet guldbrudeparret i seng, satte vi portene op og inviterede alle involverede ind på kaffe og brød. Næste morgen var meget højtidelig med hornmusik og 80 gæster til morgenkaffe. Lars optog alt på video, og han havde sit kjolesæt på til festen om aftenen. Det var en meget minderig dag, som farmor og bedstefar var meget glade for.  Den 16. januar året efter fyldte bedstefar 80 år. Det skulle ikke rigtigt markeres, men der kom alligevel 40 gæster for at fejre ham. Jo, de havde en stor familie og omgangskreds. Vi kørte derop om eftermiddagen og tilbage om aftenen."}, {"type": "para", "text": "Den 17. september 1991 havde Doris og Poul Erik sølvbryllup. Vi kørte derop aftenen før for at være med til at sætte æresporten op."}, {"type": "figure", "caption": "", "page": 170, "file": "assets/images-bog2/p170_01.jpg", "dim": [887, 591]}, {"type": "para", "text": "Den var lavet, da vi kom, og det var dejligt, for jeg har aldrig været særligt kreativ til det med æresporte, selv om jeg efterhånden har prøvet det nogle gange. Heldigvis er der altid nogen, der er gode til at arrangere blomster."}, {"type": "para", "text": "Jeg har aldrig nogensinde set så flot en æresport, men det er åbenbart niveauet i Svenstrup. Lars var naturligvis med. Vi drak kaffe hos Tages genboer, Lis og Ole. Næste morgen var vi 100 til morgensang og efterfølgende kaffe, og 30 til frokost. Vi kørte hjem kl. 15, da jeg skulle på arbejde kl. 17. Festen skulle holdes om lørdagen på Rold Storkro, og vi havde fået lavet en sang. Vi havde i tiden forinden udtænkt og lavet en flot sangskjuler, som vi lige skulle lave færdig lørdag eftermiddag. Da Doris og Poul Erik havde telt og var friluftsmennesker, havde vi lavet en plade med grønt græs og syet et gult telt, som stod på græsset. Desuden havde vi pyntet det med campingmøbler, små dukker og cykler, så det så rigtig fint ud. Sangene skulle ligge i teltet. Jeg havde min røde kjole på fra Lars’ konfirmation, Vagn havde smoking på, og Lars havde sit konfirmationstøj på, så vi var mægtig fine til festen, som begyndte kl. 17 og sluttede kl. 3. Det var en dejlig fest, og jeg holdt tale."}, {"type": "figure", "caption": "Den 17. september 1991. Det er usædvanligt at have alle fire forældre med til sit sølvbryllup, og at de er friske. Fra venstre er det Krista, Chr. Viggo, Doris, Poul Erik, Jacob og Herdis.", "page": 170, "file": "assets/images-bog2/p170_02.jpg", "dim": [750, 1181]}, {"type": "para", "text": "Den 26. december 1991 fyldte mormor 90 år, og det var et helt mirakel, at hun og vi kom til at opleve den dag, for forinden havde der været bud efter hende. Den weekend, hvor Købmandens og mor besøgte os i september, blev mormor syg. Søndag den 8. september, lige efter de var kommet hjem nede fra os, ringede Ditte og fortalte, at mormor var blevet indlagt på sygehuset med lungebetændelse, og mor var taget med hende. Det var et hårdt slag for mig, for jeg elskede min mormor meget højt. Jeg husker, at jeg gik rundt med konstant kvalme i de dage, og jeg ville så gerne besøge hende, inden det blev for sent. Onsdag den 11. september tog jeg så toget til Hjørring, og hvor blev jeg glad og overrasket over at se mormor sidde op i sengen, da jeg kom ind. Mor og moster var der også. Men allerede dagen efter fik hun tilbagefald, og Helge og Erik blev kaldt hjem den 13. september. Mormor var imidlertid sej, og da vi besøgte hende igen dagen før festen i Rold, altså den 20. september, havde hun det godt. Da vi så igen besøgte hende den 28. september, var hun oppegående og talte om sin 90-års fødselsdag og hvordan den skulle holdes. Så var vi klar over, at hun nok skulle komme over det i denne omgang. Fødselsdagen oprandt, og fødselaren havde aldrig set bedre ud. I hvid bluse og lang sort nederdel sad hun der ved hovedbordet på Dybvad Kro, ved siden af sin bror Alfred og blandt sine godt 40 gæster, både familie og venner. Vi havde en overraskelse i ærmet til hende: Vi havde planlagt, at Anne-Mette og Lars skulle give danseopvisning efter middagen, så vi løj for mormor og spurgte hende, om vi måtte tage Anne-Mette med, da vi havde lovet at ”passe” hende den dag. Anne-Mette var en frisk pige, så hun faldt godt ind i selskabet, for hun var just ikke mundlam. Fødselaren indledte med at holde en tale – uden manuskript, og så kom taler og sange ellers i en lind strøm. Jeg havde lavet en sang fra Lars, som han selv kom ind med. Desuden holdt mor en fin tale, og Per holdt en sjov tale om alt det, der var sket i verden på de 90 år. Det var sjovt, for mormor kunne ikke lade være med at sidde og kommentere talen, bl.a. sagde hun, at vi aldrig skulle have solgt de Vestindiske Øer, og da Per nævnte 90-års fødselsdagen fra TV, kommenterede hun også på, at hun i hvert fald ikke skulle have sådan en gammel ”fister” med i seng. Det var meget underholdende. Jeg holdt også en tale, hvor jeg talte om mit elskede Konditori og min barndom der. Efter middagen klædte danseparret om til fin kjole og kjolesæt, og inden musikken spillede op til dans, annoncerede jeg i mikrofonen, at nu havde vi en overraskelse til oldemor, men hun var jo ikke dum, den gamle dame, for hun sagde: ”Det havde jeg da regnet ud”. Men hun var glad for dansen, og gæsterne var så begejstrede, at nogle af de gamle damer kom hen og gav dem penge for den gode underholdning, så jeg var en stolt mor. Bagefter blev der danset flittigt, og musikken spillede flere fællesdanse, hvor næsten alle var på gulvet og dansede med mange forskellige partnere. Efter festen kørte vi, de nærmeste, med mormor hjem og stillede alle hendes gaver an. Hun var ikke engang træt på det tidspunkt. Det havde i sandhed været en dejlig og minderig aften."}, {"type": "figure", "caption": "", "page": 171, "file": "assets/images-bog2/p171_01.jpg", "dim": [1155, 787]}, {"type": "figure", "caption": "", "page": 171, "file": "assets/images-bog2/p171_02.jpg", "dim": [993, 795]}, {"type": "figure", "caption": "", "page": 172, "file": "assets/images-bog2/p172_01.jpg", "dim": [527, 712]}, {"type": "para", "text": "Vi bliver i familien, for den 19. februar 1994 kunne Tage fejre 25-års jubilæum ved Jysk Pumpebeton, som senere kom til at hedde Unicon. Det blev holdt til frokost i Godthåb Forsamlingshus, og det var med både musik og dans. Vi var med til at give ham et armbåndsur til 1398 kr. Den 29. august samme år fyldte Anna-Lise 50 år, hvor hun holdt en fest ude, og igen havde jeg skrevet en sang. Den 15. januar 1995 var det Tages tur til at fylde 50 år, men denne gang ryddede de stuen og dækkede op til 30 gæster derhjemme. Der skulle ikke gøres så megen stads ud af den fødselsdag – man er vel en beskeden vendelbo."}, {"type": "figure", "caption": "", "page": 172, "file": "assets/images-bog2/p172_03.jpg", "dim": [782, 519]}, {"type": "figure", "caption": "", "page": 172, "file": "assets/images-bog2/p172_02.jpg", "dim": [786, 519]}, {"type": "para", "text": "Thomas og Lars på Møllerens Hus med havudsigt                                   80-årige farmor med sine to drenge Den 3. august 1994 fyldte farmor 80 år. Hun var jo lige blevet enke, så vi syntes ikke, at hun skulle være alene på sin fødselsdag. Derfor tog vi hende med hjem den 31. juli efter et besøg nordpå, og jeg husker, at vi hyggede os om dagen, mens Vagn var på arbejde, med at sidde på terrassen i det gode vejr. Vi fik snakket meget, mens farmor strikkede og hæklede. På selve dagen havde vi bestilt bord på Møllerens Hus, og der mødtes vi med familierne fra Svenstrup til en dejlig aften."}, {"type": "para", "text": "Søndag den 1. oktober 1995 fyldte Lars 18 år. Anne-Mette og mor Kirsten kom til morgenkaffe kl. 8, og de blev der og hjalp til hele dagen. Vi var 27 til frokost, som jeg selv havde lavet. Der var både familien og de nærmeste venner. Det var en meget hyggelig dag, men det, jeg husker bedst, var faster Doris’ tale til Lars. Hun var selv så rørt, at hun græd under det meste af talen. Lars havde en særlig plads hos sin faster, og de var meget glade for hinanden. I talen sagde Doris bl.a., at Lars altid havde været så sød, og vi havde aldrig haft problemer med ham. De sidste gæster gik kl. 21, hvorefter vi kørte Marianne og Per i lufthavnen. To dage inden fødselsdagen havde Lars 12 gæster til hjemmebagte pizzaer, frugt, chips og kage, og en anden aften havde vi inviteret Anne-Mette og hendes forældre, kæreste og bror ud at spise på ”Stedet” i Århus."}, {"type": "figure", "caption": "Så er alle gæsterne gået og Lars slapper af, den 1.10.1995", "page": 173, "file": "assets/images-bog2/p173_01.jpg", "dim": [789, 1163]}, {"type": "para", "text": "Den 7. september 1996 ringede min svigermor og fortalte, at Anna-Lise og Tage var blevet gift dagen før på Rådhuset i Ålborg. Tage havde jo fundet sammen med Anna-Lise, som var blevet enke i 1987, og hun var flyttet ind hos Tage. Nu ville de så have papir på hinanden, men at vi ikke måtte være med, var næsten utilgiveligt, blev Doris og jeg enige om i telefonen. Vagn havde endda spist til aften hos Anna-Lise og Tage aftenen før, fordi de havde været til begravelse med Christian Sørensen fra Linderum. Vagn havde imod al sædvane ikke spurgt Tage, hvad han skulle lave næste dag, fredag, så Tage slap for at stikke en løgn. Ikke engang Anna-Lises børn vidste noget. Det skulle hævnes, så sammen med Doris og Poul Erik udtænkte vi en plan: De inviterede Anna-Lise og Tage til spisning fredag den 27. september, og så inviterede vi ca. 15 venner og arbejdskolleger til brudeparret til at møde op på Frederikshøjvej 7 samme aften kl. 18.30. Vi samledes hos Preben og Ellen, inden vi i samlet trop (21 mennesker) gik over og ringede på hos Anna-Lise og Tage. Der gik lidt tid, for de var i bad og troede jo, at de skulle i byen, men så kom de frem, Anna-Lise i morgenkåbe, og så meget overraskede ud. Vi sang for dem under paraplyerne, for det regnede, hvorefter vi blev budt indenfor. Vi lod, som om vi regnede med, at de ville servere noget for os, og jeg tror da også, at Tage dimlede noget om, at de kunne bestille noget mad. Vi havde købt glaslysestager til dem sammen med familien. Lars var ikke med, da han var til fest på Universitetet. Vi tog det ganske roligt, for vi havde bestilt bord på en restaurant i Jomfru Ane Gade og en bus til at komme og hente os. Vi var ved at bilde Tage ind, at han skulle have kedeldragt og gummistøvler på, men de kom begge i det pæne tøj, som de jo allerede havde lagt frem. Det blev en forrygende aften, og på restauranten havde vi bestilt hot dogs til brudeparret som forret. Stemningen var helt i top, og efter middagen gik vi på værtshus i Gaden, eller rettere sagt på flere værtshuse. Vi dansede og morede os, og et af stederne satte de brudevalsen på, da de hørte, at det var et bryllup, vi fejrede, så brudeparret måtte pænt danse brudevals. Vi kom først i seng kl. 5, men alle havde haft en sjov aften. På årsdagen for brylluppet holdt Anna-Lise og Tage så en stor fest på en restaurant, og vi lavede æresport til lejligheden. Jeg havde skrevet en sang på melodien: ”Alfred skal giftes nu til morgen”, og Doris og jeg lavede en sketch, hvor vi ringede til hinanden og talte om, hvor skuffede vi var over, at vi ikke havde været med til vielsen, og at de så heller ingen gave skulle have. Den fik ikke for lidt, og folk syntes vist, det var rigtig sjovt."}, {"type": "figure", "caption": "", "page": 173, "file": "assets/images-bog2/p173_02.jpg", "dim": [1163, 792]}, {"type": "figure", "caption": "", "page": 173, "file": "assets/images-bog2/p173_03.jpg", "dim": [585, 723]}, {"type": "para", "text": "Vi var også i 90’erne til et væld af runde fødselsdage, jubilæer, konfirmationer, bryllupper og sølvbryllupper hos venner, men jeg vil kun nævne de vigtigste."}, {"type": "para", "text": "Reinholt fyldte 60 år den 22. december 1993, men festen med over 100 gæster blev først holdt den Generalprøve hos Grete og Poul                                             Reinholt med sine to muser 22. januar 1994. Grete og jeg havde fået den geniale idé, at vi ville optræde som bakkesangerinder, og vi ville give den gas. Vi lejede kostumer i en butik i Århus, og det var med fjer i hatten, corsage og sving i skørtet. Gretes antræk var blåt, og mit var rødt. Dernæst skrev vi en sang på flere melodier om Reinholt, og vi skulle helst huske teksten udenad, for vi skulle jo agere sammen med Reinholt samtidig. Gæsterne fik også udleveret sangen, men de skulle kun synge med på omkvædet. Vi allierede os også med musikken, som skulle akkompagnere os. Aftenen før holdt vi generalprøve hos Grete for mændene og drengene. Da aftenen oprandt, var vi så nervøse, at vi slet ikke kunne spise noget, før vi havde det overstået. Præsten var også med til festen, da han var en del af old boys holdet, som var inviteret med, og han skulle altid op og synge, når der var fest. Tænk, han insisterede på, at han ville have sit indslag overstået først, fordi han først kunne spise noget, når det var overstået, og han var endda vant til at tale i kirken, men selvfølgelig ikke for 100 mennesker, snarere en 3-4 stykker. Grete og jeg var rasende, men det blev, som han ville have det, og vi måtte vente. Da vi stod ude på toilettet og klædte om, spurgte vi hinanden, hvad vi dog havde rodet os ud i, men nu måtte det bære eller briste. Folk var ellevilde, da vi kom ind i vores kostumer og hev Reinholt med op foran musikken. Vi havde taget godt med læbestift på og friskede det op undervejs, så da vi var færdige med Reinholt, havde han læbestift over hele hovedet. Vi skiftedes til at sidde på hans knæ og danse med ham, og han nød det. Det hele blev filmet, og han har bagefter tit snakket om, hvor godt det var, det vi lavede. Bagefter var vi enormt lettede over, at det var gået så godt. I november 1990 ringede Peter Jes, som dengang var leder af Spørring Gl. Skole og Klubberne, for at spørge, om vi ville have en irsk pige til at bo i en uge. Jeg husker ikke mere, hvordan det hang sammen og hvorfor hun skulle komme, og jeg var heller ikke vild med tanken, fordi jeg på det tidspunkt havde meget travlt på arbejde, men jeg sagde til sidst ja. Hun hed Gillian og boede hos os på gæsteværelset fra den 23. til den 30. november. Hun var meget sød, og det gik fint med at have hende boende. Hun var med mig på arbejde en dag, hvor hun fortalte om Irland i mine klasser, og hun var med til julemarked i Spørring, hvor jeg havde en bod og solgte mors tasker og mit eget papirklip."}, {"type": "figure", "caption": "", "page": 174, "file": "assets/images-bog2/p174_02.jpg", "dim": [774, 1192]}, {"type": "figure", "caption": "", "page": 174, "file": "assets/images-bog2/p174_01.jpg", "dim": [763, 1171]}, {"type": "figure", "caption": "", "page": 175, "file": "assets/images-bog2/p175_01.jpg", "dim": [1160, 792]}, {"type": "para", "text": "Den 17. juni 1994 tog jeg toget til Hjørring for at deltage i mit 25-års studenterjubilæum på Hjørring Gymnasium. Jeg glædede mig meget til at møde de andre fra klassen, og det blev da også en uforglemmelig dag. Først var vi med til translokationen, men det var skuffende, at der ikke var plads til os i festsalen og at vi i stedet måtte følge med på en skærm i kælderen. Men her mødte vi så gamle kammerater fra de andre klasser og fik et glas sammen. Vores klasse kørte dernæst til Lønstrup og spiste frokost på Marinella i det fine vejr, hvorefter vi var ude og gå tur fra Mårup Kirke til fyret. Mange skulle hjem til forældrene og klæde om til om aftenen, hvilket jeg jo ikke kunne gøre, så jeg blev inviteret til at køre med en, der hed Niels, hjem til hans ejendom i Sindal og hilse på hans kone, og der fik jeg vasket sandet af tæerne og blev frisket lidt op, inden vi igen kørte til Hjørring og spiste middag i Svanelunden sammen med vores gamle dansklærer Jørgen Lorenzen. Nogle af kammeraterne havde slet ikke forandret sig, mens andre var kommet til at se lidt gamle ud. Vi besluttede at mødes igen efter 5 år, men det blev til 15, for vi mødtes igen til 40-års jubilæet. Jeg blev kørt til Thorshøj af Niels efter festen, for vi skulle næste dag rydde mors hus, da det endelig var blevet solgt."}, {"type": "figure", "caption": "", "page": 176, "file": "assets/images-bog2/p176_01.jpg", "dim": [1184, 781]}, {"type": "para", "text": "I 1.g gik jeg i klasse med en pige fra Hirtshals, der hed Lise Slot. Hun var en køn høj og slank mørkhåret pige og tillige sød. Vi blev rigtig gode veninder, og vi besøgte hinanden. Jeg husker især engang, hvor jeg tog med hende hjem fra skole og overnattede. Efter 1.g blev vi delt, og vi skulle desværre ikke gå i samme klasse mere, men vi blev ved med at ses, også lidt efter gymnasiet. Hun blev senere kæreste med Eigil Nielsen, en dengang kendt fodboldspiller, som var vokset op i Thorshøj, så jeg kendte ham godt. De blev gift og fik to drenge, men den ene døde desværre som spæd. Jeg havde glædet mig til at hilse på Lise til jubilæet, og hun var da også med, og jeg talte kort med hende, men hun virkede fremmed og fjern, og hun så lidt hærget ud. Da jeg til 40-års jubilæet i 2009 nævnte hendes navn, var der en, der kunne fortælle, at hun var død. Det gjorde virkelig indtryk på mig, især også fordi den samme person kunne fortælle, at hun havde haft et ulykkeligt ægteskab med en mand, der slog hende, og hun var begyndt at drikke. Hvor kan skæbnen dog være hård."}, {"type": "para", "text": "Det var sjovt at finde ud af, hvad de forskellige klassekammerater var blevet til og hvilke jobs, de havde fået: Henning Friis var eksportkonsulent med egen virksomhed i Tranbjerg. Til 40-års jubilæet fik jeg at vide, at han var død, sandsynligvis fordi han havde haft problemer med alkohol."}, {"type": "para", "text": "Poul Erik Dam var ambassaderåd i Washington, USA."}, {"type": "para", "text": "Hans Jørgen Olsen var tandlæge i Bogense."}, {"type": "para", "text": "Lars Espersen var advokat og medindehaver af advokatfirmaet Espersen A/S i Frederikshavn (og i familie med tidligere minister Lene Espersen). Hans far havde været fiskeeksportør i Hirtshals. Marianne de Thurah var hospitalslaborant i Varde."}, {"type": "para", "text": "Søren Baj Lund var tandlæge i Odense."}, {"type": "para", "text": "Inger Marie Mørk Jensen var 1. reservelæge i Viborg men boede i Silkeborg."}, {"type": "para", "text": "Carl Uggerhøj var overlæge på øjenafdelingen i Aalborg og gift med Annie. De to var klassens genier og skolekærester. De blev dog senere skilt, og til 40-års jubilæet havde han en ny kone. Niels Krogsgaard var EDB programmør og boede i Sindal."}, {"type": "para", "text": "Annie Brinkmann Kristensen (gift med Carl) var lektor på Ålborghus Gymnasium. Jens Høyrup var ingeniør i København."}, {"type": "para", "text": "Leif Bundgård var major i Varde."}, {"type": "para", "text": "Kaj Størup var revisor i Hirtshals."}, {"type": "para", "text": "Allan Aagaard var gymnasielærer i Dronninglund. træ, så det var en oplagt sangskjuler."}, {"type": "figure", "caption": "Da onkel Erik fyldte 60 år den 5. maj 1997, havde jeg lavet sang, og sangskjuleren var denne kurv med brænde, hvor Vagn havde boret hul i hvert stykke træ til sangen. Erik fyrede jo med", "page": 177, "file": "assets/images-bog2/p177_01.jpg", "dim": [943, 752]}, {"type": "figure", "caption": "", "page": 177, "file": "assets/images-bog2/p177_02.jpg", "dim": [787, 1044]}]}, {"title": "Frugt, grønt, kød og kager", "blocks": [{"type": "para", "text": "Vi havde en stor fryser, så der skulle samles til huse. Om sommeren tog jeg ud og plukkede jordbær (selvpluk), alene eller sammen med andre. Fx kan nævnes, at jeg i 1990 plukkede 18 pund jordbær sammen med Hanne, og i 1994 plukkede Per, Lars og jeg 30 pund jordbær til 6 kr. pr. pund. Hindbær, stikkelsbær, solbær og ribs havde vi i haven, og det nød vi. Hindbærrene var nemme at plukke, det var værre med ribs, solbær og stikkelsbær, men vi kunne godt lide stikkelsbærgrød, solbærsyltetøj og rysteribs. Jeg eksperimenterede sågar med at lave ribssaft, men kun i små mængder. Rødbeder, græskar og asier dyrkede vi også selv, så der blev syltet et par gange om året. Græskar syltede jeg med vanilje, som mor gjorde det, og ikke med ingefær som min svigermor gjorde det. Endelig kan nævnes, at vi i august 1990 plukkede hyben under et weekendophold hos Lis og Ole ved Bæktrup Vig, og dem lavede vi til hybenmarmelade."}, {"type": "para", "text": "Det var ovre de dage, hvor vi fik kød fra Vestergård, så vi købte kød efterhånden, som vi skulle bruge det. I september 1990 købte vi dog af Vagn Bjørn (Alices Helles svigerfar, som havde en gård) 75 kg oksekød til 36 kr. pr. kg. Der havde vi kød et stykke tid. I 1995 gav jeg Vagn en bordgrill i fødselsdagsgave. Vi havde prøvet det hos Kirsten og Erik, og konceptet tiltalte os. Jeg cyklede derfor til Hinnerup, hvor de havde dem på tilbud, og købte en. Den brugte vi meget de efterfølgende år, også på camping, og vi har den såmænd i campingvognen endnu."}, {"type": "para", "text": "Jeg bagte mere dengang, end jeg gør nu. På sidste skoledag havde jeg altid kage med til klasserne, men Vagn mobbede mig med, at han kun fik kanterne, når jeg bagte til klasserne. Jeg bagte dog også på andre tidspunkter, men tit røg det meste i fryseren, så der kun var en lille smagsprøve til Vagn og Lars. Jeg bagte rugbrød, men ikke med surdej. Man kunne købe brødblandinger, hvor der kun skulle tilsættes gær og vand, og de smagte rigtig godt. Det var mor, der havde lært mig det. Jeg bagte også flûtes engang imellem, selvom jeg aldrig har været god til gærdej. Lars havde haft hjemkundskab i skolen, og han kunne godt lide at bage. Fx bagte han boller og kagemand til Vagns fødselsdag i 1991. Året efter havde jeg fundet en opskrift på skildpadder, og da Vagn samlede på dem, fik jeg den idé, at jeg ville bage skildpadder til hans fødselsdag og overraske ham. Jeg gjorde det kun den ene gang, for det var et kæmpe arbejde, men jeg har stadig opskriften liggende. Selve skildpadden var lavet af mørdejg, og indeni var der creme og syltetøj. Skjoldet var overtrukket med chokolade, hvori der var lavet mønstre som i et skjold. De var meget virkelighedstro, og der var nok i alt 20. Jeg inviterede Mary ind på chokolade om eftermiddagen, og da fødselaren kom hjem, afslørede vi fadet med skildpadder. Han blev heldigvis rigtig glad og overrasket, og vi kunne næsten ikke nænne at sætte tænderne i de søde væsner."}, {"type": "figure", "caption": "", "page": 178, "file": "assets/images-bog2/p178_01.jpg", "dim": [1176, 776]}]}, {"title": "Mode og gaver", "blocks": [{"type": "para", "text": "Det skete, at Lars og jeg brugte Preben som frisør, hvis vi var i Svenstrup i andet ærinde eller skulle til fest deroppe. Preben tog sig udelukkende af herreklip, mens hans to ”piger” ordnede resten. I september 1990 blev Lars klippet og fik reflekser i håret, og ved samme lejlighed blev jeg klippet og farvet kastanjebrun. Det hele kostede 635 kr. Preben var godt med prismæssigt. Lars blev ligesom jeg normalt klippet hos Lis i Todbjerg. Hun var rigtig god til at sætte dansehår, både på piger og drenge. Det var også der, Lars fik krøller i håret et par gange i 1992. Lis havde en god salon og var meget kreativ. Derfor solgte hun også alt andet i salonen, såsom tøj, dekorationer, smykker, hårpynt m.m. Den 9. april 1995 holdt hun et stort modeshow i Todbjerg Forsamlingshus med 125 mennesker. Hun havde spurgt, om jeg ville hjælpe til sammen med Anne-Mettes mor Kirsten, og det ville vi naturligvis gerne, for vi havde det altid sjovt, når vi var sammen. En af dansefædrene, Arne Kromann, skulle være konferencier (han var fuld af sjov), og Lars skulle styre musikken og give et danseshow sammen med Anne-Mette. Det blev en stor succes, selvom jeg må indrømme, at jeg blev lidt skuffet, da jeg opdagede, at Kirsten skulle gå mannequin. Den tjans kunne jeg godt have tænkt mig."}, {"type": "para", "text": "Lis havde rimelige priser i sin salon, og jeg tror, at vi, der kendte hende godt, fik lidt rabat. I 1996 betalte jeg 590 kr. for klipning, farvning og permanent. Vagn havde anlagt sig skæg inden Lars’ konfirmation, og jeg syntes egentlig, at det klædte ham. Men på billederne fra konfirmationen lignede han nærmest en fremmedarbejder, så jeg ymtede lige et par gange over for ham, at det måske nu var tiden, at han skulle fjerne det. Derfor var det da også umådeligt pinligt, at han i maj samme år fjernede det, uden at jeg lagde mærke til det. Det var først senere, da han ville give mig et kys, at jeg udbrød: ”Jamen du godeste, du har jo fjernet dit skæg!”"}, {"type": "para", "text": "Lars fik briller den 19. november 1991, og de klædte ham godt, selvom jeg var lidt ked af, at han nu skulle døje med dem. Det kom han så heller ikke til at gøre ret længe, for den 21. januar 1992 fik han kontaktlinser. Han ville gerne undgå briller, når han dansede, og det var fuldt forståeligt, både af praktiske og æstetiske årsager, for han var lidt forfængelig, og han syntes vist ikke, at briller klædte ham så godt. Nu havde han dem kun i reserve. Jeg selv har aldrig ønsket kontaktlinser af den simple årsag, at jeg ikke kan forestille mig at skulle sætte et fremmedlegeme ind mod øjet. Derfor var jeg også fuld af beundring over Lars, der med stor motivation kastede sig ud i at sætte linserne i første gang. Jeg kunne dårligt tåle at se på det. Lars brugte også tid foran spejlet om morgenen med føntørrer og hårlak, og hårlak-fabrikanterne tjente fedt i den periode."}, {"type": "para", "text": "Hans Ørsnæs, som boede i Spørring og også blev kaldt Klok-Hans, var urmager og arbejdede i en brilleforretning. Han havde en lille nebengeschæft, hvor han solgte briller hjemmefra til en billig pris. Man skulle i forvejen have været hos øjenlægen, men så kunne man låne 10 stel med hjem fra Hans, inden man besluttede sig. Det var en fin forretning, også for Hans. Der gik rygter om, at det ikke var helt lovligt, og han blev da også fyret fra sit job nogle år senere og gik i lære som murer. I 1997 købte jeg et par briller hos ham til 1764 kr."}, {"type": "para", "text": "Da jeg var barn, fik man ikke rettet tænder, så jeg havde et rimeligt stort mellemrum mellem mine fortænder. Selvom jeg efterhånden havde vænnet mig til det, generede det mig lidt. Derfor slog jeg til, da min tandlæge, Alfred Wolthers, i vinteren 1991 tilbød mig, at han kunne bygge plastik på fortænderne og derved gøre mellemrummet mindre. Og sådan blev det. Jeg har stadig billederne fra ”før” og ”efter”."}, {"type": "para", "text": "Jeg kunne godt lide at købe tøj hos Chanella (ejet af Linda og Rita) i Tårs. Da de i 1990 åbnede butikken, var der mange, der sagde, at det ikke kunne gå, men de har med årene udvidet til også at handle med sko, og i dag eksisterer Chanella i bedste velgående. Min svigermor købte også tøj der, for hun syntes, de var så gode til at vejlede. De er begge et par rigtig søde og venlige piger, så kunderne føler sig godt tilpas."}, {"type": "para", "text": "Jeg har noteret mig, at jeg fik to stykker dyrt overtøj i 90’erne. I marts 1995 købte jeg en gul Helly Hansen vinterjakke til 2600 kr., og i september 1997 købte jeg en gråsort lang frakke til 2300 kr."}, {"type": "para", "text": "Lars har altid været sød til at huske Mors Dag, og jeg har noteret, at jeg i 1990 fik en papirkurv og en æske chokolade."}, {"type": "para", "text": "Vagns forældre havde en fast takst på gaver til fødselsdag, og det var ikke overdådigt, men vi fik store julegaver, og engang imellem fik vi et større beløb. Fx fik hvert par 1000 kr. i maj 1990, og børnebørnene fik hver 500 kr."}]}, {"title": "Sygdomme", "blocks": [{"type": "para", "text": "Vi var ikke meget syge i vores lille trekløver, og der skulle meget til, for at vi blev hjemme fra skole og arbejde. Det lå ligesom i vores opdragelse, og det kunne være både godt og ondt."}, {"type": "para", "text": "Folk har ofte kriser i forbindelse med runde fødselsdage, såsom 50 og 60 år, men min største fødselsdagskrise var, da jeg fyldte 40, eller kort tid efter. Jeg fik nemlig en såkaldt tennisalbue, foruden at jeg kom til at lide af blærebetændelse. Derfor tænkte jeg: ”Er det sådan at fylde 40?” Medens jeg havde en tennisalbue, gik jeg til tider med armen (højre) i en slynge, så jeg var temmelig handicappet. Alice gav mig zoneterapi og massage, og det hjalp. I 1991 behandlede hun mig også for en fibersprængning i benet, som jeg havde fået, mens jeg spillede badminton med hende. Jeg cyklede tre dage senere! Der var dog skavanker, hun ikke kunne kurere."}, {"type": "para", "text": "Kort før Lars’ konfirmation fik jeg et modermærke fjernet fra ryggen. Det havde generet mig i nogen tid, og nu skulle det væk. Der var heldigvis ikke noget ondartet i det."}, {"type": "para", "text": "Jeg havde en tendens til at udvikle vandcyster i brystet, og første gang, jeg tog til lægen med det, var jeg nervøs, for jeg forestillede mig, at det var kræft. I april 1992 fik jeg 4 vandcyster tømt hos lægen, og 5 år senere sendte de mig på Randers Sygehus. Da blev jeg bange, men det var det samme: de tømte 3 vandcyster. I marts 1996 var jeg alligevel sygemeldt i to dage, idet jeg fik konstateret lungebetændelse af natlægen, som vi havde tilkaldt. Jeg gik desværre glip af en danseturnering og Tove Frosts 50-års fødselsdag."}, {"type": "para", "text": "Allerede i marts 1991 begyndte Vagns tunge at ”slå knuder”, og han fik en knude skåret væk. Det var dog ikke nok, så han blev opereret i november samme år. Næste år kom knuden tilbage, og der skulle en ny operation til i september. Vagn døjede også til tider med ryggen, således i februar 1994, og i marts samme år begyndte han at døje med neglesvamp på tæerne. Sidstnævnte prøvede han at kurere i samråd med lægen, og en af kurene var meget dyr og bestod i at male neglene med noget blåt væske. Det hjalp i perioder, men svampen vendte altid tilbage, og i dag har han det i mindre grad. I april 1994 brækkede Vagn håndleddet og havde det i gips fra den 24. april til den 16. juni, men han var kun sygemeldt i 10 dage. I 1995 fik Vagn problemer med maven, men flere undersøgelser viste ikke noget, og til sidst forsvandt det. Derimod måtte Alice træde til, da Vagn fik problemer med iskias og dårlig ryg, og en dag i juni 1996 var det særlig slemt. Vi skulle ud til Marie og Svend en søndag til eftermiddagskaffe, men Vagn lå inde i sengen og kunne knap bevæge sig. Han fik straks en tid hos Alice men måtte tage bilen derop. Hvad hun gjorde ved ham, ved jeg ikke, men han kom nærmest løbende hjem, og vi kom i byen til kaffe. Da jeg ringede op og spurgte: ”Hvad har du gjort ved min mand?”, svarede hun: ”Ja, det skulle du lige vide, men jeg trak bukserne af ham!” Vagns arbejde gjorde, at han nemt kunne komme til skade, hvilket også skete i februar 1997, hvor han skar foden. Han forbandt den selv men måtte på skadestuen næste dag. Vagns mor gik tit rundt og var små-syg, og vi havde altid troet, at hun skulle dø før Chr. Viggo, idet hun var lidt svagelig, men sådan skulle det ikke gå. Lige før hans død faldt hun og brækkede lårbenet, så i en periode havde vi dem begge indlagt på Hjørring Sygehus. Farmor var glad for at være der, og det var praktisk, at vi kunne besøge dem begge samtidig. Vi kunne køre Krista i 1995 i Papegøjehaven                                       Vi drikker kaffe i Godthåb i 1997 efter at farmor er kørestol hen og besøge Chr. Viggo, som var sengeliggende. Efter hans død fik vi den tradition, at Krista gav middag eller frokost på sin fødselsdag den 3. august eller den nærmest lørdag. På hendes fødselsdag i 1997 faldt hun om under frokosten på Søparken i Åbybro. Heldigvis var Charlotte sygeplejerske, så hun tog affære. Faldt om er måske så meget sagt, men pludselig kunne vi ikke komme i kontakt med hende, og Tage var sikker på, at hun var død. Hun kom på sygehuset og var der i 4 timer sammen med Doris. Hun fik noget væske, og så blev de sendt hjem og kunne drikke kaffe på terrassen sammen med os andre i Godthåb. Problemet var, at Krista ikke fik nok væske, og det skete flere gange, at hun fik black-out, når vi var sammen, således den 28. juni 1998 og en måned senere under middagen til vores sølvbryllup. Som regel skulle hun bare hen og ligge lidt og have noget væske, så var hun frisk igen og kunne holde ud, til festen var forbi. Heldigvis blev huset på Blommely solgt, og farmor flyttede i en lille lejlighed i et rækkehus på Johannes Hansens Vej i Tårs den 27. maj 1995."}, {"type": "figure", "caption": "kommet tilbage fra hospitalet", "page": 180, "file": "assets/images-bog2/p180_01.jpg", "dim": [777, 519]}, {"type": "figure", "caption": "", "page": 180, "file": "assets/images-bog2/p180_02.jpg", "dim": [754, 519]}]}, {"title": "Mormors død den 21. november 1992", "blocks": [{"type": "para", "text": "Jeg talte tit med mormor i telefonen. Hun var god at snakke med, og hun var ofte min allierede, når jeg havde været på kant med mor. Når vi var sammen med mor og mormor, syntes jeg somme tider, at mor behandlede mormor dårligt og svarede hende igen, men sandheden var nok, at mor aldrig tilgav sin mor for at ville have bortadopteret mig. Mor sagde også til mig engang, at når mormor ikke var her mere, ville hun fortælle mig hele sandheden. Det skete aldrig. Jeg elskede min mormor og er sikker på, at hun har været under en eller anden form for pres, da jeg blev født. Og jeg ved, at hun elskede mig, for det vidner det, jeg nu vil fortælle, om."}, {"type": "para", "text": "Den 16. november 1992 kl. 6.45 ringede telefonen. Det var mormor, som bare ville sige, at vi ikke skulle give hende noget særligt i julegave. Vi kunne købe et par strømper eller en pose kaffe. Hun lød underlig – måske var hun ved at blive senil. Jeg tog på arbejde, og det var en af de dage, hvor jeg skulle undervise om aftenen på Handelshøjskolen. Jeg kom derfor lidt sent hjem, omkring kl. 21. Jeg var lige trådt ind i bryggerset, da telefonen ringede. Jeg forventede, at enten Vagn eller Lars tog den, men de havde hørt mig, så de forventede som altid, at det var mig, der tog telefonen. Den ringede nogle gange, inden jeg nåede den, og hvor var jeg lykkelig for, at jeg nåede den, for det var min sidste samtale med mormor. Hun lød faktisk mere frisk end om morgenen, og hun ringede for at sige et sidste farvel og for at takke mig for alt det, jeg havde været for hende i årenes løb. Hun sagde bl.a.: ”Jeg har haft ringet til dig mange gange. Sygeplejersken er her, og hun syntes, at jeg skulle prøve igen. Nu vil jeg i min seng, og så er det snart slut. Det ser ikke så voldsomt ud, når jeg ligger i min seng. Hils Lars og Vagn, og lov mig, at I vil snakke med Alfred. Hvis jeg stadig er her i morgen tidlig, ringer jeg til dig. Tak for alt, Merete”. Jeg sank lige en ekstra gang, for hvad var det, der foregik? Heldigvis havde jeg nærvær nok til også at takke hende for vores dejlige tid sammen. Jeg var helt ødelagt bagefter og tænkte på, om hun havde ringet rundt til sine fire børn på samme måde. Hun havde ringet rundt og fortalt, at julegaverne lå klar til os, men jeg fandt ikke ud af, om hun havde taget afsked med dem på samme måde, som hun havde gjort det med mig. Samtidig troede jeg ikke rigtigt på, at hun kunne mærke, at hun skulle dø, og da jeg vidste, at sygeplejersken var der, foretog jeg mig ikke yderligere. Næste morgen var jeg spændt på, om mormor ringede, men det gjorde hun ikke. Hun var dog ikke død om natten men var om morgenen blevet indlagt på hospitalet og lå nu bevidstløs, så hendes fornemmelse havde været rigtig. Mor og moster var der, og ”drengene” kom hurtigt hjem. Den 18. november vågnede mormor og lå og råbte, og den 19. november sad hun op og spiste. Havde hun igen snydt døden? Nej, den 20. november blev hun dårligere, og den 21. november kl. 0.15 sov hun stille ind, næsten 91 år gammel. Jeg havde denne gang ikke det samme behov for at komme op og tage afsked med mormor, som sidste gang, hun var indlagt, for jeg havde jo taget afsked. Jeg var afklaret med, at hun skulle herfra, og hun kom det på den måde, hun ønskede. Det ville ikke have været mormor at skulle ligge syg i længere tid, og hun havde haft et langt og godt liv. Jeg skrev et kort til hende, men hun nåede ikke at få det, mens hun var ved bevidsthed. Den 27. november begravede vi mormor, og efter begravelsen var der kaffe på Dybvad Kro, hvor jeg holdt en tale for mormor. Jeg indledte med at citere ”Altid frejdig, når du går”, fordi jeg syntes, den passede så godt på hende. Hun nåede sit mål. Det var godt, at hun ikke oplevede at miste mor året efter. Det var hårdt nok for hende, da far døde. Bagefter fandt vi de kuverter, hun havde lavet til os alle med penge til julegaver. På mit kort stod der: ”Julen 1992. En Glædelig Jul ønskes eder alle fra Mormor. + Meretes Fødselsdagsgave”. For de 200 kr., der var til min fødselsdagsgave, købte jeg et perlearmbånd. Det var mærkeligt at få julegave fra en, der var død. Da vi ryddede mors hus, fandt vi det brev fra mormor, som hun havde skrevet til mor, da hun gav dem penge til fars ophold i Tyskland: ”Kære Doris! I to var de første til at sige, at det var i orden, hvis Jeg hjalp Helge, og nu er det eders tur. Jeg er meget glad for at I faar den Tur, og hvem ved, maaske kan det hjælpe, man skal aldrig opgive, og her er lidt til Hjælp til at betale med. I skal ikke have daarlig Samvittighed men modtage dem med samme Glæde, som Jeg gi’r dem. En rigtig god Tur og en kærlig Hilsen til eder begge. Mor”."}, {"type": "figure", "caption": "", "page": 182, "file": "assets/images-bog2/p182_01.jpg", "dim": [1184, 789]}]}, {"title": "Mors kræftsygdom og død (den 18. august 1993)", "blocks": [{"type": "para", "text": "Det hele startede den 20. januar 1984. Vi skulle nordpå om fredagen til tandlæge Bornæs i Øster Vrå. Vi havde fået ham som tandlæge efter nogle uheldige oplevelser med en tandlæge i Risskov. Da vi den dag var færdige hos Bornæs, var aftalen, at vi skulle hente mor fra hendes arbejde i Børnehaven i Øster Vrå, Bødkergården. Vi fik lidt af et chok, da hun fortalte os, at hun skulle opereres for en polyp på tarmen. Jeg fik straks en kugle i maven, men mor slog det hen. Det var nok ikke noget, og hun gjorde sit til, at weekenden blev så hyggelig som muligt. Den 3. februar fik hun så diagnosen: kræft. Det var op til en weekend, og jeg havde det elendigt. Alice kom og trøstede mig om lørdagen, og Grete gav eftermiddagskaffe om søndagen, men indeni gnavede frygten for at miste mor. Hun var kun 49 år. Mor blev indlagt mandag den 6. februar, og lægen sagde, at hun havde gode chancer. Tirsdagen var frygtelig at komme igennem og onsdagen endnu værre, hvor mor blev opereret. Jeg ringede på Hjørring Sygehus for at høre, hvordan operationen var gået. Gudskelov var alt gået godt, og de mente at have fjernet hele svulsten. De havde fjernet et stykke af tyktarmen, og heldigvis slap hun for at få afføring ud gennem siden, en såkaldt stomi. Allerede dagen efter operationen talte jeg med mor i telefonen, hvor hun sagde, at hun havde det godt. Jeg var ovenud lykkelig."}, {"type": "para", "text": "Inden operationen havde jeg skrevet et langt brev til far, hvori jeg havde trøstet ham med, at hun var så ung og nok skulle klare det. Jeg tror ikke, far ville have kunnet klare at blive alene. Han kunne ikke lade følelserne få frit løb, så han ville bare have gået med alle sine bekymringer, og det kunne have slået ham totalt ud. Jeg havde bedt far købe en stor buket roser fra os 5, som skulle stå på hendes bord, når hun vågnede efter operationen. På kortet, som jeg sendte med brevet, stod der: ”Fra 5 der elsker dig”. Om fredagen kørte vi til Hjørring for at besøge mor, og hun havde det efter omstændighederne godt. Vi tog far med til Vestergård, hvor vi fik aftenskaffe, og vi kørte med ham til Thorshøj og sov. Om lørdagen kørte vi ud til mormor og spiste middag, hvorefter vi kørte op til mor. Vi spiste alle 4 til aften i Vestergård, og kørte så op til mor igen om aftenen. Om søndagen kom far op og spiste med os i Vestergård, hvorefter vi besøgte mor, inden vi kørte hjem til Spørring. Den dag var hun lidt sløj men havde det allerede bedre om mandagen."}, {"type": "para", "text": "Weekenden efter besøgte vi mor igen, og den 20. februar blev hun udskrevet. Far passede og plejede hende i den næste tid, og det var han god til. Vi tog nordpå den 2. marts i snestorm. Det tog 4 timer at komme fra Spørring til Thorshøj. Mor var stadig afkræftet og svag og lå noget af tiden i sengen, så jeg gjorde huset rent om lørdagen og kogte suppe. Anette Knudsen kom og satte mit hår, for vi skulle til bryllup på Tårs Hotel med Anne Mette og Lars (Alice og Svends datter)."}, {"type": "para", "text": "Den 9. marts fyldte mor 50 år. På selve dagen, en fredag, var der lidt åbent hus, hvor vennerne kom forbi og hilste på. Vi kom kl. 17 og hyggede os om aftenen. Næste dag var de allernærmeste inviteret. Vi var 12, og jeg lavede maden. Onkel Erik havde sin kæreste Gurli og dennes søn Peter med. Jeg holdt en lille tale for mor, og vi havde en dejlig aften. Mor holdt ud til kl. 1.30. Allerede den 16. marts kunne mor tage turen til Spørring, men det var nok fordi hun og far skulle med til Lars’ afdansningsbal om søndagen. Mor blev hernede, og far kom og hentede hende om torsdagen. Hun startede på arbejde igen den 4. juni 1984."}, {"type": "para", "text": "Mor blev indlagt og fik fjernet polypper 25 cm oppe i tarmen den 25. september 1990, og det gik fint. Vi bekymrede os ikke, for alt så fint ud. Det gjorde det også helt frem til foråret 1993. Vi mærkede i hvert fald ikke noget, men om mor holdt noget hemmeligt for os, fandt vi aldrig ud af. Da vi var hjemme hos mor i pinsen (den 29. maj) 1993, syntes vi godt nok, at hun virkede træt og var lidt gul i huden, og vi vidste også, at hun skulle til en undersøgelse den 1. juni, men det var ikke noget, der bekymrede os. Mor var stærk og på en eller anden måde udødelig for mig. Hun skulle nok klare den, som hun klarede alt muligt andet."}, {"type": "para", "text": "Den 1. juni skulle vi holde en klassefest for Lars’ klasse med forældre i Spørring Gl. Skole. Jeg var med i festkomitéen og var nede og dække bord sammen med Ingrid, Brians mor, om eftermiddagen. Vi skulle hver især have en til to retter mad med, så jeg havde samtidig gang i forberedelserne af to retter mad. Sidst på eftermiddagen ringede telefonen, og den samtale ændrede alt. Det var mor, der ville fortælle, at undersøgelsen viste, at hun havde uhelbredelig kræft i leveren, men at vi ikke skulle være kede af det, for hun havde ikke tænkt sig at stille træskoene endnu. Det sidste opfattede jeg knap nok, for tiden stod stille, og jeg gik som en zombie ud i køkkenet og kiggede på al den mad jeg havde gang i. Hvordan blev jeg nogensinde færdig med det? Det var Lars’ klassefest, og jeg måtte ikke skuffe ham. Han var heldigvis ikke hjemme, for han skulle ikke have noget at vide den dag. Jeg mindes ikke, at Vagn var kommet hjem, for så ville jeg nok have spurgt ham til råds. Min redning blev Grete. Jeg ringede til hende, og hun kom straks. Jeg husker, at jeg faldt hende om halsen og græd og græd. Hvor hun under fars sygdom havde holdt sig helt væk, blev hun her direkte involveret, og det var ikke sidste gang, hun hjalp mig under mors sygdom. Hun hjalp mig med at få retterne gjort færdig, og jeg kunne tænke klart igen. Men jeg havde det elendigt hele aftenen og tænkte kun på, at jeg burde være hos mor. Hun var helt alene med sin dødsdom, ligesom far havde været det i sin tid. Hvad var det for nogle børn, de havde, som ikke kunne være der, når det gjaldt? Mange tanker gik gennem mit hoved. Jeg havde aftalt med mor, at jeg skulle tage op til hende den 3. juni, som var en fredag. Den 2. juni skulle jeg til et sproglærermøde i København, og mor havde jo lært mig at være pligtopfyldende, og hun syntes ikke, at jeg skulle aflyse det, så jeg tog afsted, men jeg kunne ligeså godt være taget op til hende, for hun var bestandig i mine tanker, og jeg bidrog ikke med meget på mødet. Jeg forklarede de andre situationen, og de var naturligvis meget berørte på mine vegne. Jeg tog toget næste dag til Hjørring og rutebilen fra Hjørring til Thorshøj, en meget lang tur med ondt i maven og kvalme. På den ene side glædede jeg mig til at komme op til mor, men på den anden side frygtede jeg mødet. Mor sad ved busstoppestedet på en stor sten og ventede på mig. Hun var mærket af sygdommen, men hun kunne stadig grine og joke. Vejret var fint, og vi sad i haven. Hun var meget åben om det, der skulle ske, og hun nævnte ikke, at hun nok skulle klare den. Hun var afklaret. Om aftenen kom Per hjem fra Stockholm, hvilket var dejligt. Det var lidt nemmere at være to. Næste dag var vi med mor hos lægen. Han gav hende mellem 3 uger og 3 mdr. at leve i. Der gik 2½ måned. Indtil mors død skrev jeg ikke i min dagbog. Jeg orkede det ikke, men mange ting står stadig klart for mig. Mor ville gerne dø hjemme, og det ønske fik hun opfyldt. I starten var hun alene i perioder, men hun fik mange besøg, for mor havde mange venner og en fantastisk arbejdsplads. Pludselig skulle hun ikke på arbejde mere, og det var hårdt, både for hende og for Bødkergården, hvor hun næsten var uerstattelig. Hun fik derfor mange besøg og blomster fra ansatte, børn og forældre, især lederen Søren, og ansatte Carsten, Susanne, Bente og Birgit kom tit på besøg. Birgit var nok mors bedste veninde, og hun boede i Thorshøj og var fraskilt. Ellis, Lau Ejlersens veninde, var også flink til at komme, og Købmandens samt Vibeke og Elbo, ja jeg kunne blive ved. Som sagt modtog mor rigtig mange besøg, kort, breve og telefonopringninger, og hun fik mere end 70 meget flotte buketter blomster. Den 10. juni skrev Vibeke et længere brev til mig, hvori der bl.a. stod: ”Jeg havde bestemt, at jeg ikke ville græde, når jeg kom op til Doris – men helt kunne jeg ikke lade være. Hun var den stærkeste. Jeg beundrer hende for hendes mod og selvbeherskelse. Det var en god oplevelse at være sammen med Doris – hun pylrer ikke – selv om jeg da godt ved, at hun inderst inde har det svært”. Vi prøvede at være der så meget som muligt, og det var rigtig dejligt, når der kom besøg, for så sad vi omkring det runde bord i køkkenet, og mor livede op og fortalte historier. Det kunne være ganske muntert. Lars og jeg skulle jo på vores årlige dansetur til Italien en uge omkring Skt. Hans. Det blev for mig ikke den tur, det plejede at være, men det var godt at komme lidt væk og tænke på noget andet. Jeg tænkte på, hvad jeg skulle købe med hjem til mor, og jeg fortryder så bitterligt, at jeg ikke bare købte en pæn t-shirt. I stedet købte jeg noget chokolade. Da vi kom hjem fortalte hun mig, at Elbo og Vibeke havde været på besøg. De havde været i udlandet, og hun syntes da godt, at Vibeke kunne have købt noget til hende. For at lette lidt på min dårlige samvittighed købte jeg en pæn natkjole til mor. Hvor var jeg dog forbandet praktisk! Da Vagn hentede os ved bussen efter Italiensturen, fortalte han, at mor var blevet indlagt med tarmslyng og havde det rigtig skidt. Hun havde været til Bente og Jørns sølvbryllup men var blevet dårlig under festen. Vi kørte derop næste dag, hvor hun lige var kommet hjem. Fra nu af blev jeg hos mor, og Vagn og Lars kom i weekenderne. De lærte at klare sig uden mig, lave mad, vaske og stryge. Per kom også så meget, han kunne, og også Marianne var der. Der kom hjemmepleje på, som sørgede for mors personlige pleje, og de lagde stor vægt på, at hun var pæn i tøjet og havde læbestift på hver dag. Mors store bekymring var, hvordan det skulle ende. Hun ville nødig sidde som en grøntsag og skulle mades. Det var rigtig søde sygehjælpere, der kom, og de forsikrede hende om, at det kom ikke til at ske. Jeg tog mig af huset og det sociale. Mors krop var i forfald, men huset skulle være i orden, så jeg skrubbede og skurede, vaskede vinduer og sørgede for, at alle hendes blomster havde frisk vand hele tiden. Jeg lavede også mad på mors anvisninger, og vi fik god mad hver dag. Mor fik megen medicin, og nogle gange var hun lettere dopet. Det kunne vi mærke, når der kom besøg. Så kunne hun finde på at stille inde i stuen efter sin middagssøvn i natkjole og med bare ben, og hun kunne være nærmest overstadig og grine og pjatte. Hun tog også naturmedicin og drak presset saft og vitamindrik, for kosten var vigtig. Mors hud blev mere og mere gul, og hun fik hævede ben. Derfor elskede hun, når jeg hver aften smurte hendes ben ind i creme og masserede dem. Hun elskede også at få neglelak på tåneglene, så vi brugte megen tid på personlig hygiejne og velvære. Selv om det var en svær tid, blev det også en god tid. Vi fik snakket om meget, og intet var tabu. Mor sagde på et tidspunkt, at det var mærkelig som livet havde været for hende. Hun havde aldrig holdt en rigtig stor rund fødselsdag. Da hun blev 30, skulle jeg konfirmeres, da hun blev 40, skulle Per konfirmeres, da hun blev 50, var hun lige blevet opereret for kræft, ”og nu når jeg ikke at fylde 60”. Det var en bitter pille at sluge. Hun sagde også, da hun blev lidt mere usikker på benene og skulle støtte sig til dørkarmene, når hun gik: ”Man kommer til verden som et ubehjælpsomt barn, der må støtte sig til alting, og man forlader verden på samme måde”. En dag fandt hun alle sine smykker frem og fortalte mig, hvem hun havde fået dem af, og hun bad mig fjerne smykker og sølvtøj fra huset, så snart hun var død, i tilfælde af indbrud. Hun valgte også nogle smykker ud, som hun gav til nogle af sine bedste venner, fx gav hun et smykke til Kirsten, som boede overfor og som tit kiggede over, og Agathe fra Norge fik også et."}, {"type": "para", "text": "En dag spurgte jeg mor, om hun i stedet for denne sygdomsperiode hellere ville være faldet død om af en blodprop. Hun svarede, at hun foretrak denne periode, så hun kunne få taget ordentlig afsked med alle. Og det fik hun. Det var rigtig hårdt at se, når familie og venner kom på besøg for sidste gang og tog afsked. Selv granvoksne mænd gik grædende ud af stuen, fx onkel Viggo fra Fyn og Mariannes far, Børge. På et tidspunkt fortalte mor, at Mariannes forældre ville komme på besøg et par dage. Det skulle hedde sig, at de var på de kanter, men måske gjorde de kun turen for at besøge mor. Jeg havde aldrig mødt dem, men mor var meget begejstret for dem. Jeg tænkte, at mor måske var for syg til at have dem på besøg, men mine tanker blev hurtigt gjort til skamme, for det var rigtig dejligt, at de kom, og jeg kom også til at synes vældig godt om dem. På samme måde med Mariannes søster Bente, som også kom og var i nogle dage. Det var et frisk pust, og hun var rigtig sød. Sidst i juli meddelte Agathe, mors penneveninde fra Norge, at hun gerne ville komme og besøge mor, og de to fik snakket meget og grædt meget. Det var en frygtelig dag, da hun tog afsted. Mit hjerte blødte. Agathe kom igen til bisættelsen. Alice og Reinholt tog også turen fra Spørring en dag, hvilket vi var meget glade for."}, {"type": "figure", "caption": "", "page": 185, "file": "assets/images-bog2/p185_01.jpg", "dim": [1163, 792]}, {"type": "para", "text": "Det var også rørende, når folk sendte blomster til mor, fx den dag der kom en buket fra Lars’ dansepartner Anne-Mette og en buket fra Grete og Poul. Der blev tudet meget i det hus men også grinet. Især når de kom på besøg fra Bødkergården. Mor havde gjort meget til, at Carsten og Susanne skulle blive til et par, men der var ingen synlige tegn, heller ikke når de kom på besøg sammen. Først en af de sidste gange de kom, inden mor døde, så vi dem i tæt omfavnelse udenfor, da de gik. De prøvede på at trøste hinanden, men det var mere end et venskabeligt knus, kunne vi se, så vi tænkte, at nu var mors plan lykkedes. Vi prøvede at fortælle mor det, men vi ved ikke, om hun forstod det. Billedet på foregående side er fra sommeren 1995, hvor Susanne og Carsten får deres lille Nikoline døbt. Det ville have glædet mor."}, {"type": "para", "text": "Mor havde en meget flot plakat liggende, som hun gerne ville have indrammet og give Vagn i fødselsdagsgave, så vi kørte til Sæby en dag til en glarmester, og Vagn fik sit billede den 12. august. Det billede betyder meget for os. Det hang i mange år over sofaen og hænger nu i gangen i vores nye hus. Mor nåede desværre ikke at se billedet på sin plads."}, {"type": "para", "text": "Da tiden nærmede sig, at min sommerferie var forbi, måtte vi tage stilling til, hvad vi så skulle gøre. Det var min plan at søge om plejeorlov, men jeg havde en fantastisk arbejdsgiver, som sagde, at jeg bare kunne holde fri, til det hele var overstået, for vi var jo godt klar over, at der ikke gik flere måneder. Jeg fik en kollega til at overtage min undervisning. Det var en stor lettelse. Heldigvis lå mor kun i sengen den sidste uge, først i soveværelset og de sidste par dage i en hospitalsseng inde i stuen. Inden Per kom hjem, var jeg alene med mor om natten. På et tidligt tidspunkt blev det bestemt, at jeg skulle sove i fars seng ved siden af mor, men jeg var ved at kvæles af røg. Mor røg stadigvæk, også i soveværelset, selv om vi bad hende lade være af frygt for brandfaren. Det skete da også et par gange, at hun brændte hul i lagenet. Normalt kunne man ikke lugte, at der blev røget i huset, men soveværelset var slemt. En aften, nogle dage før mor døde, var jeg alene med mor og skulle være det om natten. Hjemmehjælpen kom først om morgenen. Mor var begyndt at tale lidt i vildelse og ville op. Jeg hjalp hende på toilettet, og hun ville ud i køkkenet og ryge. Mens vi sad derude var hun helt klar, og hun sagde til mig, at nu var det nok snart forbi, så jeg kunne få en normal hverdag igen. Jeg faldt mor om halsen og fortalte hende for jeg ved ikke hvilken gang, hvor højt jeg elskede hende. Hun var overbevist om, at hun skulle møde far igen, og det gav hende ro. Jeg fortalte hende, at hun skulle tænke på, at hun ville leve videre i Per og mig, og dertil nikkede hun. Næste aften var hun dårligere, og hun ville ustandselig ud af sengen. Hun havde stor uro i kroppen, og hun talte om en lille sød hund, der var ude i gangen. Mor havde aldrig kunnet fordrage hunde, men hun havde et papirklip af en hund i gangen, og det var sikkert den, hun fantaserede om. Pludselig blev der banket på døren, og ind kom Købmandens som frelsende engle. De hjalp mig med at få mor lagt i seng og holdt i ro, selvom det var svært, og så sagde de, at jeg bare skulle ringe, hvis der blev noget. Da de var gået, og mor tilsyneladende sov, gik jeg i seng i gæsteværelset ved siden af. Jeg børstede ikke tænder eller tog nattøj på men lagde mig i min træningsdragt, som jeg tit brugte som hjemmedragt, og så lå jeg og lyttede til lydene. Jeg skammede mig ved at tænke: ”Nu må det gerne snart være slut. Jeg orker ikke mere. Jeg er så træt”. Og dernæst tænkte jeg: ”Måske er mor død i morgen tidlig”. Men det var hun ikke. Det var sidste nat, jeg var alene med hende. Kl. 7 stod hjemmehjælpen der med en pose rundstykker, og jeg kunne være faldet hende om halsen, endnu en frelsende engel. Vi fik en hospitalsseng i stuen, og vi fik hyppigere besøg af hjemmehjælpen. Mor kunne ikke spise. Hun havde i længere tid haft betændelse og blærer i munden, og hver morgen og aften måtte jeg tage hendes forlorne tænder ud og gøre dem rene. Per og Marianne kom hjem, og vi skiftedes til at sidde vagt de sidste par nætter. Mor døde om eftermiddagen den 18. august, efter at Per var kommet tilbage fra en løbetur. Hun døde til tonerne af Inger Lauritzens viser, som vi vidste, at hun holdt så meget af. Vi sad der, da det skete, og jeg mener også, sygeplejersken var der. Per og jeg krammede hinanden, men der var ingen tårer, mere en følelse af lettelse. Hun havde fået fred. Jeg fik lov til at hjælpe med at gøre mor i stand. Hun havde ønsket at blive bisat i sin sorte sølvbryllupskjole, og hun var faktisk meget smuk og fredfyldt, som hun lå der. Vi skulle finde noget at lægge over mor indtil næste dag, hvor bedemanden skulle komme og lægge hende i kisten, og Per, som aldrig er handlingslammet, fandt en af mors fine hvide damaskduge. Jeg husker endnu, at vi sad ude ved køkkenbordet kort efter mor var død og gennemgik mors adresseliste for at se, hvem vi skulle ringe til. Det var Per, der ringede rundt og sagde: ”Mor er gået bort”. Vagn kom samme aften men kørte hjem igen, og næste dag havde han Lars med. Vi fik om formiddagen besøg af bedemanden, Dittes bror Villy Hejslet. Mor skulle samme eftermiddag køres i kapel ved Skæve Kirke, så vi inviterede de nærmeste til at komme og være med til at synge mor ud. Senere på formiddagen var vi henne og snakke med præsten for Torslev Kirke, som tidligere havde været på besøg og aftalt det hele med mor. Hun kendte lidt til præsten, selv om hun ikke var fast kirkegænger, og hun ville gerne have ham til at forrette bisættelsen i Skæve Kirke. Da vi kom tilbage fra præsten, stod min gamle klassekammerat Aase ude på vejen. Vi standsede bilen, og jeg løb ud og fik en stor omfavnelse af hende. Hun boede i Østrig men var hjemme og ville gerne med om eftermiddagen. Mor havde nogle gange passet hendes dengang 8-årige søn, Jens Karl, og han havde lavet nogle tegninger til mor, som hun fik med i kisten sammen med en sten, som Alice havde givet hende. Vi fik taget en meget smuk afsked med mor fra Tryvej 10, fra det dejlige hjem, som hun og far havde skabt og som hun elskede så højt. Mor blev bisat den 21. august, på fars dødsdag, og der var mange mennesker til bisættelsen. Om formiddagen hentede vi Agathe ved færgen i Frederikshavn, og vi kørte til kirken, hvor mors kiste skulle bæres ind. Lisbeth og Bent var der også, og Lars. Vi så mor en sidste gang, og jeg husker endnu Lisbeths ord: ”Åh, de flittige hænder”. Inden bisættelsen stod vi uden for kirken og hilste på gæsterne, da de kom, og det var meget rørende at se folk, som man overhovedet ikke havde forventet ville dukke op. Rørende var det også, da John stillede sig op og sang for mor i kirken: ”Jeg er træt og går til ro”, og Ejvind spillede ”Nærmere Gud til dig” på trompet. Det var flot. Der havde været et særligt nært forhold mellem mor og John. Jeg var med til at bære kisten sammen med Vagn, Per, Erik, Helge og Marianne. Mor havde udtrykkeligt sagt, at hun ikke ville have onkel Ib til at bære, så vi bad Ib og moster om at tage sig af Lars. Lægen havde givet mig noget beroligende, så jeg bedre kunne komme igennem bisættelsen, men det fortrød jeg, for jeg kunne ikke få mine følelser ud. Det ville have været befriende at kunne lade tårerne få frit løb, og det er jo kun naturligt sådan en dag. De kom dog senere. Efter bisættelsen var vi 100 til kaffe i selskabslokalerne, som engang havde været DLG. Der var flere smukke taler, bl.a. fra Ejvind og lederen af Bødkergården Søren. Per holdt en smuk tale, og jeg læste et digt op, jeg havde skrevet. Vi havde også fået lavet en speciel sang til lejligheden på melodien til ”Tænk, når engang…”. Alle 4 vers begyndte med: ”Sov, lille mor”. Om aftenen spiste vi på Tryvej 10, hvor også mors yndlingskusine Lisbeth fra Sverige og dennes mand Bent var med. Der var tre dødsannoncer og to mindeord i avisen om mor, hvilket også vidner om hendes popularitet. Bødkergården havde i stedet for at sende blomster doneret 977 kr. til Kræftens Bekæmpelse. Der var 10 kranse, hvoraf de 9 var med bånd, 27 buketter, 21 dekorationer og ca. 1500 kr. Efter bisættelsen kom der flere breve til os fra mors venner med dejlige ord om mor, og et par forældre fra Bødkergården sendte os ”Tanker omkring Doris: Vi tænkte aldrig så langt, at Doris skulle have haft ”Ugens Buket”. Hvis nogen havde fortjent den, var det Doris. Der var altid et ”smørhul”, et knus, hjælp til en løs tand, tid til et slag kort, en munter bemærkning, derved blev en grå dag altid lys i Doris’ selskab. Hun var hyggesprederen ved enhver lejlighed, hvor hun også magtede at gøre ethvert måltid til en fest. En uforglemmelig skat. Et par forældre”."}, {"type": "figure", "caption": "", "page": 187, "file": "assets/images-bog2/p187_01.jpg", "dim": [1163, 779]}, {"type": "para", "text": "Jeg skrev 130 takkekort. Det skulle være, som da far døde, hvor mor skrev ud til alle. Den 28. august satte vi urnen ned, og samme dag havde vi besøg af ejendomsmægleren. Om aftenen var vi 20 til at spise, alle de nærmeste venner, som havde hjulpet os i den svære tid. Det blev trods alt en god og minderig aften, hvor der blev snakket meget om mor. Vi gav Birgit en check på 5.000 kr., og alle damerne fik en af mors selvfabrikerede skindtasker, da de gik. Vi havde lagt alle taskerne ud på sengen, så damerne kunne vælge, efterhånden som de tog hjem. Selvom det var en lettelse, at mor fik fred, havde jeg mange tude-ture bagefter, og det var først midt i oktober, at jeg fik ryddet op i mors tøj. Det, jeg selv kunne passe, beholdt jeg. Jeg kunne godt lide at gå i mors tøj, selvom mange syntes, det var mærkeligt. Den 7. november var vi i Skæve Kirke, hvor både mors og mormors navne blev læst op. Den dag mor kunne være fyldt 60 år, den 9. marts 1994, var der mange på kirkegården med blomster til hende, og i Bødkergården sang børnene for hende. Jeg begyndte på arbejde igen den 30. august 1993, og jeg havde købt vin til dem, der havde hjulpet mig under mors sygdom."}, {"type": "figure", "caption": "", "page": 188, "file": "assets/images-bog2/p188_01.jpg", "dim": [988, 723]}, {"type": "para", "text": "I min dagbog den 16. januar 1994 har jeg noteret, at måren er tilbage i mors hus. Mens mor var syg, døjede hun med en mår på loftet. Det var synd for hende, for hun kunne ligge om natten og høre den. Vi prøvede alt muligt for at komme af med den, såsom at stille naftalinkugler derop og skære en gren af det træ, hvorfra vi mener den sprang, og på et tidspunkt blev den da også borte, men nu var den der altså igen. Senere samme måned var vi alle hjemme og rydde op i skabe og skuffer, og den 6. juni blev huset solgt til en børnefamilie fra Sæby til 438.000 kr. med overtagelse den 1. september samme år. Det var mærkeligt at lukke døren for sidste gang til dette hus, som havde dannet rammen om Pers barndom og vores ungdom. Nu var det kun en tom skal. Vi kører altid forbi huset, når vi er i Vendsyssel, og det er dejligt at se, at det stadig ser pænt ud, og de forandringer, der er foretaget, har kun gjort det pænere."}, {"type": "para", "text": "Med mine forældres alt for tidlige bortgang føler jeg, at de er gået glip af mange lykkelige begivenheder i familien, og vi taler tit om, at de jo meget nemt kunne have levet i dag. De oplevede ikke at få flere børnebørn, og Veronica og Alexander oplevede ikke at kende deres farmor og farfar. De kunne også nemt have oplevet deres tre skønne oldebørn, men sådan skulle det ikke være. Vi må være taknemlige for den tid, vi fik lov at have sammen med dem."}]}, {"title": "Bedstefar dør den 20. juli 1994", "blocks": [{"type": "para", "text": "Bedstefar, som havde haft Diabetes II i flere år, kom på Hjørring Sygehus den 15. oktober 1993, og den 3. november kom han på genoptræningscenter, hvor han var til den 2. december. Den 30. maj 1994 kom han på plejehjem men blev indlagt på sygehuset den 5. juni på grund af væskemangel og blodig diarré. Han kom på Motellet i Hjørring den 9. juni, samme dag som farmor kom hjem fra sygehuset, hvor de havde været indlagt sammen."}, {"type": "para", "text": "Vi fik som sagt travlt med at komme hjem fra Sverige, da vi hørte, at bedstefar var død, så næste dag, den 21. juli, tog vi sammen med farmor op på Motellet for at se bedstefar. Mens vi stod der ved sengen, sagde farmor så sødt til bedstefar: ”Wi hår vel nok hat månne gue or sammen”. Bedstefar blev begravet fra Ugilt Kirke lørdag den 23. juli i det dejligste sommervejr, og vi stod uden for kirken og hilste på alle gæsterne. Grunden til at det var Ugilt Kirke var, at Tårs Kirke var under renovering. Vi kørte efter højtideligheden til Tårs Kirkegård, hvor bedstefar blev begravet. Thomas og Lars var med til at bære kisten. Bagefter drak vi kaffe på Tårs Hotel. Jeg husker dagen som en smuk begivenhed. Det havde altid været bedstefars frygt at dø, som han gjorde. Han sagde tit, når nogen var død af en blodprop, at det var en nem død, og sådan havde han også selv ønsket det. I stedet skete der det, han frygtede mest, nemlig at han kom til at sidde på et plejehjem og gå med ble. Derfor ville det have været dejligt, hvis bedstefar kunne have været skånet for sine sidste to år, men sådan noget bestemmer man jo ikke selv. Han fik trods alt et langt og godt liv sammen med farmor."}, {"type": "figure", "caption": "", "page": 189, "file": "assets/images-bog2/p189_01.jpg", "dim": [1171, 779]}]}, {"title": "Andre dødsfald", "blocks": [{"type": "para", "text": "Den 3. december 1990 ringede Alice om morgenen for at fortælle, at Villy Morgenstjerne var død aftenen før af en blodprop. De var blevet kaldt derop, og hun havde givet kunstigt åndedræt, men det havde desværre ikke hjulpet. Det var et stort chok, for Villy var en af vores gode venner og en rigtig guttermand, som levede et sundt liv. Hans egen far blev kun 57 år, og Villy havde været bange for, at det samme skulle overgå ham. Det gjorde det desværre, for Villy var omkring den alder. Den 4. december gik vi den tunge gang op til Ruth for at kondolere."}, {"type": "para", "text": "Den 19. juli 1991 fandt onkel Alfred sin kone Karen død i en stol. Det var vores opfattelse, at de to havde levet hver deres liv, da Alfred gerne ville i byen og Karen foretrak en mere tilbagetrukket tilværelse, og de havde ingen børn fået, men efter Karens død blev hun hævet op på en piedestal, og ingen måtte røre hendes ting. Da Alfred døde i 2006, stod alt som i Karens tid, og hendes tøj hang i skabene."}, {"type": "para", "text": "Den 28. december 1992 døde Pouls far Mikael Andersen efter nogen tids sygdom. Han blev 84 år. Den 14. marts 1993 døde min veninde Lisbets far Lau Ejlersen. Mor fik beskeden, mens hun var hos os, og det påvirkede hende meget, da hun var bedste veninde med Ellis, Laus veninde fra Skagen. Måske havde hun på fornemmelsen, at hun ville blive den næste."}, {"type": "para", "text": "I 1994 døde min farmors bror Johannes Hagbard Møller. Han havde ingen børn, så jeg arvede en lille skilling: 3.022,38 kr."}, {"type": "para", "text": "Det påvirkede os meget, da vi hørte om Tom Møllers selvmord den 12. marts 1994. Tom var 33 år gammel og søn af Grethe og Søren Johan, og han var gift med Eva og Leos Annette og havde to drenge. Vi fattede ikke, hvad der havde drevet ham til at køre ud i en skov og stikke en slange fra udstødningen ind i bilen. Det var frygteligt for de pårørende. Ligeledes påvirkede det os også, da taxachauffør Calle Bech kørte sig selv ihjel i sin taxa den 1. maj 1995. Vagn havde set, at han kørte ud om morgenen (inden forbindelsesvejen blev lavet), men han kom aldrig tilbage. Han var skredet ud i et sving og landet på en mark. Samme år den 11. juni døde Børge Bonne, 67 år gammel. Han hørte også til vennekredsen, så vi var naturligvis med til begravelsen og kommer den dag i dag stadig sammen med hans kone Ellen. Børge havde dårligt hjerte og døde efter længere tids sygdom. Lige før vores sølvbryllup døde min kusine Elins mand Kurt Brøcher af modermærkekræft, eller metastaser deraf."}, {"type": "para", "text": "Vores nabo Mary blev syg i februar 1998, samme år som hun ville være fyldt 80 år om sommeren og samme år som vores sølvbryllup. Hun var indlagt flere gange, hvor vi besøgte hende på sygehuset, men de kunne ikke rigtigt finde ud af, hvad hun fejlede. Jeg lavede mad og gik ind til hende med, da hun kom hjem, og jeg besøgte hende hver anden dag. Hun må have følt sig nogenlunde rask, for vi modtog en fin indbydelse til hendes fødselsdag den 12. juli. Vi takkede naturligvis ja, og vi afleverede også en fin indbydelse til hende til vores sølvbryllup. Ingen af festerne kom hun til at opleve. Den 9. juni fik hun en hospitalsseng ind i stuen, og jeg besøgte hende hver dag. Per og Marianne sendte blomster fra Hong Kong den 16. juni. Den dag tog vi afsked med Mary. Hun fik mere og mere morfin og sov meget af tiden. Hun døde den 21. juni og blev sunget ud kl. 15.30. Vi gik bag efter rustvognen ned til kirken. Til begravelsen den 24. juni var jeg med til at pynte kirke. Vi var alle tre til begravelse, og ved kaffen på Spørring Hotel bagefter holdt jeg en tale, og vi satte mindeord i avisen."}, {"type": "para", "text": "Nu havde vi så én mindre at besøge, og vi savnede Mary. Den tradition, vi er født op med, hvor vi besøger gamle mennesker, eksisterer ikke i dag. I 90’erne havde vi en del ældre mennesker, vi besøgte fra tid til anden: Mary, Marie og Svend, onkel Alfred, Mie i Hørby, og jeg besøgte Karen Lis’ mor og danse- ”mormor” (Kirsten og jeg besøgte Kenneths mormor i Tilst). Alle kaldte hende ”mormor”, og hun var det sødeste menneske, som var dejlig at besøge."}]}, {"title": "Vores lille trekløver", "blocks": [{"type": "para", "text": "Nu skal vi over til noget mere muntert. Folk ville aldrig tro på det, når jeg sagde, at vi ingen problemer havde med Lars. Mange af mine kolleger beklagede sig over deres børn og glædede sig til, at de flyttede hjemmefra. Den tanke var mig virkelig fjern. Jeg synes ikke engang, at vi opdragede på ham. Det var ligesom ikke nødvendigt. Måske var han FOR nem? Men det var dejligt ikke at skulle råbe og skrige og skælde ud. Der var ingen, der smækkede med dørene, og alt var lutter idyl efter vores mening. Jeg tror også, at Lars befandt sig godt. Han erklærede i hvert fald på et tidspunkt, at han altid ville bo i huset, og at det var os, der kom til at flytte, når vi skulle på plejehjem. Sådan gik det nu ikke."}, {"type": "para", "text": "Vi kunne godt lide at hygge os med film på video eller i TV, eller en tur i biografen, og i efterårsferien havde Lars og jeg en tradition med at skulle ind til byen en dag, hvor vi så var på Mc Donalds og måske en tur i biografen. Vi spillede også Trivial Pursuit, Monopoly og andre spil, selv om Vagn aldrig har været meget for spil. Vi tog til Parkunderholdning om sommeren og i Friheden, og skulle vi på restaurant, var Lars’ favorit ”Bones”. Lars og Vagn kunne også godt lide at tage til fodbold sammen, fx i Parken. Og så var der naturligvis ferierne, hvor vi virkelig nød samværet, enten på camping eller på rejser. Vi syntes også, det var dejligt, når Lars havde kammerater med hjem, enten fra skolen eller fra dans. guitar han fik af Jane og Lene"}, {"type": "figure", "caption": "Lars i kælderen 1992 med den", "page": 191, "file": "assets/images-bog2/p191_01.jpg", "dim": [1181, 784]}]}, {"title": "Lars går i skole", "blocks": [{"type": "para", "text": "Til en samtale på Bakkegårdsskolen i 1990 fik vi at vide, at Lars var så dygtig, at de ikke vidste, hvad de skulle stille op med ham. De var bange for, at han kom til at kede sig. Det var to stolte forældre, der kom hjem den aften."}, {"type": "para", "text": "Klassen havde fået en venskabsklasse i Skotland, og den 7. september 1992 drog klassen afsted dertil. Mor havde sendt et sødt kort til Lars med penge til turen. Lars skulle bo hos en pige i 9 dage, Alison Dingwall, i byen Nairn, og det var så meningen, at klassen fra Skotland skulle komme til Trige året efter. Desværre kom Alison ikke med til Danmark, så i stedet fik vi en 12-årig dreng, Scott, til at bo hos os fra den 12. til den 21. april 1993. Han havde aldrig været hjemmefra, så han længtes meget hjem i starten, og han var også yngre end de andre. Det endte nu med at blive en god oplevelse at have Scott boende, og jeg er stadig på julekort med hans mor, som desværre blev enke kort efter, at Scott var hos os."}, {"type": "figure", "caption": "", "page": 191, "file": "assets/images-bog2/p191_02.jpg", "dim": [1158, 792]}, {"type": "para", "text": "Han var enebarn og følte sig mest tryg, hvis han kunne få lov til at blive hjemme hos Vagn og mig om aftenen i stedet for at deltage i de sammenkomster, de andre gik til. Hans yndlingsplads var i den 2-personers sofa foran TV, men vi snakkede også meget med ham. Desværre forstuvede han en arm under fodboldspil på skolen, og vi måtte på skadestuen med ham, hvor han fik armen i en slynge. Hver dag var skotterne med deres værter i skole, men i weekenden måtte vi så finde på noget at vise ham. Vi tog til Ebeltoft en dag og viste ham Fregatten Jylland, hvorefter vi tog ud og fiskede i Mårup Put & Take. Det blev en stor succes, for Scott fangede to ørreder. Hvor var han stolt, da han blev fotograferet med dem, og til afskedsfesten, hvor hver især skulle have mad med, lavede jeg en flot fiskeret med kold ørred, som han havde fanget. Det var helt vemodigt den dag, vi skulle tage afsked med ham."}, {"type": "figure", "caption": "", "page": 192, "file": "assets/images-bog2/p192_01.jpg", "dim": [832, 551]}, {"type": "para", "text": "På et tidspunkt troede vi, at Lars ville have været arkitekt. Han var i erhvervspraktik i november 1992 på Klinges Tegnestue, og han fik også lavet nogle fine tegninger, men det var alligevel ikke det, der havde størst interesse."}, {"type": "para", "text": "Den 19. maj 1993 havde Lars sidste skoledag i 9. klasse, hvor de var på La Tour og spise og bagefter på Blitz. Herren kom hjem kl. 3. Til eksamen fik Lars to 13-taller, det ene i diktat, fem 11-taller, bl.a. i fysik, et 10-tal og tre 9- taller, bl.a. i dansk, samt en fin udtalelse. Vi var stolte.  Lars fik en stelton papirkniv af sin mormor i eksamensgave, for som hun sagde: ”Lars skal have en fin gave af mig nu, for jeg kommer ikke til at opleve, at han får studenterhuen på”. Det havde hun desværre ret i."}, {"type": "figure", "caption": "Lars får overrakt eksamensbevis af skoleinspektør Ingrid Kjærgård Lars til James Bond fest efterår 1995", "page": 192, "file": "assets/images-bog2/p192_02.jpg", "dim": [646, 792]}]}, {"title": "Lars går på gymnasium", "blocks": [{"type": "figure", "caption": "", "page": 192, "file": "assets/images-bog2/p192_04.jpg", "dim": [787, 1176]}, {"type": "figure", "caption": "Lars 16 år", "page": 192, "file": "assets/images-bog2/p192_03.jpg", "dim": [547, 702]}, {"type": "figure", "caption": "", "page": 193, "file": "assets/images-bog2/p193_01.jpg", "dim": [1168, 1592]}, {"type": "para", "text": "Klassebillede fra 2.z, 1994-1995. Lars sidder i midten foran med Inge-Marie på sin venstre side."}, {"type": "para", "text": "Der var ingen tvivl om, at Lars skulle på gymnasiet efter 9. klasse, og det skulle være den matematiske linje. Vi var til orienteringsmøde på Risskov Amtsgymnasium i februar for at høre lidt om stedet og fagene, og det var en rigtig god oplevelse. Bagefter var Lars meget opsat på, at det var der, han ville gå. Det var derfor hans førsteprioritet, da han søgte ind, og stor var skuffelsen, da han i juni fik brev om, at han skulle gå på Århus Katedralskole. Lars var som regel stille og rolig, men han blev så rasende, at han krøllede brevet sammen og kylede det hen i et hjørne. Der var imidlertid ikke noget at gøre, så Lars startede efter ferien på Katedralskolen. Det viste sig heldigvis hurtigt, at han blev rigtig glad for at gå der, og Inge-Marie fra vejen gik i parallelklassen, så de fulgtes tit ad. Vi var allerede til et møde derinde midt i september, og på Lars’ 16-års fødselsdag var han til fest derinde. I februar 1994 var vi til forældrekonsultation, hvor vi var rundt og snakke med flere af Lars’ lærere, og det var dejligt at høre, at han fik ros. Det var også en fin karakterbog, han kom hjem med første gang med et snit på 8,8. Alt tydede på, at Lars trivedes på Katedralskolen og havde fået gode kammerater, og når han var glad, var vi det også. Den 10. november 1994 deltog Lars i Operation Dagsværk, hvor det gjaldt om at samle penge ind til U-landsprojekter. Mange elever stod på Strøget og samlede penge ind, men det var ikke lige noget for Lars, så i stedet gjorde han huset rent og tjente derved en skilling, som han kunne donere til det godgørende formål, som havde eksisteret siden 1985."}, {"type": "para", "text": "Da Lars fyldte 17 år, fik han lov til at invitere 15 gæster i kælderen, og der blev festet til kl. 5 om morgenen. Vi nød, at der var liv i huset. Den dag skulle nok komme, hvor vi sad alene tilbage. Kasper Hansen var et år ældre end Lars og gik også på Katedralskolen, og det skete nok, at de to var sammen, også til fester. Det var hyggeligt, når Kasper kom på besøg, bl.a. den dag, han havde fået en tatovering. Han kom ind og viste os den, og Vagn roste den. Jeg sagde ikke noget men tænkte: ”Lars er heldigvis ikke interesseret i den slags”. Det kunne jeg selvfølgelig ikke vide, men Lars var ikke typen, der ville have tatoveringer, og det var hans mor glad for. Jeg har også altid været glad for, at Lars ikke var overmodig og skulle springe i elastik eller faldskærm eller køre på knallert og motorcykel. Det ville jeg ikke have brudt mig om."}, {"type": "para", "text": "I februar 1995 blev der holdt karneval på Katedralskolen, og Lars var klædt ud som tømrer, en nem udklædning Samme forår var han med klassen på studietur til Firenze i en uge, og da de kom hjem, blev der holdt gallaaften på skolen. Lars lånte Vagns smoking til formålet. Temaet var James Bond. I juni samme år lavede han en historieopgave, hvor han fik ros for sit gruppearbejde, og til eksamen i 2.g scorede han et 10-tal i skriftlig matematik. I 3.g gjaldt det, og der skulle skrives 3-års opgave, hvortil eleverne fik en uge fri i december. Lars klarede sine lektier uden vores indblanding – det eneste, jeg kunne hjælpe ham med, var engelsk, og det skete ikke særlig tit, at han havde brug for det. Vi undrede os over, at han kunne have alt muligt kørende samtidig med, at han læste, det være sig musik og TV, men sådan var tiderne blevet."}, {"type": "figure", "caption": "", "page": 194, "file": "assets/images-bog2/p194_01.jpg", "dim": [787, 1176]}, {"type": "para", "text": "Jeg gik desværre glip af at se Lars gå mannequin på Spørring Hotel den 21. september 1995. Jeg var på seminar med overnatning netop den dag. Samtidig med at Lars skulle passe sin skole, skulle han også tage kørekort. Han bestod teorien den 20. december 1995 og var oppe og bestod køreprøven den 18. januar 1996."}, {"type": "para", "text": "Den 2. maj 1996 var vi med Lars til Dronningebal i Kongreshuset, hvor eleverne skulle danse lanciers. Lars’ dansepartner Henriette havde en flot lang grøn kjole på, og Lars havde sit kjolesæt på. Det var et flot par, og vi var som forældre endnu engang stolte af vores flotte og dygtige søn. Det var en rigtig dejlig aften. Få dage senere, den 8. maj, havde de sidste skoledag, og så begyndte læseferien. Jeg husker, at jeg var ligeså nervøs som Lars, måske mere, når han skulle op til eksamen, men han klarede sig fint og fik bl.a. 10 i mundtlig matematik. Anne-Mette Bugge gik også til studentereksamen på handelsgymnasiet i Randers og fik huen den 13. juni, så den aften var vi til studenterfest i Helsted, selvom Lars havde travlt med at læse, for han skulle op i det sidste fag, historie, den 17. juni."}, {"type": "para", "text": "Vi havde planlagt fester i dagene der kom, og vi havde bestilt Rikke Højs kæreste Jes, som var kok, til at komme og lave maden. Vi havde haft et møde med ham, og han skulle også købe det hele ind. Søndag den 16. juni hentede vi farmor i Hobro, og hun fik soveværelset, for vi skulle nødig risikere, Lars sidder på forreste række nr. 2 fra venstre, og Inge-Marie sidder yderst til højre på samme række."}, {"type": "figure", "caption": "", "page": 195, "file": "assets/images-bog2/p195_01.jpg", "dim": [935, 666]}, {"type": "para", "text": "at hun faldt ud af sengen, som hun havde gjort nogle år tidligere på gæsteværelset. Vi dækkede op til 31 i stuen til middag næste aften, og så gik vi i seng i campingvognen. Jeg lukkede ikke et øje om natten af nervøsitet for, hvordan Lars skulle klare sig i historie. Jeg husker det selv som et hadefag i min gymnasietid, men Lars var noget bedre i det fag, end jeg havde været, så det skulle nok gå. Han skulle op om formiddagen, og det var dejligt, for så havde vi dagen foran os. Han så ikke glad ud, da han kom ud fra eksamenslokalet, men det blev til et 7-tal, så forældrene var tilfredse. Men så skete der det, der ikke må ske: huen passede ikke! Den var et nummer for lille."}, {"type": "para", "text": "Lars blev irriteret og rev den af, og jeg blev ked af det, for det er jo sådan en dag, man skal gå rundt med huen og være glad over den veloverståede eksamen, så hvad skulle vi stille op? Det var jo de leverandører, der havde taget mål, som havde lavet en fejl, så vi gik ind på Katedralskolens kontor, fik nummeret på firmaet og ringede så til dem fra en telefonboks. Samtidig spurgte vi på kontoret, om de ikke skulle ske at have en hue liggende i størrelse 57. Det havde de ikke, men de havde en i størrelse 59, som vi måtte få. Firmaet, vi ringede til, beklagede fejlen og ville sende en ny hat med posten, så Lars endte med at få tre studenterhuer, men det havde han såmænd også fortjent. Vi forede den største at huerne, så den kom til at passe så nogenlunde. Der var i hvert fald ikke nogen, der lagde mærke til, at den var for stor. Mary kom og spiste frokost sammen med os. Hun snakkede så godt med farmor. Om aftenen kom familien (min familie var desværre ikke repræsenteret) og de nærmeste venner til en dejlig middag, som Jes og Rikke serverede. Familien Bugge var også med, og Marie og Svend Sønderup. Det blev en rigtig hyggelig aften, og næste aften gentog vi succesen, også med 31 gæster til buffet, denne gang flere venner og unge mennesker. Jeg havde taget fri mandag og tirsdag, men onsdag var jeg afsted fra morgenstunden og kom så hjem til et hus, der bar præg af en overstået fest. Jeg fik ryddet op, og næste dag skulle jeg have eksamen og besøg af Anne-Mette og Lars den 17. juni studenterne. Vi havde forberedt alt, til de skulle komme. De skulle have frugt og snacks, og det havde vi stillet an ved flere borde. Endelig, kl. 20.30 kom bilen med de glade studenter rullende, og jeg mindedes min egen studentertid i Hjørring. Vi kom ikke hjem til mine forældre, for det var for langt at køre. Vi kørte bare rundt til dem, der boede i Hjørring og omegn. Efter en lang dag med mange besøg, var de unge mennesker lidt matte, og et par af drengene måtte lade vandet i blomsterbedene, men de var glade og søde, og vi havde fornøjelsen af at have dem i 25 minutter. De havde stadig flere besøg at aflægge. Det var rigtig hyggeligt at se dem alle."}, {"type": "figure", "caption": "", "page": 196, "file": "assets/images-bog2/p196_03.jpg", "dim": [676, 997]}, {"type": "figure", "caption": "Der er 27 år mellem de to studenterhuer og mellem os", "page": 196, "file": "assets/images-bog2/p196_01.jpg", "dim": [781, 1171]}, {"type": "figure", "caption": "Dagen efter var vi til dimission, som blev holdt i", "page": 196, "file": "assets/images-bog2/p196_02.jpg", "dim": [781, 1016]}, {"type": "para", "text": "Inge-Marie og Lars efter dimissionen Domkirken, og jeg må med skam melde, at det var vores første besøg der. Den varede fra kl. 10.00 til 12.30, hvorefter Vagn tog på fisketur i 7 timer, og jeg sov i 3 timer. Det havde været nogle hektiske dage, men vi kunne se tilbage på det hele med glæde."}]}, {"title": "Lars har fritidsjob", "blocks": [{"type": "para", "text": "Et godt sted at starte er som avisdreng, og det gjorde Lars i 1989 og 1990. Klaus havde også ruten en overgang, og sommetider hjalp de hinanden. Jobbet gav dog ikke ret stor en løn, så den 31. august 1991 begyndte Lars at arbejde på et gartneri lidt uden for Spørring. Arbejdet bestod i at sætte stiklinger, og jo mere man rubbede neglene, jo mere tjente man. I sommeren 1992 tjente Lars 2.000 kr. på en uge. I november 1991 skulle eleverne i 7. klasse i praktik i 2 uger. Lars fik job hos Supersoft i Vestergade, og det var noget, han kunne bruge. De var også rigtig glade for ham og gav ham gaver for over 1000 kr. da han stoppede. Jeg bagte kage, som han havde med den sidste dag. Efter gartneriet begyndte Lars at arbejde i Spørring Brugs, og det blev han også vældig glad for. Det var nemmere at gå ned i Brugsen end at skulle cykle op ad bakken til gartneriet, og så var arbejdet også mere varieret. Lars faldt godt til i Brugsen, og uddeler Henrik Melin var glad for ham. Lars var god til at finde ud af tingene og havde flair for elektronik, og så var han til og med serviceminded og smilende. Også efter at Lars flyttede hjemmefra, kom han og arbejdede i Brugsen i weekenderne, og i uge 5 i 1998 arbejdede han der i 30 timer. Det var hyggeligt at komme ned og handle, når Lars var der."}, {"type": "para", "text": "Vi havde også en ordning herhjemme i 1993, hvor Lars gjorde rent for 40 kr. i timen, og han havde visse pligter herhjemme, såsom at slå græs og vaske vinduer. Det kneb nogle gange med at holde orden i kælderen, og jeg skulle jo bare have ladet det ligge, men det kunne jeg ikke, så jeg gik ned og ryddede op engang imellem."}, {"type": "para", "text": "Lars fik også sin gang på Arkitektskolen, hvor han hjalp Vagn med forskelligt og fik løn for det. Fx var han med Vagn på arbejde og var ansat på Arkitektskolen i sommeren 1996 (fra den 19. juli), i 1997 i ugerne 5, 22, 23, 24 og 25, og i 1998 i ugerne 27, 28 og 29. Uanset hvor Lars var ansat, var han vellidt og dygtig."}, {"type": "figure", "caption": "", "page": 197, "file": "assets/images-bog2/p197_02.jpg", "dim": [689, 984]}]}, {"title": "Lars og dansen", "blocks": [{"type": "figure", "caption": "", "page": 197, "file": "assets/images-bog2/p197_01.jpg", "dim": [763, 1017]}, {"type": "para", "text": "I 1990 var Lars juniordanser og dansede med Anne Berthelsen i Raffi i Randers, ledet af Janna Clausen. Til JM i standard i januar blev de nr. 1 i B-rækken. Janna var fantastisk sammen med børnene, og de elskede hende. Hun var en frisk pige, der ikke selv havde børn, og hun var altid sød og fik os til at føle os hjemme, når vi var til dans med børnene. Men hun havde ikke styr på sin økonomi. Hun lånte engang nogle penge af os til en turnering, som vi aldrig fik igen. Børnene trænede et par gange om ugen og fik også enetimer, og det foregik oftest på den måde, at Lars og jeg kørte til Randers og hentede Anne, og efter dansen kørte vi hende hjem igen. Hendes forældre hed Betty og Kim, og hun havde også en lillesøster. Moren var en lille tynd splejs, og Anne var heller ikke stor, men hun var meget charmerende og havde som sagt et grønt og et brunt øje."}, {"type": "para", "text": "Vi var for alvor ved at komme ind i danseverdenen og var til turneringer vidne til forældre, der pacede deres børn frem. Lars fik rigtigt dansetøj og lyse striber i håret. En af de rigtig gode ture, vi var på, var turneringen i Skotland en uge i april 1990. Der var mange lokale tilskuere om aftenen, når de unge mennesker dansede turnering, og når turneringen var slut, kom publikum på gulvet. Der herskede en danseglæde uden lige. Det var også på denne tur, at Lambadaen holdt sit indtog, en dans, hvor der skulle gang i hofterne. Anne og Lars blev faktisk rigtig gode til det og stillede også op i Hele holdet under ledelse af Flemming Kjærsgård. Anne og Lars forrest til venstre   denne disciplin."}, {"type": "figure", "caption": "", "page": 198, "file": "assets/images-bog2/p198_01.jpg", "dim": [1179, 789]}, {"type": "para", "text": "En anden god tur, hvor også Vagn var med, var Pinsefestivalen 1990 på Hotel Nyborg Strand, hvor vi boede på et vandrehjem ved siden af hotellet. Vi var flere forældre og Janna, der hyggede os sammen. Anne og Lars klarede sig pænt og lå placeret i midten. Sidst i juni var jeg med Lars til en turnering i Hamborg. Dansetøj var meget dyrt, og det var normalt, at man købte tøjet brugt. I august købte vi en brugt smoking af Gurli Radick. Hun var syerske inde på Århus Teater og syede dansetøj, og hendes søn Frank, der var ældre end Lars, var en meget dygtig danser. Lars var bestemt ikke ked af at skulle danse i en smoking, der havde tilhørt Frank. Vi var ikke så velbevandrede inden for dansen som Annes forældre, der heller ikke gik af vejen for at fortælle os, at Anne havde vundet medaljer tidligere, så vi lod ligesom dem bestemme, hvad der skulle ske, og de syntes, at vi skulle skifte til en anden klub, Midtjysk Sportsdanserforening, som lå i Århus. Dette skete den 29. oktober 1990, en klub der senere ændrede navn til Århus Sportsdanserforening. Her fik de Kenneth Pedersen som træner, en meget dygtig og veltalende mand midt i 30’erne. Men danseverdenen kan være hård og ubarmhjertig. Det måtte vi sande den 13. januar 1991, da Betty ringede og sagde, at Anne havde fundet en ny partner, Lars Valdbo. Sådan gjorde man. Hvis man ikke var tilfreds med partneren, fandt man en ny og prøvedansede med ham i al hemmelighed. Hvis det så viste sig, at det fungerede, ringede man bare til den gamle dansepartner og sluttede samarbejdet. Næsten ligeså hårdt som at blive brændt af af sin kæreste. Vi var rigtig kede af det, også på Lars’ vegne. Vores redning blev Kenneth, som kendte mange dansere, og han vidste, at der gik en pige ledig i Randers, der hed Anne-Mette Bugge, så allerede den 29. januar begyndte de at danse sammen. Anne-Mette var en dygtig danser, og de passede godt sammen. Hun var frisk, og munden stod ikke stille på hende, men hun havde også temperament, og somme tider kunne vi godt have lidt ondt af Lars, for han føjede hende næsten altid, men i det store og hele tror jeg, at de kom godt ud af det med hinanden. Ellers havde de nok heller ikke danset sammen i 7 år. Anne-Mettes mor og jeg fattede straks sympati for hinanden, og det blev til et godt og varmt venskab med mange dejlige oplevelser i dansens verden. Jens Bugge havde en VVS-forretning i Helsted, hvor Kirsten sad på kontoret, men Jens kom vi aldrig rigtigt til at kende. Han var mere involveret i sønnen Carstens motocross sport, så det var sjældent, vi så ham. Den første gang, vi var inviteret hjem til dem, lå han på sofaen og læste avis, da vi kom, og han gad knap nok rejse sig og hilse på os. Han var flink nok, men han var måske lidt genert, og ofte kom Kirsten alene, når vi var til noget inden for dansen."}, {"type": "figure", "caption": "", "page": 199, "file": "assets/images-bog2/p199_01.jpg", "dim": [898, 637]}, {"type": "para", "text": "Men penge var der nok af, og han kunne undvære sin bare for Anne-Mette. Dans var en Hos Lis og Bent 1996. Bent, Kirsten, Anne Grethe, mig, Frio og Vagn              dyr sport, og når Anne-Mette skulle have en ny kjole, kostede den op mod 12.000 kr. Det var flotte kjoler hun fik, syet af Kenneths svigermor Hanne i Vejle, først en lilla, dernæst en lyserød, så en orange, en blå og til sidst en sort, og det var kun standardkjoler. Så kom latinkjolerne desforuden. Vi slap med ca. 6.000 kr. for et kjolesæt syet hos skrædder Fabricius i november 1991, men Lars fik også mere end ét kjolesæt, for han voksede fra dem. Heldigvis kunne vi sælge dem igen. Ud over tøj og sko var der også enetimer, som de fik en del af i starten for at blive danset sammen. De trænede fast to gange om ugen, og inden de selv fik kørekort, var Kirsten og jeg altid med. Kirsten og Anne-Mette kom og hentede os, og så sad vi mødre og sludrede med de andre danseforældre, mens børnene dansede. Det var rigtig hyggeligt."}, {"type": "para", "text": "Mange lørdage var der turneringer, regionsturneringer, JM og DM i både standard og latin, og når det foregik på Sjælland, startede vi i bus tidligt lørdag morgen og kom hjem natten til søndag. Fx var vi i 1992 til turneringer i 20 weekends. Det blev efterhånden en livsstil, og det var dejligt at følge de unge mennesker, især de gange, hvor de klarede sig godt. De lå ikke i toppen, men de knoklede og klarede sig ofte rigtig fint. Det var ikke et spørgsmål om at blive nr. 1 men et spørgsmål om at slå den og den og være lidt bedre end sidst. Jeg havde altid videokamera med, så alt blev filmet. Den første turnering, Anne-Mette og Lars deltog i som par, dansede de mod Anne og Lars Valdbo, og vi frydede os over, at de to par blev ens placeret. Betty ville nok gerne have set Anne slå Lars."}, {"type": "para", "text": "I de danselokaler, hvor danserne trænede, var der store spejle, så de kunne se sig selv. Vi købte et stort spejl og satte op i strygeværelset, så Lars kunne træne selv, men Vagn måtte flere gange skrue bissen på, når der gik for lang tid mellem seancerne."}, {"type": "para", "text": "Den 12. oktober 1991 var Kirsten med de unge til en turnering i Vejlby-Risskov Hallen, hvor vi ikke kunne deltage. Da de skulle hjem, var Kirstens BMW blevet stjålet med dansetøj og det hele. Den blev fundet tre dage senere uden tøj. Den havde været brugt til et rambuk tyveri, hvilket vi også kunne læse om i avisen. Vi fik 7.000 kr. i erstatning fra forsikringen og måtte have et nyt sæt syet. Når ÅS stod for turneringerne og der skulle lægges et rigtigt dansegulv, især til de store internationale turneringer, var Vagn foregangsmand, og han lavede også bagtæppe sammen med bl.a. Poul Møller."}, {"type": "figure", "caption": "", "page": 200, "file": "assets/images-bog2/p200_02.jpg", "dim": [750, 519]}, {"type": "figure", "caption": "", "page": 200, "file": "assets/images-bog2/p200_01.jpg", "dim": [785, 520]}, {"type": "para", "text": "Lars nyder vandet i Cervia 1991                                        Anne-Mette, Nicole, Lars, Jannick & Trine Årets højdepunkt var fra 1991 og 5 år i træk turneringen i Cervia i Italien. Vi kørte i bus fra Randers med Frio ved rattet, dansere og forældre, hovedsageligt mødre, og så startede en uge med dasen på stranden om dagen og turneringer om aftenen ofte til kl. 1, hvorefter vi lige skulle en tur på pizzeria. Det var en kæmpeturnering med dansere fra hele verden, og konkurrencen var hård. Man skulle være glad, hvis man kom videre til anden runde."}, {"type": "figure", "caption": "", "page": 200, "file": "assets/images-bog2/p200_04.jpg", "dim": [625, 893]}, {"type": "figure", "caption": "Lars K, Ina, Jesper, Rikke, Anne-Mette & Lars på pizzeria i 1992", "page": 200, "file": "assets/images-bog2/p200_03.jpg", "dim": [804, 543]}, {"type": "para", "text": "Cervia 1994"}, {"type": "para", "text": "Til 2. Regionsturnering i Latin den 18. januar 1992 kom Anne-Mette og Lars i semifinalen og blev nr. 11, hvilket var et flot resultat. De var dog klart bedre i standard. Her blev de en delt 7’er i A-rækken ud af 23 par til 3. Regionsturnering i Standard den 22. februar samme år. De dansede nu i Junior 2-rækken. Vores kære børn fik mange spændende oplevelser gennem dansen og mange kammerater. En af oplevelserne var, da de blev inviteret ind i Sport i 2’eren i TV2 Odense den 29. marts 1992, og vi kunne sidde hjemme i stuen og se, hvordan de valsede rundt i studiet. Det var stort, og vi var endnu engang glade og stolte."}, {"type": "para", "text": "En stor oplevelse var også, da vi mødte op inde i ÅS for at hylde verdensmestrene fra ÅS, Allan Tornsberg og Vibeke Toft den 18. oktober 1992. Kort derefter blev ÅS-danserne inviteret til en trænings-weekend i Oslo af Tor Fløysvik, en anden kendt danser. Jeg kan stadig begræde det faktum, at vi ikke var til stede, da Anne-Mette og Lars var med til at vinde guld ved Danmarksmesterskabet for hold den 7. november 1992 i Aalborg Stadionhal. Vi var med fra starten, men på grund af en fætter-kusinefest i Vagns familie, som vi ikke syntes, vi kunne sige nej til, måtte vi forlade dansen for at være i Tårs Forsamlingshus til aften. Vi havde slet ikke regnet med, at det skulle blive til en guldmedalje. Hvor ville det have været dejligt at være der, da holdet blev udråbt som vindere, og hvor var det synd for Lars, at vi ikke var der for ham. Heldigvis ringede han til mor og fortalte hende resultatet, og det var hun beæret over. Det skete, at mor var med ude og se turneringer. Hvor ville det have været fedt at have haft mor med til denne turnering, men vi kan ikke gøre det om. Junior 2 holdet bestod af Morten Lohse/Charlotte Svanholm og Lars Kromann/Camilla Pedersen i latin og Jesper Velling/Vicky Thybo og Lars Møller Christensen/Anne-Mette Bugge i standard. Ud over guldmedaljen fik hver danser også overrakt en stor buket blomster."}, {"type": "figure", "caption": "", "page": 201, "file": "assets/images-bog2/p201_01.jpg", "dim": [622, 879]}, {"type": "para", "text": "Traditionen tro arrangerede Århus Kommune en DM fest for de unge sportstalenter, der i året havde vundet guld, denne gang den 25. marts 1993 på Sct. Anna Gade Skole. Her var vi heldigvis med og kunne sidde som de stolte forældre og overvære, at hver danser fik overrakt en glaspokal med Århus Byvåben samt rosende omtale."}, {"type": "figure", "caption": "", "page": 201, "file": "assets/images-bog2/p201_02.jpg", "dim": [1086, 697]}, {"type": "para", "text": "Traktementet var pizza, og efter det officielle spillede aftenens DJ op til dans. Også her vandt ÅS klart, imens vi voksne hyggede os og nød atmosfæren. Jo, det var en god aften for os alle."}, {"type": "para", "text": "Det gik generelt godt for AnneMette og Lars i Junior 2 rækken, især i standard, og ved regionsturneringerne var de blandt de bedste, så de kvalificerede sig til at komme med til DM i standard den 6. marts 1993, hvor de blev nr. 21 ud af 31 par. Der var virkelig hård konkurrence, og nogle af parrene var blandt de bedste i verden. Jeg var tit nervøs til turneringerne, fordi jeg så gerne ville, at det skulle gå dem godt, så jeg var nervøs for, at de skulle lave fejl, danse ind i andre par eller falde under quickstep’en. Jeg pakkede altid Lars’ tøj og tilbehør til turneringerne, og oftest huskede jeg det hele, men en gang havde jeg glemt hans seler til kjolesættet. Da var gode råd dyre, men vi kunne heldigvis låne et par af en anden danser. Jeg satte også i starten hår på Lars, men det var jeg ikke god til. Somme tider fik vi Lis til det, og da Lars blev ældre, gjorde han det selv. Han blev rigtig god til det. Det klædte ham også godt, da han en overgang fik permanent i håret og lyse striber. Danserne skulle jo se solbrændte ud, så pigerne smurte sig ind i selvbruner, nogle gange med 1992                                     blandet resultat, hvis cremen ikke var blevet fordelt rigtigt. Mange af drengene brugte ”jord” i ansigtet, en slags farvet pudder (Nilens jord), som gjorde, at de så solbrændte ud. Det var min opgave, inden Lars gik på gulvet, at give ham ”jord” i hovedet og sætte rygnummeret på. Sidstnævnte kunne også være en udfordring, for det skulle sidde lige og ikke falde af undervejs. Og så skulle vi naturligvis heppe på vores par under dansen, jo mere, jo bedre. Engang Mary var med, blev hun meget forarget over alt det råberi, indtil jeg forklarede hende, at sådan gjorde man altså. Anne-Mette og Lars fik nyt standardtøj i starten af 1993, så til ÅS forårsopvisning den 13. marts var de flotte. Det var dejligt, at mor var med her, for det var den sidste dans, hun så dem i. I latin var der også succeser, idet Anne-Mette og Lars vandt A-rækken til Jysk/Fynske Mesterskaber i Latin den 27. marts 1993 i Struer, hvor de dansede en flot finale, Anne-Mette i sin flotte gule latinkjole og Lars i sin fine sorte latindragt syet af Hanne i Vejle. Han havde også en hvid skjorte med store ærmer, han kunne bruge til bukserne. Efterfølgende, hvor de kvalificerede sig til DM i Latin, blev de nr. 19 ud af 28 par, hvilket vi alle var rigtig godt tilfredse med."}, {"type": "figure", "caption": "", "page": 202, "file": "assets/images-bog2/p202_01.jpg", "dim": [675, 841]}, {"type": "para", "text": "Vi brugte mange penge på enetimer, men det var nødvendigt, og det gjorde alle. Og det var virkelig sagen, når de blev trænet af de kendte, fx Tor Fløysvik, Jens Werner samt Vibeke og Allan."}, {"type": "para", "text": "Til den nye dansesæson i 1993 rykkede de op i Ynglingerækken, og selvom konkurrencen nu var hårdere, formåede de alligevel at få en fin andenplads i B-rækken til den første turnering i standard i september. Til deres første latinturnering den 2. oktober blev de nr. 11 i A-rækken og kvalificerede sig til Ranglisteturneringen. Til 2. Regionsturnering i Standard den 27. november blev de nr. 11 i Arækken og slog overraskende 5 par, som de ikke havde regnet med at slå, og til DM for Hold i 1993 vandt deres hold bronze. Danserne havde altid smarte klubdragter på, når de ikke dansede turnering, sponsoreret af ÅS. I 1993 var den rød og hvid med logo og danserens navn på."}, {"type": "para", "text": "Ud over turneringerne fik Anne-Mette og Lars også mange andre dejlige oplevelser med dansen. De blev inviteret til at give opvisninger forskellige steder. Det kunne være til forskellige fester, julefrokoster eller Hammel Hestemarked, eller det kunne være til en polterabend, hvor de skulle lære brudeparret at danse brudevals. For eksempel gav de opvisning for 160 loge-brødre i Rotary på Årslev Kro den 2. oktober 1993. Den 6. september 1993 var der i TV-sporten på TV2 direkte dans fra Musikhuset, hvor Anne-Mette og Lars var med. Den 19. juni 1994 var de med til at give show i Hørning Hallen under ledelse af Kenneths søster Kristina Mølgaard, som selv var tidligere danser og en meget dygtig instruktør."}, {"type": "para", "text": "Som sagt hjalp Vagn til ved turneringer, og Lars for så vidt også, hvis det var muligt. For eksempel styrede han lyset til World Cup i 10 Danse i Vejlby-Risskov Hallen den 11. september 1993, et meget betroet job, som han klarede til topkarakter. Det blev ved med at gå godt i Ynglingerækken, for til Jysk-Fynske Mesterskaber i Standard den 22. januar 1994 vandt de A-rækken, hvilket var flot, og til 3. Regionsturnering i Standard den 12. februar blev de nr. 12 og kvalificerede sig til DM. Her fik de også et pænt resultat og blev nr. 22 med 13 krydser. Vi gik altid meget op i, hvor mange krydser de fik. Tangoen var deres bedste den dag. Til DM i Latin den 16. april kom de i kvartfinalen og blev nr. 16, hvilket vi alle var ovenud tilfredse med."}, {"type": "figure", "caption": "", "page": 203, "file": "assets/images-bog2/p203_01.jpg", "dim": [583, 832]}, {"type": "para", "text": "Lars fik syet latintøj hos Hanne i Vejle i foråret 1994. Regningen var på knap 4.000 kr., hvoraf sy-lønnen var det halve. Vi kørte derfor til Vejle et par gange for at prøve tøj. Udover sommerturneringen i Italien blev det også til andre udlandsture, fx den 11. & 12. juni 1994, hvor Kirsten og jeg tog med vores børn til en turnering i Alterstal ved Hamborg. Her var de bl.a med til en spændende turnering, hvor der til sidst var åben votering, og de blev nr. 4 i standard og fik overrakt præmier. Det var en rigtig god tur, hvor vi voksne som sædvanlig hyggede os med hinanden."}, {"type": "para", "text": "Den nok bedste placering i Standard opnåede Anne-Mette og Lars den 10. september 1994 i VejlbyRisskov Hallen, hvor de var med til en Unibank-Cup i standarddanse for ynglinge ved World Open Latin. Der var 14 par, og de blev nr. 8 og slog Morten og Charlotte med hele 2 pladser. Inge-Marie blev nr. 12. Den aften var vi pavestolte, men de dansede også utroligt flot. En anden god placering i Standard blev opnået ved 3. Regionsturnering den 11. februar 1995 i Gistrup Hallen. Her kom de i finalen og blev nr. 6. Til lykke. Og succesen fortsatte, for til DM i Standard den 11. marts blev de nr. 15 ud af 28 par og fik 13 krydser."}, {"type": "para", "text": "Til en af turneringerne vandt Lars et stykke sort stof, som vi senere fik syet en vest af til ham. Det tog Hanne 408 kr. for."}, {"type": "para", "text": "Til turneringerne var det sjovt at se de små danse. Instruktørernes egne børn var kvikke på et dansegulv, men de havde det vel i blodet. Kenneths Nicole og Ringgårds Dennick var rigtig søde sammen, selv om de var fra konkurrerende danseinstruktører. Og jeg husker også Jannick Birkehøj, en sød og meget dygtig lille purk, som 20 år senere skulle blive vores instruktør hos VM Dans."}, {"type": "para", "text": "Vi var næsten altid med til generalforsamling i ÅS, og hvert år blev der overrakt en ”Elefantorden” i form af en træelefant og et indrammet diplom til en, der havde gjort noget særligt for ÅS. Elefanten skulle så næste år gå videre til den nye udkårne. I 1995 blev det overraskende Vagn, der fik elefanten. Vi havde slet ikke tænkt tanken, men helt overraskende var det måske alligevel ikke, for Vagn havde gjort et stort arbejde for ÅS i deres lokaler i Nørregade, hvor der var blevet istandsat og møbleret for 35.000 kr., kun ved frivillig hjælp. Det var et dejligt skulderklap at få, og Vagn blev, også efter Lars stoppede med at danse, ved med at hjælpe ÅS til turneringer."}, {"type": "para", "text": "En person, vi heller ikke skal glemme, er Jørgen Thygesen, som altid var turneringsleder til de store stævner i ÅS. Han gjorde et kæmpe arbejde for klubben og var et meget fint menneske. Han havde altid en frisk bemærkning klar og et kæmpeknus, og da han pludselig døde, tog jeg med til hans begravelse i Egå Kirke. Han blev naturligvis mindet ved den efterfølgende turnering, og i flere år derefter blev Jørgen Thygesens mindelegat overrakt af hans enke."}, {"type": "para", "text": "Anne-Mette og Lars tog i sommeren 1995 imod en invitation til en turnering i Grömitz i Nordtyskland. Den skulle foregå den 8. juli, og vi valgte at lade den være starten på vores camping sommerferie. Det samme gjorde Bugges, som også havde campingvogn. Det blev både en hyggelig og udbytterig tur, for Anne-Mette og Lars opnåede en flot andenplads ud af 9 hovedsagelig voksne par. Turneringen foregik på en kro med et lille intimt dansegulv omgivet af grupperinger af borde og stole, hvor tilskuerne kunne sidde. Der kom mange lokale tilskuere, og der var virkelig god stemning og tilråb fra publikum, når danserne fejede hen over gulvet. Anne-Mette og Lars var et af favoritparrene og blev vældigt populære på gulvet. Igen kunne vi som forældre se stolte til, da de blev hyldet og fik præmier: 1 flot pokal, blomster, medalje, bog om Grömitz, stort flot glasfad, marcipanmedalje, chokolade, middag, drikkevarer og 100 DM hver. I august var de dernede igen og blev nr. 3, og de fik næsten de samme præmier som sidst, udover at Lars også fik en stor kasse med øl og ølglas."}, {"type": "para", "text": "Anne-Mette og Lars fik mange venner gennem dansen, og det skete, at nogle af dem kom på besøg og overnattede. Det hændte også, at Anne-Mette spiste og overnattede hos os. Jeg tror, at Kirsten havde håbet på, at der kunne blive et kærestepar ud af Anne-Mette og Lars, og for mig var Lars jo også enhver svigermors drøm, men jeg var godt klar over, at det aldrig blev. Anne-Mette var nok lidt for skrap for Lars og ville gerne bestemme, men vi var meget glade for hende, for hun var en frisk pige og var altid god for en frisk bemærkning. Der var gensidig sympati og respekt, men kærester – nej. Anne-Mette fik jo også ret tidligt en kæreste i Thomas, som var en meget stille dreng, der ikke var kommet over bumsealderen endnu. Han kørte motocross ligesom Anne-Mettes bror, og det var nok det, hun var faldet for. Thomas var også med i Tyskland. Forholdet holdt dog ikke."}, {"type": "para", "text": "Lige inden Tysklandsturen fyldte Anne-Mette 18 år den 5. juli. Den aften var vi inviteret til middag på ”No.1” i Randers sammen med fødselaren, hendes forældre, hendes bror og kæresten Thomas. Vi gjorde det samme, da Lars blev 18 år, dog ikke i Randers men på ”Stedet” i Århus."}, {"type": "para", "text": "Lars fik nyt kjolesæt hos Gurli i september 1995, så han var helt klar til 1. Regionsturnering den 23. september. Måske var det derfor, de fik så flot et resultat. De blev nr. 5 i A-rækken og slog igen Jesper Velling, hvilket sikkert ikke faldt i god jord hos Jespers mor Eva, som vi ikke brød os særligt meget om. Nr. 2 blev Thomas Evers Poulsen, som dansede med Vicki Thybo."}, {"type": "para", "text": "Ved 2. Regionsturnering i Standard den 25. november 1995 kom Anne-Mette og Lars i A-finalen og blev nr. 5, hvilket også blev omtalt i avisen. Ja, det gik rigtig godt, og i flere turneringer fik de finalepladseringer, også i 1996. Det blev til en 8. plads i A-rækken i Latin, nr. 10 ud af 31 par til 2. Rangliste i Standard, nr. 6 i finalen til Jysk-Fynske Mesterskaber i Standard, sølvmedalje til DM Hold, og sådan kunne jeg blive ved. I 1996 blev de også udråbt som Årets Par og fik en vandrepokal."}, {"type": "para", "text": "Det var ikke kun Vagn, der stillede op i ÅS, når der skulle arbejdes. Jeg gjorde også en indsats, synes jeg selv, til ÅS Træningslejr den 9.-11. august 1996, hvor jeg var madmor for 40 dansere. Det startede fredag aften med aftensmad, og der skulle noget på bordet til 40 sultne dansere. Jeg havde hjælp af Kirsten, og vi havde været ude og købe ind sammen. Jeg lavede de to gange aftensmad hjemme og transporterede det hele derud. Danserne sov der om natten, men jeg kørte hjem og ladede batterierne op til næste dag, hvor jeg startede tidligt hjemmefra og købte rundstykker på vej derud. Jeg lejede også en sodavandsmaskine hos McDonalds, så danserne kunne tappe drikkevarer dagen lang. Vi plukkede buketroser i haven til at pynte bordene med, og vi gjorde det rigtig hyggeligt derude i klublokalerne. Om aftenen kom der flere forældre og hyggede, så alt i alt blev det en vellykket træningslejr, og jeg fik megen ros for maden."}, {"type": "figure", "caption": "", "page": 205, "file": "assets/images-bog2/p205_01.jpg", "dim": [789, 1062]}, {"type": "para", "text": "Det skete, at danserne kunne score kontanter, såsom da Anne-Mette og Lars gav show hos DER i Silkeborg og fik 3.000 kr., og da de til JM i Latin i 1997 fik en samlet 6. plads i Grand Prix og vandt 1000 kr. Nu var de kommet op i voksenrækken, så nu var det slut med de fine placeringer, lige bortset fra den nævnte 6. plads og en sølvmedalje for hold."}, {"type": "para", "text": "Anne-Mette fik ny kjole den 13. september 1997 til 14.000 kr., og den 2. december samme år foreslog Lars, at de skulle stoppe med dansen efter DM i marts. Det var måske ikke det smarteste tidspunkt på grund af den nye kjole, men det var blevet for svært at være med på en tilfredsstillende måde, og en af grundene til, at resultaterne var blevet dårligere var også, at Anne-Mette havde taget på i vægt. Hun havde det svært med vægten og havde i flere år kæmpet for at holde sig nogenlunde slank, men nu var det løbet løbsk for hende, og det var også synd for Lars, at han skulle trække rundt med den last. De var da også enige om at stoppe, så det var fint nok. De havde begge kærester, og Lars havde sine studier at passe, så tiden var inde. Anne-Mette og Lars dansede deres sidste dans den 7. marts 1998, og Lars havde købt en armring og en buket blomster til Anne-Mette i afskedsgave. Vi mødre tudede, og det var næsten ikke til at bære at tænke på, at vi aldrig mere skulle se dem feje hen over dansegulvet i en smuk engelsk vals eller en forrygende quickstep, to danse, de var rigtig dygtige til. Vi havde Lars’ kæreste Marianne med til turneringen, og jeg husker, at hun tog omkring mig og forsøgte at trøste mig på vej ud til bilen. Om aftenen skulle vi til Ellens 60-års fødselsdag med musik og dans, så da fik jeg heldigvis andet at tænke på. Et kapitel var slut, men hvor havde vi haft mange dejlige oplevelser sammen med Lars igennem dansen. Den 18. april 1998 deltog vi i ÅS 25-års Jubilæum i Congress Center, og Marianne og Lars var med. Herefter blev vi i nogen tid ved med at deltage i de store turneringer, både som tilskuere og hjælpere. Det var svært at slippe dansen. Derfor glædede det mig også meget, da Lars og hans nye kæreste Mette begyndte at gå til dans, og jeg havde også håbet, at mine børnebørn skulle komme til at lære at danse. Der er dog stadig håb med de mindste."}]}, {"title": "Lars går på universitetet og bliver forelsket", "blocks": [{"type": "para", "text": "Efter endt studentereksamen var der ingen tvivl: Lars ville læse videre på Århus Universitet. Han ville ikke først ud at rejse eller have arbejde som så mange unge, og det passede os fint. Ofte kan det være svært at vende tilbage til bøgerne, når man først er kommet vær fra miljøet. Jeg var jo også selv startet på Århus Universitet lige efter studentereksamen. I vores familie lavede man ingen svinkeærinder, og var man startet på noget, gjorde man det færdigt. Det var dog lige før, at Lars var kommet til at bryde den familietradition."}, {"type": "para", "text": "Lars blev optaget på Århus Universitet den 27. juli 1996 på studiet økonomi-matematik, og undervisningen startede den 26. august. Lars bestod sin økonomieksamen den 27. januar 1997, men i løbet af semesteret fandt han ud af, at det var økonomien, han ville følge, så den 1. september begyndte han på økonomistudiet. Han skiftede altså spor, men hellere det end for sent at finde ud af, at man havde valgt forkert, og det år, der var gået, var ingenlunde spildt."}, {"type": "para", "text": "I sin fritid tog Lars meget på Blitz, som var et populært diskotek i Århus, og der var også fester på Uni, som han deltog i. Vagn kørte ham til fest på Universitetet en aften i september 1997 og skulle hente ham igen. Jeg var på en rejse til Berlin og hørte først historien, da jeg kom hjem. Mens Vagn holdt uden for Universitetet og ventede på Lars kl. 1 om natten, blev døren pludselig revet op. Det var Lars, der erklærede, at han skulle sove ude hos sin kæreste, og han spurgte, om Vagn godt ville køre dem derud. Om søndagen den 14. september var Marianne med Lars hjemme for første gang, og det var første gang, at han havde en pige med hjemme. Hun læste også økonomi og hed Simonsen til efternavn. Hendes mor var læge i Poulstrup og var skilt fra Mariannes far, der boede i London med en ny kone og to børn. Marianne var fra 2-års alderen vokset op med en ny far, Ole, som havde fået to børn med Mariannes mor. Det var et indviklet familieforhold, men Marianne var en sød pige, og vi kom hurtigt til at holde af hende. Hun var en klog pige, og Lars og hun konkurrerede om karaktererne. Ved vintereksamen i 1998 fik Lars 8-10-10 og Marianne fik 9-11-8, så det stod lige, og til sommereksamen fik Lars 7-10 og Marianne 9-9. Mariannes ambitioner var nok lidt højere end Lars’, og i dag er hun professor ved Aarhus Universitet."}, {"type": "para", "text": "Vi var glade for at have Lars boende hjemme, og selvom han havde visse pligter, så havde han det som blommen i et æg. Han fik alle de serviceydelser, som hjemmeboende studerende får, og transporten til Århus var nem. Marianne var altid velkommen, og det benyttede hun sig i høj grad af, hvilket kun var hyggeligt. Derfor kom det også som et chok for mig, da Lars den 4. januar 1998 erklærede, at han ville flytte hjemmefra. Jeg var ved at tage julepynt ned, og pludselig sad jeg på hug på gulvet og var totalt handlingslammet. Vagn var nogenlunde forberedt på, at det ville ske, men i min naivitet havde jeg ikke set det komme. Vagn havde aftalt en fisketur med Leif Nilaus, så jeg ringede op til Jette og spurgte, om jeg måtte komme derop. Det måtte jeg naturligvis, og hun ydede mig den ”krisehjælp”, jeg havde brug for. Hun var god til at trøste mig, selv om hun ikke rigtigt kunne sætte sig i mit sted, idet de havde haft en del problemer med Lasse og bestemt ikke ville begræde den dag, han flyttede. Bagefter kunne jeg jo godt forstå, at Marianne og Lars gerne ville have en lille lejlighed for dem selv. Vi tilbød at tage med dem ud og se på lejligheder, så den 8. januar så vi to lejligheder, og den 1. marts tre lejligheder. Den 8. marts kom Mariannes familie fra Poulstrup til kaffe, og bagefter var vi alle inde og se på lejligheden i Nordborggade 57, som de købte den 13. marts for 750.000 kr. Den var på 60 m2 og rigtig hyggelig. De flyttede ind den 25. april, og vi forærede Lars en cykel til 4.000 kr. I juni og juli hjalp Vagn Lars med at tapetsere stuen og soveværelset med lidt hjælp fra Erik maler."}, {"type": "para", "text": "Nu var der stille på Østervang 25, og vi savnede pludselig høj musik fra kælderen, trin på trappen og hyggestunder i stuen. En ny æra var begyndt, og vi skulle til at vænne os til kun at være to. Det gik nu meget godt, faktisk bedre end jeg havde frygtet. Men det var hyggeligt engang imellem at tage forbi lejligheden til en kop kaffe og te på vej hjem fra arbejde, og de unge kom da også tit på besøg, så krisen var overstået."}, {"type": "para", "text": "Fordi Lars var så heldig (eller dygtig) at få arbejde under sin uddannelse hos Rambøll Management, kneb det med at få studierne færdiggjort, og på et tidspunkt frygtede moderen for, at han aldrig ville gøre sin uddannelse færdig, men han overraskede os positivt den dag, han ringede og fortalte, at han havde fået 12 i sit speciale og nu kunne kalde sig cand.oecon. Han havde formået, samtidig med at han havde fuldtidsjob, havde stiftet familie og var i gang med en husrenovering, at gøre sin uddannelse færdig. Godt gået Lars. Jeg tror, han gjorde det lidt for at glæde sin mor."}]}, {"title": "Lars’ fritidsinteresser", "blocks": [{"type": "para", "text": "Lars kunne få megen tid til at gå med sin PC, og han hørte meget radio. En aften i maj 1990 hørte vi ham pludselig i radio ABC. Han havde ringet ind for at være med i en konkurrence, og han vandt to billetter til fodbold i Randers dagen efter. Han inviterede selvfølgelig sin far med. De to hyggede sig med at gå til fodbold sammen, og favoritklubben var og er stadig AGF."}, {"type": "para", "text": "Der gik naturligvis megen tid med dansen, men når der var en weekend, hvor der ikke var dans, tog Lars gerne til fest, enten til skurfest i Trige eller på Blitz. Første gang, Lars var til skurfest, var den 4. september 1992. Jeg tror, at han kom lidt sammen med Helle fra klassen, for han var også med hende hjemme, men han kom ikke hjem og fortalte så meget, og selv om jeg spurgte, fik jeg ikke meget at vide. Hun var ellers en pæn og sød pige, så dengang ønskede jeg, at de blev kærester. Lars købte printer i oktober 1992. Han meldte sig ind i Ungdomsklubben i marts 1993. Det var ikke tit, at han drak for meget, men til en skurfest i april 1994 ringede Lasse Nilaus og sagde, at vi hellere måtte hente Lars, så Vagn kørte derop efter ham. Det var godt, at de unge mennesker kunne se efter hinanden og tilkalde hjælp, når det var nødvendigt. Næste dag fandt Lars ud af, at hans penge var blevet stjålet, så det var rigtig træls oveni tømmermændene."}, {"type": "para", "text": "Lars var meget glad for at se TV, så det var en stor oplevelse for ham, da han kom med til DR TVoptagelser med Poul Thomsen i 1994."}, {"type": "para", "text": "Lars var også samler, og i mange år samlede han på nøgleringe. Vagn lavede en tavle over hans seng, hvor de alle hang. Desuden samlede han på frimærker, julemærker, førstedagskuverter og mønter. De to førstnævnte samler han vist stadig på."}]}, {"title": "Jul og nytår i 90’erne", "blocks": [{"type": "para", "text": "I 1990 kom Per og mor og holdt jul med os i Spørring. Lars hjalp altid med at bage til jul, også efter han flyttede hjemmefra, og vi førte traditionen videre med at være inde og handle søndag før jul. I min barndom var det Aalborg, men nu var det naturligvis Århus. Når vi havde handlet, spiste vi på restaurant og gik i biografen. Nytårsaften holdt vi hos Tage og Anna-Lise sammen med Preben og Ellen."}, {"type": "para", "text": "I 1991 lavede vi pakkekalendere til vores forældre. Mor kom og fejrede jul hos os, så vi var 4 juleaften. Så kørte vi til mormors fødselsdag 2. juledag, og om aftenen holdt vi juleaften i Tårs sammen med Tage og Anna-Lise. Nytårsaften holdt vi hos Preben og Ellen. Det samme julemønster gentog sig året efter, hvor mor og jeg fik hver sit TV i julegave (til køkkenet). Nytår 1992 holdt vi i Spørring sammen med Tage og Anna-Lise. I 1993, hvor vi tog væk fra julen og til Gambia, holdt vi jul i Tårs den 18. december. Nytårsaften sad vi alene tre, for da var vi lige kommet hjem fra ferie og trængte til at slappe af. Til gengæld kørte vi til Tårs nytårsdag. Året efter havde vi fornøjelsen at have både Per og Marianne her.  Det var en spændende aften, for Marianne skulle have en bil i Julen 1992 i Spørring julegave. Vagn havde været med Per ude og købe en rød Peugeot til Marianne, og jeg havde viklet den ind i silkebånd i garagen, hvortil en skattejagt skulle føre hende. Nej, hvor blev hun glad og overrasket, og hun skulle straks ud og prøve den, selv om vi var midt i gaveudpakning. Marianne har altid været glad for at køre bil. Jeg havde ellers lidt besvær med at finde ud af, hvad man skulle servere for en vegetar juleaften. Det endte med en nøddesteg. 4. juledag var vi i Skagen. Nu kom der nogle år, hvor vi nød at sidde alene to nytårsaften, spise nogle lækre fiskeretter foran TV og bare slappe af. Efter midnat blev der som regel ringet efter os fra nogle venner. Det kunne være Finn og Karen Lis, Anne og Niels, Ruth og Ras eller Alice og Reinholt."}, {"type": "figure", "caption": "", "page": 208, "file": "assets/images-bog2/p208_01.jpg", "dim": [1184, 779]}, {"type": "para", "text": "I 1995 købte vi juletræ hos Ingrid og Erik Sørensen, hvor vi også havde vores campingvogn stående om vinteren. Per og Marianne kom her den 23. december, men vi var alene juleaften. Vi havde Vagns familie juledag og var i Skagen 3. juledag sammen med onkel Alfred."}, {"type": "figure", "caption": "", "page": 208, "file": "assets/images-bog2/p208_02.jpg", "dim": [975, 710]}, {"type": "para", "text": "I 1996 var Per og Marianne her igen juleaften, og 4. juledag besøgte vi moster og Ib i deres sommerhus. I 1997 hjalp både Marianne og Lars med julebagningen. Vi var alene tre juleaften, men det hyggede vi os med."}, {"type": "para", "text": "Vi havde købt rigtig mange gaver til hinanden. 1. juledag kom Vagns familie, og 2. juledag kom Per, Marianne og onkel Erik. Af hensyn til Marianne fik vi ørred og ris à l’amande. 4. juledag kørte vi til Skagen, og Lars havde sin kæreste Marianne med. Vi hentede Alfred og havde også ham med. Da vi kørte ham hjem, gav han os en kuvert med 1000 kr. Julen var en hyggelig tid, og jeg havde megen julepynt, der skulle op at hænge. Den 4. januar 1995 tog det 4 timer at pille det hele ned. Jeg hjalp også ofte Mary med at pynte juletræ og hænge det op, hun ikke kunne nå, og når det skulle ned igen, hjalp jeg hende også. Nytårsdag så vi altid Wienerkoncert i TV."}]}, {"title": "Vores sølvbryllup den 28. juli 1998", "blocks": [{"type": "para", "text": "Vi er gift samme dag som Jette og Leif Nilaus, og da vi jo havde en del fælles venner, holdt vi ret tidligt et planlægningsmøde vedrørende vores sølvbryllupper. Heldigvis viste det sig, at de helst ville holde festen på dagen, mens vi helst ville holde festen den efterfølgende lørdag. Vi måtte så love dem, at vi ville komme til deres fest, og de ville endda invitere Marianne og Lars med, så det lovede vi."}, {"type": "para", "text": "Vi var ikke i tvivl om, at vi ville holde festen på Spørring Hotel. Siden vores kobberbryllup havde sønnen og svigerdatteren, Keld og Helle, overtaget driften, da Grethe havde fået en hjerneblødning og sad i kørestol. Hun havde også mistet talens brug, men hjernen fejlede ikke noget. Grethe og Egon havde stadig deres gang på Hotellet, og når man kom derned, ville de gerne snakke. Egon kunne forstå næsten alt det, Grethe prøvede at sige, så det var bedst, når han var der. En af de gange, vi var dernede, var der noget, Grethe ville spørge mig om, og Egon kunne for en gangs skyld ikke forstå hende. Pludselig slog det mig, at det nok var Lars, hun spurgte til, og da jeg nævnte det, nikkede hun glad. Hun havde været meget glad for byens børn og unge mennesker, og hun var interesseret i, hvordan det gik dem. Jeg var glad for, at vi fandt ud af det."}, {"type": "para", "text": "Vi bestilte festen allerede den 16. april 1996, og musikken bestilte vi den 25. maj 1997. Det var næsten umuligt, men efter 15 forsøg lykkedes det. Det blev Ole Vendelbo, der skulle spille for os, og hans honorar var 4.000 kr. Vi havde den ordning med Hotellet, at vi selv kom med vinen, og så skulle vi betale et vist beløb i ”proppenge”. Vi bestilte vinen i Føtex den 15. maj og hentede det den 4. juli."}, {"type": "para", "text": "Foruden de to sølvbryllupper, der allerede er nævnt, var vi også inviteret til Anne og Niels’ sølvbryllupsfest den 13. juni på Nilles Kro, også en lørdag. Der skulle laves sange, som vi altid gjorde i vennekredsen, laves æresporte, købes gaver og købes nyt tøj. Man kunne jo ikke have den samme kjole på til alle tre fester. Jeg havde købt en lang blå kjole i Frankrig året før, som jeg ville have på til Anne og Niels’ fest, og til Jette og Leifs fest købte jeg en blå sommerkjole i Hadsten. Den 4. juni købte vi smoking og sko til Vagn. Han kunne godt have det samme tøj på til tre fester, når bare han skiftede butterfly."}, {"type": "para", "text": "Invitationerne havde jeg lavet selv med hjælp fra Lars. Vi var til Vivi og Frodes sølvbryllup kort forinden blevet fotograferet, da vi kom, hvor jeg bar en rød kjole, og Vagn bar smoking og rød butterfly. Det var et ret godt billede, så det besluttede vi os for at bruge på forsiden af kortet, som var rødt. Inde i kortet var der et løst ark, hvorpå Lars havde skrevet teksten på PC. Det var bundet til kortet med en sølvsnor og –hjerte. Invitationerne blev sendt ud den 12. juni, og ud af de 100 gæster, vi inviterede, fik vi 7 afbud. Vi ville jo gerne gøre det rigtige, så vi spurgte Lars, om vi ikke skulle invitere Mariannes mor og stedfar med. Det syntes han ikke var en god idé. Jeg gik ham lidt på klingen for at vide, hvorfor, og fik så svaret: ”Mor, det har du ikke lyst til at vide”. Det viste sig, at de var ved at blive skilt, og så snakkede vi ikke mere om det."}, {"type": "para", "text": "Vagn og jeg var inde i Århus hos Belmondo og se på kjole til mig den 11. juni. Vi fandt en flot lang kjole i thaisilke i grønne og blå farver med stort skørt holdt ud af tyl-underlag. Den var stropløs og sad bare helt perfekt, til en pris af 3.200 kr. Marianne og Lars var med inde og se den nogle dage senere, og de syntes også, den var flot, så jeg købte den."}, {"type": "para", "text": "Selv om vi skulle holde festen ude, var der mange forberedelser, der skulle planlægges og udføres, men heldigvis var det ferietid, så vi skulle ikke også gå på arbejde op til festen. Der skulle ud over det allerede nævnte tænkes på indkvartering til nogle af gæsterne, taler, folder med velkomstsang og menu, bordplan, ønskeseddel, morgengave, hjælp i køkkenet til morgenbesøg, bestilling af morgenbrød og bestilling af pølsebord til frokost. Vi skulle købe ind, bage småkager, gøre rent, ordne haven, bestille frisørtider m.m., men hvor var det sjovt, og vi glædede os helt vildt. Jeg havde tre frisørtider hos Lis: Den 14. juli blev jeg klippet og permanentet, den 27. juli blev jeg farvet og føntørret, og den 1. august blev jeg føntørret og fik lagt make-up."}, {"type": "para", "text": "Bordkortene skulle være specielle. Jeg havde set modeller i en bog, hvor man i karton klippede sorte herresko til mændene og grønne damesko til damerne. Der var sølvfarvede snørebånd i mændenes og laksefarvede silkebånd i damernes sko. Marianne hjalp mig, og hun skrev navnene på skoene med sølv, da hun havde en fin håndskrift. Vi påbegyndte projektet den 5. juli og var færdige den 17. juli. Den 13. juli var vi med Lars inde og købe nyt tøj, og jeg købte ur til Vagn i morgengave. Jeg skrev også et digt, som skulle følge med morgengaven. Den 15. juli bagte jeg småkager, som vi gerne måtte tage med på Hotellet til kaffen."}, {"type": "para", "text": "Når jeg ser tilbage på den sidste måned inden den store dag, var det egentlig utroligt alt det, vi klarede. Vagn var i gang med at hjælpe Lars med at male deres lejlighed, og jeg var inde og gøre rent. Vi var til Svends 85-års fødselsdag på Frederikshøj Kro og til efterbryllup med Pernille og Jan, vi så VM i fodbold sammen med genboens, og jeg var ude og plukke jordbær sammen med Grete, Vagn var på fisketur, og vi havde hele slænget en aften for at lave sang til Jette og Leif, hvor det endte med, at jeg lavede elleve vers og Niels et, og sangskjuleren var en bryllupskage. Jeg cyklede ture, vi tog til Århus og så på billeder, fordi farmor ville give os et stort billede i gave, og jeg tog sol i solarium for at blive lidt solbrændt, til jeg skulle have min festkjole på, og for at det ikke skulle være løgn, pakkede jeg campingvognen den 16. juli, for vi skulle da lige holde lidt ferie på Hanstholm Camping. Den 18. juli kørte vi afsted, men da vi kom til Randers, måtte vi vende om og køre hjem efter checkhæftet, som vi havde glemt. 10 km. fra Hanstholm strejkede bilen, men langt om længe nåede vi frem, efter at have været undervejs i 5 timer. Nu kunne vi så til gengæld slappe af i en uge med fiskeri og cykelture. Vi fik også skrevet tale og øvet os på at holde den uden manuskript (herom senere). I Thisted fandt vi det billede, vi kunne lide, og det kostede kun 1445 kr. Men vi skulle naturligvis have ligeså meget, som Doris og Poul Erik havde fået til deres sølvbryllup, så vi fik 3.500 kr. ved siden af og en flot blå glasskål."}, {"type": "para", "text": "Vi stillede borde an i stuen den 26. juli og dækkede næste dag til 57 gæster. Marianne og Lars kom hjem og hjalp til, men de skulle jo også være med til at lave æresport, som foregik nede på Ellens gård. Med til at hjælpe var også Alice, Reinholt, Grete, Poul, Klaus, Kirsten, Erik, Hanne og Keld. Vi vidste det godt, og havde sat øl og vand ud til dem, når de efter mørkets frembrud skulle sætte porten op. Kaffen og kagen havde Ellen sørget for, og når man var hos Ellen, manglede der ikke noget. Vagn og jeg var helt færdige med alle forberedelser kl. 19, så vi gik os en dejlig tur og hyggede os med lidt mad og en øl. Da vi kom tilbage, undrede det mig godt nok, at der stod en blå cykel i bryggerset, men vi havde jo lige givet Lars en ny cykel, så jeg tænkte, at det nok var den. Næste morgen fandt jeg ud af, at det var Vagns morgengave til mig, en Centurion City Bike. Vi sov faktisk godt den nat og hørte slet ikke, hvor meget de larmede, da de satte porten op."}, {"type": "para", "text": "Næste morgen, tirsdag den 28. juli, vågnede jeg kl. 4 og kunne ikke sove mere af bare spænding, så vi stod op kl. 5. Rikke Frost kom kl. 6.30 med rundstykkerne fra Hadsten. Hun havde lovet at være i køkkenet under morgenbesøget, og Lars og Marianne hjalp også til. Vi skulle have rugbrød med pålæg, som jeg havde skåret aftenen forinden, pynt, rundstykker med to slags ost, og kage. Jeg havde købt en lang lysegrøn kjole med blomsterranker fra ”Greenhouse”, og Vagn havde en matchende skjorte på og mørke bukser. Da klokken nærmede sig 7, gik vi op på gæsteværelset og kiggede ud gennem persiennerne, og det var sjovt at se, hvordan folk strømmede til. ”Nej, har du set, de kommer også”, sagde vi til hinanden. Det var ikke kun dem, der var inviteret med til festen, der kom, der var også naboer, som ville hilse på, og det var rørende. Der var også dem, der skulle komme langvejs fra til festen, der ikke kom til morgenbesøget, men det var også den eneste ulempe ved at holde festen på to dage. Vi kunne se, at Lars gik rundt og delte foldere ud, som han havde fået lavet med morgensangene. Det krævede også noget af ham som enebarn, for han havde ingen søskende at kunne dele opgaverne med, men han havde fået hjælp af Alice til at lave sang til festen. Det var en dejlig morgen, og da musikken lød præcis kl. 7.00, skulle vi lige synke en ekstra gang. Lars havde bestilt musik gennem Reinholt, som var fanebærer i Centralværkstedets Orkester, og det var Jørgen og to andre fra CO, der spillede. Det gjorde de rigtig godt, først til ”I østen stiger solen op”, dernæst ”Det er så yndigt at følges ad”, og til sidst ”Hør Vagn og Merete luk vinduet op”. Endelig kunne vi lukke døren op og se den flotte æresport, eller æresporte, for der var faktisk to, med blåt skold, som det sig hør og bør, og det var Reinholt, der havde skrevet på det så flot så flot. Det var et bevægende øjeblik at se alle de kære venner og familie, der var kommet for at fejre os. Der var kø for at komme til at hilse på os, og Tage tog video af alle gæsterne, mens de gik ind til kaffebordene. Vi fik mange gaver, over 20 buketter blomster og ligeså mange flasker, og af Marianne og Lars fik vi højtalere til køkkenet. Jeg fik lov at pakke alle gaverne op selv. Lars havde taget en af mine sko og en af Vagns sko og sølvsprayet dem. De stod på trappen med en brændende kærlighed og en husfred, en meget sød tradition. Skoen var dog en, jeg stadig brugte, men pyt, hvor der handles, spildes der. Der var tænkt på alt, selv vores husnummer, som jo var 25, havde Reinholt beklædt med sølvpapir. Hvor var det rørende alt det arbejde, alle havde lagt i denne dag."}, {"type": "figure", "caption": "", "page": 211, "file": "assets/images-bog2/p211_01.jpg", "dim": [787, 1139]}, {"type": "para", "text": "Lis og Bent fra Todbjerg kom kørende i hver sin bil, fordi Bent skulle fortsætte på arbejde i en bank i Århus efter morgenbesøget, men vi så ham ikke, for han var blevet væk. Det der skete var, at de kom kørende ad den nye omfartsvej med Lis forrest. Da de kommer til Spørring og skal dreje til højre, tænker Bent: ”Lis kan aldrig finde vej, så det er nok forkert. Jeg drejer sgu til venstre”. Så Lis drejede til højre og Bent til venstre. ”Fint”, tænkte Bent, ”jeg er kommet det rigtige sted hen, for der er optræk til morgenmusik derhenne”. Han undrede sig dog over, at han ikke kendte nogen og ikke kunne finde Lis. Det viste sig, at han var kommet til Jette og Leifs morgenbesøg, og da han fandt ud af, at det var det forkerte sølvbryllup, ville han ikke køre op til os, så han kørte direkte på arbejde."}, {"type": "para", "text": "”Sjakket” havde delt sig, så nogen var gået til Jette og Leif først, og nogen til os først, og så var der vagtskifte lidt senere. På den måde var der to hold gæster, der sang for os. Det passede fint, at der kom nogle gæster senere, for det endte med, at vi kom op på 80 gæster i løbet af dagen. Familien og nogle af vennerne blev der til pølsebord til frokost, og hvor var det dejligt, at vi ikke selv skulle holde fest om aftenen. Der var dog ikke megen tid til at rydde op, da den sidste gæst var gået, for vi skulle jo klædes om og være klar til at tage til Jette og Leifs sølvbryllup på Møllerens Hus. Det var en dejlig fest, selvom vi var ved at dø af varme. Vi måtte ikke lukke vinduerne op, da naboerne i så fald ville klage over larm, så hvis vi ville have lidt frisk luft, måtte vi gå udenfor. Det var der mange, der gjorde. Vi blev naturligvis nævnt og gratuleret ved bordet, men vi var ikke interesserede i at stjæle billedet fra Jette og Leif. Det var jo deres fest. Det gik nu også meget fint. Vi havde herefter de næste dage til at få styr på huset igen, inden det næste hold gæster skulle ankomme. Nu var det vennerne fra Højgårdsparken og Gl. Landevej, der skulle lave æresport til Hotellet, hjulpet af Marianne og Per, som havde lavet skjoldet denne gang. Det blev også en flot port, pyntet med roser og sølvbånd. Folderen, som lå ved hver kuvert, havde vores brudebillede på forsiden og invitationsbilledet på bagsiden. Indeni var velkomstsangen på melodien ”Græshoppen og valmuen”, og i omkvædet havde jeg nævnt alle de byer, som gæsterne kom fra. Menuen bestod af røget ørred med grønsagsterrine og flutes, kalvefilet med ristede champignons, grønsager, smørristede kartofler og rødvinssauce, og desserttallerken. Vinene var fra Italien, undtagen dessertvinen, som var Muscatvin fra Californien. Moster havde bagt kransekage til kaffen."}, {"type": "para", "text": "Inden vi skulle hjemmefra, havde vi en nervepirrende oplevelse. Jeg havde lige taget min fine kjole på og kom ind i stuen, hvor Elbo og Vibeke samt Ditte og Ejvind sad. Pludselig siger Ejvind: ”Hvad er det for en stor rund dims, du har siddende bag på din kjole – det ligner en stor broche”. Jeg kiggede mig rundt, og ganske rigtigt – nederst bagpå sad alarmen! Den havde de glemt at fjerne i butikken, og jeg var gået ud, uden at den havde virket. Nu var gode råd dyre. Jeg kunne ikke komme til mit eget sølvbryllup med alarmen siddende i min fine kjole, som om jeg havde stjålet den. Det var lørdag sidst på eftermiddagen, og Belmondo havde garanteret lukket. Hvad skulle vi gøre? Hvis vi selv prøvede at fjerne den, risikerede vi, at kjolen blev ødelagt af det farvestof, der oftest er i sådanne alarmer. Jeg fandt alligevel regningen fra forretningen og ringede nummeret op. Gudskelov kom der en stemme i den anden ende. Det var den 1. august, og der blev gjort status, så der var folk på arbejde. De beklagede fejlen men kunne trøste os med, at vi selv kunne fjerne pladen med en knibtang. Lars gik ud på værkstedet og kom ind med det rette værktøj, så jeg kunne blive klar til at tage imod vores gæster kl. 17.30. Hvor var det skønt at stå i Hotellets gang og tage imod på denne dejlige aften. Folk var virkelig festklædte og i godt humør. Vi havde taget alle gaverne med fra om tirsdagen, bl.a. den fine gæstebog, som Doris havde broderet efter samme motiv som den, hun havde syet til vores bryllup. Kun farverne var lidt anderledes. Vi fik endnu engang et væld af gaver, så gavebordet bugnede. Vi havde aftalt med Ras, at han skulle fotografere os alle parvis på trappen, så man kunne se de fine kjoler, og efter festen forærede han os et album med alle billederne, hvilket vi var meget glade for. Der var lavet traditionel bordopstilling med et hovedbord og tre lange borde, og duge og servietter var lysegrønne og matchede damernes bordkort. Maden var dejlig, men jeg havde ingen appetit, for jeg var stadig meget spændt på, hvad der ville ske af ting og sager under middagen og hvordan vores tale skulle gå. Der var mange festlige sange og indslag: Alice havde lavet en rigtig god sang fra Lars og Marianne på melodien: ”Jeg har min hest, jeg har min lasso”. Den sluttede med omkvædet fra ”Kald det kærlighed” – det var bare så rørende. Sangen blev afleveret af Lars klædt ud som lystfisker og med sangene i et net, og Marianne bar på et spil ”Lykkehjulet”, fordi jeg godt kunne lide at se den udsendelse på TV. Desuden havde Lars skrevet en smuk og rørende tale til os, som han afleverede på skrift ved bordet. Han har altid haft let til tårer, så han var bange for, at han ikke kunne holde den. Det var en fin måde at gøre det på. Der var en rigtig sjov sang fra Vagns familie præsenteret i en campingvogn, og Marianne havde også været i sit bedste digterhjørne med en sang fra hende og Per, som var pakket ind i Hong Kong dollars. Hanne og Keld havde en sang med på vendelbomål, som Keld spillede til på harmonika, og Alice, Reinholt, Grete og Poul havde lavet sang på melodien ”Vi er jo alle i samme båd”. De opførte den på scenen med en stor papirrulle med tegninger, der passede til sangen, og så pegede de på billederne efterhånden som vi kom frem. Behøver jeg at sige, at det var Reinholt, der havde været kunstneren bag værket. Den sidste sang var fra moster og Ib på melodien ”Pomp and Circumstance”, og alle stod op og viftede med flagene, hvilket gav en god stemning. Indslaget fra de 9 vennepar var ikke en sang. Vi havde jo været til to sølvbryllupper, hvor vi havde lavet sang, så nu skulle der ske noget andet. Og det gjorde der i sandhed også. Vagn og jeg blev ført ud af Niels og Leif, og vi fik alle fire ”rumdragter” på. Niels og jeg fik røde overtræksveste på og udgjorde rødt hold, og Vagn og Leif fik blå veste på og udgjorde blåt hold, à la en TV-udsendelse, der kørte på det tidspunkt. Karen havde syet vestene. Vi gik så op på scenen, hvor alle rekvisitter stod. Vi fik at vide, at jeg skulle stege fiskefileter, og Vagn skulle lave en fuglekasse. Det var jo let nok, for det havde vi prøvet før, indtil konkurrencen gik i gang, og Leif råbte: ”BYT!” Vi skulle bytte roller, og jeg skulle nu pludselig lave en fuglekasse, og Vagn skulle stege fiskefileter. Vi blev godt hjulpet af holdkaptajnerne, og gæsterne havde fået udleveret røde og blå kort, og skulle heppe på os undervejs. Jeg husker ikke, hvem der vandt, men det var vældig festligt og sjovt."}, {"type": "figure", "caption": "", "page": 212, "file": "assets/images-bog2/p212_01.jpg", "dim": [726, 1022]}, {"type": "para", "text": "Så kommer vi til talerne, og ret tidligt på aftenen slog Vagn på glasset og rejste sig op. Nu forventede alle, at han ville holde en tale à la dem, Niels og Leif havde holdt for deres sølvbrude og med rosende ord lovprise mig. Men han meddelte tværtimod, at han ville fremhæve alle mine svagheder, hvorved jeg resolut rejste mig og sagde, at nu måtte han virkelig holde op, for hvis han kunne gøre det, så havde jeg også en masse at klage over ved ham. Det udviklede sig til et mindre skænderi. Vi gjorde det uden manuskript, og det virkede spontant fra min side, så der var nogle af gæsterne, der var ved at føle sig pinligt berørte, indtil det gik op for dem, at det var indstuderet. Jeg synes selv, vi kom godt fra det, og det var sjovt og meget uhøjtideligt. Udover vores egen og Lars’ taler holdt Per en rigtig god tale, og der var taler fra Doris og Poul Erik, fra Ejvind, moster og Keld. Undervejs blev der banket i tallerknerne, og vi måtte op på stolene og kysse. Da de råbte: ”Strømpebånd” måtte jeg hive op i kjolen og vise, at jeg havde et lyseblåt strømpebånd på, og da de råbte: ”Boxershorts”, trak Vagn bukserne ned og viste sine fine nye koboltblå underbukser. Vi fulgte helt traditionerne. Traditionen sagde også, at man skulle danse brudevals inden kl. 24. Den tradition ville vi gerne have brudt, for vi var ikke færdige med maden kl. 24, men det kom vi ikke til at bestemme. Vi måtte inden desserten op på scenen for at danse brudevals, som vi havde øvet os på sammen med Lars, og så kom Karen med saksen, som hun altid havde i tasken til sådanne lejligheder. Vagn fik klippet sokker, men han var forberedt, så han havde gamle sokker på og et par nye med, og han havde smurt neglelak på tåneglene. Vi havde ikke forestillet os, at vi skulle gentage succesen efter desserten, hvor dansegulvet blev ryddet. Og nu kom saksen minsandten frem igen, og de nye sokker blev molesterede."}, {"type": "para", "text": "Ballet bagefter gik godt, og den fik ikke for lidt. Musikken gav den gas, og han kunne spille hvad som helst. Vi havde hørt ham hos Vivi og Frode, så vi vidste, at han var god. Vi fik ham til at spille lidt længere, for Hotellet var lige glade med, hvornår vi stoppede. Vi fik æggekage til natmad, og som de sidste vandrede vi kl. 5 op gennem Østervang sammen med genboens, som bar på 11-årige Pernille. Hun var faldet i søvn på Hotellets sofa."}, {"type": "para", "text": "Vi betalte Hotellet 34.547 kr., og festen løb i alt op i 63.341,87 kr., men det var alle pengene værd. Vi nåede lige at sove i kælderen i to timer, før vi skulle op og lave morgenmad til 40 gæster, som havde sovet rundt omkring i byen. Det havde været en fest-uge, vi aldrig ville glemme."}, {"type": "figure", "caption": "", "page": 214, "file": "assets/images-bog2/p214_01.jpg", "dim": [670, 983]}, {"type": "figure", "caption": "", "page": 214, "file": "assets/images-bog2/p214_02.jpg", "dim": [766, 1139]}, {"type": "figure", "caption": "", "page": 214, "file": "assets/images-bog2/p214_03.jpg", "dim": [774, 1120]}, {"type": "figure", "caption": "", "page": 214, "file": "assets/images-bog2/p214_04.jpg", "dim": [781, 1091]}, {"type": "figure", "caption": "De 5 billeder: 1.Marianne og Lars 2. Marianne og Per 3. Moster og Ib 4. Farmor og Thomas 5. Charlotte og Jette", "page": 215, "file": "assets/images-bog2/p215_01.jpg", "dim": [766, 1089]}]}, {"title": "Historiske begivenheder", "blocks": [{"type": "para", "text": "- Sovjetunionens sammenbrud i 1991. Enden på Den kolde krig - Balkankrig i det tidligere Jugoslavien - Golfkrigen 1991 og embargo mod Irak - Efter 1992 stiger aktiemarkedet kraftigt. Mod slutningen af årtiet er stigningen særligt kraftig for IT-virksomheder og virksomheder inden for bioteknologi - Apartheid opgives i Sydafrika, og en ANC-regering med Nelson Mandela i spidsen overtager magten - Danmarks fodboldlandshold vinder EM i 1992 - Bill Clinton besøger, som den første siddende amerikanske præsident nogensinde, Danmark - Popgruppen Aqua opnår international succes med deres sang ”Barbie Girl” - Den 27. april 1993 har vi rekord varmegrader: 28 grader Celcius - Den 18. maj 1993 stemmer danskerne JA til Maastricht-Traktaten - Prins Joachim bliver forlovet og gift med Prinsesse Alexandra i 1995 - 50 året for Danmarks befrielse fejres den 4. maj 1995. Vi var til 20 bål på stranden ude hos Hanne og Keld. Senere gik vi ind på Rådhuspladsen, hvor der var stor mindehøjtidelighed med 10.000 mennesker. Dagen efter var jeg med til 2 min. stilhed på Rådhuspladsen kl. 12 - På TV ser vi i 1997 Strisser på Samsø, Taxa, Bryggeren, Columbo og Danielle Steel, min yndlingsforfatter - I 1997 fejrer Dronning Margrethe 25-års jubilæum. Vi ser hende køre i karet i Århus den 18. januar 1997 - Prinsesse Diana dør den 30. august 1997 - Danmark vinder guld i håndbold over Norge i 1997 - Der er valg den 11. marts 1998. Poul Nyrup Rasmussen fortsætter som statsminister - Storkonflikt starter den 27. april 1998 - I biograferne går i 1998 Titanic, som vi ser sammen med Lis og Ole - Kraftig vækst i brugen af internet. Fald i prisen på computere og anden teknologi - Kloning af fåret Dolly"}]}, {"title": "Efterskrift", "blocks": [{"type": "para", "text": "Torsdag den 24. juli 2014"}, {"type": "para", "text": "Kære Lars"}, {"type": "para", "text": "Mens du og far går og bygger i Søllerød, sidder jeg her i sommervarmen og prøver at få denne bog færdig, som har været undervejs i flere år. Jeg vil gerne give dig den i julegave i år. Jeg har brugt noget af denne uge til at finde en masse billeder til bogen, og det er ikke svært, for hvor har vi mange albums fra vores liv sammen. Det vanskelige ligger i at begrænse sig, for vi har så mange gode billeder af dig."}, {"type": "figure", "caption": "", "page": 216, "file": "assets/images-bog2/p216_01.jpg", "dim": [779, 1169]}, {"type": "para", "text": "Siden jeg startede på bogen, har du og Mette fået endnu to sønner, Frederik og Carl, og hvor er far og jeg dog lykkelige for de tre skønne børnebørn. Og sidste skud på stammen, Carl, ligner dig på en prik. Det er næsten som en rejse tilbage i tiden, når jeg sidder med ham på skødet."}, {"type": "para", "text": "Jeg håber, drengene engang vil synes, at det er sjovt at læse om deres fars barndom."}, {"type": "para", "text": "Denne bog er mere end en erindringsbog."}, {"type": "para", "text": "Den er en kærlighedserklæring til dig, og jeg vil slutte med et citat fra min mor, din mormor, som sagde mange kloge ting. Da du blev født, gav hun mig et lilla køresæt, som hun havde syet i patchwork, og på kortet stod der: ”Kære elskede Merete."}, {"type": "para", "text": "Jeg ønsker dig hjertelig til lykke med din lille knægt. Du har nu opnået det bedste i denne verden, du er blevet mor. Kærlig hilsen mor”."}, {"type": "para", "text": "Mange kærlige knus og tanker fra Mor"}, {"type": "para", "text": "Venstre side: Højre side: Nr. 1: Huset set fra vejen og fra oven Nr. 1: Stue Nr. 2: Meretes kontor Nr. 2: Badeværelse Nr. 3: Køkken Nr. 3: Lars’ værelse i kælderen Nr. 4: Overdækket terrasse Nr. 4: Vagns værelse i kælderen Nr. 4: Bryggers"}, {"type": "figure", "caption": "Vores hus lige inden det blev solgt i 2009", "page": 217, "file": "assets/images-bog2/p217_01.jpg", "dim": [1500, 1000]}, {"type": "figure", "caption": "", "page": 218, "file": "assets/images-bog2/p218_01.jpg", "dim": [1071, 606]}, {"type": "figure", "caption": "", "page": 218, "file": "assets/images-bog2/p218_02.jpg", "dim": [910, 606]}, {"type": "figure", "caption": "", "page": 218, "file": "assets/images-bog2/p218_06.jpg", "dim": [909, 565]}, {"type": "figure", "caption": "", "page": 218, "file": "assets/images-bog2/p218_05.jpg", "dim": [909, 606]}, {"type": "figure", "caption": "", "page": 218, "file": "assets/images-bog2/p218_04.jpg", "dim": [909, 551]}, {"type": "figure", "caption": "", "page": 218, "file": "assets/images-bog2/p218_03.jpg", "dim": [909, 606]}, {"type": "figure", "caption": "", "page": 218, "file": "assets/images-bog2/p218_08.jpg", "dim": [870, 525]}, {"type": "figure", "caption": "", "page": 218, "file": "assets/images-bog2/p218_07.jpg", "dim": [1065, 710]}, {"type": "figure", "caption": "", "page": 218, "file": "assets/images-bog2/p218_09.jpg", "dim": [804, 499]}]}]}], "cover": []};
